#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .init();

    // 结构化诊断日志（coolzhu-diagnostics）：JSONL + trace_id/span + outcome，供开机自检/soak 机判。
    // 与既有 diag!/err.log（人读面包屑）并存互补，不替换。
    match diagnostics::init("coolzhu-web-console") {
        Ok(path) => info!("结构化诊断日志已就绪: {}", path.display()),
        Err(error) => {
            diagnostics::error_event(
                "gui-web",
                "diagnostics_init_failed",
                "Failed to initialize structured diagnostics",
                &error,
                &[("phase", "startup".to_string())],
            );
            warn!("结构化诊断日志初始化失败: {error}");
        }
    }
    if let Err(error) = browser_bridge::ensure_runtime_nonce_file() {
        warn!("浏览器 Computer Use 运行时握手文件初始化失败: {error}");
    }

    // 进程重启后先恢复持久化 run，再 bind/scheduler；已有数据库恢复失败必须 fail-closed，
    // 避免旧任务 worker 在状态未校正时继续运行。数据库尚不存在时恢复函数是 no-op。
    let runtime_run_db_path = default_session_sqlite_path();
    match recover_incomplete_runtime_runs(&runtime_run_db_path) {
        Ok(recovered) if recovered > 0 => {
            info!(
                "runtime run 启动恢复完成: recovered={}, path={}",
                recovered,
                runtime_run_db_path.display()
            );
        }
        Ok(_) => {}
        Err(error) => {
            diagnostics::error_event(
                "gui-web",
                "runtime_run_recovery_failed",
                "Failed to recover incomplete runtime runs",
                &error,
                &[("path", runtime_run_db_path.display().to_string())],
            );
            return Err(Box::new(error) as Box<dyn std::error::Error>);
        }
    }

    let bind_addr = config_web_bind_addr();
    let address: SocketAddr = match bind_addr.parse() {
        Ok(address) => address,
        Err(error) => {
            diagnostics::error_event(
                "gui-web",
                "bind_address_parse_failed",
                "Failed to parse configured web bind address",
                &error,
                &[("bind_addr", bind_addr.clone())],
            );
            return Err(Box::new(error) as Box<dyn std::error::Error>);
        }
    };
    let listener = match tokio::net::TcpListener::bind(address).await {
        Ok(listener) => listener,
        Err(error) => {
            diagnostics::error_event(
                "gui-web",
                "listener_bind_failed",
                "Failed to bind web console listener",
                &error,
                &[("bind_addr", bind_addr.clone())],
            );
            return Err(Box::new(error) as Box<dyn std::error::Error>);
        }
    };
    #[cfg(windows)]
    {
        use std::os::windows::io::AsRawSocket;

        if let Err(error) =
            windows_process_guard::make_socket_non_inheritable(listener.as_raw_socket())
        {
            diagnostics::error_event(
                "gui-web",
                "listener_inherit_guard_failed",
                "Failed to mark web console listener as non-inheritable",
                &error,
                &[("bind_addr", bind_addr.clone())],
            );
            return Err(Box::new(error) as Box<dyn std::error::Error>);
        }
    }
    let local_address = match listener.local_addr() {
        Ok(local_address) => local_address,
        Err(error) => {
            diagnostics::error_event(
                "gui-web",
                "listener_local_address_failed",
                "Failed to read web console listener address",
                &error,
                &[("bind_addr", bind_addr.clone())],
            );
            return Err(Box::new(error) as Box<dyn std::error::Error>);
        }
    };
    let url = listener_client_url(local_address);

    info!("COOLZHU AGENT Web 控制台已启动: {url}");
    persist_gui_web_url(&url);
    set_showui_console_url(&url);
    if desktop_shell_managed_by_launcher() {
        info!("桌面壳由 package launcher 管理，Web Console 跳过自动拉起桌宠");
    } else {
        let showui_status = start_showui_service(&url);
        if let Some(pid) = showui_status.pid {
            spawn_showui_exit_monitor(pid);
        }
    }
    spawn_scheduled_task_scheduler();
    if env::args().any(|arg| arg == "--open") {
        open_browser(&url);
    }

    let server_result = axum::serve(listener, app())
        .with_graceful_shutdown(async {
            web_console_shutdown_signal().notified().await;
            info!("桌宠退出联动：web-console 开始优雅退出");
        })
        .await;
    shutdown_local_model_services_on_exit();
    let _ = terminate_showui_service_process();
    match server_result {
        Ok(()) => Ok(()),
        Err(error) => {
            diagnostics::error_event(
                "gui-web",
                "server_run_failed",
                "Web console server exited with an error",
                &error,
                &[("url", url)],
            );
            Err(Box::new(error) as Box<dyn std::error::Error>)
        }
    }
}

fn listener_client_url(local_address: SocketAddr) -> String {
    let client_address = match local_address.ip() {
        std::net::IpAddr::V4(address) if address.is_unspecified() => {
            SocketAddr::from(([127, 0, 0, 1], local_address.port()))
        }
        std::net::IpAddr::V6(address) if address.is_unspecified() => SocketAddr::new(
            std::net::IpAddr::V6(std::net::Ipv6Addr::LOCALHOST),
            local_address.port(),
        ),
        _ => local_address,
    };
    format!("http://{client_address}/")
}

/// 桌宠退出联动 web-console 优雅退出的信号。
fn web_console_shutdown_signal() -> &'static tokio::sync::Notify {
    static SIGNAL: OnceLock<tokio::sync::Notify> = OnceLock::new();
    SIGNAL.get_or_init(tokio::sync::Notify::new)
}

/// 当前活跃桌宠进程 pid（区分「活跃桌宠退出」与「重启后陈旧 pid」）。
fn current_showui_pid() -> Option<u32> {
    showui_service_process()
        .lock()
        .ok()
        .and_then(|process| process.as_ref().map(std::process::Child::id))
}

/// 桌宠退出是否联动关闭 web-console（默认开启；显式配置 false 才保留控制台）。
fn pet_exit_closes_console_enabled() -> bool {
    read_config(|config| config.pet.pet_exit_closes_console)
}

fn spawn_showui_exit_monitor(pid: u32) {
    tokio::spawn(async move {
        let mut interval = tokio::time::interval(Duration::from_secs(3));
        loop {
            interval.tick().await;
            if !SHOWUI_SERVICE_ENABLED.load(Ordering::SeqCst) {
                continue;
            }
            if !process_exists(pid) {
                // 仅当死掉的是「当前活跃桌宠」时联动（避免重启后旧 pid 监控误触发）。
                let was_active = current_showui_pid() == Some(pid);
                mark_showui_service_process_exited(pid);
                if was_active && pet_exit_closes_console_enabled() {
                    warn!("桌宠进程 {pid} 退出，web-console 联动优雅退出");
                    web_console_shutdown_signal().notify_one();
                } else {
                    warn!("ShowUI shell process {pid} exited; Web Console stays running");
                }
                break;
            }
        }
    });
}

#[cfg(windows)]
fn process_exists(pid: u32) -> bool {
    let output = std::process::Command::new("tasklist")
        .args(["/FI", &format!("PID eq {pid}"), "/NH"])
        .creation_flags(CREATE_NO_WINDOW)
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .output();
    let Ok(output) = output else {
        return false;
    };
    String::from_utf8_lossy(&output.stdout).contains(&pid.to_string())
}

#[cfg(not(windows))]
fn process_exists(pid: u32) -> bool {
    std::process::Command::new("sh")
        .arg("-c")
        .arg(format!("kill -0 {pid}"))
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .map(|status| status.success())
        .unwrap_or(false)
}

