fn web_card_api_audit_item(
    id: &str,
    name: &str,
    tier: &str,
    endpoints: &[&str],
    loading_state: bool,
    error_state: bool,
    empty_state: bool,
) -> WebCardApiCard {
    let mut gaps = Vec::new();
    if endpoints.is_empty() {
        gaps.push("missing endpoint".to_string());
    }
    if !loading_state {
        gaps.push("missing loading state".to_string());
    }
    if !error_state {
        gaps.push("missing error state".to_string());
    }
    if !empty_state {
        gaps.push("missing empty state".to_string());
    }
    WebCardApiCard {
        id: id.to_string(),
        name: name.to_string(),
        tier: tier.to_string(),
        endpoints: endpoints
            .iter()
            .map(|endpoint| endpoint.to_string())
            .collect(),
        loading_state,
        error_state,
        empty_state,
        status: if gaps.is_empty() { "ready" } else { "gap" }.to_string(),
        gaps,
    }
}

