fn showui_service_process() -> &'static Mutex<Option<std::process::Child>> {
    static PROCESS: OnceLock<Mutex<Option<std::process::Child>>> = OnceLock::new();
    PROCESS.get_or_init(|| Mutex::new(None))
}

/// 全局 compute-use 真实输入串行化闸门。
///
/// 物理键鼠注入是全机唯一资源：多个聊天室会话同时触发 compute-use 动作会互相
/// 抢占光标/焦点造成错乱。这里用一个进程级 `tokio::sync::Mutex` 作为公平排队锁——
/// 所有真实输入（点击/键入/拖拽/热键）在执行前必须先拿到该锁，从而天然串行、
/// 先到先得，且因为是 async 锁不会阻塞 worker 线程（高效排队，不自旋）。
fn compute_use_input_gate() -> &'static tokio::sync::Mutex<()> {
    static GATE: OnceLock<tokio::sync::Mutex<()>> = OnceLock::new();
    GATE.get_or_init(|| tokio::sync::Mutex::new(()))
}

fn showui_console_url_store() -> &'static Mutex<Option<String>> {
    static URL: OnceLock<Mutex<Option<String>>> = OnceLock::new();
    URL.get_or_init(|| Mutex::new(None))
}

fn vision_realtime_state() -> &'static Mutex<VisionRealtimeElementState> {
    static STATE: OnceLock<Mutex<VisionRealtimeElementState>> = OnceLock::new();
    STATE.get_or_init(|| Mutex::new(VisionRealtimeElementState::default()))
}

fn vision_realtime_loop_handle() -> &'static Mutex<Option<tokio::task::JoinHandle<()>>> {
    static HANDLE: OnceLock<Mutex<Option<tokio::task::JoinHandle<()>>>> = OnceLock::new();
    HANDLE.get_or_init(|| Mutex::new(None))
}

fn set_showui_console_url(url: &str) {
    if let Ok(mut stored) = showui_console_url_store().lock() {
        *stored = Some(url.to_string());
    }
}

fn showui_console_url() -> String {
    showui_console_url_store()
        .lock()
        .ok()
        .and_then(|stored| stored.clone())
        .unwrap_or_else(|| format!("http://{}/", config_web_bind_addr()))
}

fn showui_service_config_disabled() -> bool {
    !config_pet_enabled()
}

fn poll_showui_service_process(process: &mut Option<std::process::Child>) -> Option<u32> {
    let child = process.as_mut()?;
    match child.try_wait() {
        Ok(Some(status)) => {
            info!("ShowUI service exited with status {status}");
            *process = None;
            None
        }
        Ok(None) => Some(child.id()),
        Err(error) => {
            warn!("Failed to poll ShowUI service status: {error}");
            None
        }
    }
}

fn mark_showui_service_process_exited(pid: u32) {
    let mut cleared = false;
    if let Ok(mut process) = showui_service_process().lock() {
        let matches = process
            .as_ref()
            .map(|child| child.id() == pid)
            .unwrap_or(false);
        if matches {
            if let Some(mut child) = process.take() {
                let _ = child.try_wait();
                cleared = true;
            }
        }
    }
    if cleared {
        info!("ShowUI service process {pid} cleared; enabled intent is preserved.");
    }
}

fn showui_service_status_with_message(message: impl Into<String>) -> ShowUiServiceResponse {
    let (running, pid) = showui_service_process()
        .lock()
        .ok()
        .map(|mut process| {
            let pid = poll_showui_service_process(&mut process);
            (pid.is_some(), pid)
        })
        .unwrap_or((false, None));
    ShowUiServiceResponse {
        enabled: SHOWUI_SERVICE_ENABLED.load(Ordering::Relaxed)
            && !showui_service_config_disabled(),
        running,
        available: local_port_listening(LOCAL_SHOWUI_PORT),
        pid,
        disabled: showui_service_config_disabled(),
        desktop_pet_exe: desktop_pet_executable().map(|path| path.display().to_string()),
        console_url: showui_console_url_store()
            .lock()
            .ok()
            .and_then(|stored| stored.clone()),
        message: message.into(),
    }
}

fn desktop_shell_managed_value(value: Option<&std::ffi::OsStr>) -> bool {
    value.is_some_and(|value| {
        matches!(
            value.to_string_lossy().trim().to_ascii_lowercase().as_str(),
            "1" | "true" | "yes" | "on"
        )
    })
}

fn desktop_shell_managed_by_launcher() -> bool {
    desktop_shell_managed_value(std::env::var_os("COOLZHU_DESKTOP_SHELL_MANAGED").as_deref())
}

fn managed_showui_service_status(message: impl Into<String>) -> ShowUiServiceResponse {
    ShowUiServiceResponse {
        enabled: true,
        running: true,
        available: local_port_listening(LOCAL_SHOWUI_PORT),
        pid: None,
        disabled: false,
        desktop_pet_exe: desktop_pet_executable().map(|path| path.display().to_string()),
        console_url: showui_console_url_store()
            .lock()
            .ok()
            .and_then(|stored| stored.clone()),
        message: message.into(),
    }
}

fn start_showui_service(console_url: &str) -> ShowUiServiceResponse {
    SHOWUI_SERVICE_ENABLED.store(true, Ordering::Relaxed);
    set_showui_console_url(console_url);
    if desktop_shell_managed_by_launcher() {
        return managed_showui_service_status("Desktop shell is managed by package launcher.");
    }
    if showui_service_config_disabled() {
        return showui_service_status_with_message("ShowUI service is disabled by config.");
    }
    let mut process = match showui_service_process().lock() {
        Ok(process) => process,
        Err(_) => return showui_service_status_with_message("ShowUI service lock failed."),
    };
    if let Some(pid) = poll_showui_service_process(&mut process) {
        return ShowUiServiceResponse {
            enabled: true,
            running: true,
            available: local_port_listening(LOCAL_SHOWUI_PORT),
            pid: Some(pid),
            disabled: false,
            desktop_pet_exe: desktop_pet_executable().map(|path| path.display().to_string()),
            console_url: Some(console_url.to_string()),
            message: "ShowUI service is already running.".to_string(),
        };
    }
    *process = launch_desktop_pet(console_url);
    let pid = process.as_ref().map(std::process::Child::id);
    ShowUiServiceResponse {
        enabled: true,
        running: pid.is_some(),
        available: local_port_listening(LOCAL_SHOWUI_PORT),
        pid,
        disabled: false,
        desktop_pet_exe: desktop_pet_executable().map(|path| path.display().to_string()),
        console_url: Some(console_url.to_string()),
        message: if pid.is_some() {
            "ShowUI service started.".to_string()
        } else {
            "ShowUI executable is unavailable or failed to start.".to_string()
        },
    }
}

fn web_console_parent_pid_arg(pid: u32) -> String {
    format!("--web-console-pid={pid}")
}

fn stop_showui_service() -> ShowUiServiceResponse {
    if desktop_shell_managed_by_launcher() {
        return managed_showui_service_status(
            "Desktop shell is managed by package launcher and remains available.",
        );
    }
    terminate_showui_service_process_with_messages(
        "ShowUI service stopped; web shell kept open.",
        "ShowUI service is already stopped; web shell kept open.",
    )
}

fn terminate_showui_service_process() -> ShowUiServiceResponse {
    terminate_showui_service_process_with_messages(
        "ShowUI service stopped.",
        "ShowUI service is already stopped.",
    )
}

fn terminate_showui_service_process_with_messages(
    stopped_message: &str,
    already_stopped_message: &str,
) -> ShowUiServiceResponse {
    SHOWUI_SERVICE_ENABLED.store(false, Ordering::Relaxed);
    let mut stopped = false;
    if let Ok(mut process) = showui_service_process().lock() {
        if let Some(mut child) = process.take() {
            shutdown_desktop_pet(&mut child);
            stopped = true;
        }
    }
    showui_service_status_with_message(if stopped {
        stopped_message
    } else {
        already_stopped_message
    })
}

// ===================== 本地模型服务开关 =====================
// 8GB 显存单活跃：chat=本地文本推理(8082) ⇆ vision=UI-DETR(7860)+ShowUI(8000)。
// 停用按端口杀进程（释放显存，无论谁启动）；启用按已验证命令 spawn。bge-m3(8081) 不随切换。

const LOCAL_UIDETR_PORT: u16 = 7860;
const LOCAL_SHOWUI_PORT: u16 = 8000;
const LOCAL_EMBED_PORT: u16 = 8081;

#[derive(Debug, Clone, Copy)]
struct LocalChatRuntimeConfig {
    port: u16,
    context_window: u32,
    max_output_tokens: u32,
    reasoning_budget: u32,
    gpu_layers: u32,
    parallel_slots: u32,
    startup_timeout_ms: u64,
}

fn local_chat_runtime_config() -> LocalChatRuntimeConfig {
    read_config(|config| {
        normalized_local_chat_runtime_config(
            config.model.local_chat_port,
            config.model.local_chat_context_window,
            config.model.local_chat_max_output_tokens,
            config.model.local_chat_reasoning_budget,
            config.model.local_chat_gpu_layers,
            config.model.local_chat_parallel_slots,
            config.model.local_chat_startup_timeout_ms,
        )
    })
}

fn normalized_local_chat_runtime_config(
    port: u16,
    context_window: u32,
    max_output_tokens: u32,
    reasoning_budget: u32,
    gpu_layers: u32,
    parallel_slots: u32,
    startup_timeout_ms: u64,
) -> LocalChatRuntimeConfig {
    let context_window = context_window.max(1);
    let max_output_tokens = max_output_tokens
        .max(1)
        .min(context_window.saturating_sub(1).max(1));
    LocalChatRuntimeConfig {
        port,
        context_window,
        max_output_tokens,
        reasoning_budget: reasoning_budget.min(max_output_tokens.saturating_sub(1)),
        gpu_layers,
        parallel_slots: parallel_slots.clamp(1, 8),
        startup_timeout_ms: startup_timeout_ms.clamp(1_000, 120_000),
    }
}

fn local_gemma_runtime_args(runtime: LocalChatRuntimeConfig) -> Vec<String> {
    vec![
        "--host".to_string(),
        "127.0.0.1".to_string(),
        "--port".to_string(),
        runtime.port.to_string(),
        "-ngl".to_string(),
        runtime.gpu_layers.to_string(),
        "-c".to_string(),
        runtime.context_window.to_string(),
        "-np".to_string(),
        runtime.parallel_slots.to_string(),
        "--reasoning-budget".to_string(),
        runtime.reasoning_budget.to_string(),
        "--jinja".to_string(),
    ]
}

/// 切换后的活跃模式纯逻辑映射（便于单测 / 状态展示）。
fn local_active_mode(gemma: bool, vision: bool) -> &'static str {
    match (gemma, vision) {
        (true, false) => "chat",
        (false, true) => "vision",
        (true, true) => "mixed",
        (false, false) => "off",
    }
}

fn local_port_listening(port: u16) -> bool {
    let addr = std::net::SocketAddr::from(([127, 0, 0, 1], port));
    std::net::TcpStream::connect_timeout(&addr, std::time::Duration::from_millis(300)).is_ok()
}

fn local_vision_endpoint_reachable(base_url: &str) -> bool {
    let without_scheme = base_url
        .split_once("://")
        .map_or(base_url, |(_, rest)| rest);
    let authority = without_scheme.split('/').next().unwrap_or_default();
    let (host, port) = authority.rsplit_once(':').map_or_else(
        || {
            let default_port = if base_url.starts_with("https://") {
                443
            } else {
                80
            };
            (authority, default_port)
        },
        |(host, port)| {
            (
                host.trim_matches(['[', ']']),
                port.parse::<u16>().unwrap_or(0),
            )
        },
    );
    if port == 0 {
        return false;
    }
    if matches!(host, "127.0.0.1" | "localhost" | "::1") {
        local_port_listening(port)
    } else {
        // 远端兼容端点不能用本机 TCP 探测判断；请求阶段仍会有真实健康/凭据错误。
        true
    }
}

fn local_gemma_ready(port: u16) -> bool {
    use std::io::Write as _;

    let addr = std::net::SocketAddr::from(([127, 0, 0, 1], port));
    let timeout = std::time::Duration::from_millis(800);
    let Ok(mut stream) = std::net::TcpStream::connect_timeout(&addr, timeout) else {
        return false;
    };
    let _ = stream.set_read_timeout(Some(timeout));
    let _ = stream.set_write_timeout(Some(timeout));
    let request =
        format!("GET /health HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nConnection: close\r\n\r\n");
    if stream.write_all(request.as_bytes()).is_err() {
        return false;
    }
    let mut response = [0_u8; 256];
    let Ok(read) = stream.read(&mut response) else {
        return false;
    };
    let head = String::from_utf8_lossy(&response[..read]);
    head.starts_with("HTTP/1.1 200") || head.starts_with("HTTP/1.0 200")
}

/// 按端口杀掉监听进程（释放显存），与启动者无关。
#[cfg(windows)]
fn kill_listeners_on_port(port: u16) {
    let script = format!(
        "Get-NetTCPConnection -LocalPort {port} -State Listen -ErrorAction SilentlyContinue | \
         ForEach-Object {{ Stop-Process -Id $_.OwningProcess -Force -ErrorAction SilentlyContinue }}"
    );
    let _ = std::process::Command::new("powershell")
        .args(["-NoProfile", "-NonInteractive", "-Command", &script])
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status();
}
#[cfg(not(windows))]
fn kill_listeners_on_port(_port: u16) {}

/// 在 exe 上溯目录中定位仓库内资源（脚本路径）。
fn repo_resource_path(rel: &str) -> Option<std::path::PathBuf> {
    if let Ok(exe) = std::env::current_exe() {
        for anc in exe.ancestors() {
            let candidate = anc.join(rel);
            if candidate.exists() {
                return Some(candidate);
            }
        }
    }
    std::env::current_dir()
        .ok()
        .map(|cwd| cwd.join(rel))
        .filter(|p| p.exists())
}

/// 定位 llama-server.exe（优先 cuda-12.4 构建）。
fn find_llama_server_exe() -> Option<std::path::PathBuf> {
    let base = user_home_dir()?.join("llama.cpp");
    let mut fallback = None;
    for entry in std::fs::read_dir(&base).ok()?.flatten() {
        let dir = entry.path();
        let exe = dir.join("llama-server.exe");
        if !dir.is_dir() || !exe.exists() {
            continue;
        }
        let name = dir
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("")
            .to_ascii_lowercase();
        if name.contains("cuda-12.4") {
            return Some(exe);
        }
        if fallback.is_none() {
            fallback = Some(exe);
        }
    }
    fallback
}

fn local_model_log_path() -> PathBuf {
    let workspace = active_workspace_path();
    read_config(|config| {
        workspace_data_dir_for(&workspace, config)
            .join("logs")
            .join("local-gemma.log")
    })
}

fn spawn_detached_logged(mut cmd: std::process::Command, log_path: &Path) -> Result<u32, String> {
    if let Some(parent) = log_path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|error| format!("创建本地模型日志目录失败: {error}"))?;
    }
    let stdout = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_path)
        .map_err(|error| format!("打开本地模型日志失败: {error}"))?;
    let stderr = stdout
        .try_clone()
        .map_err(|error| format!("复制本地模型日志句柄失败: {error}"))?;
    cmd.stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::from(stdout))
        .stderr(std::process::Stdio::from(stderr));
    #[cfg(windows)]
    cmd.creation_flags(CREATE_NO_WINDOW);

    let mut child = cmd
        .spawn()
        .map_err(|error| format!("启动本地模型进程失败: {error}"))?;
    #[cfg(windows)]
    {
        if let Err(error) = local_model_child_job()?.assign(&child) {
            let _ = child.kill();
            let _ = child.wait();
            return Err(format!("绑定本地模型进程生命周期失败: {error}"));
        }
    }
    Ok(child.id())
}

#[cfg(windows)]
fn local_model_child_job() -> Result<&'static windows_process_guard::ChildProcessJob, String> {
    static JOB: OnceLock<windows_process_guard::ChildProcessJob> = OnceLock::new();
    if JOB.get().is_none() {
        let job = windows_process_guard::ChildProcessJob::new_kill_on_close()
            .map_err(|error| format!("创建本地模型 Job Object 失败: {error}"))?;
        let _ = JOB.set(job);
    }
    JOB.get()
        .ok_or_else(|| "本地模型 Job Object 初始化失败".to_string())
}

fn spawn_detached(mut cmd: std::process::Command) -> bool {
    cmd.stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null());
    #[cfg(windows)]
    cmd.creation_flags(CREATE_NO_WINDOW);

    let mut child = match cmd.spawn() {
        Ok(child) => child,
        Err(error) => {
            warn!("本地模型服务进程启动失败: {error}");
            return false;
        }
    };
    #[cfg(windows)]
    {
        if let Err(error) = local_model_child_job().and_then(|job| {
            job.assign(&child)
                .map_err(|error| format!("绑定本地模型进程生命周期失败: {error}"))
        }) {
            warn!("{error}");
            let _ = child.kill();
            let _ = child.wait();
            return false;
        }
    }
    true
}

fn configured_local_chat_model_path() -> Option<PathBuf> {
    read_config(|config| {
        config
            .model
            .local_chat_model_path
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(PathBuf::from)
    })
}

fn configured_local_chat_mmproj_path() -> Option<PathBuf> {
    read_config(|config| {
        config
            .model
            .local_chat_mmproj_path
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(PathBuf::from)
    })
}

fn validate_local_chat_model_path(raw: &str) -> Result<String, String> {
    let value = raw.trim();
    if value.is_empty() {
        return Err("本地模型文件路径不能为空".to_string());
    }
    let path = PathBuf::from(value);
    let canonical = path
        .canonicalize()
        .map_err(|error| format!("本地模型文件不存在或不可访问: {error}"))?;
    if !canonical.is_file() {
        return Err("本地模型路径必须指向文件".to_string());
    }
    let is_gguf = canonical
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("gguf"));
    if !is_gguf {
        return Err("本地模型文件必须是 .gguf 格式".to_string());
    }
    Ok(canonical.to_string_lossy().to_string())
}

fn start_local_gemma() -> (bool, String) {
    let runtime = local_chat_runtime_config();
    if local_gemma_ready(runtime.port) {
        return (true, format!("{LOCAL_MODEL_BRAND} 已在运行"));
    }
    if local_port_listening(runtime.port) {
        return (
            false,
            format!(
                "端口 {} 已被非健康服务占用；请关闭占用进程后重试",
                runtime.port
            ),
        );
    }
    let Some(exe) = find_llama_server_exe() else {
        return (
            false,
            "未找到 llama-server.exe（~/llama.cpp/*cuda-12.4*/）".to_string(),
        );
    };
    let Some(model) = configured_local_chat_model_path() else {
        return (false, "尚未配置本地文本推理的 GGUF 模型文件".to_string());
    };
    if !model.is_file() {
        return (false, "配置的本地模型文件不存在或不可访问".to_string());
    }
    let mut cmd = std::process::Command::new(exe);
    cmd.arg("-m").arg(&model);
    if let Some(mmproj) = configured_local_chat_mmproj_path().filter(|path| path.is_file()) {
        cmd.arg("--mmproj").arg(&mmproj);
    }
    cmd.args(local_gemma_runtime_args(runtime));
    let log_path = local_model_log_path();
    let pid = match spawn_detached_logged(cmd, &log_path) {
        Ok(pid) => pid,
        Err(error) => return (false, error),
    };
    let deadline = Instant::now() + Duration::from_millis(runtime.startup_timeout_ms);
    while Instant::now() < deadline {
        if local_gemma_ready(runtime.port) {
            return (
                true,
                format!(
                    "{LOCAL_MODEL_BRAND} ready（PID {pid}，context={}，max_output={}，reasoning_budget={}，slots={}，日志={}）",
                    runtime.context_window,
                    runtime.max_output_tokens,
                    runtime.reasoning_budget,
                    runtime.parallel_slots,
                    log_path.display()
                ),
            );
        }
        std::thread::sleep(Duration::from_millis(500));
    }
    (
        false,
        format!(
            "{LOCAL_MODEL_BRAND} 启动超时（PID {pid}，请检查日志 {}）",
            log_path.display()
        ),
    )
}

fn start_local_uidetr() -> (bool, String) {
    if local_port_listening(LOCAL_UIDETR_PORT) {
        return (true, "UI-DETR 已在运行".to_string());
    }
    let Some(script) = repo_resource_path("modules/vision/resources/uidetr/uidetr_service.py")
    else {
        return (false, "未找到 uidetr_service.py".to_string());
    };
    let model_path = active_vision_router_config()
        .detection
        .model_path
        .unwrap_or_default();
    let mut cmd = std::process::Command::new("python");
    cmd.arg(&script).arg("--model").arg(&model_path).args([
        "--host",
        "127.0.0.1",
        "--port",
        "7860",
    ]);
    if spawn_detached(cmd) {
        (true, "UI-DETR 启动中".to_string())
    } else {
        (false, "UI-DETR 启动失败（需 python 环境）".to_string())
    }
}

fn start_local_showui() -> (bool, String) {
    if local_port_listening(LOCAL_SHOWUI_PORT) {
        return (true, "ShowUI 已在运行".to_string());
    }
    let Some(script) = repo_resource_path("modules/vision/resources/local-vlm/start-local-vlm.ps1")
    else {
        return (false, "未找到 start-local-vlm.ps1".to_string());
    };
    let mut cmd = std::process::Command::new("powershell");
    cmd.args(["-NoProfile", "-ExecutionPolicy", "Bypass", "-File"])
        .arg(&script)
        .args(["-Profile", "showui"]);
    if spawn_detached(cmd) {
        (true, "ShowUI 启动中（首次加载较久）".to_string())
    } else {
        (false, "ShowUI 启动失败".to_string())
    }
}

#[derive(Debug, Clone, Serialize)]
struct LocalServiceStatus {
    name: String,
    role: String,
    port: u16,
    running: bool,
}

#[derive(Debug, Clone, Serialize)]
struct LocalModelsStatusResponse {
    active_mode: String,
    services: Vec<LocalServiceStatus>,
    model_path: Option<String>,
    model_path_exists: bool,
    message: String,
}

fn local_models_status_response(message: impl Into<String>) -> LocalModelsStatusResponse {
    let gemma_port = local_chat_runtime_config().port;
    let gemma = local_gemma_ready(gemma_port);
    let uidetr = local_port_listening(LOCAL_UIDETR_PORT);
    let showui = local_port_listening(LOCAL_SHOWUI_PORT);
    let embed = local_port_listening(LOCAL_EMBED_PORT);
    let model_path = configured_local_chat_model_path();
    let model_path_exists = model_path.as_ref().is_some_and(|path| path.is_file());
    LocalModelsStatusResponse {
        active_mode: local_active_mode(gemma, uidetr || showui).to_string(),
        services: vec![
            LocalServiceStatus {
                name: LOCAL_MODEL_BRAND.to_string(),
                role: "chat".to_string(),
                port: gemma_port,
                running: gemma,
            },
            LocalServiceStatus {
                name: "UI-DETR".to_string(),
                role: "vision".to_string(),
                port: LOCAL_UIDETR_PORT,
                running: uidetr,
            },
            LocalServiceStatus {
                name: "ShowUI".to_string(),
                role: "vision".to_string(),
                port: LOCAL_SHOWUI_PORT,
                running: showui,
            },
            LocalServiceStatus {
                name: "bge-m3 (embeddings)".to_string(),
                role: "memory".to_string(),
                port: LOCAL_EMBED_PORT,
                running: embed,
            },
        ],
        model_path: model_path.map(|path| path.to_string_lossy().to_string()),
        model_path_exists,
        message: message.into(),
    }
}

/// 本地模型服务开关：chat / vision / off。停用按端口杀进程释放显存，再启用目标组。
fn switch_local_models(mode: &str) -> LocalModelsStatusResponse {
    let message = match mode {
        "chat" => {
            kill_listeners_on_port(LOCAL_UIDETR_PORT);
            kill_listeners_on_port(LOCAL_SHOWUI_PORT);
            let (_, gemma) = start_local_gemma();
            format!("切到 chat：已停 UI-DETR/ShowUI 释放显存。{gemma}")
        }
        "vision" => {
            kill_listeners_on_port(local_chat_runtime_config().port);
            let (_, uidetr) = start_local_uidetr();
            let (_, showui) = start_local_showui();
            format!("切到 vision：已停本地文本推理释放显存。UI-DETR：{uidetr}；ShowUI：{showui}")
        }
        "off" => {
            kill_listeners_on_port(local_chat_runtime_config().port);
            kill_listeners_on_port(LOCAL_UIDETR_PORT);
            kill_listeners_on_port(LOCAL_SHOWUI_PORT);
            "已停用全部本地模型服务（bge-m3 嵌入不受影响）".to_string()
        }
        other => {
            return local_models_status_response(format!(
                "未知模式: {other}（支持 chat / vision / off）"
            ));
        }
    };
    local_models_status_response(message)
}

fn local_model_exit_shutdown_ports() -> Vec<u16> {
    let mut ports = vec![
        local_chat_runtime_config().port,
        LOCAL_UIDETR_PORT,
        LOCAL_SHOWUI_PORT,
        LOCAL_EMBED_PORT,
    ];
    ports.sort_unstable();
    ports.dedup();
    ports
}

fn shutdown_local_model_services_on_exit() {
    let ports = local_model_exit_shutdown_ports();
    info!(
        "web-console 退出清理：停止本地模型服务端口 {}",
        ports
            .iter()
            .map(u16::to_string)
            .collect::<Vec<_>>()
            .join(", ")
    );
    for port in ports {
        kill_listeners_on_port(port);
    }
}

