fn validate_chat_room_permission_update(
    payload: &ChatRoomPermissionUpdateRequest,
) -> ApiResult<String> {
    let profile = payload.permission_profile.trim();
    match profile {
        ROOM_PERMISSION_WORKSPACE_WRITE => Ok(profile.to_string()),
        ROOM_PERMISSION_FULL_ACCESS if !payload.risk_acknowledged => Err(api_error(
            StatusCode::BAD_REQUEST,
            "full access requires risk_acknowledged=true",
        )),
        ROOM_PERMISSION_FULL_ACCESS if !payload.confirmed_twice => Err(api_error(
            StatusCode::BAD_REQUEST,
            "full access requires confirmed_twice=true",
        )),
        ROOM_PERMISSION_FULL_ACCESS => Ok(profile.to_string()),
        _ => Err(api_error(
            StatusCode::BAD_REQUEST,
            "permission_profile must be workspace-write or full-access",
        )),
    }
}

async fn api_tools_pending_for_scope(query: PendingApprovalsQuery) -> Json<PendingApprovalsResponse> {
    let pending = pending_approvals()
        .lock()
        .map(|map| {
            let now = Instant::now();
            map.values()
                .filter(|record| {
                    now.duration_since(record.created_at) < PENDING_APPROVAL_TTL
                        && pending_approval_matches_filter(
                            record,
                            query.session_id.as_deref(),
                            query.chat_room_id.as_deref(),
                        )
                })
                .cloned()
                .collect()
        })
        .unwrap_or_default();
    Json(PendingApprovalsResponse { pending })
}

async fn api_tools_pending_query(
    Query(query): Query<PendingApprovalsQuery>,
) -> Json<PendingApprovalsResponse> {
    api_tools_pending_for_scope(query).await
}

