#[derive(Debug, Clone, Serialize, Deserialize)]
struct ConfigScheduledTask {
    id: String,
    target_session_id: String,
    content: String,
    run_at_ms: u64,
    #[serde(default)]
    interval_ms: Option<u64>,
    #[serde(default)]
    permissions: Vec<String>,
    #[serde(default = "default_scheduled_task_status")]
    status: String,
    #[serde(default)]
    created_at_ms: u64,
    #[serde(default)]
    last_run_at_ms: Option<u64>,
    #[serde(default)]
    last_error: Option<String>,
    /// 计划类型：once（单次）/ interval（固定毫秒间隔）/ daily（每天 HH:MM）/ weekly（每周指定星期 HH:MM）。
    #[serde(default = "default_schedule_kind")]
    schedule_kind: String,
    /// 挂钟小时（0-23），daily/weekly 用。
    #[serde(default)]
    wall_hour: u8,
    /// 挂钟分钟（0-59），daily/weekly 用。
    #[serde(default)]
    wall_minute: u8,
    /// 触发星期（0=周日..6=周六），weekly 用；空表示每天。
    #[serde(default)]
    weekdays: Vec<u8>,
    /// 本地时区相对 UTC 的分钟偏移（东八区=+480），由前端 `-getTimezoneOffset()` 提供。
    #[serde(default)]
    tz_offset_minutes: i32,
    /// 任务类型：poll（轮询型，默认；完成后内容不变按计划重排）/ goal（Goal 推进型；
    /// 每次到点推进绑定 goal 一个阶段，content 更新为进度摘要，整体目标完成后停止触发）。
    #[serde(default = "default_scheduled_task_kind")]
    task_kind: String,
    /// Goal 推进型绑定的目标 id（task_kind="goal" 时必填）。
    #[serde(default)]
    goal_id: Option<String>,
}

fn default_scheduled_task_status() -> String {
    "scheduled".to_string()
}

