/// REQ-TOOL-010：工具权限与 Protected 路径配置。
///
/// - `protected_paths.rules` 为空时，`effective_protected_rules()` 回退。
///   `runtime::default_protected_rules()`；非空时 **完全替换** 默认规则
///   （避"merge "id 冲突和用户以为关了某条实际上还生效的困惑）。
/// - `protected_paths.append_defaults = true` 才在用户列表末尾追加默认规则。
///   保证安全出口。默"false 以显式意图。
/// - `protected_paths.extra_rules` "无论如何都追"的补充规则，等价于用。
///   在默认基础上加条目，比 `append_defaults` 更精确。
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
struct ConfigTool {
    #[serde(default)]
    protected_paths: ConfigToolProtectedPaths,
    #[serde(default)]
    execution: ConfigToolExecution,
    #[serde(default)]
    dev_open_permissions: bool,
    #[serde(default)]
    permission_profile: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ConfigToolExecution {
    #[serde(default = "default_tool_timeout_ms")]
    default_timeout_ms: u64,
    #[serde(default = "default_tool_max_concurrency")]
    max_concurrency: usize,
    #[serde(default = "default_tool_max_feedback_rounds")]
    max_feedback_rounds: usize,
    #[serde(default = "default_true")]
    command_gate_enabled: bool,
}

impl Default for ConfigToolExecution {
    fn default() -> Self {
        Self {
            default_timeout_ms: default_tool_timeout_ms(),
            max_concurrency: default_tool_max_concurrency(),
            max_feedback_rounds: default_tool_max_feedback_rounds(),
            command_gate_enabled: default_true(),
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct ToolExecutionPolicy {
    default_timeout_ms: u64,
    max_concurrency: usize,
    max_feedback_rounds: usize,
}

fn default_tool_timeout_ms() -> u64 {
    30_000
}

fn default_tool_max_concurrency() -> usize {
    4
}

fn default_tool_max_feedback_rounds() -> usize {
    40
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
struct ConfigToolProtectedPaths {
    /// 完整替换默认规则；未设置或空数组"fallback。
    #[serde(default)]
    rules: Vec<ConfigProtectedRule>,
    /// "`rules` 末尾追加默认规则。未设置 = false。
    #[serde(default)]
    append_defaults: bool,
    /// 始终追加到最终规则列表末尾。
    #[serde(default)]
    extra_rules: Vec<ConfigProtectedRule>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ConfigProtectedRule {
    id: String,
    glob: String,
    #[serde(default = "default_protected_access")]
    access: String,
}

fn default_protected_access() -> String {
    "any".to_string()
}

impl From<ConfigProtectedRule> for runtime::ProtectedRule {
    fn from(value: ConfigProtectedRule) -> Self {
        Self {
            id: value.id,
            glob: value.glob,
            access: value.access,
        }
    }
}

/// REQ-TOOL-010：解析当前配置下生效"Protected 路径规则列表。
///
/// 优先级：
///   1. `rules` 非空 "视为"用户接管"，使"rules" 可"default + extra。
///   2. `rules` ""使用默认规则" extra。
fn effective_protected_rules() -> Vec<runtime::ProtectedRule> {
    let config = match workspace_config().lock() {
        Ok(guard) => guard.clone(),
        Err(_) => WorkspaceConfig::default(),
    };
    let cfg = config.tool.protected_paths;
    let mut out: Vec<runtime::ProtectedRule> = if cfg.rules.is_empty() {
        default_protected_rules()
    } else {
        cfg.rules
            .into_iter()
            .map(runtime::ProtectedRule::from)
            .collect()
    };
    if cfg.append_defaults {
        for rule in default_protected_rules() {
            if !out.iter().any(|existing| existing.id == rule.id) {
                out.push(rule);
            }
        }
    }
    for rule in cfg.extra_rules {
        let converted = runtime::ProtectedRule::from(rule);
        if !out.iter().any(|existing| existing.id == converted.id) {
            out.push(converted);
        }
    }
    out
}

fn tool_execution_policy() -> ToolExecutionPolicy {
    let execution = workspace_config()
        .lock()
        .map(|guard| guard.tool.execution.clone())
        .unwrap_or_default();
    ToolExecutionPolicy {
        default_timeout_ms: execution.default_timeout_ms.clamp(100, 600_000),
        max_concurrency: execution.max_concurrency.clamp(1, 16),
        // 对齐 opencode 等"长 agentic 循环跑到完成"：上限由 16 提到 64，给读→改→编译多步留足轮数。
        // 运行期仍有 L1 重复空转纠偏 + 每次 LLM 调用 600s 超时(#6) 兜底，防失控。
        max_feedback_rounds: execution.max_feedback_rounds.clamp(1, 64),
    }
}

/// WebSearch 自己探测/降级多个后端，内部预算已含逐后端尝试；这里在预算之外再留一点
/// 收尾余量（构造失败文案、进程回收）。
const WEB_SEARCH_TIMEOUT_SLACK_MS: u64 = 5_000;

fn tool_timeout_ms_for(tool_name: &str, input: &JsonValue) -> u64 {
    // timeout_ms 字段语义为毫秒；timeout 字段语义为秒（PowerShell/bash schema 已标 SECONDS），需 ×1000。
    // 否则模型传 timeout:10（秒）会被外层 tokio 超时当 10ms，几十毫秒内杀掉命令 → runtime-timeout。
    let requested = if let Some(ms) = input.get("timeout_ms").and_then(JsonValue::as_u64) {
        ms
    } else if let Some(secs) = input.get("timeout").and_then(JsonValue::as_u64) {
        secs.saturating_mul(1000)
    } else if is_web_search_tool(tool_name) {
        // 固定 30s 默认值小于"多后端探测"的真实耗时：工具还没跑出可读失败原因就被强杀，
        // 模型只拿到 runtime-timeout、看不到哪个后端不可达。改为按工具声明的预算发时间。
        // 取 max 而不是直接覆盖：用户把 default_timeout_ms 调大时不应被这里改小。
        // 这里只读目标 workspace 的配置、不改全局 config root：设 root 是执行器（
        // execute_runtime_tool_blocking）的职责，在这里改会覆盖调用方指定的 workspace。
        let declared = tools::web_search_total_budget_ms_at(&active_workspace_path())
            .saturating_add(WEB_SEARCH_TIMEOUT_SLACK_MS);
        declared.max(tool_execution_policy().default_timeout_ms)
    } else {
        tool_execution_policy().default_timeout_ms
    };
    requested.clamp(1, 600_000)
}

fn is_web_search_tool(tool_name: &str) -> bool {
    tool_name.replace('-', "_").eq_ignore_ascii_case("websearch")
}

fn unwrap_raw_tool_input(input: &JsonValue) -> JsonValue {
    unwrap_raw_tool_input_depth(input, 0)
}

fn unwrap_raw_tool_input_depth(input: &JsonValue, depth: usize) -> JsonValue {
    if depth >= 4 {
        return input.clone();
    }
    let Some(raw) = input
        .get("raw")
        .and_then(JsonValue::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return input.clone();
    };
    let Ok(mut parsed) = serde_json::from_str::<JsonValue>(raw) else {
        return input.clone();
    };
    let Some(parsed_object) = parsed.as_object_mut() else {
        return input.clone();
    };
    if parsed_object.contains_key("raw") {
        parsed = unwrap_raw_tool_input_depth(&parsed, depth + 1);
    }
    let Some(parsed_object) = parsed.as_object_mut() else {
        return input.clone();
    };
    if let Some(input_object) = input.as_object() {
        for (key, value) in input_object {
            if key != "raw" && !parsed_object.contains_key(key) {
                parsed_object.insert(key.clone(), value.clone());
            }
        }
    }
    parsed
}

fn runtime_tool_input_with_defaults(tool_name: &str, input: &JsonValue) -> JsonValue {
    let mut normalized = unwrap_raw_tool_input(input);
    let Some(object) = normalized.as_object_mut() else {
        return normalized;
    };
    let default_timeout = tool_execution_policy().default_timeout_ms;
    let normalized_tool = tool_name.replace('-', "_");
    match normalized_tool.as_str() {
        "read_file" | "write_file" | "edit_file" => {
            if let Some(path_value) = object.get_mut("path") {
                if let Some(path_text) =
                    path_value.as_str().map(str::trim).filter(|v| !v.is_empty())
                {
                    let path = PathBuf::from(path_text);
                    let resolved = if path.is_absolute() {
                        path
                    } else {
                        active_workspace_path().join(path)
                    };
                    *path_value = json!(resolved.to_string_lossy());
                }
            }
        }
        "bash" | "PowerShell" => {
            object
                .entry("cwd".to_string())
                .or_insert_with(|| json!(active_workspace_path().to_string_lossy()));
            object
                .entry("timeout".to_string())
                .or_insert_with(|| json!(default_timeout));
        }
        "REPL" => {
            object
                .entry("timeout_ms".to_string())
                .or_insert_with(|| json!(default_timeout));
        }
        _ => {}
    }
    normalized
}

fn config_file_path_for(workspace: &Path) -> PathBuf {
    workspace.join(CONFIG_FILE_NAME)
}

fn load_workspace_config_at(workspace: &Path) -> WorkspaceConfig {
    let path = config_file_path_for(workspace);
    if let Ok(content) = std::fs::read_to_string(&path) {
        diag!(
            "[CONFIG] load: path={}, size={}",
            path.display(),
            content.len()
        );
        match toml::from_str::<WorkspaceConfig>(&content) {
            Ok(config) => {
                diag!(
                    "[CONFIG] load: parse OK, enable_real_llm={}",
                    config.model.enable_real_llm
                );
                return config;
            }
            Err(e) => {
                warn!("coolzhu.toml 解析失败，使用默认配置: {e}");
                diag!("[CONFIG] load: PARSE FAILED: {e}");
                return WorkspaceConfig::default();
            }
        }
    } else {
        diag!(
            "[CONFIG] load: file not found at {}, creating default",
            path.display()
        );
    }
    let config = WorkspaceConfig::default();
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    if let Ok(content) = toml::to_string_pretty(&config) {
        let _ = std::fs::write(&path, content);
        diag!("[CONFIG] load: wrote capability-enabled defaults; credentials remain unset");
    }
    config
}

fn save_workspace_config_at(workspace: &Path, config: &WorkspaceConfig) {
    let path = config_file_path_for(workspace);
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    if let Ok(content) = toml::to_string_pretty(config) {
        let content = render_config_with_preserved_sections(&path, &content);
        let _ = std::fs::write(&path, content);
    }
}

/// `coolzhu.toml` 不只属于主控台：tool-registry 也从同一个文件读 `[web_search]`。
/// `WorkspaceConfig` 不认识这些段，整体重写会把它们静默抹掉——用户手写的搜索后端会在
/// 任意一次 dashboard 写入（加允许目录、改任务计划等）之后消失。
/// 这里把不认识的顶层段原样带回，保证配置是"叠加"而不是"覆盖"。
fn render_config_with_preserved_sections(path: &Path, serialized: &str) -> String {
    let Ok(existing) = std::fs::read_to_string(path) else {
        return serialized.to_string();
    };
    let Ok(existing_value) = toml::from_str::<toml::Value>(&existing) else {
        return serialized.to_string();
    };
    let Ok(mut merged) = toml::from_str::<toml::Value>(serialized) else {
        return serialized.to_string();
    };
    let (Some(existing_table), Some(merged_table)) =
        (existing_value.as_table(), merged.as_table_mut())
    else {
        return serialized.to_string();
    };
    // WorkspaceConfig 的字段一律参与序列化（没有 skip_serializing_if），
    // 所以"新版里没有的顶层段"就是本进程不认识的段。
    let mut preserved = Vec::new();
    for (key, value) in existing_table {
        if !merged_table.contains_key(key) {
            merged_table.insert(key.clone(), value.clone());
            preserved.push(key.clone());
        }
    }
    if preserved.is_empty() {
        return serialized.to_string();
    }
    diag!(
        "[CONFIG] save: preserved unknown section(s) {:?} from existing coolzhu.toml",
        preserved
    );
    toml::to_string_pretty(&merged).unwrap_or_else(|_| serialized.to_string())
}

fn mutate_workspace_config(
    mutate: impl FnOnce(&mut WorkspaceConfig) -> ApiResult<()>,
) -> ApiResult<WorkspaceConfig> {
    let workspace = active_workspace_path();
    let mut guard = workspace_config().lock().map_err(|_| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "workspace config lock failed",
        )
    })?;
    mutate(&mut guard)?;
    let config = guard.clone();
    save_workspace_config_at(&workspace, &config);
    Ok(config)
}

fn workspace_config() -> &'static Mutex<WorkspaceConfig> {
    static CONFIG: OnceLock<Mutex<WorkspaceConfig>> = OnceLock::new();
    CONFIG.get_or_init(|| {
        let workspace = default_workspace_path();
        diag!("[CONFIG] init: workspace={}", workspace.display());
        let config = load_workspace_config_at(&workspace);
        diag!(
            "[CONFIG] init: enable_real_llm={}",
            config.model.enable_real_llm
        );
        Mutex::new(config)
    })
}

fn reload_workspace_config() {
    let workspace = active_workspace_path();
    diag!("[CONFIG] reload: workspace={}", workspace.display());
    let config = load_workspace_config_at(&workspace);
    if let Ok(mut guard) = workspace_config().lock() {
        *guard = config;
    }
}

fn read_config<T>(f: impl Fn(&WorkspaceConfig) -> T) -> T {
    match workspace_config().lock() {
        Ok(guard) => f(&guard),
        Err(e) => {
            diag!("[CONFIG] mutex poisoned: {e}");
            f(&WorkspaceConfig::default())
        }
    }
}

