fn resolve_project_existing_path(root: &Path, input: Option<&str>) -> ApiResult<PathBuf> {
    let base = root.canonicalize().map_err(|_| {
        api_error(
            StatusCode::BAD_REQUEST,
            "current workspace is not accessible",
        )
    })?;
    let raw = input.map(str::trim).filter(|value| !value.is_empty());
    if let Some(path) = raw {
        validate_project_query_path(path)?;
    }
    let candidate = raw
        .map(PathBuf::from)
        .map(|path| {
            if path.is_absolute() {
                path
            } else {
                base.join(path)
            }
        })
        .unwrap_or_else(|| base.clone());
    let canonical = candidate
        .canonicalize()
        .map_err(|_| api_error(StatusCode::BAD_REQUEST, "project path does not exist"))?;
    if !canonical.starts_with(&base) {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "project path escapes the current workspace",
        ));
    }
    Ok(canonical)
}

fn resolve_project_mutation_existing_path(root: &Path, input: &str) -> ApiResult<PathBuf> {
    let base = root.canonicalize().map_err(|_| {
        api_error(
            StatusCode::BAD_REQUEST,
            "current workspace is not accessible",
        )
    })?;
    let trimmed = input.trim();
    validate_project_query_path(trimmed)?;
    let candidate = if trimmed.is_empty() {
        base.clone()
    } else {
        base.join(trimmed)
    };
    reject_project_reparse_components(&base, &candidate)?;
    let canonical = candidate
        .canonicalize()
        .map_err(|_| api_error(StatusCode::BAD_REQUEST, "project path does not exist"))?;
    if !canonical.starts_with(&base) {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "project path escapes the current workspace",
        ));
    }
    Ok(canonical)
}

fn reject_project_reparse_components(base: &Path, candidate: &Path) -> ApiResult<()> {
    let relative = candidate.strip_prefix(base).map_err(|_| {
        api_error(
            StatusCode::FORBIDDEN,
            "project path escapes the current workspace",
        )
    })?;
    let mut current = base.to_path_buf();
    for component in relative.components() {
        current.push(component.as_os_str());
        let Ok(metadata) = std::fs::symlink_metadata(&current) else {
            continue;
        };
        if project_metadata_is_reparse_point(&metadata) {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "IDE mutation refuses symlink or reparse-point paths",
            ));
        }
    }
    Ok(())
}

#[cfg(windows)]
fn project_metadata_is_reparse_point(metadata: &std::fs::Metadata) -> bool {
    use std::os::windows::fs::MetadataExt;
    const FILE_ATTRIBUTE_REPARSE_POINT: u32 = 0x0400;
    metadata.file_attributes() & FILE_ATTRIBUTE_REPARSE_POINT != 0
}

#[cfg(not(windows))]
fn project_metadata_is_reparse_point(metadata: &std::fs::Metadata) -> bool {
    metadata.file_type().is_symlink()
}

fn validate_project_query_path(path: &str) -> ApiResult<()> {
    if Path::new(path).components().any(|component| {
        matches!(
            component,
            Component::ParentDir | Component::Prefix(_) | Component::RootDir
        )
    }) {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "project path escapes the current workspace",
        ));
    }
    Ok(())
}

fn project_relative_path_for_query(input: Option<&str>) -> ApiResult<Option<String>> {
    let Some(path) = input.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    validate_project_query_path(path)?;
    Ok(Some(path.replace('\\', "/")))
}

fn project_tree_node(
    root: &Path,
    path: &Path,
    depth: usize,
    remaining: &mut usize,
    warnings: &mut Vec<String>,
) -> ApiResult<ProjectTreeNode> {
    let metadata = std::fs::symlink_metadata(path)
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error.to_string()))?;
    if project_metadata_is_reparse_point(&metadata) {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "project tree refuses symlink or reparse-point entries",
        ));
    }
    let kind = if metadata.is_dir() { "dir" } else { "file" }.to_string();
    let mut node = ProjectTreeNode {
        name: path
            .file_name()
            .map(|name| name.to_string_lossy().to_string())
            .unwrap_or_else(|| path.to_string_lossy().to_string()),
        path: display_path(path),
        relative_path: relative_project_path(root, path),
        kind,
        file_size: metadata.is_file().then_some(metadata.len()),
        modified: metadata.modified().ok().and_then(system_time_millis),
        children: Vec::new(),
        omitted_count: 0,
    };

    if !metadata.is_dir() || depth == 0 {
        return Ok(node);
    }

    let mut entries = Vec::new();
    for entry in std::fs::read_dir(path)
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error.to_string()))?
    {
        match entry {
            Ok(entry) => entries.push(entry),
            Err(error) => {
                node.omitted_count += 1;
                warnings.push(format!(
                    "{}: directory entry omitted: {error}",
                    display_path(path)
                ));
            }
        }
    }
    entries.sort_by(|left, right| {
        let left_dir = left.file_type().map(|ty| ty.is_dir()).unwrap_or(false);
        let right_dir = right.file_type().map(|ty| ty.is_dir()).unwrap_or(false);
        right_dir
            .cmp(&left_dir)
            .then_with(|| left.file_name().cmp(&right.file_name()))
    });

    for entry in entries {
        if *remaining == 0 {
            node.omitted_count += 1;
            continue;
        }
        project_tree_append_child(
            root,
            &entry.path(),
            depth - 1,
            remaining,
            &mut node,
            warnings,
        );
    }
    Ok(node)
}

fn project_tree_append_child(
    root: &Path,
    child_path: &Path,
    depth: usize,
    remaining: &mut usize,
    node: &mut ProjectTreeNode,
    warnings: &mut Vec<String>,
) {
    match project_tree_node(root, child_path, depth, remaining, warnings) {
        Ok(child) => {
            *remaining = (*remaining).saturating_sub(1);
            node.children.push(child);
        }
        Err((_, Json(error))) => {
            node.omitted_count += 1;
            warnings.push(format!(
                "{}: omitted: {}",
                display_path(child_path),
                error.error
            ));
        }
    }
}

fn relative_project_path(root: &Path, path: &Path) -> String {
    path.strip_prefix(root)
        .unwrap_or(path)
        .to_string_lossy()
        .replace('\\', "/")
}

fn project_file_meta(root: &Path, path: &Path) -> ApiResult<ProjectFileMetaResponse> {
    let metadata = std::fs::metadata(path)
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error.to_string()))?;
    if !metadata.is_file() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "project path must be a file",
        ));
    }
    let bytes = std::fs::read(path)
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error.to_string()))?;
    let binary = is_binary_bytes(&bytes);
    let previewable = !binary && metadata.len() <= MAX_PROJECT_FILE_PREVIEW_BYTES;
    let editable = previewable
        && bytes.len() <= MAX_PROJECT_FILE_EDIT_BYTES
        && !metadata.permissions().readonly();
    let has_utf8_bom = bytes.starts_with(&[0xEF, 0xBB, 0xBF]);
    let text_bytes = if has_utf8_bom { &bytes[3..] } else { &bytes };
    let line_ending = project_line_ending(text_bytes);
    Ok(ProjectFileMetaResponse {
        name: path
            .file_name()
            .map(|name| name.to_string_lossy().to_string())
            .unwrap_or_default(),
        path: display_path(path),
        relative_path: relative_project_path(root, path),
        kind: "file".to_string(),
        file_size: metadata.len(),
        modified: metadata.modified().ok().and_then(system_time_millis),
        binary,
        previewable,
        editable,
        max_preview_bytes: MAX_PROJECT_FILE_PREVIEW_BYTES,
        max_edit_bytes: MAX_PROJECT_FILE_EDIT_BYTES,
        revision: project_file_revision(&bytes),
        encoding: if has_utf8_bom { "utf-8-bom" } else { "utf-8" }.to_string(),
        line_ending,
        has_utf8_bom,
    })
}

fn is_binary_bytes(bytes: &[u8]) -> bool {
    let text_bytes = bytes.strip_prefix(&[0xEF, 0xBB, 0xBF]).unwrap_or(bytes);
    bytes.contains(&0) || std::str::from_utf8(text_bytes).is_err()
}

fn project_line_ending(bytes: &[u8]) -> String {
    let crlf = bytes.windows(2).filter(|pair| *pair == b"\r\n").count();
    let lf = bytes.iter().filter(|byte| **byte == b'\n').count();
    if crlf > 0 && crlf.saturating_mul(2) >= lf.max(1) {
        "crlf".to_string()
    } else {
        "lf".to_string()
    }
}

fn project_file_revision(bytes: &[u8]) -> String {
    format!("{:016x}-{}", hash_bytes(bytes), bytes.len())
}

fn normalize_project_text_line_endings(content: &str, line_ending: &str) -> Vec<u8> {
    let normalized = content.replace("\r\n", "\n").replace('\r', "\n");
    if line_ending.eq_ignore_ascii_case("crlf") {
        normalized.replace('\n', "\r\n").into_bytes()
    } else {
        normalized.into_bytes()
    }
}

fn validate_project_entry_name(name: &str) -> ApiResult<()> {
    let trimmed = name.trim();
    let mut components = Path::new(trimmed).components();
    if trimmed.is_empty()
        || !matches!(components.next(), Some(Component::Normal(_)))
        || components.next().is_some()
        || trimmed.chars().all(|ch| ch == '.')
        || trimmed.ends_with('.')
        || trimmed.ends_with(' ')
        || trimmed
            .chars()
            .any(|ch| ch == '\0' || "<>:\"/\\|?*".contains(ch))
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "invalid project entry name",
        ));
    }
    let stem = trimmed
        .split('.')
        .next()
        .unwrap_or_default()
        .to_ascii_uppercase();
    if matches!(
        stem.as_str(),
        "CON"
            | "PRN"
            | "AUX"
            | "NUL"
            | "COM1"
            | "COM2"
            | "COM3"
            | "COM4"
            | "COM5"
            | "COM6"
            | "COM7"
            | "COM8"
            | "COM9"
            | "LPT1"
            | "LPT2"
            | "LPT3"
            | "LPT4"
            | "LPT5"
            | "LPT6"
            | "LPT7"
            | "LPT8"
            | "LPT9"
    ) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "reserved Windows entry name",
        ));
    }
    Ok(())
}

fn atomic_replace_project_file(path: &Path, bytes: &[u8]) -> ApiResult<()> {
    let parent = path
        .parent()
        .ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "project file has no parent"))?;
    let permissions = std::fs::metadata(path).map_err(io_api_error)?.permissions();
    let mut temp_path = None;
    let mut temp_file = None;
    for attempt in 0..32_u32 {
        let candidate = parent.join(format!(
            ".coolzhu-ide-{}-{}-{attempt}.tmp",
            std::process::id(),
            unix_timestamp_millis()
        ));
        match std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&candidate)
        {
            Ok(file) => {
                temp_path = Some(candidate);
                temp_file = Some(file);
                break;
            }
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(error) => return Err(io_api_error(error)),
        }
    }
    let temp_path = temp_path.ok_or_else(|| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "cannot allocate atomic save temp file",
        )
    })?;
    let mut file = temp_file.expect("temp file accompanies temp path");
    let result = (|| -> std::io::Result<()> {
        std::io::Write::write_all(&mut file, bytes)?;
        file.sync_all()?;
        std::fs::set_permissions(&temp_path, permissions)?;
        drop(file);
        replace_project_file(&temp_path, path)
    })();
    if let Err(error) = result {
        let _ = std::fs::remove_file(&temp_path);
        return Err(io_api_error(error));
    }
    Ok(())
}

fn replace_project_file(source: &Path, destination: &Path) -> std::io::Result<()> {
    std::fs::rename(source, destination)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct WorkspaceScopePaths {
    session_db: PathBuf,
    legacy_session_json: PathBuf,
    attachment_dir: PathBuf,
    audit_log: PathBuf,
}

fn workspace_scope_paths_for(workspace: &Path, config: &WorkspaceConfig) -> WorkspaceScopePaths {
    let data_dir = workspace_data_dir_for(workspace, config);
    let session_db = config
        .session
        .db_path
        .as_deref()
        .and_then(|value| resolve_config_path(workspace, value))
        .unwrap_or_else(|| data_dir.join("web-sessions.sqlite3"));
    let legacy_session_json = config
        .session
        .json_path
        .as_deref()
        .and_then(|value| resolve_config_path(workspace, value))
        .unwrap_or_else(|| data_dir.join("web-sessions.json"));
    let attachment_dir = config
        .attachment
        .store_dir
        .as_deref()
        .and_then(|value| resolve_config_path(workspace, value))
        .unwrap_or_else(|| data_dir.join("attachments"));
    let audit_log = session_db
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| data_dir.clone())
        .join("tool-audit.jsonl");

    WorkspaceScopePaths {
        session_db,
        legacy_session_json,
        attachment_dir,
        audit_log,
    }
}

fn workspace_data_dir_for(workspace: &Path, config: &WorkspaceConfig) -> PathBuf {
    resolve_config_path(workspace, &config.paths.data_dir)
        .unwrap_or_else(|| workspace.join(DATA_DIR_NAME))
}

fn resolve_config_path(workspace: &Path, value: &str) -> Option<PathBuf> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return None;
    }
    let path = PathBuf::from(trimmed);
    Some(if path.is_absolute() {
        path
    } else {
        workspace.join(path)
    })
}

fn workspace_identity(workspace: &Path) -> String {
    let normalized = workspace
        .canonicalize()
        .unwrap_or_else(|_| workspace.to_path_buf())
        .to_string_lossy()
        .replace('\\', "/")
        .to_ascii_lowercase();
    format!("ws-{:016x}", hash_bytes(normalized.as_bytes()))
}

fn allowed_workspace_roots() -> Vec<PathBuf> {
    let mut roots = vec![default_workspace_path()];
    if let Some(home) = user_home_dir() {
        roots.push(home);
    }
    if let Ok(cwd) = env::current_dir() {
        roots.push(cwd);
    }
    roots.push(active_workspace_path());
    let config_roots: Vec<String> = read_config(|c| c.workspace.allowed_roots.clone());
    for root in &config_roots {
        let trimmed = root.trim();
        if !trimmed.is_empty() {
            roots.push(PathBuf::from(trimmed));
        }
    }
    let mut canonical = Vec::new();
    let mut seen = HashSet::new();
    for root in roots {
        if let Ok(path) = root.canonicalize() {
            let key = path.to_string_lossy().to_ascii_lowercase();
            if seen.insert(key) {
                canonical.push(path);
            }
        }
    }
    canonical
}

fn user_home_dir() -> Option<PathBuf> {
    env::var_os("USERPROFILE")
        .map(PathBuf::from)
        .or_else(|| env::var_os("HOME").map(PathBuf::from))
}

fn resolve_allowed_workspace(input: &str) -> ApiResult<PathBuf> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err(api_error(StatusCode::BAD_REQUEST, "workspace 路径不能为空"));
    }
    let requested = PathBuf::from(trimmed);
    let canonical = requested
        .canonicalize()
        .map_err(|_| api_error(StatusCode::BAD_REQUEST, "workspace 路径不存在或不可访问"))?;
    if !canonical.is_dir() {
        return Err(api_error(StatusCode::BAD_REQUEST, "workspace 必须是目"));
    }
    let roots = allowed_workspace_roots();
    if !workspace_is_within_allowed_roots(&canonical, &roots) {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "workspace 不在允许目录内；请在 coolzhu.toml 的 workspace.allowed_roots 中授权",
        ));
    }
    Ok(canonical)
}

fn workspace_is_within_allowed_roots(path: &Path, allowed_roots: &[PathBuf]) -> bool {
    allowed_roots.iter().any(|root| path.starts_with(root))
}

fn resolve_workspace_tool_path(input: Option<&str>) -> ApiResult<PathBuf> {
    let workspace = active_workspace_path();
    resolve_workspace_tool_path_in(&workspace, input)
}

fn resolve_workspace_tool_path_in(workspace: &Path, input: Option<&str>) -> ApiResult<PathBuf> {
    let base = workspace.canonicalize().map_err(|_| {
        api_error(
            StatusCode::BAD_REQUEST,
            "当前 workspace 不存在或不可访问，无法限定工具权限边",
        )
    })?;
    let candidate = input
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
        .map(|path| {
            if path.is_absolute() {
                path
            } else {
                base.join(path)
            }
        })
        .unwrap_or_else(|| base.clone());
    let canonical = candidate.canonicalize().map_err(|_| {
        api_error(
            StatusCode::BAD_REQUEST,
            "工具路径不存在或不可访问；请确认路径位于当前工程目录",
        )
    })?;
    if !canonical.starts_with(&base) {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "工具路径越界：默认文件读写权限仅限当前工程目",
        ));
    }
    Ok(canonical)
}

fn validate_workspace_relative_pattern(pattern: &str) -> ApiResult<()> {
    let path = Path::new(pattern);
    if path.is_absolute()
        || path.components().any(|component| {
            matches!(
                component,
                Component::ParentDir | Component::Prefix(_) | Component::RootDir
            )
        })
    {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "搜索 pattern 不允许使用绝对路径或 .. 越过当前工程目录",
        ));
    }
    Ok(())
}

fn workspace_is_writable(path: &Path) -> bool {
    let probe = path.join(format!(".coolzhu-write-probe-{}", unix_timestamp_millis()));
    match std::fs::OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&probe)
    {
        Ok(_) => {
            let _ = std::fs::remove_file(probe);
            true
        }
        Err(_) => false,
    }
}

#[derive(Debug)]
struct WorkspaceBoundaryDiagnostics {
    boundary: String,
    status: String,
    message: String,
}

fn workspace_boundary_diagnostics(
    workspace: &Path,
    allowed_roots: &[PathBuf],
) -> WorkspaceBoundaryDiagnostics {
    if workspace_is_within_allowed_roots(workspace, allowed_roots) {
        WorkspaceBoundaryDiagnostics {
            boundary: "allowed-root".to_string(),
            status: "ok".to_string(),
            message: "workspace 位于允许目录内；工具真实执行仍需单独授权".to_string(),
        }
    } else {
        WorkspaceBoundaryDiagnostics {
            boundary: "outside-allowed-root".to_string(),
            status: "warn".to_string(),
            message: "workspace 不在允许目录内，设置请求会被拒绝".to_string(),
        }
    }
}

async fn api_tools_catalog() -> ApiResult<Json<ToolsCatalogResponse>> {
    Ok(Json(build_tools_catalog()))
}

async fn api_tool_detail(
    AxumPath(tool_id): AxumPath<String>,
) -> ApiResult<Json<ToolDetailResponse>> {
    let catalog = build_tools_catalog();
    let Some(item) = catalog
        .categories
        .iter()
        .flat_map(|category| category.items.iter())
        .find(|item| item.item.id == tool_id)
        .cloned()
    else {
        return Err(api_error(StatusCode::NOT_FOUND, "工具不存"));
    };

    Ok(Json(ToolDetailResponse {
        item,
        generated_at: catalog.generated_at,
    }))
}

async fn api_tool_dry_run(
    AxumPath(tool_id): AxumPath<String>,
    payload: Option<Json<ToolDryRunRequest>>,
) -> ApiResult<Json<ToolRunResponse>> {
    let payload = payload.map(|Json(payload)| payload).unwrap_or_default();
    run_tool_dry_run(
        &tool_id,
        payload
            .input
            .unwrap_or_else(|| default_tool_input(&tool_id)),
    )
    .await
}

fn build_tools_catalog() -> ToolsCatalogResponse {
    let mut categories = vec![
        ToolCategoryDto {
            id: "core-tools".to_string(),
            name: "Core Tools".to_string(),
            description: "CLI、文件、检索、Agent 和运行时基础工具".to_string(),
            icon: "cli".to_string(),
            items: builtin_tool_catalog_items(),
        },
        ToolCategoryDto {
            id: "vision-tools".to_string(),
            name: "Vision Tools".to_string(),
            description: "内视觉截图、屏幕文字描述和目标定位工具".to_string(),
            icon: "inner-vision".to_string(),
            items: vision_tool_catalog_items(),
        },
        ToolCategoryDto {
            id: "computer-use".to_string(),
            name: "Computer Use".to_string(),
            description: "安全靶场、闭环规划和真实输入前的 dry-run 工具".to_string(),
            icon: "mouse-left".to_string(),
            items: computer_use_tool_catalog_items(),
        },
        ToolCategoryDto {
            id: "plugins".to_string(),
            name: "Plugins".to_string(),
            description: "本地插件 opencode 候选插件，只读展示清单与风险".to_string(),
            icon: "puzzle".to_string(),
            items: plugin_catalog_items(),
        },
        ToolCategoryDto {
            id: "skills".to_string(),
            name: "Skills".to_string(),
            description: "本地 SKILL opencode 候选 SKILL，先展示后迁移验证".to_string(),
            icon: "skill".to_string(),
            items: skill_catalog_items(),
        },
    ];

    for category in &mut categories {
        category.items.sort_by(|left, right| {
            left.item
                .status
                .cmp(&right.item.status)
                .then_with(|| left.item.name.cmp(&right.item.name))
        });
    }

    let summary = ToolCatalogSummary {
        categories: categories.len(),
        items: categories.iter().map(|category| category.items.len()).sum(),
        executable_now: categories
            .iter()
            .flat_map(|category| category.items.iter())
            .filter(|item| item.item.executable_now)
            .count(),
        migration_candidates: categories
            .iter()
            .flat_map(|category| category.items.iter())
            .filter(|item| item.item.source == "opencode-candidate")
            .count(),
    };

    ToolsCatalogResponse {
        generated_at: unix_timestamp_millis(),
        summary,
        categories,
        notes: vec![
            "catalog 已接入 runtime 工具链：权限由统一闸门或开发开放模式决定。".to_string(),
            "opencode 来源条目标记为 candidate，需要迁移验证后才能启用。".to_string(),
            "开发开放模式开启时，写入、shell、agent 等内置工具会直接标记为可执行".to_string(),
        ],
    }
}

fn builtin_tool_catalog_items() -> Vec<ToolCatalogItemDetail> {
    let dev_open = dev_open_tool_permissions_enabled();
    let permissions = GlobalToolRegistry::builtin()
        .permission_specs(None)
        .into_iter()
        .collect::<BTreeMap<_, _>>();

    mvp_tool_specs()
        .into_iter()
        .map(|spec| {
            let permission = permissions.get(spec.name).map_or_else(
                || spec.required_permission.as_str().to_string(),
                |mode| mode.as_str().to_string(),
            );
            let risk = risk_for_permission(&permission);
            let executable_now = dev_open || permission == "read-only";
            let summary = spec.description.to_string();
            tool_detail(
                ToolCatalogItemSummary {
                    id: format!("core.{}", spec.name),
                    name: spec.name.to_string(),
                    display_name: spec.name.to_string(),
                    category_id: "core-tools".to_string(),
                    category_name: "Core Tools".to_string(),
                    source: "builtin".to_string(),
                    source_label: "当前内置".to_string(),
                    status: if executable_now {
                        "available".to_string()
                    } else {
                        "dry-run-gated".to_string()
                    },
                    risk,
                    permissions: vec![permission],
                    executable_now,
                    summary,
                    action_hint: if executable_now {
                        "可通过 runtime 工具链执行".to_string()
                    } else {
                        "需要 dry-run/execute 权限闸门后再开放。".to_string()
                    },
                    tool_count: None,
                },
                Some(spec.input_schema),
                None,
                vec![
                    "来自 tool-registry 的内置工具定义".to_string(),
                    if executable_now {
                        "工具支持通过 runtime 链路执行".to_string()
                    } else {
                        "写入、shell、agent 等工具只展示 schema，真实执行暂未开放".to_string()
                    },
                ],
            )
        })
        .collect()
}

