fn input_string(input: &JsonValue, key: &str) -> Option<String> {
    input
        .get(key)
        .and_then(JsonValue::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn input_bool(input: &JsonValue, key: &str) -> Option<bool> {
    input.get(key).and_then(JsonValue::as_bool)
}

fn input_u64(input: &JsonValue, key: &str) -> Option<u64> {
    input.get(key).and_then(JsonValue::as_u64)
}

fn input_u32(input: &JsonValue, key: &str) -> Option<u32> {
    input_u64(input, key).and_then(|value| u32::try_from(value).ok())
}

fn input_i32(input: &JsonValue, key: &str) -> Option<i32> {
    input
        .get(key)
        .and_then(JsonValue::as_i64)
        .and_then(|value| i32::try_from(value).ok())
}

fn input_string_array(input: &JsonValue, key: &str) -> Option<Vec<String>> {
    let values = input.get(key)?.as_array()?;
    let items = values
        .iter()
        .filter_map(JsonValue::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .collect::<Vec<_>>();
    (!items.is_empty()).then_some(items)
}

fn input_usize(input: &JsonValue, key: &str) -> Option<usize> {
    input_u64(input, key).and_then(|value| usize::try_from(value).ok())
}

fn input_point(input: &JsonValue, key: &str) -> Option<PointDto> {
    let value = input.get(key)?;
    if let Some(object) = value.as_object() {
        let x = object
            .get("x")
            .and_then(JsonValue::as_i64)
            .and_then(|value| i32::try_from(value).ok())?;
        let y = object
            .get("y")
            .and_then(JsonValue::as_i64)
            .and_then(|value| i32::try_from(value).ok())?;
        return Some(PointDto { x, y });
    }

    let array = value.as_array()?;
    let x = array
        .first()
        .and_then(JsonValue::as_i64)
        .and_then(|value| i32::try_from(value).ok())?;
    let y = array
        .get(1)
        .and_then(JsonValue::as_i64)
        .and_then(|value| i32::try_from(value).ok())?;
    Some(PointDto { x, y })
}

fn input_bbox(input: &JsonValue, key: &str) -> Option<RoiDto> {
    let value = input.get(key)?;
    if let Some(object) = value.as_object() {
        let left = object
            .get("left")
            .or_else(|| object.get("x"))
            .and_then(JsonValue::as_i64)
            .and_then(|value| i32::try_from(value).ok())?;
        let top = object
            .get("top")
            .or_else(|| object.get("y"))
            .and_then(JsonValue::as_i64)
            .and_then(|value| i32::try_from(value).ok())?;
        let width = object
            .get("width")
            .and_then(JsonValue::as_i64)
            .and_then(|value| i32::try_from(value).ok())?;
        let height = object
            .get("height")
            .and_then(JsonValue::as_i64)
            .and_then(|value| i32::try_from(value).ok())?;
        return Some(RoiDto {
            left,
            top,
            width,
            height,
        });
    }

    let array = value.as_array()?;
    let left = array
        .first()
        .and_then(JsonValue::as_i64)
        .and_then(|value| i32::try_from(value).ok())?;
    let top = array
        .get(1)
        .and_then(JsonValue::as_i64)
        .and_then(|value| i32::try_from(value).ok())?;
    let right = array
        .get(2)
        .and_then(JsonValue::as_i64)
        .and_then(|value| i32::try_from(value).ok())?;
    let bottom = array
        .get(3)
        .and_then(JsonValue::as_i64)
        .and_then(|value| i32::try_from(value).ok())?;
    Some(RoiDto {
        left: left.min(right),
        top: top.min(bottom),
        width: right
            .max(left)
            .saturating_sub(left.min(right))
            .saturating_add(1),
        height: bottom
            .max(top)
            .saturating_sub(top.min(bottom))
            .saturating_add(1),
    })
}

fn dry_run_tool_search(input: &JsonValue) -> JsonValue {
    let query = input_string(input, "query")
        .unwrap_or_default()
        .to_ascii_lowercase();
    let max_results = input_usize(input, "max_results").unwrap_or(8).clamp(1, 20);
    let mut results = build_tools_catalog()
        .categories
        .into_iter()
        .flat_map(|category| category.items.into_iter())
        .filter(|item| {
            if query.is_empty() {
                true
            } else {
                let haystack = format!(
                    "{} {} {} {}",
                    item.item.id,
                    item.item.display_name,
                    item.item.category_name,
                    item.item.summary
                )
                .to_ascii_lowercase();
                haystack.contains(&query)
            }
        })
        .take(max_results)
        .map(|item| {
            json!({
                "id": item.item.id,
                "name": item.item.display_name,
                "category": item.item.category_name,
                "status": item.item.status,
                "risk": item.item.risk,
                "dry_run": tool_supports_dry_run(&item.item)
            })
        })
        .collect::<Vec<_>>();
    if results.is_empty() && !query.is_empty() {
        results = build_tools_catalog()
            .categories
            .into_iter()
            .flat_map(|category| category.items.into_iter())
            .take(max_results)
            .map(|item| {
                json!({
                    "id": item.item.id,
                    "name": item.item.display_name,
                    "category": item.item.category_name,
                    "status": item.item.status,
                    "risk": item.item.risk,
                    "dry_run": tool_supports_dry_run(&item.item)
                })
            })
            .collect();
    }
    json!({
        "query": query,
        "results": results,
        "note": "dry-run 搜索 catalog，不加载或执行插件 SKILL"
    })
}

fn synthetic_tool_detail(
    id: &str,
    display_name: &str,
    summary: &str,
    status: &str,
    risk: &str,
    permissions: Vec<&str>,
    input_schema: JsonValue,
    notes: Vec<String>,
) -> ToolCatalogItemDetail {
    let (category_id, category_name) = if id.starts_with("vision.") {
        ("vision-tools", "Vision Tools")
    } else if id.starts_with("computer.") {
        ("computer-use", "Computer Use")
    } else {
        ("computer-use", "Computer Use")
    };
    tool_detail(
        ToolCatalogItemSummary {
            id: id.to_string(),
            name: id.to_string(),
            display_name: display_name.to_string(),
            category_id: category_id.to_string(),
            category_name: category_name.to_string(),
            source: "web-api".to_string(),
            source_label: "Web 后端 API".to_string(),
            status: status.to_string(),
            risk: risk.to_string(),
            permissions: permissions.into_iter().map(str::to_string).collect(),
            executable_now: false,
            summary: summary.to_string(),
            action_hint: "点可用查看 API schema 和风险；真实执行暂不从工具卡片触发。".to_string(),
            tool_count: None,
        },
        Some(input_schema),
        None,
        notes,
    )
}

fn schema_with_required(fields: &[&str]) -> JsonValue {
    let properties = fields
        .iter()
        .map(|field| {
            (
                (*field).to_string(),
                JsonValue::Object(
                    [("type".to_string(), JsonValue::String("string".to_string()))]
                        .into_iter()
                        .collect(),
                ),
            )
        })
        .collect();
    JsonValue::Object(
        [
            ("type".to_string(), JsonValue::String("object".to_string())),
            ("properties".to_string(), JsonValue::Object(properties)),
            (
                "required".to_string(),
                JsonValue::Array(
                    fields
                        .iter()
                        .map(|field| JsonValue::String((*field).to_string()))
                        .collect(),
                ),
            ),
        ]
        .into_iter()
        .collect(),
    )
}

fn risk_for_permission(permission: &str) -> String {
    match permission {
        "read-only" | "read" => "low",
        "workspace-write" | "write" => "medium",
        "danger-full-access" | "execute" => "high",
        _ => "medium",
    }
    .to_string()
}

fn risk_for_plugin_permissions(permissions: &[String]) -> &'static str {
    if permissions.iter().any(|permission| permission == "execute") {
        "high"
    } else if permissions.iter().any(|permission| permission == "write") {
        "medium"
    } else {
        "low"
    }
}

fn risk_rank(risk: &str) -> u8 {
    match risk {
        "high" => 3,
        "medium" => 2,
        "low" => 1,
        _ => 0,
    }
}

