fn codex_project_root() -> PathBuf {
    let mut current = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    loop {
        if current.join(".coolzhu").exists()
            && current.join("modules").exists()
            && current.join("Cargo.toml").exists()
        {
            return current;
        }
        if !current.pop() {
            break;
        }
    }
    env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn opencode_master_project_root() -> PathBuf {
    let config_path = read_config(|c| c.workspace.opencode_master_project.clone());
    if let Some(path) = config_path.filter(|v| !v.trim().is_empty()) {
        return PathBuf::from(path);
    }
    user_home_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("opencode")
        .join("master-project")
}

fn child_directories(root: &Path) -> Vec<PathBuf> {
    let mut dirs = Vec::new();
    if let Ok(entries) = std::fs::read_dir(root) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                dirs.push(path);
            }
        }
    }
    dirs.sort();
    dirs
}

#[derive(Default)]
struct ParsedSkillMetadata {
    name: Option<String>,
    description: Option<String>,
}

fn parse_skill_metadata(path: &Path) -> ParsedSkillMetadata {
    let Ok(content) = std::fs::read_to_string(path) else {
        return ParsedSkillMetadata::default();
    };
    let mut metadata = ParsedSkillMetadata::default();
    let mut in_frontmatter = false;
    for (index, line) in content.lines().take(40).enumerate() {
        let line = line.trim();
        if index == 0 && line == "---" {
            in_frontmatter = true;
            continue;
        }
        if in_frontmatter && line == "---" {
            break;
        }
        let Some((key, value)) = line.split_once(':') else {
            continue;
        };
        let value = value
            .trim()
            .trim_matches('"')
            .trim_matches('\'')
            .to_string();
        match key.trim() {
            "name" if !value.is_empty() => metadata.name = Some(value),
            "description" if !value.is_empty() => metadata.description = Some(value),
            _ => {}
        }
    }
    metadata
}

fn persist_gui_web_url(url: &str) {
    let path = gui_web_url_file();
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let _ = std::fs::write(path, url.trim_end_matches('/'));
}

fn gui_web_url_file() -> PathBuf {
    env::temp_dir().join("coolzhu-gui-web-url.txt")
}

async fn api_agents() -> Json<AgentRegistryResponse> {
    let started = Instant::now();
    diag!("[API-AGENTS] start");
    let agents = default_agent_sessions();
    diag!(
        "[API-AGENTS] default_agent_sessions done: count={}, elapsed_ms={}",
        agents.len(),
        elapsed_millis(started)
    );
    let active_started = Instant::now();
    let active_session_id = session_store()
        .lock()
        .ok()
        .and_then(|store| store.active_session_id());
    diag!(
        "[API-AGENTS] active_session_id loaded: {:?}, elapsed_ms={}, total_ms={}",
        active_session_id,
        elapsed_millis(active_started),
        elapsed_millis(started)
    );
    let active_agent_ids = active_session_id
        .filter(|id| {
            agents
                .iter()
                .any(|agent| agent.id == *id && agent.selectable && agent.enabled)
        })
        .map(|id| vec![id])
        .unwrap_or_else(|| {
            agents
                .iter()
                .filter(|agent| agent.selectable && agent.enabled)
                .take(1)
                .map(|agent| agent.id.clone())
                .collect::<Vec<_>>()
        });

    let response = AgentRegistryResponse {
        agents,
        active_agent_ids,
        memory: MemoryPolicy {
            architecture: "beads".to_string(),
            scope: "每个会话都是一个独立 Agent，每个 Agent 独立维护模型、API Key 引用和记忆珠"
                .to_string(),
            window_strategy: "短期上下文进入聊天室，长期上下文沉淀为可检索的 bead 摘要".to_string(),
            max_beads_per_agent: 256,
        },
    };
    diag!(
        "[API-AGENTS] response ready: agents={}, active={}, total_ms={}",
        response.agents.len(),
        response.active_agent_ids.len(),
        elapsed_millis(started)
    );
    Json(response)
}

async fn api_understanding_agents() -> ApiResult<Json<UnderstandingAgentListResponse>> {
    let store = session_store()
        .lock()
        .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
    let active_session_id = store.state.active_vision_session_id.clone();
    let agents = store
        .state
        .sessions
        .iter()
        .filter(|session| is_understanding_model_type(&session.model_type))
        .map(|session| understanding_agent_from_session(session, active_session_id.as_deref()))
        .collect::<Vec<_>>();

    Ok(Json(UnderstandingAgentListResponse {
        agents,
        active_session_id,
    }))
}

