fn validate_clawbot_group_identity(value: &str, label: &str) -> ApiResult<()> {
    if value.trim().is_empty() {
        Err(api_error(
            StatusCode::BAD_REQUEST,
            &format!("微信群成员授权的 {label} 不能为空"),
        ))
    } else {
        Ok(())
    }
}

fn clawbot_require_logged_in_account(account_id: &str) -> ApiResult<()> {
    validate_clawbot_group_identity(account_id, "account_id")?;
    let snapshot = clawbot_gateway_lock()?
        .load_login_snapshot()
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
    if snapshot.state != clawbot_gateway::ClawbotLoginState::Online {
        return Err(api_error(
            StatusCode::PRECONDITION_FAILED,
            "微信连接账号当前不在线，请先扫码登录",
        ));
    }
    if snapshot.account_id.as_deref() != Some(account_id.trim()) {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "请求账号与当前登录的微信连接账号不一致",
        ));
    }
    Ok(())
}

fn clawbot_require_api_operation_administrator(
    account_id: &str,
) -> ApiResult<wechat_group::WechatOperationAdministrator> {
    clawbot_gateway_lock()?
        .operation_administrator(account_id.trim())
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?
        .ok_or_else(|| {
            api_error(
                StatusCode::FORBIDDEN,
                "当前微信账号尚未在“微信连接”窗口认领操作管理员",
            )
        })
}

