fn normalize_clawbot_binding_routes(
    mut binding: clawbot_channel::ClawbotConversationBinding,
    state: &PersistedSessionState,
) -> Result<clawbot_channel::ClawbotConversationBinding, String> {
    binding.chat_room_id = match binding
        .chat_room_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        None => None,
        Some(selector) => {
            if let Some(room) = state
                .chat_rooms
                .iter()
                .find(|room| room.id.eq_ignore_ascii_case(selector))
            {
                Some(room.id.clone())
            } else {
                let matches = state
                    .chat_rooms
                    .iter()
                    .filter(|room| room.name.eq_ignore_ascii_case(selector))
                    .collect::<Vec<_>>();
                match matches.as_slice() {
                    [room] => Some(room.id.clone()),
                    [] => {
                        return Err(format!(
                            "聊天室“{selector}”不存在，请从已配置聊天室中选择。"
                        ));
                    }
                    rooms => {
                        let ids = rooms
                            .iter()
                            .map(|room| room.id.as_str())
                            .collect::<Vec<_>>()
                            .join("、");
                        return Err(format!(
                            "聊天室名称“{selector}”不唯一（{ids}），请使用稳定聊天室 ID。"
                        ));
                    }
                }
            }
        }
    };

    binding.default_session_id = match binding
        .default_session_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        None => None,
        Some(selector) => {
            if let Some(session) = state
                .sessions
                .iter()
                .find(|session| session.id.eq_ignore_ascii_case(selector))
            {
                Some(session.id.clone())
            } else {
                let matches = state
                    .sessions
                    .iter()
                    .filter(|session| session.name.eq_ignore_ascii_case(selector))
                    .collect::<Vec<_>>();
                match matches.as_slice() {
                    [session] => Some(session.id.clone()),
                    [] => {
                        if state
                            .sessions
                            .iter()
                            .any(|session| session.model.eq_ignore_ascii_case(selector))
                        {
                            return Err(format!(
                                "“{selector}”是模型名，不是会话 ID。模型名不能作为会话标识，请选择具体已配置会话。"
                            ));
                        }
                        return Err(format!(
                            "模型会话“{selector}”不存在，请从已配置会话中选择。"
                        ));
                    }
                    sessions => {
                        let ids = sessions
                            .iter()
                            .map(|session| session.id.as_str())
                            .collect::<Vec<_>>()
                            .join("、");
                        return Err(format!(
                            "会话名称“{selector}”不唯一（{ids}），请使用稳定会话 ID。"
                        ));
                    }
                }
            }
        }
    };
    Ok(binding)
}

async fn api_clawbot_upsert_binding(
    Json(payload): Json<clawbot_channel::ClawbotConversationBinding>,
) -> ApiResult<Json<clawbot_channel::ClawbotConversationBinding>> {
    let payload = {
        let store = session_store()
            .lock()
            .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
        normalize_clawbot_binding_routes(payload, &store.state)
            .map_err(|error| api_error(StatusCode::BAD_REQUEST, &error))?
    };
    let mut state = clawbot_channel_state().lock().map_err(|_| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "ClawBot 通道状态锁已损坏",
        )
    })?;
    let binding = state.upsert_binding(payload);
    save_clawbot_channel_state(&state)?;
    Ok(Json(binding))
}

async fn api_clawbot_upsert_group_binding(
    AxumPath(group_id): AxumPath<String>,
    Json(payload): Json<ClawbotGroupBindingUpdateRequest>,
) -> ApiResult<Json<wechat_group::WechatGroupRecord>> {
    clawbot_require_logged_in_account(&payload.account_id)?;
    validate_clawbot_group_identity(&group_id, "group_id")?;
    let _administrator = clawbot_require_api_operation_administrator(&payload.account_id)?;
    if payload.binding.account_id != payload.account_id || payload.binding.peer_id != group_id {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "微信群绑定正文必须与当前登录账号和路径 group_id 一致",
        ));
    }
    let binding = {
        let store = session_store()
            .lock()
            .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
        normalize_clawbot_binding_routes(payload.binding, &store.state)
            .map_err(|error| api_error(StatusCode::BAD_REQUEST, &error))?
    };
    let group = clawbot_gateway_lock()?
        .upsert_group_binding(
            payload.account_id.trim(),
            group_id.trim(),
            &binding,
            uuid_timestamp(),
        )
        .map_err(|error| api_error(StatusCode::BAD_REQUEST, &error))?;
    {
        let mut state = clawbot_channel_state().lock().map_err(|_| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "ClawBot 通道状态锁已损坏",
            )
        })?;
        state.upsert_binding(binding);
        save_clawbot_channel_state(&state)?;
    }
    Ok(Json(group))
}

async fn api_clawbot_detach_group(
    AxumPath(group_id): AxumPath<String>,
    Json(payload): Json<ClawbotGroupDetachRequest>,
) -> ApiResult<Json<wechat_group::WechatGroupDetachAudit>> {
    clawbot_require_logged_in_account(&payload.account_id)?;
    validate_clawbot_group_identity(&group_id, "group_id")?;
    let administrator = clawbot_require_api_operation_administrator(&payload.account_id)?;
    let reason = payload
        .reason
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("manual_admin_detach");
    let audit = clawbot_gateway_lock()?
        .detach_group_transaction(
            payload.account_id.trim(),
            group_id.trim(),
            reason,
            &administrator.peer_id,
            uuid_timestamp(),
        )
        .map_err(|error| api_error(StatusCode::BAD_REQUEST, &error))?;
    clawbot_remove_compat_binding(payload.account_id.trim(), group_id.trim())?;
    Ok(Json(audit))
}

