#[derive(Debug, Deserialize)]
struct ClawbotDirectCommandExecuteRequest {
    account_id: String,
    peer_id: String,
    command_text: String,
    #[serde(default)]
    deliver_to_wechat: bool,
}

#[derive(Debug, Serialize)]
struct ClawbotDirectCommandExecuteResponse {
    state: &'static str,
    code: String,
    message: String,
    pages: Vec<String>,
    artifacts: Vec<clawbot_gateway::WechatArtifactRef>,
    delivery_queued: bool,
}

async fn api_clawbot_execute_direct_command(
    Json(payload): Json<ClawbotDirectCommandExecuteRequest>,
) -> ApiResult<Json<ClawbotDirectCommandExecuteResponse>> {
    let account_id = payload.account_id.trim();
    let peer_id = payload.peer_id.trim();
    let command_text = payload.command_text.trim();
    if account_id.is_empty() || peer_id.is_empty() || command_text.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "账号、私聊联系人和命令文本均不能为空",
        ));
    }
    let binding = {
        let state = clawbot_channel_state().lock().map_err(|_| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "微信连接通道状态锁已损坏",
            )
        })?;
        state.binding(account_id, peer_id).cloned()
    }
    .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "未找到对应的私聊联系人绑定"))?;
    if !binding.enabled || !binding.allowlisted {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "私聊联系人绑定未启用或未加入 allowlist",
        ));
    }
    let command = clawbot_channel::parse_clawbot_command(command_text)
        .ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "请输入以 / 开头的有效微信命令"))?;
    if matches!(command, clawbot_channel::ClawbotCommand::Unknown { .. }) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "未识别微信命令，请先查看 /help",
        ));
    }
    let permission_profile = binding
        .chat_room_id
        .as_deref()
        .map(|room_id| {
            chat_room_permission_profile_sqlite(&default_session_sqlite_path(), room_id)
                .map_err(sqlite_api_error)
        })
        .transpose()?;
    let now_ms = uuid_timestamp();
    let message = clawbot_channel::ClawbotInboundMessage {
        account_id: account_id.to_string(),
        peer_id: peer_id.to_string(),
        conversation_id: None,
        peer_name: binding.peer_name.clone(),
        sender_id: None,
        sender_name: binding.peer_name.clone(),
        is_group: false,
        group_event: None,
        mentioned_bot: false,
        mentions: Vec::new(),
        raw_payload_summary: Some("local_wechat_connection_console".to_string()),
        context_token: binding.last_context_token.clone(),
        external_msg_id: format!("local-console-{now_ms}"),
        kind: clawbot_channel::ClawbotMessageKind::Text,
        text: Some(command_text.to_string()),
        media_refs: Vec::new(),
        received_at_ms: now_ms,
    };
    match execute_clawbot_command_runtime(&message, &command, permission_profile.as_deref()).await {
        Ok(result) => {
            let delivery_queued = if payload.deliver_to_wechat {
                !clawbot_queue_command_result(&message, &result, now_ms)?.is_empty()
            } else {
                false
            };
            Ok(Json(ClawbotDirectCommandExecuteResponse {
                state: "succeeded",
                code: "ok".to_string(),
                message: result.message,
                pages: result.pages,
                artifacts: result.artifacts,
                delivery_queued,
            }))
        }
        Err(error) => Ok(Json(ClawbotDirectCommandExecuteResponse {
            state: "failed",
            code: error.code.to_string(),
            message: error.message,
            pages: Vec::new(),
            artifacts: Vec::new(),
            delivery_queued: false,
        })),
    }
}

