async fn api_clawbot_sidecar_health() -> ApiResult<Json<ClawbotSidecarHealthDto>> {
    let sidecar_url = clawbot_sidecar_base_url();
    let health_url = format!("{}/health", sidecar_url.trim_end_matches('/'));
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(2))
        .build()
        .map_err(|error| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                &format!("初始化 ClawBot sidecar health client 失败：{error}"),
            )
        })?;

    match client.get(&health_url).send().await {
        Ok(response) => match response.error_for_status() {
            Ok(ok) => match ok.json::<ClawbotSidecarHealthDto>().await {
                Ok(mut health) => {
                    health.error = None;
                    Ok(Json(health))
                }
                Err(error) => Ok(Json(clawbot_sidecar_unavailable(format!(
                    "解析 ClawBot sidecar health 失败：{error}"
                )))),
            },
            Err(error) => Ok(Json(clawbot_sidecar_unavailable(format!(
                "ClawBot sidecar health 返回错误：{error}"
            )))),
        },
        Err(error) => Ok(Json(clawbot_sidecar_unavailable(format!(
            "ClawBot sidecar 不可用：{error}"
        )))),
    }
}

fn clawbot_sidecar_unavailable(error: String) -> ClawbotSidecarHealthDto {
    ClawbotSidecarHealthDto {
        available: false,
        sidecar_version: "unknown".to_string(),
        gateway_base_url: String::new(),
        provider: None,
        last_tick_error: None,
        error: Some(error),
    }
}

async fn api_clawbot_outbox_claim(
    Query(query): Query<ClawbotOutboxQuery>,
) -> ApiResult<Json<Vec<clawbot_gateway::ClawbotOutboxItem>>> {
    let store = clawbot_gateway_lock()?;
    store
        .claim_due_outbox(uuid_timestamp(), query.limit.unwrap_or(20).clamp(1, 100))
        .map(Json)
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))
}

async fn api_clawbot_outbox_ack(
    AxumPath(id): AxumPath<i64>,
) -> ApiResult<Json<clawbot_gateway::ClawbotOutboxItem>> {
    let store = clawbot_gateway_lock()?;
    store
        .mark_outbox_sent(id, uuid_timestamp())
        .map(Json)
        .map_err(|error| api_error(StatusCode::BAD_REQUEST, &error))
}

async fn api_clawbot_outbox_fail(
    AxumPath(id): AxumPath<i64>,
    Json(payload): Json<ClawbotOutboxFailRequest>,
) -> ApiResult<Json<clawbot_gateway::ClawbotOutboxItem>> {
    let error = payload.error.trim();
    if error.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ClawBot outbox fail 必须包含非空 error",
        ));
    }
    let (item, detached_group) = {
        let store = clawbot_gateway_lock()?;
        let item = store
            .mark_outbox_failed(
                id,
                error,
                uuid_timestamp(),
                clawbot_gateway::RetryPolicy::default(),
            )
            .map_err(|store_error| api_error(StatusCode::BAD_REQUEST, &store_error))?;
        let group = if clawbot_gateway::is_terminal_group_send_error(error) {
            store
                .group_record(&item.account_id, &item.peer_id)
                .map_err(|store_error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &store_error))?
        } else {
            None
        };
        let detached = if group.as_ref().is_some_and(|group| {
            group.lifecycle_state != wechat_group::WechatGroupLifecycleState::Removed
        }) {
            store
                .detach_group_transaction(
                    &item.account_id,
                    &item.peer_id,
                    "terminal_group_send_error",
                    "ilink_provider",
                    uuid_timestamp(),
                )
                .map_err(|store_error| {
                    api_error(StatusCode::INTERNAL_SERVER_ERROR, &store_error)
                })?;
            true
        } else {
            false
        };
        (item, detached)
    };
    if detached_group {
        clawbot_remove_compat_binding(&item.account_id, &item.peer_id)?;
    }
    Ok(Json(item))
}

fn clawbot_queue_feedback(
    message: &clawbot_channel::ClawbotInboundMessage,
    body: &str,
    now_ms: u64,
) -> ApiResult<i64> {
    let outbound = clawbot_gateway::ClawbotOutboundMessage {
        account_id: message.account_id.clone(),
        peer_id: message.peer_id.clone(),
        context_token: message.context_token.clone(),
        source_external_msg_id: Some(message.external_msg_id.clone()),
        body: clawbot_truncate_text(body, 4_000),
        file: None,
    };
    clawbot_gateway_lock()?
        .enqueue_outbox(&outbound, now_ms)
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))
}

fn clawbot_queue_feedback_pages(
    message: &clawbot_channel::ClawbotInboundMessage,
    pages: &[String],
    now_ms: u64,
) -> ApiResult<Vec<i64>> {
    pages
        .iter()
        .enumerate()
        .map(|(index, page)| {
            clawbot_queue_feedback(message, page, now_ms.saturating_add(index as u64))
        })
        .collect()
}

fn clawbot_queue_command_result(
    message: &clawbot_channel::ClawbotInboundMessage,
    result: &ClawbotRuntimeCommandResult,
    now_ms: u64,
) -> ApiResult<Vec<i64>> {
    let mut outbox_ids = clawbot_queue_feedback_pages(message, &result.pages, now_ms)?;
    for (index, file) in result.files.iter().enumerate() {
        let outbound = clawbot_gateway::ClawbotOutboundMessage {
            account_id: message.account_id.clone(),
            peer_id: message.peer_id.clone(),
            context_token: message.context_token.clone(),
            source_external_msg_id: Some(message.external_msg_id.clone()),
            body: format!("发送文件：{}", file.display_name),
            file: Some(file.clone()),
        };
        let id = clawbot_gateway_lock()?
            .enqueue_outbox(
                &outbound,
                now_ms
                    .saturating_add(result.pages.len() as u64)
                    .saturating_add(index as u64),
            )
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
        outbox_ids.push(id);
    }
    Ok(outbox_ids)
}

const CLAWBOT_FAILURE_REPLAY_WINDOW_MS: u64 = 10 * 60 * 1_000;
const CLAWBOT_DENIAL_NOTICE_WINDOW_MS: u64 = 5 * 60 * 1_000;

fn clawbot_should_guard_repeated_failure(action: &clawbot_channel::ClawbotDispatchAction) -> bool {
    matches!(
        action,
        clawbot_channel::ClawbotDispatchAction::DispatchToCoolzhu
    )
}

fn clawbot_operation_fingerprint(
    message: &clawbot_channel::ClawbotInboundMessage,
    preview: &clawbot_channel::ClawbotInboundPreview,
) -> String {
    let conversation_id = message
        .conversation_id
        .as_deref()
        .unwrap_or(message.peer_id.as_str());
    if let Some(command) = preview.command.as_ref() {
        let command_id = clawbot_channel::command_id(command);
        let args = clawbot_command_arguments(message);
        return format!(
            "wechat-command:{}:{}:{}:{}",
            message.account_id,
            conversation_id,
            command_id,
            clawbot_normalize_fingerprint_part(&args)
        );
    }
    format!(
        "wechat-chat:{}:{}:{}",
        message.account_id,
        conversation_id,
        clawbot_normalize_fingerprint_part(message.text.as_deref().unwrap_or(""))
    )
}

fn clawbot_normalize_fingerprint_part(value: &str) -> String {
    let compact = value
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase();
    let mut normalized = compact.chars().take(256).collect::<String>();
    if normalized.is_empty() {
        normalized = "-".to_string();
    }
    normalized
}

fn clawbot_truncate_text(value: &str, max_chars: usize) -> String {
    value.chars().take(max_chars).collect()
}

fn clawbot_chat_response_text(response: &SendMessageResponse) -> String {
    let mut parts = response
        .messages
        .iter()
        .filter(|message| message.role == "assistant" && message.kind == "assistant-reply")
        .map(|message| strip_context_usage_footer(&message.content))
        .filter(|content| !content.is_empty())
        .collect::<Vec<_>>();
    if parts.is_empty() {
        parts.extend(
            response
                .notes
                .iter()
                .map(|note| note.trim())
                .filter(|note| !note.is_empty())
                .map(ToOwned::to_owned),
        );
    }
    let body = parts.join("\n\n");
    if body.is_empty() {
        "任务已完成，但模型未返回可见文本。".to_string()
    } else {
        clawbot_truncate_text(&body, 4_000)
    }
}

fn strip_context_usage_footer(content: &str) -> String {
    let mut visible_lines = Vec::new();
    for line in content.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("Remote context usage:") || trimmed.starts_with("Context usage:") {
            while visible_lines.last().is_some_and(|previous: &&str| {
                previous.trim().is_empty() || previous.trim() == "---"
            }) {
                visible_lines.pop();
            }
            break;
        }
        visible_lines.push(line);
    }
    visible_lines.join("\n").trim().to_string()
}

fn clawbot_mark_inbox_terminal(
    inbox_id: i64,
    failed: bool,
    detail: &str,
    artifacts: &[clawbot_gateway::WechatArtifactRef],
    now_ms: u64,
) -> ApiResult<()> {
    let store = clawbot_gateway_lock()?;
    let current = store
        .inbox_item(inbox_id)
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
    if failed {
        store
            .mark_inbox_failed(inbox_id, detail, now_ms)
            .map(|_| ())
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))
    } else {
        let result_json = serde_json::to_string(&clawbot_gateway::WechatCommandResult {
            request_id: current.request_id,
            state: clawbot_gateway::WechatRequestState::Succeeded,
            code: "ok".to_string(),
            summary: detail.to_string(),
            details: Vec::new(),
            artifacts: artifacts.to_vec(),
            retryable: false,
        })
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error.to_string()))?;
        store
            .mark_inbox_completed(inbox_id, &result_json, now_ms)
            .map(|_| ())
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))
    }
}

fn clawbot_authorization_decision(
    message: &clawbot_channel::ClawbotInboundMessage,
    preview: &clawbot_channel::ClawbotInboundPreview,
    account_online: bool,
    is_operation_administrator: bool,
    mentioned_bot: bool,
    grant: Option<&wechat_authorization::WechatMemberGrant>,
    permission_profile: Option<&str>,
) -> wechat_authorization::WechatAuthorizationDecision {
    let group_id = message
        .conversation_id
        .as_deref()
        .unwrap_or(message.peer_id.as_str());
    let member_id = message.sender_id.as_deref().unwrap_or("");
    let room_scope = match permission_profile {
        Some(ROOM_PERMISSION_READ_ONLY) => {
            wechat_authorization::WechatRoomPermissionScope::ReadOnly
        }
        Some(ROOM_PERMISSION_FULL_ACCESS) => {
            wechat_authorization::WechatRoomPermissionScope::FullAccess
        }
        _ => wechat_authorization::WechatRoomPermissionScope::WorkspaceWrite,
    };
    wechat_authorization::evaluate_wechat_authorization(
        &wechat_authorization::WechatAuthorizationContext {
            account_online,
            binding_enabled: !matches!(
                preview.action,
                clawbot_channel::ClawbotDispatchAction::RejectDisabledBinding
                    | clawbot_channel::ClawbotDispatchAction::RejectNotAllowlisted
                    | clawbot_channel::ClawbotDispatchAction::NeedBinding
            ),
            is_group: message.is_group,
            mentioned_bot,
            management_command_without_mention: false,
            is_operation_administrator,
            is_wechat_group_admin: false,
            account_id: &message.account_id,
            group_id,
            member_id,
            required: clawbot_channel::command_required_capability(preview.command.as_ref()),
            room_scope,
            grant,
        },
    )
}

fn clawbot_group_identity(
    message: &clawbot_channel::ClawbotInboundMessage,
) -> Result<(&str, &str), (&'static str, &'static str)> {
    let group_id = clawbot_group_id(message)?;
    let member_id = message
        .sender_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or((
            "group_member_identity_missing",
            "群消息缺少稳定的成员 ID，已拒绝调度",
        ))?;
    Ok((group_id, member_id))
}

fn clawbot_group_id(
    message: &clawbot_channel::ClawbotInboundMessage,
) -> Result<&str, (&'static str, &'static str)> {
    message
        .conversation_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .or_else(|| {
            let peer_id = message.peer_id.trim();
            (!peer_id.is_empty()).then_some(peer_id)
        })
        .ok_or((
            "group_member_identity_missing",
            "群消息缺少稳定的群 ID，已拒绝调度",
        ))
}

fn clawbot_remove_compat_binding(account_id: &str, peer_id: &str) -> ApiResult<bool> {
    let mut state = clawbot_channel_state().lock().map_err(|_| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "ClawBot 通道状态锁已损坏",
        )
    })?;
    let removed = state.remove_binding(account_id, peer_id).is_some();
    if removed {
        save_clawbot_channel_state(&state)?;
    }
    Ok(removed)
}

fn clawbot_group_message_without_confirmed_mention(
    message: &clawbot_channel::ClawbotInboundMessage,
    aliases: &[String],
) -> bool {
    message.is_group
        && !wechat_group::resolve_bot_mention(
            message.mentioned_bot,
            message.text.as_deref().unwrap_or(""),
            aliases,
        )
}

fn wechat_command_runtime_state() -> &'static Mutex<wechat_command_runtime::WechatCommandRuntime> {
    static STATE: OnceLock<Mutex<wechat_command_runtime::WechatCommandRuntime>> = OnceLock::new();
    STATE.get_or_init(|| Mutex::new(wechat_command_runtime::WechatCommandRuntime::default()))
}

#[derive(Debug)]
struct ClawbotRuntimeCommandResult {
    message: String,
    pages: Vec<String>,
    artifacts: Vec<clawbot_gateway::WechatArtifactRef>,
    files: Vec<clawbot_gateway::ClawbotOutboundFile>,
}

#[derive(Debug)]
struct ClawbotRuntimeCommandError {
    code: &'static str,
    message: String,
}

impl ClawbotRuntimeCommandError {
    fn new(code: &'static str, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
        }
    }

    fn feedback(&self) -> String {
        format!("[{}] {}", self.code, self.message)
    }
}

fn clawbot_runtime_command_ok(message: String) -> ClawbotRuntimeCommandResult {
    ClawbotRuntimeCommandResult {
        pages: vec![message.clone()],
        message,
        artifacts: Vec::new(),
        files: Vec::new(),
    }
}

fn clawbot_command_arguments(message: &clawbot_channel::ClawbotInboundMessage) -> String {
    message
        .text
        .as_deref()
        .and_then(wechat_command::match_command_spec)
        .map(|(_, arguments)| arguments)
        .unwrap_or_default()
}

fn clawbot_current_binding(
    message: &clawbot_channel::ClawbotInboundMessage,
) -> Result<clawbot_channel::ClawbotConversationBinding, ClawbotRuntimeCommandError> {
    if message.is_group {
        let group_id = clawbot_group_id(message).map_err(|(_, reason)| {
            ClawbotRuntimeCommandError::new("group_member_identity_missing", reason)
        })?;
        return clawbot_gateway_lock()
            .map_err(|error| {
                ClawbotRuntimeCommandError::new("gateway_unavailable", api_error_message(error))
            })?
            .group_record(&message.account_id, group_id)
            .map_err(|error| ClawbotRuntimeCommandError::new("group_read_failed", error))?
            .and_then(|group| group.binding)
            .ok_or_else(|| {
                ClawbotRuntimeCommandError::new(
                    "binding_missing",
                    "当前微信群尚未绑定 coolzhu 聊天室。",
                )
            });
    }
    let state = clawbot_channel_state().lock().map_err(|_| {
        ClawbotRuntimeCommandError::new("channel_state_unavailable", "微信连接状态锁已损坏")
    })?;
    state
        .binding(&message.account_id, &message.peer_id)
        .cloned()
        .ok_or_else(|| {
            ClawbotRuntimeCommandError::new(
                "binding_missing",
                "当前微信会话尚未绑定 coolzhu 聊天室。",
            )
        })
}

fn clawbot_update_binding(
    message: &clawbot_channel::ClawbotInboundMessage,
    mutate: impl FnOnce(&mut clawbot_channel::ClawbotConversationBinding),
) -> Result<clawbot_channel::ClawbotConversationBinding, ClawbotRuntimeCommandError> {
    let mut binding = clawbot_current_binding(message)?;
    mutate(&mut binding);
    let mut state = clawbot_channel_state().lock().map_err(|_| {
        ClawbotRuntimeCommandError::new("channel_state_unavailable", "微信连接状态锁已损坏")
    })?;
    state.upsert_binding(binding.clone());
    state
        .save_to_path(&clawbot_channel_state_path())
        .map_err(|error| ClawbotRuntimeCommandError::new("binding_save_failed", error))?;
    drop(state);
    if message.is_group {
        let group_id = clawbot_group_id(message).map_err(|(_, reason)| {
            ClawbotRuntimeCommandError::new("group_member_identity_missing", reason)
        })?;
        clawbot_gateway_lock()
            .map_err(|error| {
                ClawbotRuntimeCommandError::new("gateway_unavailable", api_error_message(error))
            })?
            .upsert_group_binding(&message.account_id, group_id, &binding, uuid_timestamp())
            .map_err(|error| ClawbotRuntimeCommandError::new("binding_save_failed", error))?;
    }
    Ok(binding)
}

fn clawbot_publish_catalog(
    message: &clawbot_channel::ClawbotInboundMessage,
    kind: wechat_command_runtime::WechatCatalogKind,
    entries: Vec<wechat_command_runtime::WechatCatalogEntry>,
    title: &str,
) -> Result<String, ClawbotRuntimeCommandError> {
    let mut runtime = wechat_command_runtime_state().lock().map_err(|_| {
        ClawbotRuntimeCommandError::new("catalog_state_unavailable", "微信命令目录锁已损坏")
    })?;
    Ok(runtime
        .publish_snapshot(&message.account_id, &message.peer_id, kind, entries)
        .render(title))
}

fn clawbot_resolve_catalog(
    message: &clawbot_channel::ClawbotInboundMessage,
    kind: wechat_command_runtime::WechatCatalogKind,
    selector: &str,
) -> Result<wechat_command_runtime::WechatCatalogEntry, ClawbotRuntimeCommandError> {
    let runtime = wechat_command_runtime_state().lock().map_err(|_| {
        ClawbotRuntimeCommandError::new("catalog_state_unavailable", "微信命令目录锁已损坏")
    })?;
    runtime
        .resolve_selector(&message.account_id, &message.peer_id, kind, selector)
        .map_err(|error| ClawbotRuntimeCommandError::new(error.code, error.message))
}

fn clawbot_room_catalog(
    message: &clawbot_channel::ClawbotInboundMessage,
) -> Result<String, ClawbotRuntimeCommandError> {
    let keyword = clawbot_command_arguments(message).to_ascii_lowercase();
    let entries = {
        let store = session_store().lock().map_err(|_| {
            ClawbotRuntimeCommandError::new("session_store_unavailable", "会话存储锁已损坏")
        })?;
        store
            .state
            .chat_rooms
            .iter()
            .filter(|room| {
                keyword.is_empty()
                    || room.name.to_ascii_lowercase().contains(&keyword)
                    || room.id.to_ascii_lowercase().contains(&keyword)
            })
            .map(|room| wechat_command_runtime::WechatCatalogEntry {
                id: room.id.clone(),
                label: room.name.clone(),
                detail: format!("{} 条消息", room.messages.len()),
            })
            .collect()
    };
    clawbot_publish_catalog(
        message,
        wechat_command_runtime::WechatCatalogKind::Rooms,
        entries,
        "可用聊天室",
    )
}

fn clawbot_session_catalog(
    message: &clawbot_channel::ClawbotInboundMessage,
    kind: wechat_command_runtime::WechatCatalogKind,
    title: &str,
) -> Result<String, ClawbotRuntimeCommandError> {
    let entries = {
        let store = session_store().lock().map_err(|_| {
            ClawbotRuntimeCommandError::new("session_store_unavailable", "会话存储锁已损坏")
        })?;
        store
            .state
            .sessions
            .iter()
            .map(|session| wechat_command_runtime::WechatCatalogEntry {
                id: session.id.clone(),
                label: session.name.clone(),
                detail: format!("{} / {}", session.provider, session.model),
            })
            .collect()
    };
    clawbot_publish_catalog(message, kind, entries, title)
}

fn clawbot_model_catalog(
    message: &clawbot_channel::ClawbotInboundMessage,
) -> Result<String, ClawbotRuntimeCommandError> {
    let provider_filter = clawbot_command_arguments(message).to_ascii_lowercase();
    let mut entries = Vec::new();
    for provider in api::provider_catalog() {
        if !provider_filter.is_empty()
            && !provider
                .slug
                .to_ascii_lowercase()
                .contains(&provider_filter)
            && !provider
                .label
                .to_ascii_lowercase()
                .contains(&provider_filter)
        {
            continue;
        }
        for model in provider.recommended_models {
            entries.push(wechat_command_runtime::WechatCatalogEntry {
                id: format!("{}::{model}", provider.slug),
                label: (*model).to_string(),
                detail: provider.label.to_string(),
            });
        }
    }
    clawbot_publish_catalog(
        message,
        wechat_command_runtime::WechatCatalogKind::Models,
        entries,
        "可用模型",
    )
}

fn clawbot_task_catalog(
    message: &clawbot_channel::ClawbotInboundMessage,
) -> Result<String, ClawbotRuntimeCommandError> {
    let binding = clawbot_current_binding(message)?;
    let room_id = binding.chat_room_id.clone().ok_or_else(|| {
        ClawbotRuntimeCommandError::new(
            "room_not_selected",
            "当前微信会话尚未选择 coolzhu 聊天室，请先发送 /rooms 和 /room。",
        )
    })?;
    let goals = query_goals_sqlite(
        &default_session_sqlite_path(),
        &binding.workspace_id,
        GoalListQuery {
            status: None,
            chat_room_id: Some(room_id),
            limit: Some(20),
        },
    )
    .map_err(|error| {
        ClawbotRuntimeCommandError::new("tasks_query_failed", api_error_message(error))
    })?;
    let entries = goals
        .iter()
        .map(|goal| wechat_command_runtime::WechatCatalogEntry {
            id: goal.id.clone(),
            label: goal.title.clone(),
            detail: format!(
                "状态={} · 迭代 {}/{}",
                goal.status, goal.current_iteration, goal.max_iterations
            ),
        })
        .collect();
    let mut text = clawbot_publish_catalog(
        message,
        wechat_command_runtime::WechatCatalogKind::Tasks,
        entries,
        "当前聊天室任务 / Goal",
    )?;
    if goals.is_empty() {
        text.push_str("\n说明：模型对话即时任务当前不持久化；可用 /queue status 查看消息队列。");
    } else {
        text.push_str("\n发送 /task <编号或ID> 查看详情；/queue status 查看消息队列。");
    }
    Ok(text)
}

fn clawbot_task_detail_text(
    message: &clawbot_channel::ClawbotInboundMessage,
    selector: &str,
) -> Result<String, ClawbotRuntimeCommandError> {
    let binding = clawbot_current_binding(message)?;
    let selector = selector.trim();
    if selector.is_empty() {
        return Err(ClawbotRuntimeCommandError::new(
            "task_selector_required",
            "请提供任务 ID，或先发送 /tasks 后使用编号，例如 /task 1。",
        ));
    }
    let goal_id = match clawbot_resolve_catalog(
        message,
        wechat_command_runtime::WechatCatalogKind::Tasks,
        selector,
    ) {
        Ok(entry) => entry.id,
        Err(_) if selector.parse::<usize>().is_err() => selector.to_string(),
        Err(error) => return Err(error),
    };
    let goal = get_goal_sqlite(
        &default_session_sqlite_path(),
        &binding.workspace_id,
        &goal_id,
    )
    .map_err(|error| {
        ClawbotRuntimeCommandError::new("task_lookup_failed", api_error_message(error))
    })?;
    if let Some(bound_room_id) = binding.chat_room_id.as_deref() {
        if goal.chat_room_id != bound_room_id {
            return Err(ClawbotRuntimeCommandError::new(
                "task_room_mismatch",
                "该任务不属于当前微信会话绑定的聊天室。",
            ));
        }
    }
    Ok(format!(
        "任务详情\n标题：{}\nID: {}\n聊天室：{}\n状态：{}\n迭代：{}/{}\n后台运行：{}\n更新时间：{}",
        goal.title,
        goal.id,
        goal.chat_room_id,
        goal.status,
        goal.current_iteration,
        goal.max_iterations,
        if goal.background { "是" } else { "否" },
        goal.updated_at
    ))
}

fn clawbot_resolve_task_goal(
    message: &clawbot_channel::ClawbotInboundMessage,
    selector: &str,
    use_latest_active_when_empty: bool,
) -> Result<(clawbot_channel::ClawbotConversationBinding, GoalDto), ClawbotRuntimeCommandError> {
    let binding = clawbot_current_binding(message)?;
    let room_id = binding.chat_room_id.as_deref().ok_or_else(|| {
        ClawbotRuntimeCommandError::new(
            "room_not_selected",
            "当前微信会话尚未选择 coolzhu 聊天室，请先发送 /rooms 和 /room。",
        )
    })?;
    let selector = selector.trim();
    let goal = if selector.is_empty() && use_latest_active_when_empty {
        query_goals_sqlite(
            &default_session_sqlite_path(),
            &binding.workspace_id,
            GoalListQuery {
                status: None,
                chat_room_id: Some(room_id.to_string()),
                limit: Some(20),
            },
        )
        .map_err(|error| {
            ClawbotRuntimeCommandError::new("tasks_query_failed", api_error_message(error))
        })?
        .into_iter()
        .find(|goal| !matches!(goal.status.as_str(), "completed" | "cancelled"))
        .ok_or_else(|| {
            ClawbotRuntimeCommandError::new(
                "active_task_not_found",
                "当前聊天室没有可停止的活动任务。可先发送 /tasks 查看任务状态。",
            )
        })?
    } else {
        if selector.is_empty() {
            return Err(ClawbotRuntimeCommandError::new(
                "task_selector_required",
                "请提供任务 ID，或先发送 /tasks 后使用编号。",
            ));
        }
        let goal_id = match clawbot_resolve_catalog(
            message,
            wechat_command_runtime::WechatCatalogKind::Tasks,
            selector,
        ) {
            Ok(entry) => entry.id,
            Err(_) if selector.parse::<usize>().is_err() => selector.to_string(),
            Err(error) => return Err(error),
        };
        get_goal_sqlite(
            &default_session_sqlite_path(),
            &binding.workspace_id,
            &goal_id,
        )
        .map_err(|error| {
            ClawbotRuntimeCommandError::new("task_lookup_failed", api_error_message(error))
        })?
    };
    if goal.chat_room_id != room_id {
        return Err(ClawbotRuntimeCommandError::new(
            "task_room_mismatch",
            "该任务不属于当前微信会话绑定的聊天室。",
        ));
    }
    Ok((binding, goal))
}

fn clawbot_select_existing_session(
    message: &clawbot_channel::ClawbotInboundMessage,
    selector: &str,
    compatibility_alias: bool,
) -> Result<String, ClawbotRuntimeCommandError> {
    let selector = selector.trim();
    if selector.is_empty() {
        return Err(ClawbotRuntimeCommandError::new(
            "session_selector_required",
            "请先发送 /sessions 查看已有会话，再发送 /use <编号|会话ID|唯一会话名>。/new 仅作为 /use 的兼容别名，不会创建新会话。",
        ));
    }

    let selected_id = if selector.parse::<usize>().is_ok() {
        clawbot_resolve_catalog(
            message,
            wechat_command_runtime::WechatCatalogKind::Sessions,
            selector,
        )?
        .id
    } else {
        let store = session_store().lock().map_err(|_| {
            ClawbotRuntimeCommandError::new("session_store_unavailable", "会话存储锁已损坏")
        })?;
        if let Some(session) = store
            .state
            .sessions
            .iter()
            .find(|session| session.id.eq_ignore_ascii_case(selector))
        {
            session.id.clone()
        } else {
            let name_matches = store
                .state
                .sessions
                .iter()
                .filter(|session| session.name.eq_ignore_ascii_case(selector))
                .collect::<Vec<_>>();
            match name_matches.as_slice() {
                [session] => session.id.clone(),
                [] => {
                    return Err(ClawbotRuntimeCommandError::new(
                        "session_not_found",
                        format!(
                            "未找到已有会话“{selector}”。模型名不能作为会话标识，请发送 /sessions 后使用编号、会话 ID 或唯一会话名。"
                        ),
                    ));
                }
                sessions => {
                    let candidates = sessions
                        .iter()
                        .map(|session| format!("{} ({})", session.name, session.id))
                        .collect::<Vec<_>>()
                        .join("、");
                    return Err(ClawbotRuntimeCommandError::new(
                        "session_selector_ambiguous",
                        format!(
                            "会话名“{selector}”不唯一：{candidates}。请使用 /sessions 返回的编号或稳定会话 ID。"
                        ),
                    ));
                }
            }
        }
    };

    let session = session_store()
        .lock()
        .map_err(|_| {
            ClawbotRuntimeCommandError::new("session_store_unavailable", "会话存储锁已损坏")
        })?
        .state
        .sessions
        .iter()
        .find(|candidate| candidate.id == selected_id)
        .cloned()
        .ok_or_else(|| {
            ClawbotRuntimeCommandError::new(
                "catalog_snapshot_stale",
                "会话目录已经变化，请重新发送 /sessions。",
            )
        })?;
    clawbot_update_binding(message, |binding| {
        binding.default_session_id = Some(session.id.clone());
    })?;
    let alias_note = if compatibility_alias {
        "\n兼容说明：/new 等同于 /use，本次未创建新会话。"
    } else {
        ""
    };
    Ok(format!(
        "已选择已有模型会话：{}\nID: {}\nProvider: {}\n模型：{}{}",
        session.name, session.id, session.provider, session.model, alias_note
    ))
}

fn clawbot_continue_task(
    message: &clawbot_channel::ClawbotInboundMessage,
    selector: &str,
) -> Result<String, ClawbotRuntimeCommandError> {
    let (binding, goal) = clawbot_resolve_task_goal(message, selector, false)?;
    if matches!(goal.status.as_str(), "completed" | "cancelled") {
        return Err(ClawbotRuntimeCommandError::new(
            "task_terminal",
            format!("任务 {} 已处于终态 {}，不能继续。", goal.id, goal.status),
        ));
    }
    let db_path = default_session_sqlite_path();
    let status = resume_goal_sqlite(&db_path, &binding.workspace_id, &goal.id)
    .map_err(|error| {
        ClawbotRuntimeCommandError::new("task_resume_failed", api_error_message(error))
    })?;
    let max_steps = goal
        .max_iterations
        .saturating_sub(goal.current_iteration)
        .max(1) as usize;
    let (loop_status, cancel) =
        register_goal_loop_start(&binding.workspace_id, &goal.id, max_steps);
    let loop_started = cancel.is_some();
    if let Some(cancel) = cancel {
        record_goal_loop_event_sqlite(
            &db_path,
            &binding.workspace_id,
            &goal.id,
            "goal-loop-started",
            "Goal loop started from WeChat /continue.",
            json!({
                "source": "wechat",
                "max_steps": max_steps,
                "completed_steps": loop_status.completed_steps,
                "stop_requested": loop_status.stop_requested,
            }),
        );
        let workspace_id = binding.workspace_id.clone();
        let goal_id = goal.id.clone();
        let db_path = db_path.clone();
        tokio::spawn(async move {
            run_goal_loop_background(workspace_id, goal_id, db_path, max_steps, cancel).await;
        });
    }
    Ok(format!(
        "已继续任务：{}\nID: {}\n状态：{}\n运行循环：{}",
        goal.title,
        goal.id,
        status.goal.status,
        if loop_started {
            "已启动"
        } else {
            "已在运行"
        }
    ))
}

fn clawbot_stop_task(
    message: &clawbot_channel::ClawbotInboundMessage,
    selector: &str,
) -> Result<String, ClawbotRuntimeCommandError> {
    let (binding, goal) = clawbot_resolve_task_goal(message, selector, true)?;
    let db_path = default_session_sqlite_path();
    let status = pause_goal_sqlite(
        &db_path,
        &binding.workspace_id,
        &goal.id,
    )
    .map_err(|error| {
        ClawbotRuntimeCommandError::new("task_stop_failed", api_error_message(error))
    })?;
    // pause_goal_sqlite 已在 DB commit 后发出 scoped signal；这里只读取同一
    // workspace 的 loop 状态生成兼容旧协议的文字，不提前改变内存状态。
    let loop_status = goal_loop_status_scoped(&binding.workspace_id, &goal.id);
    Ok(format!(
        "已停止任务：{}\nID: {}\n状态：{}\n运行循环停止请求：{}",
        goal.title,
        goal.id,
        status.goal.status,
        if loop_status.stop_requested {
            "已发送"
        } else {
            "当前无活动循环"
        }
    ))
}

fn clawbot_status_text(
    message: &clawbot_channel::ClawbotInboundMessage,
    permission_profile: Option<&str>,
) -> Result<String, ClawbotRuntimeCommandError> {
    let binding = clawbot_current_binding(message)?;
    let (login, metrics) = {
        let store = clawbot_gateway_lock().map_err(|error| {
            ClawbotRuntimeCommandError::new("gateway_unavailable", api_error_message(error))
        })?;
        let login = store
            .load_login_snapshot()
            .map_err(|error| ClawbotRuntimeCommandError::new("login_snapshot_failed", error))?;
        let metrics = store
            .metrics()
            .map_err(|error| ClawbotRuntimeCommandError::new("gateway_metrics_failed", error))?;
        (login, metrics)
    };
    Ok(format!(
        "微信连接状态：{:?}\n账号：{}\n聊天室：{}\n会话：{}\n目标 Agent：{}\n工作区：{}\n聊天室授权：{}\n队列：pending={} sending={} dead_letter={}\n入站：dispatching={} completed={} rejected={} failed={}",
        login.effective_state(uuid_timestamp()),
        login.account_id.as_deref().unwrap_or("未登录"),
        binding.chat_room_id.as_deref().unwrap_or("未选择"),
        binding.default_session_id.as_deref().unwrap_or("未选择"),
        if binding.target_agent_ids.is_empty() { "自动".to_string() } else { binding.target_agent_ids.join(", ") },
        binding.workspace_id,
        permission_profile.unwrap_or("workspace-write"),
        metrics.outbox_pending,
        metrics.outbox_sending,
        metrics.outbox_dead_letter,
        metrics.inbox_dispatching,
        metrics.inbox_completed,
        metrics.inbox_rejected,
        metrics.inbox_failed,
    ))
}

fn clawbot_permissions_text(
    message: &clawbot_channel::ClawbotInboundMessage,
    permission_profile: Option<&str>,
) -> Result<String, ClawbotRuntimeCommandError> {
    if !message.is_group {
        return Ok(format!(
            "当前为私聊；聊天室授权：{}。私聊仍受联系人绑定与聊天室授权约束。",
            permission_profile.unwrap_or("workspace-write")
        ));
    }
    let group_id = message
        .conversation_id
        .as_deref()
        .unwrap_or(message.peer_id.as_str());
    let member_id = message.sender_id.as_deref().unwrap_or("");
    let grant = clawbot_gateway_lock()
        .map_err(|error| {
            ClawbotRuntimeCommandError::new("gateway_unavailable", api_error_message(error))
        })?
        .group_member_grant(&message.account_id, group_id, member_id)
        .map_err(|error| ClawbotRuntimeCommandError::new("grant_read_failed", error))?;
    let Some(grant) = grant else {
        return Err(ClawbotRuntimeCommandError::new(
            "member_not_allowlisted",
            "当前群成员不在微信连接白名单中。",
        ));
    };
    Ok(format!(
        "群：{group_id}\n成员：{} ({member_id})\n预设：{:?}\n启用：{}\n聊天室授权：{}\n能力：chat={} status={} tools.read={} tools.write={} files.read={} files.write={} tasks.control={} approvals.resolve={} bindings.admin={}",
        grant.member_name.as_deref().unwrap_or("未命名"),
        grant.preset,
        grant.enabled,
        permission_profile.unwrap_or("workspace-write"),
        grant.capabilities.chat,
        grant.capabilities.status,
        grant.capabilities.tools_read,
        grant.capabilities.tools_write,
        grant.capabilities.files_read,
        grant.capabilities.files_write,
        grant.capabilities.tasks_control,
        grant.capabilities.approvals_resolve,
        grant.capabilities.bindings_admin,
    ))
}

fn clawbot_require_group_identity(
    message: &clawbot_channel::ClawbotInboundMessage,
) -> Result<(&str, &str), ClawbotRuntimeCommandError> {
    if !message.is_group {
        return Err(ClawbotRuntimeCommandError::new(
            "group_only_command",
            "该命令仅可在已识别微信群中使用。",
        ));
    }
    clawbot_group_identity(message)
        .map_err(|(code, reason)| ClawbotRuntimeCommandError::new(code, reason))
}

fn clawbot_require_operation_administrator(
    message: &clawbot_channel::ClawbotInboundMessage,
) -> Result<wechat_group::WechatOperationAdministrator, ClawbotRuntimeCommandError> {
    let (_, member_id) = clawbot_require_group_identity(message)?;
    let administrator = clawbot_gateway_lock()
        .map_err(|error| {
            ClawbotRuntimeCommandError::new("gateway_unavailable", api_error_message(error))
        })?
        .operation_administrator(&message.account_id)
        .map_err(|error| ClawbotRuntimeCommandError::new("administrator_read_failed", error))?
        .ok_or_else(|| {
            ClawbotRuntimeCommandError::new(
                "operation_administrator_required",
                "当前微信账号尚未在“微信连接”窗口认领操作管理员。",
            )
        })?;
    if administrator.peer_id != member_id {
        return Err(ClawbotRuntimeCommandError::new(
            "operation_administrator_required",
            "该命令仅允许已认领的 ClawBot 操作管理员执行。",
        ));
    }
    Ok(administrator)
}

fn wechat_member_role_label(preset: wechat_authorization::WechatMemberPreset) -> &'static str {
    match preset {
        wechat_authorization::WechatMemberPreset::None => "无权限",
        wechat_authorization::WechatMemberPreset::ChatMember => "聊天成员",
        wechat_authorization::WechatMemberPreset::Operator => "操作员",
        wechat_authorization::WechatMemberPreset::Collaborator => "旧版角色（已禁用）",
        wechat_authorization::WechatMemberPreset::Administrator => "旧版管理员（已禁用）",
    }
}

fn clawbot_group_members_text(
    message: &clawbot_channel::ClawbotInboundMessage,
) -> Result<String, ClawbotRuntimeCommandError> {
    let (group_id, _) = clawbot_require_group_identity(message)?;
    let store = clawbot_gateway_lock().map_err(|error| {
        ClawbotRuntimeCommandError::new("gateway_unavailable", api_error_message(error))
    })?;
    let administrator = store
        .operation_administrator(&message.account_id)
        .map_err(|error| ClawbotRuntimeCommandError::new("administrator_read_failed", error))?;
    let members = store
        .list_group_member_grants(&message.account_id, group_id)
        .map_err(|error| ClawbotRuntimeCommandError::new("member_list_failed", error))?;
    if members.is_empty() {
        return Ok(format!("当前群 {group_id} 尚未识别到成员。"));
    }
    let mut lines = vec![format!("当前群已识别成员：{}", members.len())];
    for (index, member) in members.iter().enumerate() {
        let role = if administrator
            .as_ref()
            .is_some_and(|value| value.peer_id == member.member_id)
        {
            "操作管理员"
        } else {
            wechat_member_role_label(member.preset)
        };
        lines.push(format!(
            "{}. {} ({}) · {} · 最后出现：{}",
            index + 1,
            member.member_name.as_deref().unwrap_or("未命名成员"),
            member.member_id,
            role,
            member.last_seen_at_ms,
        ));
    }
    Ok(lines.join("\n"))
}

fn clawbot_set_group_member_role(
    message: &clawbot_channel::ClawbotInboundMessage,
    arguments: &str,
) -> Result<String, ClawbotRuntimeCommandError> {
    let administrator = clawbot_require_operation_administrator(message)?;
    let (group_id, _) = clawbot_require_group_identity(message)?;
    let parts = arguments.split_whitespace().collect::<Vec<_>>();
    if parts.len() != 2 {
        return Err(ClawbotRuntimeCommandError::new(
            "invalid_member_role_arguments",
            "用法：/member <成员ID> operator|chat|none",
        ));
    }
    let preset = match parts[1].to_ascii_lowercase().as_str() {
        "operator" => wechat_authorization::WechatMemberPreset::Operator,
        "chat" => wechat_authorization::WechatMemberPreset::ChatMember,
        "none" => wechat_authorization::WechatMemberPreset::None,
        _ => {
            return Err(ClawbotRuntimeCommandError::new(
                "invalid_member_role",
                "成员角色只允许 operator、chat、none。",
            ));
        }
    };
    let grant = clawbot_gateway_lock()
        .map_err(|error| {
            ClawbotRuntimeCommandError::new("gateway_unavailable", api_error_message(error))
        })?
        .set_group_member_role(
            &message.account_id,
            group_id,
            parts[0],
            preset,
            &administrator.peer_id,
            uuid_timestamp(),
        )
        .map_err(|error| ClawbotRuntimeCommandError::new("member_role_update_failed", error))?;
    Ok(format!(
        "已更新群成员角色：{} ({}) → {}",
        grant.member_name.as_deref().unwrap_or("未命名成员"),
        grant.member_id,
        wechat_member_role_label(grant.preset),
    ))
}

fn clawbot_current_group_text(
    message: &clawbot_channel::ClawbotInboundMessage,
) -> Result<String, ClawbotRuntimeCommandError> {
    let (group_id, _) = clawbot_require_group_identity(message)?;
    let group = clawbot_gateway_lock()
        .map_err(|error| {
            ClawbotRuntimeCommandError::new("gateway_unavailable", api_error_message(error))
        })?
        .group_record(&message.account_id, group_id)
        .map_err(|error| ClawbotRuntimeCommandError::new("group_read_failed", error))?
        .ok_or_else(|| {
            ClawbotRuntimeCommandError::new("group_not_observed", "当前微信群尚未被事件识别。")
        })?;
    let binding = group.binding.as_ref();
    Ok(format!(
        "微信群：{}\nID：{}\n同步状态：{:?}\n同步证据：{}\n已识别成员：{}\n聊天室：{}\n会话：{}",
        group.group_name.as_deref().unwrap_or("未命名群"),
        group.group_id,
        group.lifecycle_state,
        group.sync_evidence,
        group.recognized_member_count,
        binding
            .and_then(|value| value.chat_room_id.as_deref())
            .unwrap_or("未绑定"),
        binding
            .and_then(|value| value.default_session_id.as_deref())
            .unwrap_or("未选择"),
    ))
}

fn clawbot_detach_current_group(
    message: &clawbot_channel::ClawbotInboundMessage,
) -> Result<String, ClawbotRuntimeCommandError> {
    let administrator = clawbot_require_operation_administrator(message)?;
    let (group_id, _) = clawbot_require_group_identity(message)?;
    clawbot_gateway_lock()
        .map_err(|error| {
            ClawbotRuntimeCommandError::new("gateway_unavailable", api_error_message(error))
        })?
        .detach_group_transaction(
            &message.account_id,
            group_id,
            "operation_administrator_confirmed_removed",
            &administrator.peer_id,
            uuid_timestamp(),
        )
        .map_err(|error| ClawbotRuntimeCommandError::new("group_detach_failed", error))?;
    clawbot_remove_compat_binding(&message.account_id, group_id).map_err(|error| {
        ClawbotRuntimeCommandError::new("binding_cleanup_failed", api_error_message(error))
    })?;
    Ok(format!(
        "已清理微信群 {group_id} 的绑定、成员权限与待发送消息。"
    ))
}

async fn execute_clawbot_command_runtime(
    message: &clawbot_channel::ClawbotInboundMessage,
    command: &clawbot_channel::ClawbotCommand,
    permission_profile: Option<&str>,
) -> Result<ClawbotRuntimeCommandResult, ClawbotRuntimeCommandError> {
    let command_id = clawbot_channel::command_id(command);
    let spec = wechat_command::command_spec_by_id(command_id).ok_or_else(|| {
        ClawbotRuntimeCommandError::new(
            "command_not_registered",
            format!("命令注册信息不存在：{command_id}"),
        )
    })?;
    if let wechat_command::WechatCommandAvailability::FeatureGated(reason) = spec.availability {
        return Err(ClawbotRuntimeCommandError::new(
            "command_unavailable",
            format!("{} 当前不可用：{reason}", spec.syntax),
        ));
    }

    match command {
        clawbot_channel::ClawbotCommand::Help { .. } => {
            let pages = clawbot_channel::command_reply_pages(command, 1_200)
                .unwrap_or_else(|| vec!["请发送 /help 查看完整目录。".to_string()]);
            let message = pages.first().cloned().unwrap_or_default();
            Ok(ClawbotRuntimeCommandResult {
                message,
                pages,
                artifacts: Vec::new(),
                files: Vec::new(),
            })
        }
        clawbot_channel::ClawbotCommand::Unknown { input } => Err(ClawbotRuntimeCommandError::new(
            "unknown_command",
            format!("未识别微信命令：{input}。请发送 /help 查看完整目录。"),
        )),
        clawbot_channel::ClawbotCommand::Status => Ok(clawbot_runtime_command_ok(
            clawbot_status_text(message, permission_profile)?,
        )),
        clawbot_channel::ClawbotCommand::ListRooms => {
            Ok(clawbot_runtime_command_ok(clawbot_room_catalog(message)?))
        }
        clawbot_channel::ClawbotCommand::SelectRoom { room } => {
            let selected = clawbot_resolve_catalog(
                message,
                wechat_command_runtime::WechatCatalogKind::Rooms,
                room,
            )?;
            let exists = session_store()
                .lock()
                .map_err(|_| {
                    ClawbotRuntimeCommandError::new("session_store_unavailable", "会话存储锁已损坏")
                })?
                .state
                .chat_rooms
                .iter()
                .any(|candidate| candidate.id == selected.id);
            if !exists {
                return Err(ClawbotRuntimeCommandError::new(
                    "catalog_snapshot_stale",
                    "聊天室目录已经变化，请重新发送 /rooms。",
                ));
            }
            clawbot_update_binding(message, |binding| {
                binding.chat_room_id = Some(selected.id.clone());
            })?;
            Ok(clawbot_runtime_command_ok(format!(
                "已选择 coolzhu 聊天室：{}\nID: {}",
                selected.label, selected.id
            )))
        }
        clawbot_channel::ClawbotCommand::ListSessions => {
            Ok(clawbot_runtime_command_ok(clawbot_session_catalog(
                message,
                wechat_command_runtime::WechatCatalogKind::Sessions,
                "可用模型会话",
            )?))
        }
        clawbot_channel::ClawbotCommand::ListTasks => {
            Ok(clawbot_runtime_command_ok(clawbot_task_catalog(message)?))
        }
        clawbot_channel::ClawbotCommand::ContinueTask { task_id } => Ok(
            clawbot_runtime_command_ok(clawbot_continue_task(message, task_id)?),
        ),
        clawbot_channel::ClawbotCommand::NewTurn => Ok(clawbot_runtime_command_ok(
            clawbot_select_existing_session(message, "", true)?,
        )),
        clawbot_channel::ClawbotCommand::UseSessionOrModel { selector } => Ok(
            clawbot_runtime_command_ok(clawbot_select_existing_session(message, selector, false)?),
        ),
        clawbot_channel::ClawbotCommand::SelectTargets { target_agent_ids } => {
            let mut selected_ids = Vec::new();
            let mut selected_labels = Vec::new();
            for selector in target_agent_ids {
                let selected = clawbot_resolve_catalog(
                    message,
                    wechat_command_runtime::WechatCatalogKind::Targets,
                    selector,
                )?;
                if !selected_ids.contains(&selected.id) {
                    selected_ids.push(selected.id);
                    selected_labels.push(selected.label);
                }
            }
            clawbot_update_binding(message, |binding| {
                binding.target_agent_ids.clone_from(&selected_ids);
            })?;
            Ok(clawbot_runtime_command_ok(format!(
                "已选择目标 Agent：{}",
                selected_labels.join(", ")
            )))
        }
        clawbot_channel::ClawbotCommand::Registered {
            command_id,
            arguments,
        } => match command_id.as_str() {
            "ping" => Ok(clawbot_runtime_command_ok(format!(
                "pong — 微信连接到 coolzhu 正常。\n时间戳：{}\n消息 ID：{}",
                uuid_timestamp(),
                message.external_msg_id
            ))),
            "whoami" => Ok(clawbot_runtime_command_ok(format!(
                "微信账号：{}\n会话：{}\n发送者：{}\n类型：{}\n已 @机器人：{}",
                message.account_id,
                message
                    .conversation_id
                    .as_deref()
                    .unwrap_or(&message.peer_id),
                message.sender_id.as_deref().unwrap_or(&message.peer_id),
                if message.is_group { "群聊" } else { "私聊" },
                message.mentioned_bot,
            ))),
            "room.current" => {
                let binding = clawbot_current_binding(message)?;
                Ok(clawbot_runtime_command_ok(format!(
                    "当前聊天室：{}",
                    binding.chat_room_id.as_deref().unwrap_or("未选择")
                )))
            }
            "group.current" => Ok(clawbot_runtime_command_ok(clawbot_current_group_text(
                message,
            )?)),
            "group.detach" => Ok(clawbot_runtime_command_ok(clawbot_detach_current_group(
                message,
            )?)),
            "models" => Ok(clawbot_runtime_command_ok(clawbot_model_catalog(message)?)),
            "model.status" => {
                let binding = clawbot_current_binding(message)?;
                let session_id = binding.default_session_id.ok_or_else(|| {
                    ClawbotRuntimeCommandError::new(
                        "session_not_selected",
                        "尚未选择默认模型会话，请先发送 /sessions 和 /use。",
                    )
                })?;
                let text = {
                    let store = session_store().lock().map_err(|_| {
                        ClawbotRuntimeCommandError::new(
                            "session_store_unavailable",
                            "会话存储锁已损坏",
                        )
                    })?;
                    let session = store
                        .state
                        .sessions
                        .iter()
                        .find(|session| session.id == session_id)
                        .ok_or_else(|| {
                            ClawbotRuntimeCommandError::new(
                                "session_not_found",
                                "绑定的默认模型会话已不存在。",
                            )
                        })?;
                    format!(
                        "当前会话：{}\nID: {}\nProvider: {}\n模型：{}\n模型类型：{}\n推理强度：{}",
                        session.name,
                        session.id,
                        session.provider,
                        session.model,
                        session.model_type,
                        session.reasoning_effort
                    )
                };
                Ok(clawbot_runtime_command_ok(text))
            }
            "targets" => Ok(clawbot_runtime_command_ok(clawbot_session_catalog(
                message,
                wechat_command_runtime::WechatCatalogKind::Targets,
                "可用目标 Agent",
            )?)),
            "target.clear" => {
                clawbot_update_binding(message, |binding| binding.target_agent_ids.clear())?;
                Ok(clawbot_runtime_command_ok(
                    "已清空显式目标 Agent；后续消息由聊天室默认路由。".to_string(),
                ))
            }
            "workspace.current" => {
                let binding = clawbot_current_binding(message)?;
                Ok(clawbot_runtime_command_ok(format!(
                    "当前工作区：{}\n路径：{}",
                    binding.workspace_id,
                    active_workspace_path().display()
                )))
            }
            "cwd" => Ok(clawbot_runtime_command_ok(format!(
                "授权工作目录：{}",
                active_workspace_path().display()
            ))),
            "queue.status" => {
                let metrics = clawbot_gateway_lock()
                    .map_err(|error| {
                        ClawbotRuntimeCommandError::new(
                            "gateway_unavailable",
                            api_error_message(error),
                        )
                    })?
                    .metrics()
                    .map_err(|error| {
                        ClawbotRuntimeCommandError::new("gateway_metrics_failed", error)
                    })?;
                Ok(clawbot_runtime_command_ok(format!(
                    "消息队列：pending={} sending={} sent={} dead_letter={}\n入站：received={} dispatching={} completed={} rejected={} failed={}",
                    metrics.outbox_pending,
                    metrics.outbox_sending,
                    metrics.outbox_sent,
                    metrics.outbox_dead_letter,
                    metrics.inbox_received,
                    metrics.inbox_dispatching,
                    metrics.inbox_completed,
                    metrics.inbox_rejected,
                    metrics.inbox_failed,
                )))
            }
            "new" => Ok(clawbot_runtime_command_ok(clawbot_select_existing_session(
                message, arguments, true,
            )?)),
            "task" => Ok(clawbot_runtime_command_ok(clawbot_task_detail_text(
                message, arguments,
            )?)),
            "continue" => Ok(clawbot_runtime_command_ok(clawbot_continue_task(
                message, arguments,
            )?)),
            "stop" => Ok(clawbot_runtime_command_ok(clawbot_stop_task(
                message, arguments,
            )?)),
            "file.get" => {
                let attachment =
                    wechat_file::file_get_attachment(&active_workspace_path(), arguments.trim())
                        .map_err(|error| {
                            ClawbotRuntimeCommandError::new(error.code, error.message)
                        })?;
                let summary = format!(
                    "文件附件已准备：{}\n大小：{} bytes\n校验：{}",
                    attachment.relative_path, attachment.size_bytes, attachment.checksum
                );
                Ok(ClawbotRuntimeCommandResult {
                    message: summary,
                    pages: Vec::new(),
                    artifacts: vec![clawbot_gateway::WechatArtifactRef {
                        id: format!("wxfile:{}", message.external_msg_id),
                        display_name: attachment.display_name.clone(),
                        path: Some(attachment.relative_path),
                        mime: attachment.mime.clone(),
                        size_bytes: Some(attachment.size_bytes),
                        sha256: None,
                    }],
                    files: vec![clawbot_gateway::ClawbotOutboundFile {
                        local_path: attachment.local_path,
                        display_name: attachment.display_name,
                        mime: attachment.mime,
                        size_bytes: attachment.size_bytes,
                        checksum: Some(attachment.checksum),
                    }],
                })
            }
            "file.list" | "file.info" | "file.write" => {
                wechat_file::execute_file_command(&active_workspace_path(), command_id, arguments)
                    .map(clawbot_runtime_command_ok)
                    .map_err(|error| ClawbotRuntimeCommandError::new(error.code, error.message))
            }
            "permissions" => Ok(clawbot_runtime_command_ok(clawbot_permissions_text(
                message,
                permission_profile,
            )?)),
            "members" => Ok(clawbot_runtime_command_ok(clawbot_group_members_text(
                message,
            )?)),
            "member.set" => Ok(clawbot_runtime_command_ok(clawbot_set_group_member_role(
                message, arguments,
            )?)),
            "errors" => {
                let (last_error, dead_letters, failed) = {
                    let store = clawbot_gateway_lock().map_err(|error| {
                        ClawbotRuntimeCommandError::new(
                            "gateway_unavailable",
                            api_error_message(error),
                        )
                    })?;
                    let snapshot = store.load_login_snapshot().map_err(|error| {
                        ClawbotRuntimeCommandError::new("login_snapshot_failed", error)
                    })?;
                    let metrics = store.metrics().map_err(|error| {
                        ClawbotRuntimeCommandError::new("gateway_metrics_failed", error)
                    })?;
                    (
                        snapshot.last_error,
                        metrics.outbox_dead_letter,
                        metrics.inbox_failed,
                    )
                };
                Ok(clawbot_runtime_command_ok(format!(
                    "最近连接错误：{}\n入站失败：{}\n发送死信：{}",
                    last_error.as_deref().unwrap_or("无"),
                    failed,
                    dead_letters
                )))
            }
            "reconnect" => {
                let snapshot = refresh_clawbot_login_now().await.map_err(|error| {
                    ClawbotRuntimeCommandError::new(
                        "sidecar_reconnect_failed",
                        api_error_message(error),
                    )
                })?;
                let effective_state = snapshot.effective_state(uuid_timestamp());
                if effective_state == clawbot_gateway::ClawbotLoginState::Error {
                    return Err(ClawbotRuntimeCommandError::new(
                        "sidecar_reconnect_failed",
                        snapshot
                            .last_error
                            .unwrap_or_else(|| "Sidecar 重连失败，但未返回错误详情。".to_string()),
                    ));
                }
                Ok(clawbot_runtime_command_ok(format!(
                    "微信连接重连请求已完成。\n状态：{:?}\n账号：{}\n登录代次：{}",
                    effective_state,
                    snapshot.account_id.as_deref().unwrap_or("未登录"),
                    snapshot.generation
                )))
            }
            _ => Err(ClawbotRuntimeCommandError::new(
                "command_executor_missing",
                format!("命令 {} 已注册但实时执行器尚未接通。", spec.syntax),
            )),
        },
        _ => Err(ClawbotRuntimeCommandError::new(
            "command_executor_missing",
            format!("命令 {} 已注册但实时执行器尚未接通。", spec.syntax),
        )),
    }
}

async fn api_clawbot_inbound_dispatch(
    Json(envelope): Json<clawbot_channel::ClawbotInboundEnvelope>,
) -> ApiResult<Json<ClawbotInboundDispatchResponse>> {
    let now_ms = uuid_timestamp();
    let payload_json = serde_json::to_string(&envelope)
        .map_err(|error| api_error(StatusCode::BAD_REQUEST, &error.to_string()))?;
    let registration = {
        let store = clawbot_gateway_lock()?;
        store
            .register_inbox(
                &clawbot_gateway::ClawbotInboxInput {
                    account_id: envelope.message.account_id.clone(),
                    external_msg_id: envelope.message.external_msg_id.clone(),
                    peer_id: envelope.message.peer_id.clone(),
                    payload_json,
                },
                now_ms,
            )
            .map_err(|error| api_error(StatusCode::BAD_REQUEST, &error))?
    };
    let inbox = match registration {
        clawbot_gateway::InboxRegistration::Accepted(inbox) => inbox,
        clawbot_gateway::InboxRegistration::Duplicate(inbox) => {
            return Ok(Json(ClawbotInboundDispatchResponse {
                status: "duplicate".to_string(),
                inbox_id: inbox.id,
                outbox_id: None,
                permission_profile: None,
                preview: None,
                message: "external_msg_id 已处理，未重复调用模型或工具。".to_string(),
            }));
        }
        clawbot_gateway::InboxRegistration::Conflict(inbox) => {
            return Err(api_error(
                StatusCode::CONFLICT,
                &format!(
                    "external_msg_id 与已登记 payload 冲突（inbox_id={}）",
                    inbox.id
                ),
            ));
        }
    };

    if envelope.guard_action() == clawbot_channel::ClawbotIngressGuardAction::RejectRecursive {
        clawbot_gateway_lock()?
            .mark_inbox_rejected(inbox.id, "rejected_recursive", now_ms)
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
        return Ok(Json(ClawbotInboundDispatchResponse {
            status: "rejected_recursive".to_string(),
            inbox_id: inbox.id,
            outbox_id: None,
            permission_profile: None,
            preview: None,
            message: "已拒绝 gateway 回声或非零 hop，不写 outbox。".to_string(),
        }));
    }

    if envelope.message.is_group {
        if let Some(group_event) = envelope.message.group_event {
            let group_id = match clawbot_group_id(&envelope.message) {
                Ok(group_id) => group_id.to_string(),
                Err((code, reason)) => {
                    let feedback = format!("[{code}] {reason}");
                    clawbot_gateway_lock()?
                        .mark_inbox_rejected(inbox.id, &feedback, now_ms)
                        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
                    return Ok(Json(ClawbotInboundDispatchResponse {
                        status: code.to_string(),
                        inbox_id: inbox.id,
                        outbox_id: None,
                        permission_profile: None,
                        preview: None,
                        message: feedback,
                    }));
                }
            };
            let lifecycle_message = match group_event {
                wechat_group::WechatGroupEventKind::BotAdded => {
                    clawbot_gateway_lock()?
                        .observe_group_lifecycle(
                            &envelope.message.account_id,
                            &group_id,
                            envelope.message.peer_name.as_deref(),
                            wechat_group::WechatGroupLifecycleState::AwaitingConfirmation,
                            "provider_bot_added",
                            now_ms,
                        )
                        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
                    "已记录机器人加入微信群事件，等待首条真实群消息确认成员身份。".to_string()
                }
                wechat_group::WechatGroupEventKind::BotRemoved => {
                    {
                        let store = clawbot_gateway_lock()?;
                        let existing = store
                            .group_record(&envelope.message.account_id, &group_id)
                            .map_err(|error| {
                                api_error(StatusCode::INTERNAL_SERVER_ERROR, &error)
                            })?;
                        if existing.is_none() {
                            store
                                .observe_group_lifecycle(
                                    &envelope.message.account_id,
                                    &group_id,
                                    envelope.message.peer_name.as_deref(),
                                    wechat_group::WechatGroupLifecycleState::Removed,
                                    "provider_bot_removed",
                                    now_ms,
                                )
                                .map_err(|error| {
                                    api_error(StatusCode::INTERNAL_SERVER_ERROR, &error)
                                })?;
                        }
                        if !matches!(
                            existing.as_ref().map(|group| group.lifecycle_state),
                            Some(wechat_group::WechatGroupLifecycleState::Removed)
                        ) {
                            store
                                .detach_group_transaction(
                                    &envelope.message.account_id,
                                    &group_id,
                                    "provider_bot_removed",
                                    "ilink_provider",
                                    now_ms,
                                )
                                .map_err(|error| {
                                    api_error(StatusCode::INTERNAL_SERVER_ERROR, &error)
                                })?;
                        }
                    }
                    clawbot_remove_compat_binding(&envelope.message.account_id, &group_id)?;
                    "已记录机器人移出微信群事件，并清理群绑定、成员权限和待发送消息。".to_string()
                }
            };
            clawbot_mark_inbox_terminal(inbox.id, false, &lifecycle_message, &[], now_ms)?;
            return Ok(Json(ClawbotInboundDispatchResponse {
                status: "group_lifecycle_updated".to_string(),
                inbox_id: inbox.id,
                outbox_id: None,
                permission_profile: None,
                preview: None,
                message: lifecycle_message,
            }));
        }
    }

    let (account_online, member_grant, is_operation_administrator, mention_aliases, group_binding) =
        if envelope.message.is_group {
            let (group_id, member_id) = match clawbot_group_identity(&envelope.message) {
                Ok(identity) => (identity.0.to_string(), identity.1.to_string()),
                Err((code, reason)) => {
                    let feedback = format!("[{code}] {reason}");
                    clawbot_gateway_lock()?
                        .mark_inbox_rejected(inbox.id, &feedback, now_ms)
                        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
                    return Ok(Json(ClawbotInboundDispatchResponse {
                        status: code.to_string(),
                        inbox_id: inbox.id,
                        outbox_id: None,
                        permission_profile: None,
                        preview: None,
                        message: feedback,
                    }));
                }
            };
            let legacy_binding = {
                let state = clawbot_channel_state().lock().map_err(|_| {
                    api_error(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        "ClawBot 通道状态锁已损坏",
                    )
                })?;
                state
                    .binding(&envelope.message.account_id, &group_id)
                    .cloned()
            };
            let store = clawbot_gateway_lock()?;
            if matches!(
                store
                    .group_record(&envelope.message.account_id, &group_id)
                    .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?
                    .map(|group| group.lifecycle_state),
                Some(wechat_group::WechatGroupLifecycleState::Removed)
            ) {
                drop(store);
                clawbot_remove_compat_binding(&envelope.message.account_id, &group_id)?;
                let feedback = "[group_removed] 机器人已从该微信群移出，拒绝恢复旧绑定。";
                clawbot_gateway_lock()?
                    .mark_inbox_rejected(inbox.id, feedback, now_ms)
                    .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
                return Ok(Json(ClawbotInboundDispatchResponse {
                    status: "group_removed".to_string(),
                    inbox_id: inbox.id,
                    outbox_id: None,
                    permission_profile: None,
                    preview: None,
                    message: feedback.to_string(),
                }));
            }
            let (mut group, member) = store
                .observe_group_identity(
                    &envelope.message.account_id,
                    &group_id,
                    envelope.message.peer_name.as_deref(),
                    &member_id,
                    envelope.message.sender_name.as_deref(),
                    now_ms,
                )
                .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
            if group.binding.is_none() {
                if let Some(binding) = legacy_binding.as_ref() {
                    group = store
                        .upsert_group_binding(
                            &envelope.message.account_id,
                            &group_id,
                            binding,
                            now_ms,
                        )
                        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
                }
            }
            let administrator = store
                .operation_administrator(&envelope.message.account_id)
                .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
            let is_administrator = administrator
                .as_ref()
                .is_some_and(|administrator| administrator.peer_id == member_id);
            let aliases = administrator
                .map(|administrator| administrator.bot_mention_aliases)
                .filter(|aliases| !aliases.is_empty())
                .unwrap_or_else(|| vec!["ClawBot".to_string()]);
            let snapshot = store
                .load_login_snapshot()
                .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
            let online = snapshot.state == clawbot_gateway::ClawbotLoginState::Online
                && snapshot.account_id.as_deref() == Some(envelope.message.account_id.as_str());
            (
                online,
                Some(member),
                is_administrator,
                aliases,
                group.binding,
            )
        } else {
            let store = clawbot_gateway_lock()?;
            store
                .observe_direct_contact(
                    &envelope.message.account_id,
                    &envelope.message.peer_id,
                    envelope.message.peer_name.as_deref(),
                    now_ms,
                )
                .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
            let snapshot = store
                .load_login_snapshot()
                .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
            let online = snapshot.state == clawbot_gateway::ClawbotLoginState::Online
                && snapshot.account_id.as_deref() == Some(envelope.message.account_id.as_str());
            (online, None, false, Vec::new(), None)
        };

    let preview = {
        let state = clawbot_channel_state().lock().map_err(|_| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "ClawBot 通道状态锁已损坏",
            )
        })?;
        if envelope.message.is_group {
            state.preview_inbound_with_binding(envelope.message.clone(), group_binding.as_ref())
        } else {
            state.preview_inbound(envelope.message.clone())
        }
    };
    let silently_ignore_group =
        clawbot_group_message_without_confirmed_mention(&envelope.message, &mention_aliases);
    let mentioned_bot = envelope.message.is_group && !silently_ignore_group;
    if silently_ignore_group {
        let feedback = "[bot_mention_unconfirmed] 群消息没有明确 @当前微信机器人，已静默忽略。";
        clawbot_gateway_lock()?
            .mark_inbox_rejected(inbox.id, feedback, now_ms)
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
        return Ok(Json(ClawbotInboundDispatchResponse {
            status: "bot_mention_unconfirmed".to_string(),
            inbox_id: inbox.id,
            outbox_id: None,
            permission_profile: None,
            preview: Some(preview),
            message: feedback.to_string(),
        }));
    }
    let permission_profile = preview
        .chat_room_id
        .as_deref()
        .map(|room_id| {
            chat_room_permission_profile_sqlite(&default_session_sqlite_path(), room_id)
                .map_err(sqlite_api_error)
        })
        .transpose()?;

    if matches!(
        preview.action,
        clawbot_channel::ClawbotDispatchAction::ApplyCommand
            | clawbot_channel::ClawbotDispatchAction::DispatchToCoolzhu
    ) {
        let authorization = clawbot_authorization_decision(
            &envelope.message,
            &preview,
            account_online,
            is_operation_administrator,
            mentioned_bot,
            member_grant.as_ref(),
            permission_profile.as_deref(),
        );
        if let wechat_authorization::WechatAuthorizationDecision::Deny { code, reason } =
            authorization
        {
            let feedback = format!("[{code}] {reason}");
            clawbot_gateway_lock()?
                .mark_inbox_rejected(inbox.id, &feedback, now_ms)
                .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
            let outbox_id = if envelope.message.is_group {
                let (group_id, member_id) = clawbot_group_identity(&envelope.message)
                    .map_err(|(_, reason)| api_error(StatusCode::BAD_REQUEST, reason))?;
                let should_notify = clawbot_gateway_lock()?
                    .claim_denial_notice_window(
                        &envelope.message.account_id,
                        group_id,
                        member_id,
                        code,
                        now_ms,
                        CLAWBOT_DENIAL_NOTICE_WINDOW_MS,
                    )
                    .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
                should_notify
                    .then(|| clawbot_queue_feedback(&envelope.message, &feedback, now_ms))
                    .transpose()?
            } else {
                Some(clawbot_queue_feedback(
                    &envelope.message,
                    &feedback,
                    now_ms,
                )?)
            };
            return Ok(Json(ClawbotInboundDispatchResponse {
                status: "authorization_denied".to_string(),
                inbox_id: inbox.id,
                outbox_id,
                permission_profile,
                preview: Some(preview),
                message: feedback,
            }));
        }
    }

    if matches!(
        preview.action,
        clawbot_channel::ClawbotDispatchAction::ApplyCommand
            | clawbot_channel::ClawbotDispatchAction::DispatchToCoolzhu
    ) {
        let operation_fingerprint = clawbot_operation_fingerprint(&envelope.message, &preview);
        if let Some(previous_failure) = {
            let store = clawbot_gateway_lock()?;
            store
                .set_inbox_operation_fingerprint(inbox.id, &operation_fingerprint, now_ms)
                .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
            if clawbot_should_guard_repeated_failure(&preview.action) {
                store
                    .recent_failed_operation(
                        &envelope.message.account_id,
                        &operation_fingerprint,
                        inbox.id,
                        now_ms.saturating_sub(CLAWBOT_FAILURE_REPLAY_WINDOW_MS),
                    )
                    .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?
            } else {
                None
            }
        } {
            let feedback = format!(
                "[repeated_failure_guard] 相同微信请求最近已失败，已阻止重复调度以避免模型/工具递归调用。previous_request_id={} code={}。请修改请求内容，或在原始失败原因解除后等待看护窗口结束。",
                previous_failure.request_id,
                previous_failure.error_code.as_deref().unwrap_or("failed")
            );
            clawbot_gateway_lock()?
                .mark_inbox_failed(inbox.id, &feedback, now_ms)
                .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
            let outbox_id = clawbot_queue_feedback(&envelope.message, &feedback, now_ms)?;
            return Ok(Json(ClawbotInboundDispatchResponse {
                status: "repeated_failure_guard".to_string(),
                inbox_id: inbox.id,
                outbox_id: Some(outbox_id),
                permission_profile,
                preview: Some(preview),
                message: feedback,
            }));
        }
        let store = clawbot_gateway_lock()?;
        store
            .mark_inbox_authorized(inbox.id, now_ms)
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
        store
            .mark_inbox_dispatching(inbox.id, now_ms)
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
    }

    match preview.action {
        clawbot_channel::ClawbotDispatchAction::ApplyCommand => {
            let command = preview.command.clone().ok_or_else(|| {
                api_error(StatusCode::BAD_REQUEST, "ClawBot 命令预览缺少 command")
            })?;
            match execute_clawbot_command_runtime(
                &envelope.message,
                &command,
                permission_profile.as_deref(),
            )
            .await
            {
                Ok(result) => {
                    clawbot_mark_inbox_terminal(
                        inbox.id,
                        false,
                        &result.message,
                        &result.artifacts,
                        now_ms,
                    )?;
                    let outbox_ids = if clawbot_channel::command_id(&command) == "group.detach" {
                        Vec::new()
                    } else {
                        clawbot_queue_command_result(&envelope.message, &result, now_ms)?
                    };
                    Ok(Json(ClawbotInboundDispatchResponse {
                        status: "command_completed".to_string(),
                        inbox_id: inbox.id,
                        outbox_id: outbox_ids.first().copied(),
                        permission_profile,
                        preview: Some(preview),
                        message: result.message,
                    }))
                }
                Err(error) => {
                    let feedback = error.feedback();
                    clawbot_mark_inbox_terminal(inbox.id, true, &feedback, &[], now_ms)?;
                    let outbox_id = clawbot_queue_feedback(&envelope.message, &feedback, now_ms)?;
                    Ok(Json(ClawbotInboundDispatchResponse {
                        status: "command_failed".to_string(),
                        inbox_id: inbox.id,
                        outbox_id: Some(outbox_id),
                        permission_profile,
                        preview: Some(preview),
                        message: feedback,
                    }))
                }
            }
        }
        clawbot_channel::ClawbotDispatchAction::RejectNotAllowlisted
        | clawbot_channel::ClawbotDispatchAction::RejectDisabledBinding
        | clawbot_channel::ClawbotDispatchAction::NeedBinding => {
            let reason = preview
                .reason
                .clone()
                .unwrap_or_else(|| "ClawBot 绑定不允许调度".to_string());
            clawbot_gateway_lock()?
                .mark_inbox_rejected(inbox.id, &reason, now_ms)
                .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
            let outbox_id = if envelope.message.is_group {
                let (group_id, member_id) = clawbot_group_identity(&envelope.message)
                    .map_err(|(_, detail)| api_error(StatusCode::BAD_REQUEST, detail))?;
                let should_notify = clawbot_gateway_lock()?
                    .claim_denial_notice_window(
                        &envelope.message.account_id,
                        group_id,
                        member_id,
                        "binding_rejected",
                        now_ms,
                        CLAWBOT_DENIAL_NOTICE_WINDOW_MS,
                    )
                    .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
                should_notify
                    .then(|| clawbot_queue_feedback(&envelope.message, &reason, now_ms))
                    .transpose()?
            } else {
                Some(clawbot_queue_feedback(&envelope.message, &reason, now_ms)?)
            };
            Ok(Json(ClawbotInboundDispatchResponse {
                status: "rejected".to_string(),
                inbox_id: inbox.id,
                outbox_id,
                permission_profile,
                preview: Some(preview),
                message: reason,
            }))
        }
        clawbot_channel::ClawbotDispatchAction::DispatchToCoolzhu => {
            let dispatch_result = match clawbot_send_request(&envelope, &preview) {
                Ok(request) => api_chat_send(Json(request))
                    .await
                    .map(|Json(response)| clawbot_chat_response_text(&response)),
                Err(error) => Err(error),
            };
            let (status, failed, feedback) = match dispatch_result {
                Ok(body) => ("completed", false, body),
                Err(error) => (
                    "failed",
                    true,
                    format!("ClawBot 调度失败：{}", api_error_message(error)),
                ),
            };
            clawbot_mark_inbox_terminal(inbox.id, failed, &feedback, &[], now_ms)?;
            let outbox_id = clawbot_queue_feedback(&envelope.message, &feedback, now_ms)?;
            Ok(Json(ClawbotInboundDispatchResponse {
                status: status.to_string(),
                inbox_id: inbox.id,
                outbox_id: Some(outbox_id),
                permission_profile,
                preview: Some(preview),
                message: feedback,
            }))
        }
    }
}

fn clawbot_send_request(
    envelope: &clawbot_channel::ClawbotInboundEnvelope,
    preview: &clawbot_channel::ClawbotInboundPreview,
) -> ApiResult<SendMessageRequest> {
    let chat_room_id = preview
        .chat_room_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "ClawBot 联系人尚未绑定聊天室"))?;
    let text = envelope
        .message
        .text
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "ClawBot 入站文本不能为空"))?;
    Ok(SendMessageRequest {
        session_id: preview.session_id.clone(),
        chat_room_id: Some(chat_room_id.to_string()),
        target_agent_ids: preview.target_agent_ids.clone(),
        text: text.to_string(),
        selected_message_ids: None,
        attachments: None,
    })
}

