fn chat_room_name_for_permission(room_id: &str) -> ApiResult<String> {
    let store = session_store()
        .lock()
        .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, ""))?;
    store
        .state
        .chat_rooms
        .iter()
        .find(|room| room.id == room_id)
        .map(|room| room.name.clone())
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, ""))
}

fn chat_room_permission_status(
    room_id: &str,
    room_name: String,
) -> ApiResult<ChatRoomPermissionStatus> {
    let (permission_profile, updated_at) =
        chat_room_permission_record_sqlite(&default_session_sqlite_path(), room_id)
            .map_err(sqlite_api_error)?;
    Ok(ChatRoomPermissionStatus {
        room_id: room_id.to_string(),
        room_name,
        full_access: permission_profile == ROOM_PERMISSION_FULL_ACCESS,
        permission_profile,
        warning: FULL_ACCESS_WARNING.to_string(),
        updated_at,
    })
}

