async fn api_run_next_goal_phase(
    AxumPath(goal_id): AxumPath<String>,
) -> ApiResult<Json<GoalRunNextResponse>> {
    let workspace = active_workspace_path();
    let workspace_id = workspace_identity(&workspace);
    let db_path = default_session_sqlite_path();
    refresh_goal_runtime_role_heartbeats(&db_path, &workspace_id);
    let mut status = goal_status_sqlite(&db_path, &workspace_id, &goal_id)?;
    let mut dispatch = None;

    if next_runnable_goal_phase_id(&status.goal).is_none()
        && !matches!(
            status.goal.status.as_str(),
            "paused" | "cancelled" | "completed"
        )
    {
        let dispatched = {
            let mut store = session_store().lock().map_err(|_| {
                api_error(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "session store lock poisoned",
                )
            })?;
            store.dispatch_ready_goal_phases(&workspace_id, &goal_id)?
        };
        dispatch = Some(dispatched);
        status = goal_status_sqlite(&db_path, &workspace_id, &goal_id)?;
    }

    let Some(phase_id) = next_runnable_goal_phase_id(&status.goal) else {
        let blocked_reason = goal_run_next_blocked_reason(&status, dispatch.as_ref());
        return Ok(Json(GoalRunNextResponse {
            goal_id,
            ran_phase_id: None,
            assigned_session_id: None,
            messages: Vec::new(),
            status,
            dispatch,
            blocked_reason: Some(blocked_reason),
            generated_at: unix_timestamp_millis(),
        }));
    };

    let result = run_goal_phase_once(&workspace_id, &goal_id, &phase_id, &db_path).await?;
    Ok(Json(GoalRunNextResponse {
        goal_id,
        ran_phase_id: Some(result.phase_id.clone()),
        assigned_session_id: Some(result.assigned_session_id.clone()),
        messages: result.messages.clone(),
        status: result.status,
        dispatch,
        blocked_reason: None,
        generated_at: unix_timestamp_millis(),
    }))
}

async fn api_run_all_goal_phases(
    AxumPath(goal_id): AxumPath<String>,
    Json(payload): Json<GoalRunAllRequest>,
) -> ApiResult<Json<GoalRunAllResponse>> {
    let workspace = active_workspace_path();
    let workspace_id = workspace_identity(&workspace);
    let db_path = default_session_sqlite_path();
    refresh_goal_runtime_role_heartbeats(&db_path, &workspace_id);
    let max_steps = goal_run_all_step_limit(&payload);
    let mut dispatches = Vec::new();
    let mut runs = Vec::new();
    let mut stopped_reason =
        "Step limit reached before the goal reached a terminal state.".to_string();
    let mut status = goal_status_sqlite(&db_path, &workspace_id, &goal_id)?;

    for _ in 0..max_steps {
        refresh_goal_runtime_role_heartbeats(&db_path, &workspace_id);
        if matches!(
            status.goal.status.as_str(),
            "paused" | "cancelled" | "completed"
        ) {
            stopped_reason = format!("Goal stopped with status {}.", status.goal.status);
            break;
        }

        if next_runnable_goal_phase_id(&status.goal).is_none() {
            let dispatch = {
                let mut store = session_store().lock().map_err(|_| {
                    api_error(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        "session store lock poisoned",
                    )
                })?;
                store.dispatch_ready_goal_phases(&workspace_id, &goal_id)?
            };
            dispatches.push(dispatch);
            status = goal_status_sqlite(&db_path, &workspace_id, &goal_id)?;
        }

        let Some(phase_id) = next_runnable_goal_phase_id(&status.goal) else {
            stopped_reason = goal_run_next_blocked_reason(&status, dispatches.last());
            break;
        };

        let result = run_goal_phase_once(&workspace_id, &goal_id, &phase_id, &db_path).await?;
        status = result.status.clone();
        runs.push(result);

        if matches!(
            status.goal.status.as_str(),
            "paused" | "cancelled" | "completed"
        ) {
            stopped_reason = format!("Goal stopped with status {}.", status.goal.status);
            break;
        }
    }

    Ok(Json(GoalRunAllResponse {
        goal_id,
        max_steps,
        runs,
        dispatches,
        status,
        stopped_reason,
        generated_at: unix_timestamp_millis(),
    }))
}

async fn api_goal_loop_start(
    AxumPath(goal_id): AxumPath<String>,
    Json(payload): Json<GoalLoopStartRequest>,
) -> ApiResult<Json<GoalLoopStatusResponse>> {
    let workspace = active_workspace_path();
    let workspace_id = workspace_identity(&workspace);
    let db_path = default_session_sqlite_path();
    refresh_goal_runtime_role_heartbeats(&db_path, &workspace_id);
    let max_steps = goal_loop_start_step_limit(&payload);
    let (status, cancel) = register_goal_loop_start(&workspace_id, &goal_id, max_steps);
    if let Some(cancel) = cancel {
        record_goal_loop_event_sqlite(
            &db_path,
            &workspace_id,
            &goal_id,
            "goal-loop-started",
            "Goal loop started.",
            json!({
                "max_steps": max_steps,
                "completed_steps": status.completed_steps,
                "stop_requested": status.stop_requested,
                "started_at": status.started_at,
            }),
        );
        let workspace_id = workspace_id.clone();
        let goal_id = goal_id.clone();
        let db_path = db_path.clone();
        tokio::spawn(async move {
            run_goal_loop_background(workspace_id, goal_id, db_path, max_steps, cancel).await;
        });
    }
    Ok(Json(status))
}

async fn api_goal_loop_stop(
    AxumPath(goal_id): AxumPath<String>,
) -> ApiResult<Json<GoalLoopStatusResponse>> {
    let workspace = active_workspace_path();
    let workspace_id = workspace_identity(&workspace);
    let db_path = default_session_sqlite_path();
    // 先在 captured DB 中提交 durable Goal-phase stop request，再设置内存
    // AtomicBool；DB 失败时不能留下只有内存可见的半停止状态。
    request_goal_phase_stop_requests_sqlite(
        &db_path,
        &workspace_id,
        &goal_id,
        Some("Goal loop stop requested by user."),
    )?;
    let (status, newly_requested) = request_goal_loop_stop_scoped_with_transition(&workspace_id, &goal_id);
    if newly_requested {
        record_goal_loop_event_sqlite(
            &db_path,
            &workspace_id,
            &goal_id,
            "goal-loop-stop-requested",
            "Goal loop stop requested.",
            json!({
                "max_steps": status.max_steps,
                "completed_steps": status.completed_steps,
                "stop_requested": status.stop_requested,
            }),
        );
    }
    Ok(Json(status))
}

async fn api_goal_loop_status(
    AxumPath(goal_id): AxumPath<String>,
) -> ApiResult<Json<GoalLoopStatusResponse>> {
    let workspace_id = workspace_identity(&active_workspace_path());
    Ok(Json(goal_loop_status_scoped(&workspace_id, &goal_id)))
}

async fn run_goal_loop_background(
    workspace_id: String,
    goal_id: String,
    db_path: PathBuf,
    max_steps: usize,
    cancel: Arc<AtomicBool>,
) {
    let mut completed_steps = 0usize;
    let mut stopped_reason =
        "Step limit reached before the goal reached a terminal state.".to_string();
    let mut status = match goal_status_sqlite(&db_path, &workspace_id, &goal_id) {
        Ok(status) => status,
        Err(error) => {
            let stopped_reason = format!(
                "Goal loop failed before start: {}",
                api_error_message(error)
            );
            record_goal_loop_event_sqlite(
                &db_path,
                &workspace_id,
                &goal_id,
                "goal-loop-stopped",
                &stopped_reason,
                json!({
                    "completed_steps": completed_steps,
                    "max_steps": max_steps,
                    "stop_requested": cancel.load(Ordering::SeqCst),
                }),
            );
            finish_goal_loop_status_scoped(
                &workspace_id,
                &goal_id,
                completed_steps,
                stopped_reason,
            );
            return;
        }
    };

    for _ in 0..max_steps {
        refresh_goal_runtime_role_heartbeats(&db_path, &workspace_id);
        if cancel.load(Ordering::SeqCst) {
            stopped_reason = "Stop requested; loop stopped between phases.".to_string();
            break;
        }
        if matches!(
            status.goal.status.as_str(),
            "paused" | "cancelled" | "completed"
        ) {
            stopped_reason = format!("Goal stopped with status {}.", status.goal.status);
            break;
        }

        let mut latest_dispatch = None;
        if next_runnable_goal_phase_id(&status.goal).is_none() {
            let dispatch = {
                let mut store = match session_store().lock() {
                    Ok(store) => store,
                    Err(_) => {
                        stopped_reason =
                            "Goal loop failed: session store lock poisoned.".to_string();
                        break;
                    }
                };
                match store.dispatch_ready_goal_phases(&workspace_id, &goal_id) {
                    Ok(dispatch) => dispatch,
                    Err(error) => {
                        stopped_reason =
                            format!("Goal loop dispatch failed: {}", api_error_message(error));
                        break;
                    }
                }
            };
            latest_dispatch = Some(dispatch);
            status = match goal_status_sqlite(&db_path, &workspace_id, &goal_id) {
                Ok(status) => status,
                Err(error) => {
                    stopped_reason = format!(
                        "Goal loop status refresh failed: {}",
                        api_error_message(error)
                    );
                    break;
                }
            };
        }

        if cancel.load(Ordering::SeqCst) {
            stopped_reason = "Stop requested; loop stopped before running next phase.".to_string();
            break;
        }
        let Some(phase_id) = next_runnable_goal_phase_id(&status.goal) else {
            stopped_reason = goal_run_next_blocked_reason(&status, latest_dispatch.as_ref());
            break;
        };

        match run_goal_phase_once(&workspace_id, &goal_id, &phase_id, &db_path).await {
            Ok(result) => {
                completed_steps += 1;
                mark_goal_loop_progress_scoped(&workspace_id, &goal_id, completed_steps);
                status = result.status;
            }
            Err(error) => {
                if cancel.load(Ordering::SeqCst) || goal_phase_stop_conflict(&error) {
                    stopped_reason = format!(
                        "Goal phase stop requested; loop stopped without retrying: {}",
                        api_error_message(error)
                    );
                } else {
                    stopped_reason =
                        format!("Goal loop phase run failed: {}", api_error_message(error));
                }
                break;
            }
        }

        if matches!(
            status.goal.status.as_str(),
            "paused" | "cancelled" | "completed"
        ) {
            stopped_reason = format!("Goal stopped with status {}.", status.goal.status);
            break;
        }
    }

    record_goal_loop_event_sqlite(
        &db_path,
        &workspace_id,
        &goal_id,
        "goal-loop-stopped",
        &stopped_reason,
        json!({
            "completed_steps": completed_steps,
            "max_steps": max_steps,
            "stop_requested": cancel.load(Ordering::SeqCst),
            "goal_status": status.goal.status,
        }),
    );
    finish_goal_loop_status_scoped(&workspace_id, &goal_id, completed_steps, stopped_reason);
}

async fn run_goal_phase_once(
    workspace_id: &str,
    goal_id: &str,
    phase_id: &str,
    expected_db_path: &Path,
) -> ApiResult<GoalPhaseRunResponse> {
    let phase_trace = diagnostics::TraceIdType::generate().to_hex();
    let phase_started = std::time::Instant::now();
    diagnostics::info(
        "goal",
        "phase.begin",
        "执行 Goal 阶段",
        &[
            ("trace", phase_trace.clone()),
            ("workspace", workspace_id.to_string()),
            ("goal", goal_id.to_string()),
            ("phase", phase_id.to_string()),
        ],
    );
    let run_context = {
        let mut store = session_store().lock().map_err(|_| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "session store lock poisoned",
            )
        })?;
        if store.path != expected_db_path {
            return Err(api_error(
                StatusCode::CONFLICT,
                "session store changed workspace before Goal phase execution",
            ));
        }
        store.save()?;
        let ctx = store.prepare_goal_phase_run_context(&workspace_id, &goal_id, &phase_id)?;
        ctx
    };
    let model_response = agent_chat_response(
        &run_context.agent,
        &run_context.prompt,
        0,
        &[],
        &run_context.context_history,
        run_context.collaboration_roster.as_ref(),
        Some(&run_context.chat_room_id),
    )
    .await;
    // context usage 只作为 commit 后 lifecycle 的输入保存；在 finalizer 的
    // ownership CAS 之前绝不能触碰 SessionStore / SQLite / memory。
    let context_usage = model_response.context_usage.clone();
    let mut tool_messages = Vec::new();
    for (tool_use_id, name, input) in model_response.tool_requests.clone() {
        tool_messages.extend(
            run_model_tool_use_messages(
                &run_context.agent,
                &tool_use_id,
                &name,
                &input,
                Some(&model_response.turn_id),
                Some(&run_context.chat_room_id),
            )
            .await,
        );
    }
    // 确定性命令门控：在不持 session_store 锁时异步执行（cargo build/test 等可能耗时数十秒），
    // 失败证据作为参数传入 record，由其决定回退到 implementer 还是推进完成。
    let command_failures = run_goal_phase_command_gate(
        &run_context.db_path,
        &workspace_id,
        &run_context.goal_id,
        &run_context.phase_id,
    )
    .await;
    let result = {
        let mut store = session_store().lock().map_err(|_| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "session store lock poisoned",
            )
        })?;
        // `record_goal_phase_model_result_at_path` 保留给历史 fixture；真实 worker 必须把
        // captured db_path/run_id/claim_token 一起交给 token-aware finalizer。
        store.record_goal_phase_model_result_at_path_with_claim(
            &run_context.db_path,
            &workspace_id,
            &run_context.goal_id,
            &run_context.phase_id,
            &run_context.run_id,
            &run_context.claim_token,
            &run_context.agent,
            model_response,
            tool_messages,
            command_failures,
        )?
    };
    if result.memory_eligible {
        // context lifecycle 是提交后的附加动作；路径漂移时只保留 captured DB 的事实，
        // 不把旧 worker 的 context/memory 写进当前 workspace。
        if let Some(snapshot) = context_usage.as_ref() {
            if let Ok(mut store) = session_store().lock() {
                if store.path == run_context.db_path {
                    if let Err(error) = store.apply_context_lifecycle_after_turn(
                        &run_context.agent.id,
                        &run_context.chat_room_id,
                        snapshot,
                        context_lifecycle_policy(),
                    ) {
                        diag!(
                            "[CONTEXT-LIFECYCLE] committed Goal result follow-up failed for agent={} goal={} phase={}: {}",
                            run_context.agent.id,
                            goal_id,
                            phase_id,
                            error.1.error
                        );
                    }
                }
            }
        }
        persist_auto_memory_beads_at_path(Some(&run_context.db_path), &result.messages);
    }
    diagnostics::info(
        "goal",
        "phase.ok",
        "Goal 阶段完成",
        &[
            ("trace", phase_trace.clone()),
            ("phase", phase_id.to_string()),
            (
                "latency_ms",
                phase_started.elapsed().as_millis().to_string(),
            ),
        ],
    );
    Ok(result)
}

async fn api_attachment_index(
    Query(query): Query<AttachmentIndexQuery>,
) -> ApiResult<Json<AttachmentIndexResponse>> {
    let store = session_store()
        .lock()
        .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
    store.chat_room_attachments(None, query)
}

async fn api_attachment_upload(
    mut multipart: Multipart,
) -> ApiResult<Json<AttachmentUploadResponse>> {
    let mut original_name: Option<String> = None;
    let mut kind: Option<String> = None;
    let mut mime_type: Option<String> = None;
    let mut file_data: Option<Vec<u8>> = None;

    while let Some(field) = multipart.next_field().await.map_err(|error| {
        api_error(
            error.status(),
            &format!("Failed to read attachment form data: {error}"),
        )
    })? {
        let field_name = field.name().unwrap_or("").to_string();
        match field_name.as_str() {
            "file" => {
                if let Some(file_name) = field
                    .file_name()
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                {
                    original_name = Some(file_name.to_string());
                }
                if mime_type.is_none() {
                    mime_type = field.content_type().map(str::to_string);
                }
                let data = field.bytes().await.map_err(|error| {
                    api_error(
                        error.status(),
                        &format!("Failed to read attachment bytes: {error}"),
                    )
                })?;
                if data.is_empty() {
                    return Err(api_error(
                        StatusCode::BAD_REQUEST,
                        "Attachment file is empty",
                    ));
                }
                validate_attachment_upload_size(data.len(), attachment_upload_limit_bytes())
                    .map_err(|status| {
                        api_error(status, "Attachment file exceeds the upload limit")
                    })?;
                file_data = Some(data.to_vec());
            }
            "name" => {
                let value = multipart_field_text(field, "attachment name").await?;
                if !value.trim().is_empty() {
                    original_name = Some(value.trim().to_string());
                }
            }
            "kind" => {
                let value = multipart_field_text(field, "attachment kind").await?;
                if !value.trim().is_empty() {
                    kind = Some(value.trim().to_string());
                }
            }
            "mime_type" => {
                let value = multipart_field_text(field, "attachment mime type").await?;
                if !value.trim().is_empty() {
                    mime_type = Some(value.trim().to_string());
                }
            }
            _ => {
                let _ = field.bytes().await;
            }
        }
    }

    let data =
        file_data.ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "Missing attachment file"))?;
    let original_name = original_name.unwrap_or_else(|| "attachment".to_string());
    let mime_type = mime_type.or_else(|| mime_type_for_url(&original_name).map(str::to_string));
    let attachment_id = format!("att-{}-{:016x}", unix_timestamp_millis(), hash_bytes(&data));
    let response = uploaded_attachment_response(
        &attachment_id,
        &original_name,
        kind.as_deref().unwrap_or("file"),
        mime_type,
        data.len() as u64,
    );
    let path = attachment_store_dir().join(&response.file_name);

    if let Some(parent) = path.parent() {
        tokio::fs::create_dir_all(parent).await.map_err(|error| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                &format!("Failed to create attachment store: {error}"),
            )
        })?;
    }
    tokio::fs::write(&path, &data).await.map_err(|error| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("Failed to write attachment file: {error}"),
        )
    })?;

    Ok(Json(response))
}

fn attachment_upload_route() -> MethodRouter {
    post(api_attachment_upload).layer(DefaultBodyLimit::max(
        attachment_multipart_body_limit_bytes(),
    ))
}

fn validate_attachment_upload_size(size: usize, limit: usize) -> Result<(), StatusCode> {
    if size > limit {
        Err(StatusCode::PAYLOAD_TOO_LARGE)
    } else {
        Ok(())
    }
}

#[cfg(test)]
mod attachment_upload_limit_tests {
    use super::*;
    use http_body_util::BodyExt;
    use tower::ServiceExt;

    #[tokio::test]
    async fn multipart_route_accepts_three_mib_attachment() {
        let boundary = "coolzhu-large-upload-boundary";
        let payload = vec![b'x'; 3 * 1024 * 1024];
        let mut body = format!(
            "--{boundary}\r\nContent-Disposition: form-data; name=\"file\"; filename=\"large.bin\"\r\nContent-Type: application/octet-stream\r\n\r\n"
        )
        .into_bytes();
        body.extend_from_slice(&payload);
        body.extend_from_slice(format!("\r\n--{boundary}--\r\n").as_bytes());

        let response = Router::new()
            .route("/upload", super::attachment_upload_route())
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/upload")
                    .header(
                        header::CONTENT_TYPE,
                        format!("multipart/form-data; boundary={boundary}"),
                    )
                    .body(Body::from(body))
                    .expect("multipart request"),
            )
            .await
            .expect("upload response");

        assert_eq!(response.status(), StatusCode::OK);
        let json: JsonValue = serde_json::from_slice(
            &response
                .into_body()
                .collect()
                .await
                .expect("response body")
                .to_bytes(),
        )
        .expect("upload json");
        if let Some(file_name) = json.get("file_name").and_then(JsonValue::as_str) {
            let _ = std::fs::remove_file(super::attachment_store_dir().join(file_name));
        }
    }

    #[test]
    fn attachment_file_limit_rejects_oversized_payload() {
        assert_eq!(
            super::validate_attachment_upload_size(32 * 1024 * 1024 + 1, 32 * 1024 * 1024),
            Err(StatusCode::PAYLOAD_TOO_LARGE)
        );
    }
}

async fn api_attachment_file(AxumPath(file_name): AxumPath<String>) -> Response<Body> {
    if file_name.trim().is_empty() || sanitize_attachment_file_name(&file_name) != file_name {
        return plain_response(StatusCode::BAD_REQUEST, "invalid attachment path");
    }
    let path = attachment_store_dir().join(&file_name);
    let Ok(bytes) = tokio::fs::read(&path).await else {
        return plain_response(StatusCode::NOT_FOUND, "attachment file not found");
    };
    let mut response = Response::new(Body::from(bytes));
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static(content_type_for_path(&path)),
    );
    response
}

/// 接力单会话超时（毫秒）：从配置 session.relay_timeout_ms 读取，0 视为默认 120s，运行时钳到 [5s,600s]。
fn relay_timeout_ms() -> u64 {
    let configured = read_config(|config| config.session.relay_timeout_ms);
    let effective = if configured == 0 {
        default_relay_timeout_ms()
    } else {
        configured
    };
    effective.clamp(5_000, 600_000)
}

/// 接力式群发的单步结果：成功回复，或超时（触发一次重试）。
enum RelayStepOutcome {
    Reply {
        answer: String,
        reasoning: String,
        used_real_model: bool,
        diagnostic_note: Option<String>,
    },
    Timeout,
}

/// 构造接力提示：原始消息 + 按配置顺序的前序会话回复 + 本会话的位次。
fn build_relay_prompt(
    user_content: &str,
    accumulated: &[(String, usize, String)],
    position: usize,
    total: usize,
) -> String {
    let mut out = format!("原始消息：\n{user_content}\n");
    if !accumulated.is_empty() {
        out.push_str("\n【接力上文（按会话配置顺序，越靠前越先回复）】\n");
        for (name, pos, reply) in accumulated {
            out.push_str(&format!("- 第{pos}位 {name} 回复：{reply}\n"));
        }
    }
    out.push_str(&format!(
        "\n你是接力中的第 {position} 位（共 {total} 位）。请在以上接力基础上作答；若为报数/接龙类任务，请延续前面的序列继续。"
    ));
    out
}

/// 对单个会话执行一次接力调用，按会话超时配置（钳到 [60s,600s]）加超时门控。
async fn relay_run_one(
    agent: &AgentSessionDto,
    result: &PreparedChatDispatch,
    index: usize,
    accumulated: &[(String, usize, String)],
) -> RelayStepOutcome {
    let prompt = build_relay_prompt(
        &result.user_content,
        accumulated,
        index + 1,
        result.targets.len(),
    );
    let timeout_ms = relay_timeout_ms();
    let fut = agent_chat_response(
        agent,
        &prompt,
        result.attachment_count,
        &result.image_urls,
        &result.context_history,
        result.context_rosters.get(&agent.id),
        Some(&result.chat_room_id),
    );
    match tokio::time::timeout(std::time::Duration::from_millis(timeout_ms), fut).await {
        Err(_) => RelayStepOutcome::Timeout,
        Ok(response) => RelayStepOutcome::Reply {
            answer: response.answer_text,
            reasoning: response.reasoning_text,
            used_real_model: response.used_real_model,
            diagnostic_note: response.diagnostic_note,
        },
    }
}

/// 可协作中断的接力单步。取消后丢弃当前异步模型调用；已进入
/// `spawn_blocking`/外部同步插件的工作只能让其自然收尾，调用方不会接收其结果。
async fn relay_run_one_with_cancel(
    agent: &AgentSessionDto,
    result: &PreparedChatDispatch,
    index: usize,
    accumulated: &[(String, usize, String)],
    cancellation: &ChatTurnCancellation,
) -> Result<RelayStepOutcome, ChatTurnCancelled> {
    if cancellation.is_requested() {
        return Err(ChatTurnCancelled);
    }
    await_chat_turn(
        cancellation,
        relay_run_one(agent, result, index, accumulated),
    )
    .await
}

/// 把一次成功的接力回复（含可选推理）落入消息/任务列表。
fn relay_push_reply(
    messages: &mut Vec<ChatMessageDto>,
    tasks: &mut Vec<AgentTaskDto>,
    agent: &AgentSessionDto,
    index: usize,
    answer: &str,
    reasoning: &str,
    used_real_model: bool,
    diagnostic_note: Option<String>,
) {
    let now = unix_timestamp_millis();
    messages.push(ChatMessageDto {
        id: format!("msg-relay-{now}-{index}"),
        author: visible_agent_author(agent),
        role: "assistant".to_string(),
        target: "聊天".to_string(),
        content: sanitize_visible_model_text(agent, answer),
        kind: if used_real_model {
            "assistant-reply".to_string()
        } else {
            "assistant-fallback".to_string()
        },
        attachments: Vec::new(),
    });
    if !reasoning.trim().is_empty() {
        messages.push(ChatMessageDto {
            id: format!("msg-relay-{now}-{index}-thinking"),
            author: visible_reasoning_author(agent),
            role: "assistant".to_string(),
            target: "推理卡片".to_string(),
            content: sanitize_visible_model_text(agent, reasoning),
            kind: "reasoning".to_string(),
            attachments: Vec::new(),
        });
    }
    tasks.push(agent_task(
        agent,
        &format!("task-relay-{now}-{index}"),
        used_real_model,
        diagnostic_note,
    ));
}

/// 接力调度的状态提示（超时/重试/结束）。
fn relay_note_message(agent: &AgentSessionDto, index: usize, note: &str) -> ChatMessageDto {
    ChatMessageDto {
        id: format!("msg-relay-{}-{index}-note", unix_timestamp_millis()),
        author: format!("接力调度·{}", agent.display_name),
        role: "assistant".to_string(),
        target: "接力".to_string(),
        content: format!("[{}] {}", agent.display_name, note),
        kind: "thought".to_string(),
        attachments: Vec::new(),
    }
}

/// R3 增量持久化：把接力某一步新增的消息立即落盘（append 语义），中途崩亦不丢已完成回复。
fn persist_relay_step(result: &PreparedChatDispatch, step_msgs: &[ChatMessageDto]) {
    if step_msgs.is_empty() {
        return;
    }
    if let Err(error) = persist_chat_dispatch(
        &result.chat_room_id,
        result.conversation_session_id.as_deref(),
        &result.targets,
        step_msgs.to_vec(),
    ) {
        warn!("[RELAY] 增量持久化失败: {}", api_error_message(error));
    }
}

/// 执行接力一步并增量落盘：返回 Some(answer) 表示成功（用于累积接力上文），None 表示超时。
async fn relay_run_and_persist_step(
    result: &PreparedChatDispatch,
    agent: &AgentSessionDto,
    index: usize,
    accumulated: &[(String, usize, String)],
    is_retry: bool,
    messages: &mut Vec<ChatMessageDto>,
    tasks: &mut Vec<AgentTaskDto>,
) -> Option<String> {
    let mut step_msgs: Vec<ChatMessageDto> = Vec::new();
    let mut step_tasks: Vec<AgentTaskDto> = Vec::new();
    let answer = match relay_run_one(agent, result, index, accumulated).await {
        RelayStepOutcome::Reply {
            answer,
            reasoning,
            used_real_model,
            diagnostic_note,
        } => {
            relay_push_reply(
                &mut step_msgs,
                &mut step_tasks,
                agent,
                index,
                &answer,
                &reasoning,
                used_real_model,
                diagnostic_note,
            );
            Some(answer)
        }
        RelayStepOutcome::Timeout => {
            emit_backend_pet_event("chat.failed", Some("relay step timeout"), "chat");
            let note = if is_retry {
                "重试仍超时，已结束（每会话仅一次重试机会）"
            } else {
                "超时未回复，将在后续会话完成后重新排队重试一次"
            };
            step_msgs.push(relay_note_message(agent, index, note));
            None
        }
    };
    persist_relay_step(result, &step_msgs);
    messages.extend(step_msgs);
    tasks.extend(step_tasks);
    answer
}

/// 接力式顺序群发：按配置顺序逐个会话作答，每个会话看到【原文 + 前序所有回复】；
/// 某会话超时则跳过并入重试队列，后续会话完成后再各重试一次，仍超时则结束（每会话至多一次重试）。
/// R3：每步完成即增量持久化（先落盘用户消息）。
async fn relay_dispatch(
    result: &PreparedChatDispatch,
    messages: &mut Vec<ChatMessageDto>,
    tasks: &mut Vec<AgentTaskDto>,
) {
    // R3：先落盘用户消息，即便后续会话全部失败也不丢用户输入。
    persist_relay_step(result, &result.messages);

    let mut accumulated: Vec<(String, usize, String)> = Vec::new();
    let mut retry_indices: Vec<usize> = Vec::new();

    // 第一轮：按配置顺序接力。
    for (index, agent) in result.targets.iter().enumerate() {
        match relay_run_and_persist_step(result, agent, index, &accumulated, false, messages, tasks)
            .await
        {
            Some(answer) => accumulated.push((agent.display_name.clone(), index + 1, answer)),
            None => retry_indices.push(index),
        }
    }

    // 第二轮：超时会话各重试一次（带最新接力上文）。
    for index in retry_indices {
        let agent = result.targets[index].clone();
        if let Some(answer) =
            relay_run_and_persist_step(result, &agent, index, &accumulated, true, messages, tasks)
                .await
        {
            accumulated.push((agent.display_name.clone(), index + 1, answer));
        }
    }
}

/// POST /api/chat/send/relay —— 接力式顺序群发（按 target_agent_ids 顺序，带单次重试）。
/// 与广播式 /api/chat/send 区别：后一个会话能看到前面所有会话的回复（可实现报数/接龙/分工接力）。
async fn api_chat_send_relay(
    Json(payload): Json<SendMessageRequest>,
) -> ApiResult<Json<SendMessageResponse>> {
    let result = prepare_chat_dispatch(payload)?;
    emit_backend_pet_event("chat.started", Some("Relay chat accepted"), "chat");
    let mut messages = result.messages.clone();
    let mut tasks = result.tasks.clone();

    // relay_dispatch 内部按步增量持久化（含用户消息），此处不再全量 persist（避免重复 append）。
    relay_dispatch(&result, &mut messages, &mut tasks).await;
    persist_auto_memory_beads(&messages);
    emit_backend_pet_event("chat.completed", Some("Relay chat completed"), "chat");

    Ok(Json(SendMessageResponse {
        accepted_agent_ids: result
            .targets
            .iter()
            .map(|agent| agent.id.clone())
            .collect(),
        messages,
        tasks,
        notes: vec![format!(
            "接力式群发：按配置顺序逐个会话接力作答（每个会话可见前序回复），超时会话各获一次重试。真实模型启用={}。",
            real_llm_enabled()
        )],
    }))
}

async fn api_chat_send(
    Json(payload): Json<SendMessageRequest>,
) -> ApiResult<Json<SendMessageResponse>> {
    let result = prepare_chat_dispatch(payload)?;
    emit_backend_pet_event("chat.started", Some("Chat request accepted"), "chat");
    let mut messages = result.messages.clone();
    let mut tasks = result.tasks.clone();
    let mut auto_handoff_candidates = Vec::new();

    // 取消广播：多目标群发统一走接力（后一个会话可见前面所有会话的回复），单目标保持原逻辑。
    if result.targets.len() > 1 {
        relay_dispatch(&result, &mut messages, &mut tasks).await;
        persist_auto_memory_beads(&messages);
        emit_backend_pet_event("chat.completed", Some("Relay chat completed"), "chat");
        return Ok(Json(SendMessageResponse {
            accepted_agent_ids: result
                .targets
                .iter()
                .map(|agent| agent.id.clone())
                .collect(),
            messages,
            tasks,
            notes: vec![format!(
                "群发已统一走接力式顺序分发（取消广播）；真实模型启用={}。",
                real_llm_enabled()
            )],
        }));
    }

    for (index, agent) in result.targets.iter().enumerate() {
        // 图片生成会话：走 images 端点生成图片附件，跳过文本 LLM。
        if agent_media_gen_kind(agent) == Some("image") {
            messages.push(
                image_generation_chat_message(
                    agent,
                    &result.user_content,
                    index,
                    result.image_urls.first().map(String::as_str),
                )
                .await,
            );
            continue;
        }
        // 视频生成会话：走异步 videos 端点（提交 + 轮询）生成视频附件，跳过文本 LLM。
        if agent_media_gen_kind(agent) == Some("video") {
            messages.push(
                video_pending_chat_message(
                    agent,
                    &result.user_content,
                    index,
                    result.image_urls.first().map(String::as_str),
                )
                .await,
            );
            continue;
        }
        let task_id = format!("task-{}-{index}", unix_timestamp_millis());
        let response = agent_chat_response(
            agent,
            &result.user_content,
            result.attachment_count,
            &result.image_urls,
            &result.context_history,
            result.context_rosters.get(&agent.id),
            Some(&result.chat_room_id),
        )
        .await;
        let model_tool_write_executed = response.tool_write_executed;
        let formal_computer_use_intent = text_has_computer_use_intent(&result.user_content);
        let mut effective_tool_requests = response.tool_requests.clone();
        if effective_tool_requests.is_empty()
            && formal_computer_use_intent
            && !response.model_tool_calls_executed
        {
            if let Some(request) =
                formal_computer_use_tool_request_from_intent(&result.user_content)
            {
                diag!(
                    "[TOOL-CHAIN] formal computer-use intent produced no model tool_use; forcing {}",
                    request.1
                );
                effective_tool_requests.push(request);
            }
        }
        let has_pending_model_tool_requests = !effective_tool_requests.is_empty();
        let suppress_pre_tool_assistant_reply =
            formal_computer_use_intent && has_pending_model_tool_requests;
        let mut assistant_content = sanitize_visible_model_text(agent, &response.answer_text);
        append_context_footer(&mut assistant_content, response.context_footer.as_deref());
        let assistant_message = ChatMessageDto {
            id: format!("msg-{}-{index}", unix_timestamp_millis()),
            author: visible_agent_author(agent),
            role: "assistant".to_string(),
            target: "聊天".to_string(),
            content: assistant_content,
            kind: if response.used_real_model {
                "assistant-reply".to_string()
            } else {
                "assistant-fallback".to_string()
            },
            attachments: Vec::new(),
        };
        if !suppress_pre_tool_assistant_reply {
            auto_handoff_candidates.push(AutoHandoffCandidate {
                from_agent_id: agent.id.clone(),
                assistant_message_id: assistant_message.id.clone(),
                content: assistant_message.content.clone(),
            });
            messages.push(assistant_message);
        } else {
            diag!(
                "[TOOL-CHAIN] suppressing pre-tool assistant reply for formal computer_use intent; tool summary will be authoritative"
            );
        }
        if !response.reasoning_text.trim().is_empty() {
            emit_backend_pet_event("chat.reasoning", Some("Agent is reasoning"), "chat");
            messages.push(ChatMessageDto {
                id: format!("msg-{}-{index}-thinking", unix_timestamp_millis()),
                author: visible_reasoning_author(agent),
                role: "assistant".to_string(),
                target: "推理卡片".to_string(),
                content: sanitize_visible_model_text(agent, &response.reasoning_text),
                kind: "reasoning".to_string(),
                attachments: Vec::new(),
            });
        }
        for (tool_use_id, name, input) in effective_tool_requests {
            messages.extend(
                run_model_tool_use_messages(
                    agent,
                    &tool_use_id,
                    &name,
                    &input,
                    Some(&response.turn_id),
                    Some(&result.chat_room_id),
                )
                .await,
            );
        }
        let context_lifecycle = match apply_context_lifecycle_for_agent(
            &agent.id,
            &result.chat_room_id,
            response.context_usage.as_ref(),
        ) {
            Ok(result) => result,
            Err(error) => {
                diag!(
                    "[CONTEXT-LIFECYCLE] apply failed for agent={} room={}: {}",
                    agent.id,
                    result.chat_room_id,
                    error.1.error
                );
                ContextLifecycleResult::default()
            }
        };
        tasks.push(agent_task(
            agent,
            &task_id,
            response.used_real_model,
            response.diagnostic_note,
        ));
        if let Some(task) = context_lifecycle_task(agent, &task_id, &context_lifecycle) {
            tasks.push(task);
        }
        let semantic_tool_side_route = should_run_semantic_tool_side_route(
            result.calls_vision,
            result.calls_tool,
            &result.user_content,
        );
        append_semantic_tool_tasks(
            &mut tasks,
            agent,
            &task_id,
            result.calls_vision,
            result.calls_tool && semantic_tool_side_route,
        );

        // 纯视觉理解（看 / 描述屏幕，无明确 GUI 操作意图）不执行 computer-use 动作，
        // 交给多模态会话看图理解；仅"视觉 + 动作意图"或工具意图才进 run_tool_intent_message。
        if semantic_tool_side_route
            && !model_tool_write_executed
            && !has_pending_model_tool_requests
            && !formal_computer_use_intent
        {
            if let Some(tool_message) = run_tool_intent_message(agent, &result.user_content).await {
                messages.push(tool_message);
            }
        }
    }

    let db_path = default_session_sqlite_path();
    let workspace = active_workspace_path();
    let workspace_id = workspace_identity(&workspace);
    if let Err(error) = append_goal_trigger_consultation(
        &db_path,
        &workspace_id,
        &result,
        &mut messages,
        &mut tasks,
    ) {
        append_goal_trigger_error_message(&error, &mut messages, &mut tasks);
    }

    persist_chat_dispatch(
        &result.chat_room_id,
        result.conversation_session_id.as_deref(),
        &result.targets,
        messages.clone(),
    )?;
    let auto_handoffs =
        process_auto_handoff_candidates(&result.chat_room_id, &auto_handoff_candidates)?;
    for handoff in auto_handoffs {
        if let Some(inbound) = handoff.inbound_message {
            messages.push(chat_message_dto_from_persisted(&inbound));
        }
    }
    persist_auto_memory_beads(&messages);
    persist_reference_forward_memory(&result.reference_context, &result.targets);
    persist_group_send_shared_memory(&result.reference_context, &result.targets);
    emit_backend_pet_event("chat.completed", Some("Chat response completed"), "chat");

    Ok(Json(SendMessageResponse {
        accepted_agent_ids: result
            .targets
            .iter()
            .map(|agent| agent.id.clone())
            .collect(),
        messages,
        tasks,
        notes: vec![
            "后端已按会话 Provider/Model/API Key 引用完成目标 Agent 分发".to_string(),
            if real_llm_enabled() {
                "真实模型已启用 (coolzhu.toml model.enable_real_llm=true)。".to_string()
            } else {
                "真实模型未启用；在 coolzhu.toml [model] 中设置 enable_real_llm=true 后外发 llm-adapter。"
                    .to_string()
            },
        ],
    }))
}

fn chat_stream_done(
    result: &PreparedChatDispatch,
    turn_id: &str,
    status: ChatTurnStatus,
    tasks: Vec<AgentTaskDto>,
) -> ChatStreamDone {
    ChatStreamDone {
        turn_id: turn_id.to_string(),
        run_id: None,
        status,
        accepted_agent_ids: result
            .targets
            .iter()
            .map(|agent| agent.id.clone())
            .collect(),
        tasks,
    }
}

async fn api_chat_turn_interrupt(
    Json(payload): Json<ChatTurnInterruptRequest>,
) -> ApiResult<Json<ChatTurnInterruptResponse>> {
    let turn_id = payload.turn_id.trim();
    let chat_room_id = payload.chat_room_id.trim();
    let requested_session_id = normalized_scope_value(payload.session_id.as_deref());
    if turn_id.is_empty() || chat_room_id.is_empty() || requested_session_id.is_none() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "session_id、chat_room_id、turn_id 均必须提供有效值",
        ));
    }

    // 新 durable turn 先按完整 scope 做 SQLite stop CAS，再触发同进程 cancellation。
    // 这样错误 session/room 永远不会先唤醒内存 worker；仅查不到 DB row 时才进入
    // 迁移期间的旧 registry fallback。
    let workspace_id = workspace_identity(&active_workspace_path());
    let db_path = default_session_sqlite_path();
    if let Some(run) = query_chat_runtime_run_by_scope_sqlite(
        &db_path,
        &workspace_id,
        requested_session_id.as_deref(),
        chat_room_id,
        turn_id,
    )
    .map_err(sqlite_api_error)?
    {
        let response = interrupt_runtime_run_sqlite(&db_path, &run.id, None).map_err(|error| {
            if matches!(error, rusqlite::Error::QueryReturnedNoRows) {
                api_error(StatusCode::NOT_FOUND, "目标聊天 turn 不存在或已结束")
            } else {
                sqlite_api_error(error)
            }
        })?;
        if response.state == "stop_requested" {
            request_chat_turn_by_run_id(&response.run_id);
        }
        let status = match response.state.as_str() {
            "accepted" | "running" => ChatTurnStatus::Running,
            "stop_requested" => ChatTurnStatus::InterruptRequested,
            "completed" => ChatTurnStatus::Completed,
            "failed" => ChatTurnStatus::Failed,
            "interrupted" | "orphaned" => ChatTurnStatus::Interrupted,
            _ => ChatTurnStatus::Failed,
        };
        return Ok(Json(ChatTurnInterruptResponse {
            turn_id: turn_id.to_string(),
            status,
            outcome: response.outcome,
            idempotent: response.idempotent,
        }));
    }

    // 兼容迁移前或 accepted 写入与 registry 建立之间的极短窗口；此分支仍严格
    // 校验 session/room/turn，且只操作同进程内没有 DB row 的旧条目。
    let mut registry = chat_turn_registry()
        .lock()
        .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "聊天 turn 注册表锁已损坏"))?;
    prune_chat_turn_registry(&mut registry);
    let Some(entry) = registry.get_mut(turn_id) else {
        return Err(api_error(
            StatusCode::NOT_FOUND,
            "未找到目标聊天 turn，可能已过期或已清理",
        ));
    };
    if entry.chat_room_id != chat_room_id
        || normalized_scope_value(entry.session_id.as_deref()) != requested_session_id
    {
        return Err(api_error(
            StatusCode::NOT_FOUND,
            "目标聊天 turn 不存在或作用域不匹配",
        ));
    }

    let (status, outcome, idempotent) = match entry.status {
        ChatTurnStatus::Running => {
            entry.status = ChatTurnStatus::InterruptRequested;
            entry.cancellation.request();
            (
                ChatTurnStatus::InterruptRequested,
                "interrupt_requested".to_string(),
                false,
            )
        }
        ChatTurnStatus::InterruptRequested => {
            entry.cancellation.request();
            (
                ChatTurnStatus::InterruptRequested,
                "interrupt_requested".to_string(),
                true,
            )
        }
        terminal => (terminal, "already_finished".to_string(), true),
    };
    Ok(Json(ChatTurnInterruptResponse {
        turn_id: turn_id.to_string(),
        status,
        outcome,
        idempotent,
    }))
}

async fn api_chat_send_stream(
    Json(payload): Json<SendMessageRequest>,
) -> ApiResult<Sse<impl futures_core::Stream<Item = Result<Event, std::convert::Infallible>>>> {
    let result = prepare_chat_dispatch(payload)?;
    let turn_id = new_chat_turn_id();
    let db_path = default_session_sqlite_path();
    let workspace_id = workspace_identity(&active_workspace_path());
    let (run_id, claim_token) = new_runtime_run_identifiers()
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
    create_chat_runtime_run_sqlite(
        &db_path,
        &run_id,
        &claim_token,
        &workspace_id,
        result.conversation_session_id.as_deref(),
        &result.chat_room_id,
        &turn_id,
    )
    .map_err(sqlite_api_error)?;
    let cancellation = register_chat_turn_with_run(
        &turn_id,
        Some(run_id.clone()),
        result.conversation_session_id.clone(),
        result.chat_room_id.clone(),
    );
    let stream = async_stream::stream! {
        let mut turn_guard = ChatTurnGuard::new_runtime(
            turn_id.clone(),
            run_id.clone(),
            claim_token.clone(),
            db_path.clone(),
        );
        let mut terminal_status = ChatTurnStatus::Completed;
        let mut tasks = result.tasks.clone();
        'chat_turn: {
        match start_chat_runtime_run_sqlite(&db_path, &run_id, &claim_token) {
            Ok(true) => {}
            Ok(false) => {
                terminal_status = if cancellation.is_requested() {
                    ChatTurnStatus::Interrupted
                } else {
                    ChatTurnStatus::Failed
                };
                break 'chat_turn;
            }
            Err(error) => {
                let message = format!("聊天运行启动持久化失败: {error}");
                emit_backend_pet_event("chat.failed", Some(&message), "chat");
                yield Ok(sse_json_event("error", &ChatStreamError { message }));
                terminal_status = ChatTurnStatus::Failed;
                break 'chat_turn;
            }
        }
        emit_backend_pet_event(
            "chat.started",
            Some("Chat stream accepted"),
            "chat",
        );
        yield Ok(sse_json_event("started", &ChatStreamStarted {
            turn_id: turn_id.clone(),
            run_id: Some(run_id.clone()),
        }));
        let mut messages = result.messages.clone();
        let initial_message_count = messages.len();
        let mut auto_handoff_candidates = Vec::new();

        // 先落盘用户消息，使显式中断不会丢失输入；后续终态只写新增 assistant/tool 消息。
        if let Err(error) = persist_chat_dispatch(
            &result.chat_room_id,
            result.conversation_session_id.as_deref(),
            &result.targets,
            result.messages.clone(),
        ) {
            let message = format!("消息持久化失败: {}", error.1.error);
            emit_backend_pet_event("chat.failed", Some(&message), "chat");
            yield Ok(sse_json_event("error", &ChatStreamError { message }));
            terminal_status = ChatTurnStatus::Failed;
            break 'chat_turn;
        }
        if cancellation.is_requested() {
            terminal_status = ChatTurnStatus::Interrupted;
            break 'chat_turn;
        }

        for message in &messages {
            yield Ok(sse_json_event("message", message));
        }

        // 取消广播：多目标群发统一走接力（按配置顺序逐会话；后者见前者回复；超时跳过+各重试一次）。
        // 流式下逐会话 await 完成即 yield 整条消息（非逐 token），并 R3 增量持久化。
        if result.targets.len() > 1 {
            let mut accumulated: Vec<(String, usize, String)> = Vec::new();
            let mut retry_indices: Vec<usize> = Vec::new();
            // 第一轮接力。
            for (index, agent) in result.targets.iter().enumerate() {
                let mut step_msgs: Vec<ChatMessageDto> = Vec::new();
                let mut step_tasks: Vec<AgentTaskDto> = Vec::new();
                let relay_outcome = match relay_run_one_with_cancel(
                    agent,
                    &result,
                    index,
                    &accumulated,
                    cancellation.as_ref(),
                )
                .await
                {
                    Ok(outcome) => outcome,
                    Err(_) => {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                };
                match relay_outcome {
                    RelayStepOutcome::Reply { answer, reasoning, used_real_model, diagnostic_note } => {
                        relay_push_reply(&mut step_msgs, &mut step_tasks, agent, index, &answer, &reasoning, used_real_model, diagnostic_note);
                        accumulated.push((agent.display_name.clone(), index + 1, answer));
                    }
                    RelayStepOutcome::Timeout => {
                        emit_backend_pet_event("chat.failed", Some("relay step timeout"), "chat");
                        step_msgs.push(relay_note_message(agent, index, "超时未回复，将在后续会话完成后重新排队重试一次"));
                        retry_indices.push(index);
                    }
                }
                if cancellation.is_requested() {
                    terminal_status = ChatTurnStatus::Interrupted;
                    break 'chat_turn;
                }
                persist_relay_step(&result, &step_msgs);
                for m in &step_msgs { yield Ok(sse_json_event("message", m)); }
                messages.extend(step_msgs);
                tasks.extend(step_tasks);
            }
            // 第二轮：超时会话各重试一次（带最新接力上文）。
            for index in retry_indices {
                let agent = result.targets[index].clone();
                let mut step_msgs: Vec<ChatMessageDto> = Vec::new();
                let mut step_tasks: Vec<AgentTaskDto> = Vec::new();
                let relay_outcome = match relay_run_one_with_cancel(
                    &agent,
                    &result,
                    index,
                    &accumulated,
                    cancellation.as_ref(),
                )
                .await
                {
                    Ok(outcome) => outcome,
                    Err(_) => {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                };
                match relay_outcome {
                    RelayStepOutcome::Reply { answer, reasoning, used_real_model, diagnostic_note } => {
                        relay_push_reply(&mut step_msgs, &mut step_tasks, &agent, index, &answer, &reasoning, used_real_model, diagnostic_note);
                        accumulated.push((agent.display_name.clone(), index + 1, answer));
                    }
                    RelayStepOutcome::Timeout => {
                        step_msgs.push(relay_note_message(&agent, index, "重试仍超时，已结束（每会话仅一次重试机会）"));
                    }
                }
                if cancellation.is_requested() {
                    terminal_status = ChatTurnStatus::Interrupted;
                    break 'chat_turn;
                }
                persist_relay_step(&result, &step_msgs);
                for m in &step_msgs { yield Ok(sse_json_event("message", m)); }
                messages.extend(step_msgs);
                tasks.extend(step_tasks);
            }
            if cancellation.is_requested() {
                terminal_status = ChatTurnStatus::Interrupted;
                break 'chat_turn;
            }
            persist_auto_memory_beads(&messages);
            persist_reference_forward_memory(&result.reference_context, &result.targets);
            persist_group_send_shared_memory(&result.reference_context, &result.targets);
            break 'chat_turn;
        }

        for (index, agent) in result.targets.iter().enumerate() {
            if cancellation.is_requested() {
                terminal_status = ChatTurnStatus::Interrupted;
                break 'chat_turn;
            }
            // 图片生成会话：走 images 端点生成图片附件，yield 一条消息后跳过文本流式。
            if agent_media_gen_kind(agent) == Some("image") {
                let image_message = match await_chat_turn(
                    cancellation.as_ref(),
                    image_generation_chat_message(
                        agent,
                        &result.user_content,
                        index,
                        result.image_urls.first().map(String::as_str),
                    ),
                )
                .await
                {
                    Ok(message) => message,
                    Err(_) => {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                };
                if cancellation.is_requested() {
                    terminal_status = ChatTurnStatus::Interrupted;
                    break 'chat_turn;
                }
                yield Ok(sse_json_event("message", &image_message));
                messages.push(image_message);
                continue;
            }
            // 视频生成会话：异步 videos 端点（提交 + 轮询）生成视频，yield 一条消息后跳过文本流式。
            if agent_media_gen_kind(agent) == Some("video") {
                let video_message = match await_chat_turn(
                    cancellation.as_ref(),
                    video_pending_chat_message(
                        agent,
                        &result.user_content,
                        index,
                        result.image_urls.first().map(String::as_str),
                    ),
                )
                .await
                {
                    Ok(message) => message,
                    Err(_) => {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                };
                if cancellation.is_requested() {
                    terminal_status = ChatTurnStatus::Interrupted;
                    break 'chat_turn;
                }
                yield Ok(sse_json_event("message", &video_message));
                messages.push(video_message);
                continue;
            }
            let task_id = format!("task-{}-{index}", unix_timestamp_millis());
            // 流式路径没有包在 agent_chat_response 的 TURN_TRACE scope 中，显式生成并贯穿本轮。
            let stream_turn_id = diagnostics::TraceIdType::generate().to_hex();
            let assistant_id = format!("msg-{}-{index}", unix_timestamp_millis());
            let reasoning_id = format!("{assistant_id}-thinking");
            let mut model_tool_calls: BTreeMap<u32, (String, String, String)> = BTreeMap::new();
            let mut streamed_tool_calls_dispatched = false;
            let mut streamed_tool_write_executed = false;
            let mut assistant_message = ChatMessageDto {
                id: assistant_id.clone(),
                author: visible_agent_author(agent),
                role: "assistant".to_string(),
                target: "聊天".to_string(),
                content: String::new(),
                kind: "assistant-reply".to_string(),
                attachments: Vec::new(),
            };
            let mut reasoning_message = ChatMessageDto {
                id: reasoning_id.clone(),
                author: visible_reasoning_author(agent),
                role: "assistant".to_string(),
                target: "推理卡片".to_string(),
                content: String::new(),
                kind: "reasoning".to_string(),
                attachments: Vec::new(),
            };

            let mut used_real_model = false;
            let mut diagnostic_note = None;
            let room_caps = chat_room_capabilities_sqlite(
                &default_session_sqlite_path(),
                &result.chat_room_id,
            )
            .unwrap_or((true, true, true));
            let use_real_llm = real_llm_enabled() && room_caps.0;
            let mut assistant_started = false;
            let mut tool_result_summaries: Vec<String> = Vec::new();
            let mut context_footer: Option<String> = None;
            let mut context_usage: Option<ContextUsageSnapshot> = None;
            let mut best_remote_usage: Option<api::Usage> = None;
            let mut stream_context_assembly: Option<ContextAssembly> = None;
            emit_active_realtime_session_event(
                "assistant_started",
                json!({
                    "message_id": assistant_id.clone(),
                    "agent_id": agent.id.clone(),
                    "agent_name": agent.display_name.clone(),
                    "task_id": task_id.clone()
                }),
            );
            update_active_realtime_session_states(Some("thinking"), None);
            diag!("[LLM-CHAIN-STREAM] use_real_llm={use_real_llm}, agent={}, provider={}, model={}",
                agent.name, agent.provider, agent.model);
            if !use_real_llm {
                diag!("[LLM-CHAIN-STREAM] fallback: local_agent_response");
                diagnostic_note = Some("真实模型未启用 (coolzhu.toml model.enable_real_llm=false)，使用本地回退。".to_string());
                assistant_message.kind = "assistant-fallback".to_string();
                assistant_message.content = local_agent_response(
                    agent,
                    &result.user_content,
                    result.attachment_count,
                    "真实模型未启用 (coolzhu.toml model.enable_real_llm=false)",
                );
                assistant_started = true;
                if cancellation.is_requested() {
                    terminal_status = ChatTurnStatus::Interrupted;
                    break 'chat_turn;
                }
                yield Ok(sse_json_event("message_replace", &assistant_message));
            } else {
                let stream_result = match await_chat_turn(
                    cancellation.as_ref(),
                    stream_agent_model(
                        agent,
                        &result.user_content,
                        &result.image_urls,
                        &result.context_history,
                        result.context_rosters.get(&agent.id),
                        &stream_turn_id,
                        Some(&result.chat_room_id),
                    ),
                )
                .await
                {
                    Ok(result) => result,
                    Err(_) => {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                };
                match stream_result {
                    Ok((mut model_stream, assembly)) => {
                        if cancellation.is_requested() {
                            terminal_status = ChatTurnStatus::Interrupted;
                            break 'chat_turn;
                        }
                        used_real_model = true;
                        let mut reasoning_started = false;
                        loop {
                            let next_event = match await_chat_turn(
                                cancellation.as_ref(),
                                model_stream.next_event(),
                            )
                            .await
                            {
                                Ok(event) => event,
                                Err(_) => {
                                    terminal_status = ChatTurnStatus::Interrupted;
                                    break 'chat_turn;
                                }
                            };
                            if cancellation.is_requested() {
                                terminal_status = ChatTurnStatus::Interrupted;
                                break 'chat_turn;
                            }
                            match next_event {
                                Ok(Some(event)) => match event {
                                    StreamEvent::ContentBlockDelta(delta) => match delta.delta {
                                            ContentBlockDelta::TextDelta { text } => {
                                                let text = sanitize_visible_model_text(agent, &text);
                                                if !assistant_started {
                                                    assistant_started = true;
                                                    yield Ok(sse_json_event("message_start", &assistant_message));
                                                }
                                                assistant_message.content.push_str(&text);
                                                update_active_realtime_session_states(
                                                    Some("responding"),
                                                    None,
                                                );
                                                emit_active_realtime_session_event(
                                                    "assistant_text",
                                                    json!({
                                                        "message_id": assistant_id.clone(),
                                                        "agent_id": agent.id.clone(),
                                                        "agent_name": agent.display_name.clone(),
                                                        "delta": text.clone(),
                                                        "kind": "assistant-reply"
                                                    }),
                                                );
                                                yield Ok(sse_json_event("message_delta", &ChatStreamDelta {
                                                    id: assistant_id.clone(),
                                                    kind: "assistant-reply".to_string(),
                                                    delta: text,
                                                }));
                                            }
                                            ContentBlockDelta::ThinkingDelta { thinking } => {
                                                let thinking =
                                                    sanitize_visible_model_text(agent, &thinking);
                                                if !reasoning_started {
                                                    reasoning_started = true;
                                                    emit_backend_pet_event("chat.reasoning", Some("Agent is reasoning"), "chat");
                                                    yield Ok(sse_json_event("message_start", &reasoning_message));
                                                }
                                                update_active_realtime_session_states(
                                                    Some("thinking"),
                                                    None,
                                                );
                                                reasoning_message.content.push_str(&thinking);
                                                yield Ok(sse_json_event("message_delta", &ChatStreamDelta {
                                                    id: reasoning_id.clone(),
                                                    kind: "reasoning".to_string(),
                                                    delta: thinking,
                                                }));
                                            }
                                            ContentBlockDelta::InputJsonDelta { partial_json } => {
                                                if let Some((_, _, arguments)) =
                                                    model_tool_calls.get_mut(&delta.index)
                                                {
                                                    arguments.push_str(&partial_json);
                                                }
                                                if !reasoning_started {
                                                    reasoning_started = true;
                                                    emit_backend_pet_event("chat.reasoning", Some("Agent is reasoning"), "chat");
                                                    yield Ok(sse_json_event("message_start", &reasoning_message));
                                                }
                                                update_active_realtime_session_states(
                                                    Some("thinking"),
                                                    None,
                                                );
                                                reasoning_message.content.push_str(&partial_json);
                                                yield Ok(sse_json_event("message_delta", &ChatStreamDelta {
                                                    id: reasoning_id.clone(),
                                                    kind: "reasoning".to_string(),
                                                    delta: partial_json,
                                                }));
                                            }
                                            ContentBlockDelta::SignatureDelta { .. } => {}
                                        },
                                        StreamEvent::ContentBlockStart(start) => {
                                            if let OutputContentBlock::ToolUse { id, name, input } =
                                                start.content_block
                                            {
                                                let initial_input = if input.is_object()
                                                    && input
                                                        .as_object()
                                                        .is_some_and(|object| object.is_empty())
                                                {
                                                    String::new()
                                                } else {
                                                    input.to_string()
                                                };
                                                model_tool_calls.insert(
                                                    start.index,
                                                    (id.clone(), name.clone(), initial_input),
                                                );
                                                if !reasoning_started {
                                                    reasoning_started = true;
                                                    emit_backend_pet_event("chat.reasoning", Some("Agent requested a tool"), "chat");
                                                    yield Ok(sse_json_event("message_start", &reasoning_message));
                                                }
                                                update_active_realtime_session_states(
                                                    Some("tool_calling"),
                                                    None,
                                                );
                                                emit_active_realtime_session_event(
                                                    "action_step",
                                                    json!({
                                                        "message_id": assistant_id.clone(),
                                                        "agent_id": agent.id.clone(),
                                                        "agent_name": agent.display_name.clone(),
                                                        "tool_use_id": id.clone(),
                                                        "tool_name": name.clone(),
                                                        "status": "requested",
                                                        "input": input.clone()
                                                    }),
                                                );
                                                reasoning_message.content.push_str(&format!(
                                                    "模型请求工具：{name} {input}\n"
                                                ));
                                                yield Ok(sse_json_event("message_delta", &ChatStreamDelta {
                                                    id: reasoning_id.clone(),
                                                    kind: "reasoning".to_string(),
                                                    delta: format!("模型请求工具：{name} {input}\n"),
                                                }));
                                            }
                                        }
                                        StreamEvent::MessageStart(_)
                                        | StreamEvent::ContentBlockStop(_)
                                        | StreamEvent::MessageStop(_) => {}
                                        StreamEvent::MessageDelta(delta) => {
                                            remember_largest_remote_usage(
                                                &mut best_remote_usage,
                                                &delta.usage,
                                            );
                                        }
                                    },
                                Ok(None) => break,
                                Err(error) => {
                                    diagnostic_note = Some(format!("模型流式响应中断: {error}"));
                                    break;
                                }
                            }
                        }
                        diag!(
                            "[LLM-TOOLS] stream_response agent={} answer_len={} reasoning_len={} tool_call_count={} tool_calls={} stale_hits={}",
                            agent.id,
                            assistant_message.content.len(),
                            reasoning_message.content.len(),
                            model_tool_calls.len(),
                            model_tool_calls
                                .values()
                                .map(|(_, name, _)| name.as_str())
                                .collect::<Vec<_>>()
                                .join(","),
                            stale_tool_denial_hits(&format!(
                                "{}\n{}",
                                assistant_message.content, reasoning_message.content
                            )),
                        );
                        if assistant_message.content.trim().is_empty()
                            && model_tool_calls.is_empty()
                            && reasoning_message.content.trim().is_empty()
                        {
                            diag!("[LLM-CHAIN-STREAM] model returned EMPTY response");
                            diagnostic_note.get_or_insert_with(|| "模型流式响应为空，已回退到本地回复".to_string());
                            assistant_message.kind = "assistant-fallback".to_string();
                            assistant_message.content = local_agent_response(
                                agent,
                                &result.user_content,
                                result.attachment_count,
                                "模型流式响应为空",
                            );
                            assistant_started = true;
                            if cancellation.is_requested() {
                                terminal_status = ChatTurnStatus::Interrupted;
                                break 'chat_turn;
                            }
                            yield Ok(sse_json_event("message_replace", &assistant_message));
                        }
                        stream_context_assembly = Some(assembly);
                    }
                    Err(error) => {
                        if cancellation.is_requested() {
                            terminal_status = ChatTurnStatus::Interrupted;
                            break 'chat_turn;
                        }
                        diag!("[LLM-CHAIN-STREAM] model call FAILED: {error:?}");
                        let hint = real_model_error_hint(agent, &error);
                        diagnostic_note = Some(hint.clone());
                        assistant_message.kind = "assistant-fallback".to_string();
                        assistant_message.content = local_agent_response(
                            agent,
                            &result.user_content,
                            result.attachment_count,
                            &hint,
                        );
                        assistant_started = true;
                        if cancellation.is_requested() {
                            terminal_status = ChatTurnStatus::Interrupted;
                            break 'chat_turn;
                        }
                        yield Ok(sse_json_event("message_replace", &assistant_message));
                    }
                }
            }

            if cancellation.is_requested() {
                terminal_status = ChatTurnStatus::Interrupted;
                break 'chat_turn;
            }

            // REQ-LLM-003 / Phase C-13: tool result feedback loop（流"ToolResult 版）
            diag!(
                "[TOOL-LOOP-STREAM] gate: llm_tools_enabled={} tool_calls={} names=[{}] dispatched_already={}",
                llm_tools_enabled() && room_caps.1,
                model_tool_calls.len(),
                model_tool_calls
                    .values()
                    .map(|(_, name, _)| name.as_str())
                    .collect::<Vec<_>>()
                    .join(","),
                streamed_tool_calls_dispatched
            );
            if llm_tools_enabled() && room_caps.1 && !model_tool_calls.is_empty() {
                diag!(
                    "[TOOL-LOOP-STREAM] {} tool calls, round 2 (ToolResult blocks)...",
                    model_tool_calls.len()
                );

                // Round 1 assistant turn：所"ToolUse 原样回放给模型（id/name/input 对齐）。
                let mut assistant_tool_use_blocks: Vec<InputContentBlock> = Vec::new();
                let mut parsed_tool_calls: Vec<(String, String, JsonValue)> = Vec::new();
                if !reasoning_message.content.trim().is_empty() {
                    assistant_tool_use_blocks.push(InputContentBlock::Thinking {
                        thinking: reasoning_message.content.clone(),
                    });
                }
                for (_, (tool_use_id, name, arguments)) in &model_tool_calls {
                    let input = serde_json::from_str::<serde_json::Value>(arguments)
                        .unwrap_or_else(|_| json!({ "raw": arguments }));
                    assistant_tool_use_blocks.push(InputContentBlock::ToolUse {
                        id: tool_use_id.clone(),
                        name: name.clone(),
                        input: input.clone(),
                    });
                    parsed_tool_calls.push((tool_use_id.clone(), name.clone(), input));
                }
                emit_active_realtime_session_event(
                    "action_step",
                    json!({
                        "message_id": assistant_id.clone(),
                        "agent_id": agent.id.clone(),
                        "agent_name": agent.display_name.clone(),
                        "status": "dispatching",
                        "tool_call_count": parsed_tool_calls.len()
                    }),
                );
                let dispatches = match dispatch_model_tool_calls_parallel_with_cancel(
                    parsed_tool_calls,
                    "[TOOL-LOOP-STREAM]",
                    Some(agent.id.clone()),
                    Some(stream_turn_id.clone()),
                    Some(result.chat_room_id.clone()),
                    Arc::clone(&cancellation),
                )
                .await
                {
                    Ok(dispatches) => dispatches,
                    Err(_) => {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                };
                if cancellation.is_requested() {
                    terminal_status = ChatTurnStatus::Interrupted;
                    break 'chat_turn;
                }
                diag!(
                    "[TOOL-LOOP-STREAM] dispatch returned {} result(s): [{}]",
                    dispatches.len(),
                    dispatches
                        .iter()
                        .map(|d| format!(
                            "{}:{}",
                            d.tool_use_id,
                            if d.is_error { "err" } else { "ok" }
                        ))
                        .collect::<Vec<_>>()
                        .join(",")
                );
                streamed_tool_write_executed |= dispatches
                    .iter()
                    .any(model_tool_dispatch_result_executed_file_write);
                tool_result_summaries.extend(
                    dispatches
                        .iter()
                        .map(|dispatch| dispatch.summary_text.clone()),
                );
                let mut computer_use_terminal_failure = dispatches
                    .iter()
                    .find(|dispatch| {
                        dispatch.route == "computer-use-task-controller" && dispatch.is_error
                    })
                    .map(|dispatch| dispatch.summary_text.clone());
                let dispatch_error_count =
                    dispatches.iter().filter(|dispatch| dispatch.is_error).count();
                let dispatch_terminal_status = if dispatch_error_count == 0 {
                    "completed"
                } else {
                    "failed"
                };
                emit_active_realtime_session_event(
                    "action_step",
                    json!({
                        "message_id": assistant_id.clone(),
                        "agent_id": agent.id.clone(),
                        "agent_name": agent.display_name.clone(),
                        "status": dispatch_terminal_status,
                        "tool_call_count": dispatches.len(),
                        "error_count": dispatch_error_count
                    }),
                );
                let stream_turn_key = result
                    .messages
                    .first()
                    .map(|message| message.id.as_str())
                    .unwrap_or("stream-turn");
                let persisted_tool_messages = dispatches
                    .iter()
                    .flat_map(|dispatch| {
                        let status = if dispatch.is_error {
                            "failed"
                        } else {
                            "completed"
                        };
                        let call_summary = if dispatch.is_error {
                            format!(
                                "工具 `{}` 失败：{}",
                                dispatch.name, dispatch.summary_text
                            )
                        } else {
                            format!(
                                "工具 `{}` 已完成：{}",
                                dispatch.name, dispatch.summary_text
                            )
                        };
                        tool_messages_from_summary(
                            agent,
                            &dispatch.tool_use_id,
                            stream_turn_key,
                            &dispatch.name,
                            call_summary,
                            dispatch.tool_result_text.clone(),
                            status,
                            &dispatch.route,
                        )
                    })
                    .collect::<Vec<_>>();
                if cancellation.is_requested() {
                    terminal_status = ChatTurnStatus::Interrupted;
                    break 'chat_turn;
                }
                for message in persisted_tool_messages {
                    yield Ok(sse_json_event("message", &message));
                    messages.push(message);
                }
                let tool_result_blocks: Vec<InputContentBlock> = dispatches
                .into_iter()
                .map(|dispatch| InputContentBlock::ToolResult {
                    tool_use_id: dispatch.tool_use_id,
                    content: vec![ToolResultContentBlock::Text {
                        text: truncate_tool_result_for_context(dispatch.tool_result_text),
                    }],
                    is_error: dispatch.is_error,
                })
                .collect();
                streamed_tool_calls_dispatched = true;

                // 工具反馈轮必须延续首轮已经组装好的完整上下文。这里不能只重建
                // `current user + ToolUse + ToolResult`，否则聊天室历史、记忆、图片和
                // collaboration roster 会从 round2 起全部丢失。
                let (mut loop_messages, loop_system_prompt) =
                    if let Some(assembly) = stream_context_assembly.as_ref() {
                        (assembly.messages.clone(), assembly.system_prompt.clone())
                    } else {
                        (
                            vec![InputMessage::user_text(result.user_content.clone())],
                            build_agent_system_prompt(agent),
                        )
                    };
                loop_messages.push(InputMessage {
                    role: "assistant".to_string(),
                    content: assistant_tool_use_blocks,
                });
                loop_messages.push(InputMessage {
                    role: "user".to_string(),
                    content: tool_result_blocks,
                });
                // 多轮工具循环（round2+）：与非流式 call_agent_model_with_tool_loop 对齐。
                // 修复 CUR-GOAL-LOOP-001：此前流式只做单轮反馈，round2 模型再请求工具即被忽略，
                // 导致多步任务（建多文件 / 分步执行）必然 stall（"模型未返回最终回复"）。
                // round1 已流式执行并喂回；此处逐轮用非流式 send_message 推进，直到模型返回纯文本
                // 或达 max_feedback_rounds 上限。工具循环期间不流式 token（属"执行中"），最终整条回复。
                let max_rounds = tool_execution_policy().max_feedback_rounds.max(1) as u32;
                let mut multi_round_answer = String::new();
                let mut feedback_watchdog_hit = false;
                let mut last_loop_sig: Option<u64> = None;
                let mut loop_repeat: u32 = 0;
                let mut round_no: u32 = 2;
                loop {
                    if cancellation.is_requested() {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                    let request = agent_message_request_with_context_messages_for_room(
                        agent,
                        false,
                        &loop_system_prompt,
                        loop_messages.clone(),
                        Some(&result.chat_room_id),
                    );
                    let response = match provider_client_for_agent(agent) {
                        Ok(client) => match await_chat_turn(
                            cancellation.as_ref(),
                            client.send_message(&request),
                        )
                        .await
                        {
                            Err(_) => {
                                terminal_status = ChatTurnStatus::Interrupted;
                                break 'chat_turn;
                            }
                            Ok(Ok(resp)) => resp,
                            Ok(Err(e)) => {
                                diag!("[TOOL-LOOP-STREAM] round{round_no} send_message failed: {e:?}");
                                break;
                            }
                        },
                        Err(e) => {
                            diag!("[TOOL-LOOP-STREAM] round{round_no} provider_client failed: {e:?}");
                            break;
                        }
                    };
                    used_real_model = true;
                    if cancellation.is_requested() {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                    remember_largest_remote_usage(&mut best_remote_usage, &response.usage);
                    let tool_requests = model_tool_requests_from_blocks(&response.content);
                    if tool_requests.is_empty() {
                        multi_round_answer = answer_text(&response.content);
                        diag!(
                            "[TOOL-LOOP-STREAM] round{round_no} final reply, answer_len={}",
                            multi_round_answer.len()
                        );
                        break;
                    }
                    if let Some(last_summary) = computer_use_terminal_failure.as_deref() {
                        if tool_requests.iter().any(|(_, name, _)| {
                            is_computer_use_tool_family(name)
                        }) {
                            multi_round_answer =
                                computer_use_recursive_call_blocked_feedback(last_summary);
                            diag!(
                                "[TOOL-LOOP-STREAM] round{round_no} blocked cross-tool computer-use retry after terminal error"
                            );
                            break;
                        }
                    }
                    if round_no > max_rounds {
                        feedback_watchdog_hit = true;
                        multi_round_answer = tool_feedback_watchdog_message(
                            max_rounds as usize,
                            tool_requests.len(),
                        );
                        diag!(
                            "[TOOL-LOOP-STREAM] reached max rounds ({max_rounds}); stopping with {} pending tool call(s)",
                            tool_requests.len()
                        );
                        emit_active_realtime_session_event(
                            "action_step",
                            json!({
                                "message_id": assistant_id.clone(),
                                "agent_id": agent.id.clone(),
                                "agent_name": agent.display_name.clone(),
                                "status": "blocked",
                                "error_code": "tool_feedback_round_limit",
                                "pending_tool_call_count": tool_requests.len()
                            }),
                        );
                        break;
                    }
                    diag!(
                        "[TOOL-LOOP-STREAM] round{round_no}: {} tool call(s), dispatching...",
                        tool_requests.len()
                    );
                    // L1 空转纠偏：连续相同工具调用 → 注入纠偏提示（与非流式一致）。
                    let mut sig_parts: Vec<String> = response
                        .content
                        .iter()
                        .filter_map(|b| match b {
                            OutputContentBlock::ToolUse { name, input, .. } => {
                                Some(format!("{name}:{input}"))
                            }
                            _ => None,
                        })
                        .collect();
                    sig_parts.sort();
                    let sig = hash_bytes(sig_parts.join("|").as_bytes());
                    if last_loop_sig == Some(sig) {
                        loop_repeat += 1;
                    } else {
                        loop_repeat = 0;
                        last_loop_sig = Some(sig);
                    }
                    let dispatches = match dispatch_model_tool_calls_parallel_with_cancel(
                        tool_requests.clone(),
                        "[TOOL-LOOP-STREAM]",
                        Some(agent.id.clone()),
                        Some(stream_turn_id.clone()),
                        Some(result.chat_room_id.clone()),
                        Arc::clone(&cancellation),
                    )
                    .await
                    {
                        Ok(dispatches) => dispatches,
                        Err(_) => {
                            terminal_status = ChatTurnStatus::Interrupted;
                            break 'chat_turn;
                        }
                    };
                    if cancellation.is_requested() {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                    streamed_tool_write_executed |= dispatches
                        .iter()
                        .any(model_tool_dispatch_result_executed_file_write);
                    tool_result_summaries.extend(dispatches.iter().map(|d| d.summary_text.clone()));
                    if computer_use_terminal_failure.is_none() {
                        computer_use_terminal_failure = dispatches
                            .iter()
                            .find(|dispatch| {
                                dispatch.route == "computer-use-task-controller"
                                    && dispatch.is_error
                            })
                            .map(|dispatch| dispatch.summary_text.clone());
                    }
                    let stream_turn_key = result
                        .messages
                        .first()
                        .map(|message| message.id.as_str())
                        .unwrap_or("stream-turn");
                    let persisted_tool_messages = dispatches
                        .iter()
                        .flat_map(|dispatch| {
                            let status = if dispatch.is_error {
                                "failed"
                            } else {
                                "completed"
                            };
                            let call_summary = if dispatch.is_error {
                                format!(
                                    "工具 `{}` 失败：{}",
                                    dispatch.name, dispatch.summary_text
                                )
                            } else {
                                format!(
                                    "工具 `{}` 已完成：{}",
                                    dispatch.name, dispatch.summary_text
                                )
                            };
                            tool_messages_from_summary(
                                agent,
                                &dispatch.tool_use_id,
                                stream_turn_key,
                                &dispatch.name,
                                call_summary,
                                dispatch.tool_result_text.clone(),
                                status,
                                &dispatch.route,
                            )
                        })
                        .collect::<Vec<_>>();
                    if cancellation.is_requested() {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                    for message in persisted_tool_messages {
                        yield Ok(sse_json_event("message", &message));
                        messages.push(message);
                    }
                    let mut tr_blocks: Vec<InputContentBlock> = dispatches
                        .into_iter()
                        .map(|d| InputContentBlock::ToolResult {
                            tool_use_id: d.tool_use_id,
                            content: vec![ToolResultContentBlock::Text {
                                text: truncate_tool_result_for_context(d.tool_result_text),
                            }],
                            is_error: d.is_error,
                        })
                        .collect();
                    if loop_repeat >= 1 {
                        let any_error = tr_blocks.iter().any(|b| {
                            matches!(b, InputContentBlock::ToolResult { is_error: true, .. })
                        });
                        diag!(
                            "[TOOL-LOOP-STREAM] L1 supervisor: round{round_no} repeats identical tool call(s) (repeat={loop_repeat}, any_error={any_error}); injecting course-correction."
                        );
                        tr_blocks.push(InputContentBlock::Text {
                            text: format!(
                                "[Runtime supervisor] 你已连续 {} 次发出完全相同的工具调用{}，没有进展。请立即改变做法：换参数、换工具，或明确报告阻塞点，不要再重复同样的调用。",
                                loop_repeat + 1,
                                if any_error { "且持续失败" } else { "" }
                            ),
                        });
                    }
                    let assistant_tu = InputMessage {
                        role: "assistant".to_string(),
                        content: response
                            .content
                            .iter()
                            .filter_map(|b| match b {
                                OutputContentBlock::ToolUse { id, name, input } => {
                                    Some(InputContentBlock::ToolUse {
                                        id: id.clone(),
                                        name: name.clone(),
                                        input: input.clone(),
                                    })
                                }
                                OutputContentBlock::Thinking { thinking, .. } => {
                                    Some(InputContentBlock::Thinking {
                                        thinking: thinking.clone(),
                                    })
                                }
                                _ => None,
                            })
                            .collect(),
                    };
                    loop_messages.push(assistant_tu);
                    loop_messages.push(InputMessage {
                        role: "user".to_string(),
                        content: tr_blocks,
                    });
                    round_no += 1;
                }
                assistant_message.content.clear();
                assistant_message.kind = "assistant-reply".to_string();
                assistant_started = true;
                if !multi_round_answer.trim().is_empty() {
                    assistant_message.content = multi_round_answer;
                } else if feedback_watchdog_hit {
                    assistant_message.content =
                        tool_feedback_watchdog_message(max_rounds as usize, 1);
                } else if !tool_result_summaries.is_empty() {
                    // 多轮后模型仍无文字总结：用工具结果摘要兜底（比单轮"未返回最终回复"信息更全）。
                    assistant_message.content = format!(
                        "已执行 {} 步工具操作完成本轮任务，但模型未返回最终文字总结。已完成的工具结果摘要：\n{}",
                        tool_result_summaries.len(),
                        tool_result_summaries.join("\n")
                    );
                }
                if cancellation.is_requested() {
                    terminal_status = ChatTurnStatus::Interrupted;
                    break 'chat_turn;
                }
                yield Ok(sse_json_event("message_replace", &assistant_message));
                used_real_model = true;
                diag!(
                    "[TOOL-LOOP-STREAM] multi-round done: rounds_used={} answer_len={}",
                    round_no,
                    assistant_message.content.len()
                );
            }

            let formal_computer_use_intent = text_has_computer_use_intent(&result.user_content);
            let mut has_pending_stream_model_tool_calls = !model_tool_calls.is_empty();
            if !streamed_tool_calls_dispatched
                && !has_pending_stream_model_tool_calls
                && formal_computer_use_intent
            {
                if let Some((tool_use_id, tool_name, tool_input)) =
                    formal_computer_use_tool_request_from_intent(&result.user_content)
                {
                    diag!(
                        "[TOOL-LOOP-STREAM] formal computer-use intent produced no streamed tool_use; forcing {tool_name}"
                    );
                    model_tool_calls.insert(0, (tool_use_id, tool_name, tool_input.to_string()));
                    has_pending_stream_model_tool_calls = true;
                }
            }
            diag!(
                "[TOOL-LOOP-STREAM] post-loop: dispatched={} pending_tool_calls={}",
                streamed_tool_calls_dispatched,
                model_tool_calls.len()
            );
            if !streamed_tool_calls_dispatched {
                for (_, (tool_use_id, tool_name, tool_input)) in model_tool_calls {
                    if cancellation.is_requested() {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                    let tool_input = serde_json::from_str(&tool_input)
                        .unwrap_or_else(|_| json!({ "raw": tool_input }));
                    update_active_realtime_session_states(Some("tool_calling"), None);
                    emit_active_realtime_session_event(
                        "action_step",
                        json!({
                            "message_id": assistant_id.clone(),
                            "agent_id": agent.id.clone(),
                            "agent_name": agent.display_name.clone(),
                            "tool_name": tool_name.clone(),
                            "status": "dispatching",
                            "input": tool_input.clone()
                        }),
                    );
                    let tool_messages = match await_chat_turn(
                        cancellation.as_ref(),
                        run_model_tool_use_messages(
                            agent,
                            &tool_use_id,
                            &tool_name,
                            &tool_input,
                            Some(&stream_turn_id),
                            Some(&result.chat_room_id),
                        ),
                    )
                    .await
                    {
                        Ok(messages) => messages,
                        Err(_) => {
                            terminal_status = ChatTurnStatus::Interrupted;
                            break 'chat_turn;
                        }
                    };
                    if cancellation.is_requested() {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                    let tool_message = tool_messages
                        .first()
                        .cloned()
                        .unwrap_or_else(|| ChatMessageDto {
                            id: format!("tool-call-{}", unix_timestamp_millis()),
                            author: "系统工具执行 Agent".to_string(),
                            role: "assistant".to_string(),
                            target: agent.display_name.clone(),
                            content: "工具调用未返回可显示结果".to_string(),
                            kind: "tool-summary".to_string(),
                            attachments: Vec::new(),
                        });
                    yield Ok(sse_json_event("message", &tool_message));
                    emit_active_realtime_session_event(
                        "action_step",
                        json!({
                            "message_id": assistant_id.clone(),
                            "agent_id": agent.id.clone(),
                            "agent_name": agent.display_name.clone(),
                            "tool_name": tool_name,
                            "status": "completed",
                            "summary": compact_message_snippet(&tool_message.content, 240)
                        }),
                    );
                    tool_result_summaries.push(tool_message.content.clone());
                    for message in tool_messages {
                        if message.id != tool_message.id {
                            yield Ok(sse_json_event("message", &message));
                        }
                        messages.push(message);
                    }
                }
            }
            // 同上：纯视觉理解不触发 computer-use 动作，仅视觉动作意图 / 工具意图才执行。
            let semantic_tool_side_route = should_run_semantic_tool_side_route(
                result.calls_vision,
                result.calls_tool,
                &result.user_content,
            );
            if semantic_tool_side_route
                && !streamed_tool_write_executed
                && !has_pending_stream_model_tool_calls
                && !formal_computer_use_intent
            {
                if cancellation.is_requested() {
                    terminal_status = ChatTurnStatus::Interrupted;
                    break 'chat_turn;
                }
                let semantic_tool_message = match await_chat_turn(
                    cancellation.as_ref(),
                    run_tool_intent_message(agent, &result.user_content),
                )
                .await
                {
                    Ok(message) => message,
                    Err(_) => {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                };
                if cancellation.is_requested() {
                    terminal_status = ChatTurnStatus::Interrupted;
                    break 'chat_turn;
                }
                if let Some(tool_message) = semantic_tool_message {
                    update_active_realtime_session_states(Some("tool_calling"), None);
                    emit_active_realtime_session_event(
                        "action_step",
                        json!({
                            "message_id": assistant_id.clone(),
                            "agent_id": agent.id.clone(),
                            "agent_name": agent.display_name.clone(),
                            "tool_name": "semantic_intent",
                            "status": "completed",
                            "summary": compact_message_snippet(&tool_message.content, 240)
                        }),
                    );
                    yield Ok(sse_json_event("message", &tool_message));
                    tool_result_summaries.push(tool_message.content.clone());
                    messages.push(tool_message);
                }
            }

            if cancellation.is_requested() {
                terminal_status = ChatTurnStatus::Interrupted;
                break 'chat_turn;
            }
            if let Some(assembly) = stream_context_assembly.as_ref() {
                let policy = context_lifecycle_policy();
                let snapshot = context_usage_snapshot_for_assembly_with_usage(
                    agent,
                    assembly,
                    best_remote_usage.as_ref(),
                    policy,
                );
                context_footer = Some(context_usage_footer_for_snapshot(assembly, &snapshot, policy));
                context_usage = Some(snapshot);
            }

            let fallback_reason = diagnostic_note
                .as_deref()
                .unwrap_or("模型未产生可显示回复");
            if cancellation.is_requested() {
                terminal_status = ChatTurnStatus::Interrupted;
                break 'chat_turn;
            }
            ensure_assistant_message_visible_content(
                &mut assistant_message,
                local_agent_response(
                    agent,
                    &result.user_content,
                    result.attachment_count,
                    fallback_reason,
                ),
                &reasoning_message.content,
                &tool_result_summaries,
                &mut diagnostic_note,
            );
            if let Some(delta) =
                append_context_footer(&mut assistant_message.content, context_footer.as_deref())
            {
                if assistant_started {
                    yield Ok(sse_json_event("message_delta", &ChatStreamDelta {
                        id: assistant_id.clone(),
                        kind: assistant_message.kind.clone(),
                        delta,
                    }));
                } else {
                    yield Ok(sse_json_event("message_replace", &assistant_message));
                }
            }
            if cancellation.is_requested() {
                terminal_status = ChatTurnStatus::Interrupted;
                break 'chat_turn;
            }
            assistant_message.content =
                sanitize_visible_model_text(agent, &assistant_message.content);
            reasoning_message.content =
                sanitize_visible_model_text(agent, &reasoning_message.content);
            if !reasoning_message.content.trim().is_empty() {
                messages.push(reasoning_message.clone());
            }
            messages.push(assistant_message.clone());
            update_active_realtime_session_states(Some("idle"), None);
            emit_active_realtime_session_event(
                "assistant_done",
                json!({
                    "message_id": assistant_id.clone(),
                    "agent_id": agent.id.clone(),
                    "agent_name": agent.display_name.clone(),
                    "kind": assistant_message.kind.clone(),
                    "content": compact_message_snippet(&assistant_message.content, 1200),
                    "content_len": assistant_message.content.chars().count(),
                    "used_real_model": used_real_model
                }),
            );
            yield Ok(sse_json_event("message_done", &assistant_message));
            if cancellation.is_requested() {
                terminal_status = ChatTurnStatus::Interrupted;
                break 'chat_turn;
            }
            auto_handoff_candidates.push(AutoHandoffCandidate {
                from_agent_id: agent.id.clone(),
                assistant_message_id: assistant_message.id.clone(),
                content: assistant_message.content.clone(),
            });

            if cancellation.is_requested() {
                terminal_status = ChatTurnStatus::Interrupted;
                break 'chat_turn;
            }
            let context_lifecycle = match apply_context_lifecycle_for_agent(
                &agent.id,
                &result.chat_room_id,
                context_usage.as_ref(),
            ) {
                Ok(result) => result,
                Err(error) => {
                    diag!(
                        "[CONTEXT-LIFECYCLE] stream apply failed for agent={} room={}: {}",
                        agent.id,
                        result.chat_room_id,
                        error.1.error
                    );
                    ContextLifecycleResult::default()
                }
            };
            if cancellation.is_requested() {
                terminal_status = ChatTurnStatus::Interrupted;
                break 'chat_turn;
            }

            tasks.push(agent_task(
                agent,
                &task_id,
                used_real_model,
                diagnostic_note.clone(),
            ));
            if let Some(task) = context_lifecycle_task(agent, &task_id, &context_lifecycle) {
                tasks.push(task);
            }
            append_semantic_tool_tasks(
                &mut tasks,
                agent,
                &task_id,
                result.calls_vision,
                result.calls_tool && semantic_tool_side_route,
            );
        }

        let db_path = default_session_sqlite_path();
        let workspace = active_workspace_path();
        let workspace_id = workspace_identity(&workspace);
        if cancellation.is_requested() {
            terminal_status = ChatTurnStatus::Interrupted;
            break 'chat_turn;
        }
        let goal_consultation = append_goal_trigger_consultation(
            &db_path,
            &workspace_id,
            &result,
            &mut messages,
            &mut tasks,
        );
        if cancellation.is_requested() {
            terminal_status = ChatTurnStatus::Interrupted;
            break 'chat_turn;
        }
        match goal_consultation {
            Ok(goal_messages) => {
                for message in goal_messages {
                    if cancellation.is_requested() {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                    yield Ok(sse_json_event("message", &message));
                }
            }
            Err(error) => {
                if cancellation.is_requested() {
                    terminal_status = ChatTurnStatus::Interrupted;
                    break 'chat_turn;
                }
                let message = append_goal_trigger_error_message(&error, &mut messages, &mut tasks);
                yield Ok(sse_json_event("message", &message));
            }
        }

        if cancellation.is_requested() {
            terminal_status = ChatTurnStatus::Interrupted;
            break 'chat_turn;
        }
        let new_messages = messages
            .iter()
            .skip(initial_message_count)
            .cloned()
            .collect::<Vec<_>>();
        if let Err(error) = persist_chat_dispatch(
            &result.chat_room_id,
            result.conversation_session_id.as_deref(),
            &result.targets,
            new_messages,
        ) {
            let message = format!("消息持久化失败: {}", error.1.error);
            emit_backend_pet_event("chat.failed", Some(&message), "chat");
            yield Ok(sse_json_event("error", &ChatStreamError { message }));
            terminal_status = ChatTurnStatus::Failed;
            break 'chat_turn;
        }
        if cancellation.is_requested() {
            terminal_status = ChatTurnStatus::Interrupted;
            break 'chat_turn;
        }
        match process_auto_handoff_candidates(&result.chat_room_id, &auto_handoff_candidates) {
            Ok(auto_handoffs) => {
                for handoff in auto_handoffs {
                    if cancellation.is_requested() {
                        terminal_status = ChatTurnStatus::Interrupted;
                        break 'chat_turn;
                    }
                    if let Some(inbound) = handoff.inbound_message {
                        let dto = chat_message_dto_from_persisted(&inbound);
                        yield Ok(sse_json_event("message", &dto));
                        messages.push(dto);
                    }
                }
            }
            Err(error) => {
                let message = format!("handoff dispatch failed: {}", error.1.error);
                emit_backend_pet_event("chat.failed", Some(&message), "chat");
                yield Ok(sse_json_event("error", &ChatStreamError { message }));
                terminal_status = ChatTurnStatus::Failed;
                break 'chat_turn;
            }
        }

        if cancellation.is_requested() {
            terminal_status = ChatTurnStatus::Interrupted;
            break 'chat_turn;
        }
        persist_auto_memory_beads(&messages);
        persist_reference_forward_memory(&result.reference_context, &result.targets);
        persist_group_send_shared_memory(&result.reference_context, &result.targets);

        }
        let status = turn_guard.finish(if cancellation.is_requested() {
            ChatTurnStatus::Interrupted
        } else {
            terminal_status
        });
        if status == ChatTurnStatus::Completed {
            emit_backend_pet_event(
                "chat.completed",
                Some("Chat stream completed"),
                "chat",
            );
        }
        let mut chat_stream_done = chat_stream_done(&result, &turn_id, status, tasks);
        chat_stream_done.run_id = Some(run_id.clone());
        yield Ok(sse_json_event(
            "done",
            &chat_stream_done,
        ));
    };

    Ok(Sse::new(stream))
}

async fn api_agent_diagnostics(
    AxumPath(agent_id): AxumPath<String>,
) -> ApiResult<Json<AgentDiagnosticsResponse>> {
    let session = {
        let store = session_store()
            .lock()
            .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
        store.find_session(&agent_id).cloned()
    }
    .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "会话不存"))?;

    Ok(Json(agent_diagnostics_for_session(&session)))
}

async fn api_diagnostics_health() -> Json<DiagnosticsHealthResponse> {
    Json(build_diagnostics_health().await)
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct ProviderReadinessCounts {
    total: usize,
    ready: usize,
    warn: usize,
    error: usize,
}

fn provider_readiness_counts<'a>(
    statuses: impl IntoIterator<Item = &'a str>,
) -> ProviderReadinessCounts {
    let mut counts = ProviderReadinessCounts::default();
    for status in statuses {
        counts.total += 1;
        match status {
            "ok" => counts.ready += 1,
            "warn" => counts.warn += 1,
            "error" => counts.error += 1,
            _ => counts.warn += 1,
        }
    }
    counts
}

fn functional_config_check_for(
    real_llm_enabled: bool,
    llm_tools_enabled: bool,
    semantic_memory_enabled: bool,
    computer_use_enabled: bool,
    providers: ProviderReadinessCounts,
) -> DiagnosticsCheck {
    let model_capabilities_ok = real_llm_enabled && llm_tools_enabled && computer_use_enabled;
    let provider_session_ready = providers.ready > 0;
    let status = if model_capabilities_ok && provider_session_ready {
        "ok"
    } else {
        "warn"
    };
    let fix_hint = if !model_capabilities_ok {
        Some("开启 [model] enable_real_llm/enable_llm_tools 与 [computer_use] enabled")
    } else if real_llm_enabled && !provider_session_ready {
        Some("检查可选择会话的 provider/model/base_url 与会话凭据配置")
    } else {
        None
    };

    diagnostics_check(
        "functional.config",
        "默认能力配置",
        status,
        &format!(
            "real_llm={real_llm_enabled} llm_tools={llm_tools_enabled} semantic_memory={semantic_memory_enabled} computer_use={computer_use_enabled}；会话 provider={}/{} ready（{} warn，{} error；仅展示就绪计数）",
            providers.ready, providers.total, providers.warn, providers.error
        ),
        fix_hint,
    )
}

/// 只读常用功能自检：验证本地链路与配置，不调用真实模型、麦克风或桌面输入。
async fn api_diagnostics_functional() -> Json<FunctionalDiagnosticsResponse> {
    let workspace = active_workspace_path();
    let config = load_workspace_config_at(&workspace);
    let mut checks = Vec::new();
    let provider_health = default_agent_sessions()
        .into_iter()
        .filter(|agent| agent.selectable && agent.enabled)
        .map(|agent| agent_health(&agent))
        .collect::<Vec<_>>();
    let provider_readiness = provider_readiness_counts(
        provider_health
            .iter()
            .map(|agent| agent.provider_status.as_str()),
    );
    checks.push(functional_config_check_for(
        config.model.enable_real_llm,
        config.model.enable_llm_tools,
        config.model.enable_semantic_memory,
        config.computer_use.enabled,
        provider_readiness,
    ));

    let mut add = |id: &str, label: &str, status: &str, detail: String, fix_hint: Option<&str>| {
        checks.push(DiagnosticsCheck {
            id: id.to_string(),
            label: label.to_string(),
            status: status.to_string(),
            detail,
            fix_hint: fix_hint.map(str::to_string),
        });
    };
    let workspace_status = if workspace.is_dir() { "ok" } else { "error" };
    add(
        "functional.workspace",
        "工作区读写边界",
        workspace_status,
        format!("workspace={}", display_path(&workspace)),
        Some("请在设置中选择有效工作区"),
    );
    let session_db = default_session_sqlite_path();
    let session_status = if session_db.exists() { "ok" } else { "warn" };
    add(
        "functional.session-store",
        "会话存储",
        session_status,
        format!("sqlite={}（首次使用会自动创建）", session_db.display()),
        None,
    );
    let room_count = session_store()
        .lock()
        .ok()
        .map(|store| store.state.chat_rooms.len())
        .unwrap_or(0);
    add(
        "functional.chat-room",
        "聊天室寻址",
        if room_count > 0 { "ok" } else { "warn" },
        format!("已配置 {} 个聊天室；诊断设置按 room_id 隔离", room_count),
        Some("请新建或选择聊天室"),
    );
    let catalog = build_tools_catalog();
    add(
        "functional.tools",
        "工具目录",
        if catalog.summary.items > 0 {
            "ok"
        } else {
            "warn"
        },
        format!(
            "{} 类 / {} 项，当前可执行 {} 项",
            catalog.summary.categories, catalog.summary.items, catalog.summary.executable_now
        ),
        None,
    );
    let active_room_id = session_store()
        .lock()
        .ok()
        .and_then(|store| store.active_chat_room_id());
    if let Some(room_id) = active_room_id.as_deref() {
        if let Ok((room_real_llm, room_tools, room_computer_use)) =
            chat_room_capabilities_sqlite(&default_session_sqlite_path(), room_id)
        {
            add(
                "functional.chat-room-capabilities",
                "聊天室有效能力",
                "ok",
                format!("room={} real_llm={} llm_tools={} computer_use={}；权限档位仍由 /permissions 审批", room_id, room_real_llm, room_tools, room_computer_use),
                None,
            );
        }
    }
    add(
        "functional.stream-guard",
        "流式中断看护",
        "warn",
        "前端 AbortController + SSE error 事件 + 后端 diagnostic_note 契约可用；本次自检未注入真实网络中断，需人工点击停止复核".to_string(),
        Some("运行流式自检并在发送中点击停止，确认原因可见且不递归重试"),
    );
    let browser_health = browser_bridge::health();
    let browser_status = if browser_health.connected {
        "ok"
    } else {
        "error"
    };
    add(
        "functional.browser",
        "浏览器桥接",
        browser_status,
        format!(
            "connected={} setup_required={} nonce_file={}；真实网页操作仍需聊天室授权/用户审批",
            browser_health.connected, browser_health.setup_required, browser_health.nonce_file
        ),
        Some("安装并连接浏览器扩展/native host，或在聊天室诊断设置中保持 computer-use 关闭"),
    );
    let summary = DiagnosticsSummary {
        status: aggregate_health_status(&checks),
        ok: checks.iter().filter(|item| item.status == "ok").count(),
        warn: checks.iter().filter(|item| item.status == "warn").count(),
        error: checks.iter().filter(|item| item.status == "error").count(),
    };
    Json(FunctionalDiagnosticsResponse {
        generated_at: unix_timestamp_millis(),
        summary,
        checks,
        note: "自检是只读、可重复、无外部副作用的本地检查；模型/STT/TTS/桌面输入需单独人工验收。"
            .to_string(),
    })
}

/// 流式中断自检不发起模型请求，只核验取消/可见原因/递归看护契约。
async fn api_diagnostics_stream() -> Json<StreamDiagnosticsResponse> {
    Json(StreamDiagnosticsResponse {
        generated_at: unix_timestamp_millis(),
        status: "ok".to_string(),
        cancellation_supported: true,
        abort_reason_visible: true,
        recursion_guarded: true,
        note: "AbortController 与 SSE reader 均可取消；用户停止、网络中断和缺失 done 事件会显示原因，异常不会自动递归重试。".to_string(),
    })
}

/// harness 运行时指标计数器：L1 监管触发次数、幂等命中次数（进程级，重启清零）。
static HARNESS_L1_TRIGGERS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
static HARNESS_IDEMPOTENT_HITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

#[derive(Debug, Serialize)]
struct HarnessMetricsResponse {
    /// goal_events 聚合（跨所有 goal）。
    command_gate_failures: i64,
    verification_blocks: i64,
    replan_requests: i64,
    escalations: i64,
    /// 运行时计数器。
    l1_supervisor_triggers: u64,
    idempotent_request_hits: u64,
}

/// harness 效果指标：聚合 goal_events 关键事件 + 运行时计数器（L1 监管触发、请求幂等命中）。
/// 供观测 harness 优化效果（门控失败/回退/重试/监管/弱网去重的发生频率）。
async fn api_harness_metrics() -> ApiResult<Json<HarnessMetricsResponse>> {
    let path = {
        let store = session_store().lock().map_err(|_| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "session store lock poisoned",
            )
        })?;
        store.path.clone()
    };
    let connection = open_session_connection(&path).map_err(sqlite_api_error)?;
    initialize_session_schema(&connection).map_err(sqlite_api_error)?;
    let mut counts: HashMap<String, i64> = HashMap::new();
    if let Ok(mut stmt) =
        connection.prepare("SELECT event_type, COUNT(*) FROM goal_events GROUP BY event_type")
    {
        if let Ok(rows) = stmt.query_map([], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?))
        }) {
            for row in rows.flatten() {
                counts.insert(row.0, row.1);
            }
        }
    }
    let get = |key: &str| counts.get(key).copied().unwrap_or(0);
    Ok(Json(HarnessMetricsResponse {
        command_gate_failures: get("goal-phase-command-gate-failed"),
        verification_blocks: get("goal-phase-verification-blocked"),
        replan_requests: get("goal-phase-blocked-needs-replan"),
        // GL-05/06：blocked（超重试上限）是新的升级信号；旧的两个 attention 事件已不再产生，
        // 保留在和式里只为回看历史计数。
        escalations: get("goal-phase-replan-escalated")
            + get("goal-phase-blocked")
            + get("goal-phase-verification-attention-required")
            + get("goal-phase-command-gate-attention-required"),
        l1_supervisor_triggers: HARNESS_L1_TRIGGERS.load(std::sync::atomic::Ordering::Relaxed),
        idempotent_request_hits: HARNESS_IDEMPOTENT_HITS.load(std::sync::atomic::Ordering::Relaxed),
    }))
}

