fn mcp_servers_config_path() -> PathBuf {
    active_workspace_path()
        .join(".coolzhu")
        .join("mcp_servers.json")
}

fn load_mcp_server_configs() -> Vec<McpServerConfig> {
    let path = mcp_servers_config_path();
    if let Ok(text) = std::fs::read_to_string(&path) {
        match serde_json::from_str::<Vec<McpServerConfig>>(&text) {
            Ok(list) => return list,
            Err(error) => diag!("[MCP] workspace mcp_servers.json 解析失败，回退内置清单: {error}"),
        }
    }
    serde_json::from_str(DEFAULT_MCP_SERVERS_JSON).unwrap_or_default()
}

struct McpRuntime {
    child: tokio::process::Child,
    stdin: tokio::process::ChildStdin,
    rx: tokio::sync::mpsc::UnboundedReceiver<String>,
    next_id: u64,
    server_info: JsonValue,
    tools: Vec<JsonValue>,
}

fn mcp_runtimes() -> &'static tokio::sync::Mutex<std::collections::HashMap<String, McpRuntime>> {
    static RUNTIMES: OnceLock<tokio::sync::Mutex<std::collections::HashMap<String, McpRuntime>>> =
        OnceLock::new();
    RUNTIMES.get_or_init(|| tokio::sync::Mutex::new(std::collections::HashMap::new()))
}

/// 发送 JSON-RPC 请求并等待匹配 id 的响应（单连接串行调用；其它 id/通知行忽略）。
async fn mcp_send_request(
    runtime: &mut McpRuntime,
    method: &str,
    params: JsonValue,
) -> Result<JsonValue, String> {
    use tokio::io::AsyncWriteExt;
    runtime.next_id += 1;
    let id = runtime.next_id;
    let message = json!({"jsonrpc": "2.0", "id": id, "method": method, "params": params});
    let line = format!("{message}\n");
    runtime
        .stdin
        .write_all(line.as_bytes())
        .await
        .map_err(|error| format!("MCP stdin 写入失败: {error}"))?;
    runtime
        .stdin
        .flush()
        .await
        .map_err(|error| format!("MCP stdin flush 失败: {error}"))?;
    // initialize 首次可能触发 npx/uv 拉包 + python wrapper 装依赖，给更宽的窗口。
    let timeout_secs = if method == "initialize" { 180 } else { 60 };
    let deadline = tokio::time::Instant::now() + Duration::from_secs(timeout_secs);
    loop {
        let remaining = deadline.saturating_duration_since(tokio::time::Instant::now());
        if remaining.is_zero() {
            return Err(format!("MCP 请求超时: {method}"));
        }
        let next_line = tokio::time::timeout(remaining, runtime.rx.recv())
            .await
            .map_err(|_| format!("MCP 请求超时: {method}"))?
            .ok_or_else(|| "MCP server 输出流已关闭".to_string())?;
        let value: JsonValue = match serde_json::from_str(next_line.trim()) {
            Ok(value) => value,
            Err(_) => continue,
        };
        if value.get("id").and_then(JsonValue::as_u64) == Some(id) {
            if let Some(error) = value.get("error") {
                return Err(format!("MCP error: {error}"));
            }
            return Ok(value.get("result").cloned().unwrap_or(JsonValue::Null));
        }
    }
}

async fn mcp_send_notification(
    runtime: &mut McpRuntime,
    method: &str,
    params: JsonValue,
) -> Result<(), String> {
    use tokio::io::AsyncWriteExt;
    let message = json!({"jsonrpc": "2.0", "method": method, "params": params});
    let line = format!("{message}\n");
    runtime
        .stdin
        .write_all(line.as_bytes())
        .await
        .map_err(|error| format!("MCP stdin 写入失败: {error}"))?;
    runtime
        .stdin
        .flush()
        .await
        .map_err(|error| error.to_string())
}

/// 拉起 stdio MCP server 并完成 MCP 握手（initialize → initialized → tools/list）。
async fn mcp_connect_server(config: &McpServerConfig) -> Result<McpRuntime, String> {
    if config.transport != "stdio" {
        return Err(format!(
            "暂不支持 transport={}（HTTP 接入为 M2 范围）",
            config.transport
        ));
    }
    let mut command = Command::new(&config.command);
    command.args(&config.args);
    // 相对路径配置（例如 Obsidian vault）统一以用户当前 workspace 解析，
    // 避免继承安装目录或开发机启动目录。
    command.current_dir(active_workspace_path());
    for (key, value) in &config.env {
        command.env(key, value);
    }
    command
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    command.creation_flags(CREATE_NO_WINDOW);
    let mut child = command
        .spawn()
        .map_err(|error| format!("MCP server 启动失败({}): {error}", config.command))?;
    let stdin = child
        .stdin
        .take()
        .ok_or_else(|| "无法获取 MCP server stdin".to_string())?;
    let stdout = child
        .stdout
        .take()
        .ok_or_else(|| "无法获取 MCP server stdout".to_string())?;
    let stderr = child.stderr.take();

    let (tx, rx) = tokio::sync::mpsc::unbounded_channel();
    tokio::spawn(async move {
        use tokio::io::{AsyncBufReadExt, BufReader};
        let mut lines = BufReader::new(stdout).lines();
        while let Ok(Some(line)) = lines.next_line().await {
            if tx.send(line).is_err() {
                break;
            }
        }
    });
    if let Some(stderr) = stderr {
        let server_id = config.id.clone();
        tokio::spawn(async move {
            use tokio::io::{AsyncBufReadExt, BufReader};
            let mut lines = BufReader::new(stderr).lines();
            while let Ok(Some(line)) = lines.next_line().await {
                diag!(
                    "[MCP:{server_id}] stderr: {}",
                    line.chars().take(300).collect::<String>()
                );
            }
        });
    }

    let mut runtime = McpRuntime {
        child,
        stdin,
        rx,
        next_id: 0,
        server_info: JsonValue::Null,
        tools: Vec::new(),
    };
    let init_result = mcp_send_request(
        &mut runtime,
        "initialize",
        json!({
            "protocolVersion": "2025-06-18",
            "capabilities": {},
            "clientInfo": {"name": "coolzhu-mcp-host", "version": "0.1.0"}
        }),
    )
    .await?;
    runtime.server_info = init_result
        .get("serverInfo")
        .cloned()
        .unwrap_or(JsonValue::Null);
    mcp_send_notification(&mut runtime, "notifications/initialized", json!({})).await?;
    let tools_result = mcp_send_request(&mut runtime, "tools/list", json!({})).await?;
    runtime.tools = tools_result
        .get("tools")
        .and_then(JsonValue::as_array)
        .cloned()
        .unwrap_or_default();
    diag!(
        "[MCP:{}] connected: server_info={} tools={}",
        config.id,
        runtime.server_info,
        runtime.tools.len()
    );
    Ok(runtime)
}

async fn api_mcp_servers() -> Json<JsonValue> {
    let configs = load_mcp_server_configs();
    let runtimes = mcp_runtimes().lock().await;
    let servers = configs
        .iter()
        .map(|config| {
            json!({
                "id": config.id,
                "name": config.name,
                "category": config.category,
                "command": format!("{} {}", config.command, config.args.join(" ")),
                "transport": config.transport,
                "enabled": config.enabled,
                "notes": config.notes,
                "connected": runtimes.contains_key(&config.id),
                "tool_count": runtimes.get(&config.id).map_or(0, |runtime| runtime.tools.len()),
            })
        })
        .collect::<Vec<_>>();
    Json(json!({
        "servers": servers,
        "config_path": mcp_servers_config_path().display().to_string(),
    }))
}

async fn api_mcp_server_connect(
    AxumPath(server_id): AxumPath<String>,
) -> ApiResult<Json<JsonValue>> {
    let config = load_mcp_server_configs()
        .into_iter()
        .find(|config| config.id == server_id)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "MCP server 配置不存在"))?;
    let mut runtimes = mcp_runtimes().lock().await;
    if let Some(mut previous) = runtimes.remove(&server_id) {
        let _ = previous.child.kill().await;
    }
    let runtime = mcp_connect_server(&config)
        .await
        .map_err(|error| api_error(StatusCode::BAD_GATEWAY, &error))?;
    let tools = runtime
        .tools
        .iter()
        .map(|tool| {
            json!({
                "name": tool.get("name").and_then(JsonValue::as_str).unwrap_or(""),
                "description": tool
                    .get("description")
                    .and_then(JsonValue::as_str)
                    .unwrap_or("")
                    .chars()
                    .take(160)
                    .collect::<String>(),
            })
        })
        .collect::<Vec<_>>();
    let server_info = runtime.server_info.clone();
    let tool_count = tools.len();
    runtimes.insert(server_id.clone(), runtime);
    Ok(Json(json!({
        "connected": true,
        "server_id": server_id,
        "server_info": server_info,
        "tool_count": tool_count,
        "tools": tools,
    })))
}

async fn api_mcp_server_disconnect(AxumPath(server_id): AxumPath<String>) -> Json<JsonValue> {
    let mut runtimes = mcp_runtimes().lock().await;
    if let Some(mut runtime) = runtimes.remove(&server_id) {
        let _ = runtime.child.kill().await;
        Json(json!({"disconnected": true, "server_id": server_id}))
    } else {
        Json(json!({"disconnected": false, "server_id": server_id, "error": "未连接"}))
    }
}

#[derive(Debug, Deserialize)]
struct McpCallRequest {
    server_id: String,
    tool: String,
    #[serde(default)]
    arguments: JsonValue,
}

/// tools/call 转发：写/破坏性工具的授权门控由调用方（聊天工具链 / 前端确认）负责，
/// 本端点是 MCP Host 的原始通道（预装调试用）。
async fn api_mcp_call(Json(request): Json<McpCallRequest>) -> ApiResult<Json<JsonValue>> {
    let started = Instant::now();
    let mut runtimes = mcp_runtimes().lock().await;
    let runtime = runtimes.get_mut(&request.server_id).ok_or_else(|| {
        api_error(
            StatusCode::BAD_REQUEST,
            "MCP server 未连接：先 POST /api/mcp/servers/{id}/connect",
        )
    })?;
    let arguments = if request.arguments.is_null() {
        json!({})
    } else {
        request.arguments.clone()
    };
    let result = mcp_send_request(
        runtime,
        "tools/call",
        json!({"name": request.tool, "arguments": arguments}),
    )
    .await
    .map_err(|error| api_error(StatusCode::BAD_GATEWAY, &error))?;
    Ok(Json(json!({
        "server_id": request.server_id,
        "tool": request.tool,
        "result": result,
        "elapsed_ms": elapsed_millis(started),
    })))
}

/// MCP/SKILL 安装（P1）：本项目 plugin/skill 为本地源（plugin_source_roots / skills 目录），
/// 加载即可用——这里校验并返回"已就绪"提示，为 P2 远程 marketplace 拉取到 scope 目录预留接口。
async fn api_plugins_install(
    Json(payload): Json<PluginInstallRequest>,
) -> ApiResult<Json<PluginInstallResponse>> {
    let scope = payload.scope.as_deref().unwrap_or("user");
    if payload.id.trim().is_empty() {
        return Err(api_error(StatusCode::BAD_REQUEST, "缺少安装项 id"));
    }
    let message = format!(
        "“{}”来自本地源，已加载即可用（scope={scope}）。远程 marketplace 拉取安装将在 P2 接入。",
        payload.id
    );
    Ok(Json(PluginInstallResponse {
        message,
        installed: true,
    }))
}

// ===== 浏览器多媒体智能降级（任务2）=====
// 抖音/B站等大站设 X-Frame-Options / CSP frame-ancestors，WebView2 内核会拒绝在 iframe 内嵌渲染。
// 前端打开 URL 前先调 /api/browser/embeddable 探测响应头：可嵌→主面板 iframe；禁嵌→改用独立窗口/系统浏览器。

#[derive(Debug, Deserialize)]
struct BrowserEmbedRequest {
    url: String,
}

#[derive(Debug, Serialize)]
struct BrowserEmbedResponse {
    embeddable: bool,
    reason: String,
    final_url: String,
    status: Option<u16>,
}

/// 从 URL 粗解析出小写 host（去 scheme/userinfo/port/path）。仅用于域名清单匹配，不做严格校验。
fn host_of(url: &str) -> Option<String> {
    let after = url.split("://").nth(1)?;
    let authority = after.split(|c| c == '/' || c == '?' || c == '#').next()?;
    let host_port = authority.rsplit('@').next()?;
    let host = host_port.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host.to_ascii_lowercase())
    }
}

/// 已知禁止 iframe 内嵌 / 重多媒体（视频流、强 SPA、JS frame-busting）站点清单。
/// 这些站点常用 CSP meta 标签或 JS 反嵌，响应头探测不到，命中即直接判禁嵌走独立窗口。
fn known_no_embed_reason(url: &str) -> Option<String> {
    let host = host_of(url)?;
    const BLOCK: &[&str] = &[
        "douyin.com",
        "iesdouyin.com",
        "bilibili.com",
        "weibo.com",
        "weibo.cn",
        "xiaohongshu.com",
        "zhihu.com",
        "taobao.com",
        "tmall.com",
        "jd.com",
        "youtube.com",
        "youtu.be",
        "twitter.com",
        "x.com",
        "facebook.com",
        "instagram.com",
        "kuaishou.com",
        "ixigua.com",
        "v.qq.com",
        "mp.weixin.qq.com",
        "douban.com",
    ];
    for domain in BLOCK {
        if host == *domain || host.ends_with(&format!(".{domain}")) {
            return Some(format!("已知禁嵌/重多媒体站点（{domain}），改用独立窗口"));
        }
    }
    None
}

/// 依据 X-Frame-Options 与 CSP frame-ancestors 判定页面能否被本控制台（异源 iframe）嵌入。
/// 返回 (blocked, reason)。控制台与目标站必然异源，故 SAMEORIGIN / 'self' 都视为拒绝。纯函数，便于单测。
fn analyze_frame_embeddable(
    x_frame_options: Option<&str>,
    content_security_policy: Option<&str>,
) -> (bool, String) {
    if let Some(xfo) = x_frame_options {
        let v = xfo.trim().to_ascii_lowercase();
        if v.contains("deny") {
            return (true, "X-Frame-Options: DENY".to_string());
        }
        if v.contains("sameorigin") {
            return (true, "X-Frame-Options: SAMEORIGIN".to_string());
        }
        if v.contains("allow-from") {
            // ALLOW-FROM 已废弃且仅允许单一来源，按受限处理。
            return (true, "X-Frame-Options: ALLOW-FROM（受限）".to_string());
        }
    }
    if let Some(csp) = content_security_policy {
        for directive in csp.split(';') {
            let lower = directive.trim().to_ascii_lowercase();
            if let Some(rest) = lower.strip_prefix("frame-ancestors") {
                let value = rest.trim();
                if value.is_empty() || value.contains("'none'") {
                    return (true, "CSP frame-ancestors 'none'".to_string());
                }
                if value.contains('*') {
                    return (false, "CSP frame-ancestors *（放行）".to_string());
                }
                // 'self' 或列举具体源：异源控制台不在白名单内，拒绝。
                return (true, format!("CSP frame-ancestors {value}（受限）"));
            }
        }
    }
    (false, "未发现内嵌限制".to_string())
}

/// 浏览器嵌入探测：GET 目标 URL（只读响应头），判定能否在控制台 iframe 内嵌。
/// 探测失败（网络/超时）按"不可嵌"返回，避免 iframe 乐观放行导致空白或跨源卡死。
async fn api_browser_embeddable(
    Json(payload): Json<BrowserEmbedRequest>,
) -> ApiResult<Json<BrowserEmbedResponse>> {
    let url = payload.url.trim().to_string();
    if url.is_empty() {
        return Err(api_error(StatusCode::BAD_REQUEST, "缺少 url"));
    }
    let lower = url.to_ascii_lowercase();
    if !(lower.starts_with("http://") || lower.starts_with("https://")) {
        // 非 http(s)（file:/about: 等）不探测，直接交前端按可嵌处理。
        return Ok(Json(BrowserEmbedResponse {
            embeddable: true,
            reason: "非 http(s) 协议，跳过探测".to_string(),
            final_url: url,
            status: None,
        }));
    }
    // 第一道判定：已知禁嵌/重多媒体站点（响应头可能探不到 CSP meta / JS 反嵌），直接走独立窗口。
    if let Some(reason) = known_no_embed_reason(&url) {
        return Ok(Json(BrowserEmbedResponse {
            embeddable: false,
            reason,
            final_url: url,
            status: None,
        }));
    }
    let client = match reqwest::Client::builder()
        .timeout(Duration::from_secs(8))
        .user_agent(
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36",
        )
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            return Ok(Json(BrowserEmbedResponse {
                embeddable: false,
                reason: format!("探测客户端初始化失败：{e}"),
                final_url: url,
                status: None,
            }));
        }
    };
    // Range: bytes=0-0 提示服务器尽量少回 body（只为读响应头）。
    match client
        .get(&url)
        .header(reqwest::header::RANGE, "bytes=0-0")
        .send()
        .await
    {
        Ok(resp) => {
            let status = resp.status().as_u16();
            let final_url = resp.url().to_string();
            let xfo = resp
                .headers()
                .get("x-frame-options")
                .and_then(|v| v.to_str().ok())
                .map(|s| s.to_string());
            let csp = resp
                .headers()
                .get("content-security-policy")
                .and_then(|v| v.to_str().ok())
                .map(|s| s.to_string());
            let (blocked, reason) = analyze_frame_embeddable(xfo.as_deref(), csp.as_deref());
            Ok(Json(BrowserEmbedResponse {
                embeddable: !blocked,
                reason,
                final_url,
                status: Some(status),
            }))
        }
        Err(e) => Ok(Json(BrowserEmbedResponse {
            embeddable: false,
            reason: format!("探测失败，按不可嵌处理：{e}"),
            final_url: url,
            status: None,
        })),
    }
}

#[derive(Debug, Deserialize)]
struct BrowserOpenExternalRequest {
    url: String,
}

#[derive(Debug, Serialize)]
struct BrowserOpenExternalResponse {
    opened: bool,
    message: String,
}

/// 仅允许 http(s) 且不含空白/引号/shell 元字符的 URL，杜绝交给系统命令时的注入面。
fn is_safe_external_url(url: &str) -> bool {
    let lower = url.to_ascii_lowercase();
    if !(lower.starts_with("http://") || lower.starts_with("https://")) {
        return false;
    }
    !url.chars().any(|c| {
        c.is_control()
            || c.is_whitespace()
            || matches!(c, '"' | '\'' | '`' | '|' | '<' | '>' | '^' | '\\')
    })
}

/// 用系统默认浏览器打开 URL（桌面端兜底：独立 WebView 窗口不可用时仍能正常看抖音等多媒体站点）。
/// Windows 走 rundll32 FileProtocolHandler，不经 shell，避免命令注入。
async fn api_browser_open_external(
    Json(payload): Json<BrowserOpenExternalRequest>,
) -> ApiResult<Json<BrowserOpenExternalResponse>> {
    let url = payload.url.trim().to_string();
    if !is_safe_external_url(&url) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "仅支持安全的 http(s) URL",
        ));
    }
    #[cfg(target_os = "windows")]
    let spawn = std::process::Command::new("rundll32.exe")
        .args(["url.dll,FileProtocolHandler", &url])
        .spawn();
    #[cfg(target_os = "macos")]
    let spawn = std::process::Command::new("open").arg(&url).spawn();
    #[cfg(all(not(target_os = "windows"), not(target_os = "macos")))]
    let spawn = std::process::Command::new("xdg-open").arg(&url).spawn();
    match spawn {
        Ok(_) => Ok(Json(BrowserOpenExternalResponse {
            opened: true,
            message: format!("已用系统默认浏览器打开：{url}"),
        })),
        Err(e) => Err(api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("打开系统浏览器失败：{e}"),
        )),
    }
}

#[derive(Debug, Serialize)]
struct DetectProxyResponse {
    proxy_url: Option<String>,
    candidates: Vec<u16>,
}

/// 自动探测本机可用的 HTTP 代理（Clash/mihomo/v2ray 等）：逐个尝试常见端口，
/// 通过该端口请求 generate_204 验证能出网，返回首个可用代理。供独立浏览器窗口绕开 fake-ip 直连被拒。
async fn api_browser_detect_proxy() -> ApiResult<Json<DetectProxyResponse>> {
    // 常见本地代理端口，按常见度排序（7897=clash-verge/mihomo 混合端口，7890=clash 经典）。
    const PORTS: &[u16] = &[7897, 7890, 7891, 2080, 10809, 1087, 8889];
    let mut working: Option<String> = None;
    let mut candidates: Vec<u16> = Vec::new();
    for &port in PORTS {
        let proxy = format!("http://127.0.0.1:{port}");
        let proxy_obj = match reqwest::Proxy::all(&proxy) {
            Ok(p) => p,
            Err(_) => continue,
        };
        let client = match reqwest::Client::builder()
            .proxy(proxy_obj)
            .connect_timeout(Duration::from_millis(400))
            .timeout(Duration::from_secs(4))
            .build()
        {
            Ok(c) => c,
            Err(_) => continue,
        };
        // 端口无服务会被快速 RST（connect_timeout 兜底）；连上且能出网（204/2xx）才算可用代理。
        if let Ok(resp) = client
            .get("http://www.gstatic.com/generate_204")
            .send()
            .await
        {
            if resp.status().as_u16() == 204 || resp.status().is_success() {
                candidates.push(port);
                if working.is_none() {
                    working = Some(proxy);
                }
            }
        }
    }
    Ok(Json(DetectProxyResponse {
        proxy_url: working,
        candidates,
    }))
}

#[cfg(test)]
mod browser_embed_tests {
    use super::{analyze_frame_embeddable, is_safe_external_url};

    #[test]
    fn no_headers_is_embeddable() {
        let (blocked, _) = analyze_frame_embeddable(None, None);
        assert!(!blocked);
    }

    #[test]
    fn xfo_deny_and_sameorigin_block() {
        assert!(analyze_frame_embeddable(Some("DENY"), None).0);
        assert!(analyze_frame_embeddable(Some("SAMEORIGIN"), None).0);
        assert!(analyze_frame_embeddable(Some("sameorigin"), None).0);
        assert!(analyze_frame_embeddable(Some("ALLOW-FROM https://x.com"), None).0);
    }

    #[test]
    fn csp_frame_ancestors_self_or_none_blocks() {
        assert!(
            analyze_frame_embeddable(None, Some("default-src 'self'; frame-ancestors 'none'")).0
        );
        assert!(analyze_frame_embeddable(None, Some("frame-ancestors 'self'")).0);
        assert!(analyze_frame_embeddable(None, Some("frame-ancestors https://trusted.com")).0);
    }

    #[test]
    fn csp_wildcard_or_absent_allows() {
        assert!(!analyze_frame_embeddable(None, Some("frame-ancestors *")).0);
        assert!(!analyze_frame_embeddable(None, Some("default-src 'self'")).0);
    }

    #[test]
    fn known_no_embed_hosts_blocked() {
        use super::known_no_embed_reason;
        assert!(known_no_embed_reason("https://www.douyin.com").is_some());
        assert!(known_no_embed_reason("https://www.douyin.com/video/123").is_some());
        assert!(known_no_embed_reason("https://www.bilibili.com/").is_some());
        assert!(known_no_embed_reason("https://example.com").is_none());
        assert!(known_no_embed_reason("https://evil-douyin.com").is_none());
    }

    #[test]
    fn safe_url_accepts_http_rejects_others() {
        assert!(is_safe_external_url("https://www.douyin.com/"));
        assert!(is_safe_external_url("http://example.com/path?x=1&y=2"));
        assert!(!is_safe_external_url("file:///c:/secret.txt"));
        assert!(!is_safe_external_url("javascript:alert(1)"));
        assert!(!is_safe_external_url("https://a.com/\" & calc"));
        assert!(!is_safe_external_url("https://a.com/`whoami`"));
    }
}

/// 聊天请求幂等窗口（毫秒）：弱网下用户重复提交同一消息时去重。设 0 关闭。
fn chat_idempotency_window_ms() -> u64 {
    read_config(|c| c.session.chat_idempotency_window_ms)
}

/// (指纹 → 最近提交时间戳) 内存表，用于聊天请求幂等去重。
fn chat_idempotency_registry() -> &'static Mutex<HashMap<u64, u64>> {
    static REGISTRY: OnceLock<Mutex<HashMap<u64, u64>>> = OnceLock::new();
    REGISTRY.get_or_init(|| Mutex::new(HashMap::new()))
}

/// 检测聊天请求是否为时间窗内的重复提交（弱网保护）。命中返回拒绝原因；否则登记并放行。
/// 指纹含 session/room/目标 agent/规范化文本/附件(url+name)，确保不同内容不误判；附件不同→不同指纹。
fn check_chat_request_duplicate(payload: &SendMessageRequest) -> Option<String> {
    let window_ms = chat_idempotency_window_ms();
    if window_ms == 0 {
        return None;
    }
    let text = payload.text.trim();
    // 纯空内容不参与去重（已被前置校验处理）。
    if text.is_empty()
        && payload
            .attachments
            .as_ref()
            .map_or(true, |items| items.is_empty())
    {
        return None;
    }
    let mut fingerprint = String::new();
    fingerprint.push_str(payload.session_id.as_deref().unwrap_or(""));
    fingerprint.push('|');
    fingerprint.push_str(payload.chat_room_id.as_deref().unwrap_or(""));
    fingerprint.push('|');
    fingerprint.push_str(&payload.target_agent_ids.join(","));
    fingerprint.push('|');
    fingerprint.push_str(text);
    fingerprint.push('|');
    if let Some(attachments) = payload.attachments.as_ref() {
        for attachment in attachments {
            fingerprint.push_str(&attachment.url);
            fingerprint.push('#');
            fingerprint.push_str(&attachment.name);
            fingerprint.push(';');
        }
    }
    let key = hash_bytes(fingerprint.as_bytes());
    let now = unix_timestamp_millis();
    let mut map = chat_idempotency_registry().lock().ok()?;
    map.retain(|_, ts| now.saturating_sub(*ts) < window_ms);
    if let Some(last) = map.get(&key) {
        if now.saturating_sub(*last) < window_ms {
            HARNESS_IDEMPOTENT_HITS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            return Some("检测到重复提交（可能弱网重发），已忽略本次重复请求。".to_string());
        }
    }
    map.insert(key, now);
    None
}

fn prepare_chat_dispatch(payload: SendMessageRequest) -> ApiResult<PreparedChatDispatch> {
    let text = payload.text.trim();
    let selected_message_ids = payload.selected_message_ids.clone().unwrap_or_default();
    if text.is_empty()
        && payload.attachments.as_ref().map_or(true, Vec::is_empty)
        && selected_message_ids.is_empty()
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "消息内容、引用历史或附件至少需要提供一个",
        ));
    }

    // 请求幂等（弱网保护）：同一 (session, room, agents, text, 附件指纹) 在时间窗内重复提交→拒绝重复执行，
    // 避免弱网重发导致同一指令被执行两次（不 emit、不调模型、不存消息）。realtime 链路独立，不受影响。
    if let Some(reason) = check_chat_request_duplicate(&payload) {
        return Err(api_error(StatusCode::CONFLICT, &reason));
    }

    let selectable_agents = default_agent_sessions()
        .into_iter()
        .filter(|agent| agent.selectable && agent.enabled)
        .collect::<Vec<_>>();
    let targets = if payload.target_agent_ids.is_empty() {
        selectable_agents.iter().take(1).collect::<Vec<_>>()
    } else {
        let selectable_by_id = selectable_agents
            .iter()
            .map(|agent| (agent.id.as_str(), agent))
            .collect::<BTreeMap<_, _>>();
        let mut seen = HashSet::new();
        payload
            .target_agent_ids
            .iter()
            .filter_map(|id| {
                let id = id.trim();
                if id.is_empty() || !seen.insert(id.to_string()) {
                    return None;
                }
                selectable_by_id.get(id).copied()
            })
            .collect::<Vec<_>>()
    };

    if targets.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "没有可投递的自定义会话 Agent，系统工具 Agent 和视觉 Agent 不进入下拉群发列表",
        ));
    }

    let attachment_count = payload.attachments.as_ref().map_or(0, Vec::len);
    let attachments = payload.attachments.unwrap_or_default();
    let image_urls = encode_attachment_images(&attachments);
    let semantic_action = semantic_action_from_intent(text);
    let calls_vision =
        should_route_to_vision_agent(text) || semantic_action.as_deref() == Some("visual_action");
    let mut calls_tool = should_route_to_tool_agent(text) || semantic_action.is_some();
    let conversation_session_id = payload.session_id.clone();
    let chat_room_id = payload
        .chat_room_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(DEFAULT_CHAT_ROOM_ID)
        .to_string();
    if let Ok((_, room_tools, room_computer_use)) =
        chat_room_capabilities_sqlite(&default_session_sqlite_path(), &chat_room_id)
    {
        // 聊天室开关是全局能力的进一步收紧，不会绕过全局关闭或审批闸门。
        calls_tool = calls_tool
            && room_tools
            && (semantic_action.as_deref() != Some("computer_use") || room_computer_use);
    }
    let (selected_history, context_history, context_rosters, active_vision_session_id) = {
        let store = session_store()
            .lock()
            .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
        let selected = store.selected_chat_messages(&chat_room_id, &selected_message_ids);
        let history = store
            .state
            .chat_rooms
            .iter()
            .find(|room| room.id == chat_room_id)
            .map(|room| room.messages.clone())
            .unwrap_or_default();
        let rosters = targets
            .iter()
            .filter_map(|agent| {
                chat_room_roster_from_state(&store.state, &chat_room_id, Some(&agent.id))
                    .ok()
                    .map(|roster| (agent.id.clone(), roster))
            })
            .collect::<BTreeMap<_, _>>();
        (
            selected,
            history,
            rosters,
            store.state.active_vision_session_id.clone(),
        )
    };
    let reference_context = ChatReferenceContext::new(
        selected_message_ids.clone(),
        selected_history,
        chat_room_id.clone(),
        text,
        &targets,
    );
    let user_content = compose_user_message_content(text, &reference_context);
    let goal_trigger = prepare_goal_trigger_for_dispatch(
        text,
        targets.first().copied(),
        &selectable_agents,
        active_vision_session_id.as_deref(),
    );

    let user_kind = if attachments.is_empty() {
        "text"
    } else {
        "multimedia"
    };
    let messages = vec![ChatMessageDto {
        id: format!("msg-{}-user", unix_timestamp_millis()),
        author: "".to_string(),
        role: "user".to_string(),
        target: targets
            .iter()
            .map(|agent| agent.display_name.clone())
            .collect::<Vec<_>>()
            .join(""),
        content: user_content.clone(),
        kind: user_kind.to_string(),
        attachments: attachments.clone(),
    }];

    Ok(PreparedChatDispatch {
        targets: targets.into_iter().cloned().collect(),
        messages,
        tasks: Vec::new(),
        user_content,
        chat_room_id,
        conversation_session_id,
        attachment_count,
        image_urls,
        context_history,
        context_rosters,
        calls_vision,
        calls_tool,
        reference_context,
        goal_trigger,
    })
}

fn detect_goal_trigger_intent(text: &str) -> Option<GoalTriggerIntent> {
    let title = compact_goal_title(text);
    if title.is_empty() {
        return None;
    }
    let lower = title.to_ascii_lowercase();
    let has_long_range = lower.contains("long-running")
        || lower.contains("long range")
        || lower.contains("long-range")
        || lower.contains("multi-step")
        || lower.contains("multistep")
        || lower.contains("multi stage")
        || lower.contains("multi-stage")
        || title.contains("长程")
        || title.contains("长期")
        || title.contains("多阶")
        || title.contains("多步")
        || title.contains("串行任务")
        || title.contains("并行任务");
    let has_goal_task = (lower.contains("goal") || title.contains("目标"))
        && (lower.contains("task")
            || lower.contains("mode")
            || title.contains("任务")
            || title.contains("模式"));
    let has_artifact = lower.contains("html")
        || lower.contains("ppt")
        || lower.contains("powerpoint")
        || lower.contains("web page")
        || title.contains("网页")
        || title.contains("演示文稿")
        || title.contains("幻灯");
    let has_action = lower.contains("build")
        || lower.contains("make")
        || lower.contains("create")
        || lower.contains("generate")
        || lower.contains("produce")
        || lower.contains("implement")
        || lower.contains("finish")
        || title.contains("制作")
        || title.contains("生成")
        || title.contains("创建")
        || title.contains("实现")
        || title.contains("完成");

    if (has_long_range && (has_artifact || has_action || has_goal_task))
        || (has_goal_task && has_artifact && has_action)
    {
        Some(GoalTriggerIntent {
            title,
            reason: "long-range artifact/task semantics".to_string(),
        })
    } else {
        None
    }
}

fn compact_goal_title(text: &str) -> String {
    let first_line = text
        .lines()
        .map(str::trim)
        .find(|line| !line.is_empty())
        .unwrap_or("");
    let compacted = first_line.split_whitespace().collect::<Vec<_>>().join(" ");
    if compacted.chars().count() <= 96 {
        compacted
    } else {
        let mut value = compacted.chars().take(93).collect::<String>();
        value.push_str("...");
        value
    }
}

fn prepare_goal_trigger_for_dispatch(
    text: &str,
    commander: Option<&AgentSessionDto>,
    selectable_agents: &[AgentSessionDto],
    active_vision_session_id: Option<&str>,
) -> Option<PreparedGoalTrigger> {
    let intent = detect_goal_trigger_intent(text)?;
    let commander =
        commander.filter(|agent| goal_role_agent_eligible(agent, active_vision_session_id))?;
    let candidate_sessions = selectable_agents
        .iter()
        .filter(|agent| goal_role_agent_eligible(agent, active_vision_session_id))
        .map(|agent| GoalTriggerCandidateSession {
            session_id: agent.id.clone(),
            display_name: agent.display_name.clone(),
            model: agent.model.clone(),
            model_type: agent.model_type.clone(),
        })
        .collect::<Vec<_>>();
    Some(PreparedGoalTrigger {
        title: intent.title,
        reason: intent.reason,
        commander_session_id: commander.id.clone(),
        commander_display_name: commander.display_name.clone(),
        candidate_sessions,
        consultation_required: true,
    })
}

fn goal_role_agent_eligible(
    agent: &AgentSessionDto,
    active_vision_session_id: Option<&str>,
) -> bool {
    if !agent.selectable || !agent.enabled || agent.system {
        return false;
    }
    if active_vision_session_id.is_some_and(|id| id == agent.id) {
        return false;
    }
    !matches!(
        agent.model_type.trim().to_ascii_lowercase().as_str(),
        "vision" | "multimodal" | "video"
    )
}

