async fn run_tool_dry_run(tool_id: &str, input: JsonValue) -> ApiResult<Json<ToolRunResponse>> {
    let catalog = build_tools_catalog();
    let Some(item) = catalog
        .categories
        .iter()
        .flat_map(|category| category.items.iter())
        .find(|item| item.item.id == tool_id)
        .cloned()
    else {
        return Err(api_error(StatusCode::NOT_FOUND, "工具不存"));
    };

    if !item
        .actions
        .iter()
        .any(|action| action.id == "dry-run" && action.enabled)
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "该工具暂未开放 dry-run。插件、SKILL 和高风险写入工具仍只展示目录信息。",
        ));
    }

    let started = Instant::now();
    let output = match tool_id {
        "vision.capture_desktop" => {
            let capture_path = default_latest_desktop_capture_path();
            capture_desktop(&capture_path).await?;
            let metadata = latest_capture_metadata().await;
            json!({
                "capture": metadata,
                "preview": metadata.preview_url,
                "note": "已采集最新桌面截图；没有执行键鼠输入"
            })
        }
        "vision.describe_screen" => {
            let request = VisionDescribeScreenRequest {
                capture_path: input_string(&input, "capture_path"),
                prompt: input_string(&input, "prompt"),
                use_latest_capture: input_bool(&input, "use_latest_capture"),
                use_model: input_bool(&input, "use_model"),
                base_url: input_string(&input, "base_url"),
                model: input_string(&input, "model"),
                api_key: input_string(&input, "api_key"),
                timeout_seconds: input_u64(&input, "timeout_seconds"),
            };
            let response = run_vision_describe_screen(request).await?;
            json!(response)
        }
        "vision.find_target" | "vision.find_region" => {
            let request = VisionFindTargetRequest {
                target: input_string(&input, "target"),
                capture_path: input_string(&input, "capture_path"),
                raw_response: input_string(&input, "raw_response"),
                use_latest_capture: input_bool(&input, "use_latest_capture"),
                use_model: input_bool(&input, "use_model"),
                base_url: input_string(&input, "base_url"),
                model: input_string(&input, "model"),
                api_key: input_string(&input, "api_key"),
                timeout_seconds: input_u64(&input, "timeout_seconds"),
                readiness_verified: false,
            };
            let response = run_vision_find_target(request).await?;
            json!(response)
        }
        "computer.safe_context_menu" => {
            let response = run_safe_context_menu_test(SafeContextMenuRequest {
                execute: Some(false),
                window_width: input_u32(&input, "window_width"),
                window_height: input_u32(&input, "window_height"),
                layout: input_string(&input, "layout"),
                target_number: input_u32(&input, "target_number")
                    .and_then(|value| u16::try_from(value).ok()),
                startup_delay_ms: input_u64(&input, "startup_delay_ms"),
                startup_timeout_ms: input_u64(&input, "startup_timeout_ms"),
                marker_timeout_ms: input_u64(&input, "marker_timeout_ms"),
            })
            .await?;
            json!(response)
        }
        "computer.safe_drag_select" => {
            let response = run_safe_drag_select_test(SafeDragSelectRequest {
                execute: Some(false),
                window_width: input_u32(&input, "window_width"),
                window_height: input_u32(&input, "window_height"),
                layout: input_string(&input, "layout"),
                target_number: input_u32(&input, "target_number")
                    .and_then(|value| u16::try_from(value).ok()),
                startup_delay_ms: input_u64(&input, "startup_delay_ms"),
                startup_timeout_ms: input_u64(&input, "startup_timeout_ms"),
                marker_timeout_ms: input_u64(&input, "marker_timeout_ms"),
            })
            .await?;
            json!(response)
        }
        "computer.left_click"
        | "computer.right_click"
        | "computer.double_click"
        | "computer.context_menu_select"
        | "computer.drag_select"
        | "computer.scroll"
        | "computer.text_input"
        | "computer.press_key"
        | "computer.hotkey" => {
            let response = run_action_plan(ComputerActionPlanRequest {
                action: Some(tool_id.trim_start_matches("computer.").to_string()),
                target: input_string(&input, "target"),
                menu_item: input_string(&input, "menu_item"),
                x: input_i32(&input, "x"),
                y: input_i32(&input, "y"),
                start: input_point(&input, "start"),
                end: input_point(&input, "end"),
                bbox: input_bbox(&input, "bbox"),
                text: input_string(&input, "text"),
                key: input_string(&input, "key"),
                keys: input_string_array(&input, "keys"),
                delta: input_i32(&input, "delta"),
                execute: input_bool(&input, "execute"),
            })
            .await?;
            json!(response)
        }
        "computer.visual_action" => {
            let response = run_visual_action_dry_run(VisualActionRequest {
                target: input_string(&input, "target"),
                action: input_string(&input, "action"),
                raw_response: input_string(&input, "raw_response"),
                capture_path: input_string(&input, "capture_path"),
                use_latest_capture: input_bool(&input, "use_latest_capture"),
                use_model: input_bool(&input, "use_model"),
                base_url: input_string(&input, "base_url"),
                model: input_string(&input, "model"),
                api_key: input_string(&input, "api_key"),
                timeout_seconds: input_u64(&input, "timeout_seconds"),
                execute: input_bool(&input, "execute"),
            })
            .await?;
            json!(response)
        }
        "computer.profile" => {
            let request = ComputerUseProfileRequest {
                scenario: input_string(&input, "scenario")
                    .or_else(|| Some("desktop-icon-left-click".to_string())),
                execute: Some(false),
                confirm_after: input_bool(&input, "confirm_after").or(Some(true)),
                roi_radius: input_u32(&input, "roi_radius").or(Some(64)),
                after_delay_ms: input_u64(&input, "after_delay_ms").or(Some(120)),
                text: input_string(&input, "text"),
            };
            let response = run_computer_use_profile(request).await?;
            json!(response)
        }
        "computer.closed_loop" => {
            let scenario = find_scenario(input_string(&input, "scenario").as_deref())?;
            let response = run_closed_loop_scenario(
                scenario,
                false,
                input_bool(&input, "confirm_after").unwrap_or(true),
                input_u32(&input, "roi_radius").unwrap_or(64).clamp(12, 240),
                input_string(&input, "text").as_deref(),
            )
            .await?;
            json!(response)
        }
        "tools.semantic_dispatch" => {
            let intent = input_string(&input, "intent")
                .unwrap_or_else(|| "请看一下当前桌面并 dry-run 点击目标".to_string());
            let response = run_tool_dispatch(ToolDispatchRequest {
                intent,
                execute: Some(false),
                confirm_after: input_bool(&input, "confirm_after").or(Some(true)),
                roi_radius: input_u32(&input, "roi_radius").or(Some(64)),
                text: input_string(&input, "text"),
                target: input_string(&input, "target"),
                menu_item: input_string(&input, "menu_item"),
                raw_response: input_string(&input, "raw_response"),
                capture_path: input_string(&input, "capture_path"),
                use_latest_capture: input_bool(&input, "use_latest_capture"),
                use_model: input_bool(&input, "use_model"),
                system_control: None,
            })
            .await?;
            json!(response)
        }
        "core.read_file" => {
            let path = input_string(&input, "path").ok_or_else(|| {
                api_error(
                    StatusCode::BAD_REQUEST,
                    "core.read_file dry-run 需要 input.path。",
                )
            })?;
            let scoped_path = resolve_workspace_tool_path(Some(&path))?;
            let output = read_file(
                scoped_path.to_string_lossy().as_ref(),
                input_usize(&input, "offset"),
                input_usize(&input, "limit").or(Some(80)),
            )
            .map_err(io_api_error)?;
            json!(output)
        }
        "core.glob_search" => {
            let pattern = input_string(&input, "pattern").unwrap_or_else(|| "*.md".to_string());
            validate_workspace_relative_pattern(&pattern)?;
            let scoped_path = resolve_workspace_tool_path(input_string(&input, "path").as_deref())?;
            let output = glob_search(&pattern, Some(scoped_path.to_string_lossy().as_ref()))
                .map_err(io_api_error)?;
            json!(output)
        }
        "core.grep_search" => {
            let pattern = input_string(&input, "pattern").ok_or_else(|| {
                api_error(
                    StatusCode::BAD_REQUEST,
                    "core.grep_search dry-run 需要 input.pattern。",
                )
            })?;
            if let Some(glob) = input_string(&input, "glob") {
                validate_workspace_relative_pattern(&glob)?;
            }
            let scoped_path = resolve_workspace_tool_path(input_string(&input, "path").as_deref())?;
            let output = grep_search(&GrepSearchInput {
                pattern,
                path: Some(scoped_path.to_string_lossy().into_owned()),
                glob: input_string(&input, "glob"),
                output_mode: input_string(&input, "output_mode"),
                before: input_usize(&input, "-B"),
                after: input_usize(&input, "-A"),
                context_short: input_usize(&input, "-C"),
                context: input_usize(&input, "context"),
                line_numbers: input_bool(&input, "-n"),
                case_insensitive: input_bool(&input, "-i"),
                file_type: input_string(&input, "type"),
                head_limit: input_usize(&input, "head_limit").or(Some(20)),
                offset: input_usize(&input, "offset"),
                multiline: input_bool(&input, "multiline"),
            })
            .map_err(io_api_error)?;
            json!(output)
        }
        "core.ToolSearch" => dry_run_tool_search(&input),
        "core.Sleep" => json!({
            "duration_ms": input_u64(&input, "duration_ms").unwrap_or(0),
            "message": "Sleep dry-run 不实际等待"
        }),
        _ => {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "该工具没有可用的 dry-run handler",
            ));
        }
    };

    Ok(Json(ToolRunResponse {
        tool_id: tool_id.to_string(),
        mode: "dry-run".to_string(),
        status: "完成".to_string(),
        executed: false,
        elapsed_ms: elapsed_millis(started),
        input,
        audit: tool_run_audit_record(&output),
        output,
        notes: vec![
            "工具卡片 dry-run 不执行真实键鼠输入、插件脚本或文件写入".to_string(),
            "execute 按钮仍处于禁用状态，后续需要显式权限闸门".to_string(),
        ],
    }))
}

async fn run_tool_dispatch(payload: ToolDispatchRequest) -> ApiResult<ToolDispatchResponse> {
    let intent = payload.intent.trim();
    if intent.is_empty() {
        return Err(api_error(StatusCode::BAD_REQUEST, "工具意图不能为空"));
    }

    let semantic_action = semantic_action_from_intent(intent);
    let calls_vision =
        should_route_to_vision_agent(intent) || semantic_action.as_deref() == Some("visual_action");
    let calls_tool = should_route_to_tool_agent(intent) || semantic_action.is_some();
    if !calls_vision && !calls_tool {
        return Ok(ToolDispatchResponse {
            status: "no-op".to_string(),
            route: "none".to_string(),
            scenario: None,
            closed_loop: None,
            dispatch_plan: None,
            tool_result_text: None,
            notes: vec!["未识别到内视觉或 computer-use 触发语义".to_string()],
        });
    }

    let dispatch_plan = build_semantic_dispatch_plan(intent, &payload).await?;
    let scenario = scenario_from_tool_intent(intent);
    let Some(scenario) = scenario else {
        return Ok(ToolDispatchResponse {
            status: if dispatch_plan.is_some() {
                "dry-run-dispatch-plan-ready".to_string()
            } else {
                "needs-confirmation".to_string()
            },
            route: tool_route_label(calls_vision, calls_tool).to_string(),
            scenario: None,
            closed_loop: None,
            dispatch_plan,
            tool_result_text: None,
            notes: vec!["已识别工具意图，但缺少可映射的安全场景".to_string()],
        });
    };

    let closed_loop = run_closed_loop_scenario(
        scenario,
        payload.execute.unwrap_or(false),
        payload.confirm_after.unwrap_or(true),
        payload.roi_radius.unwrap_or(64).clamp(12, 240),
        payload.text.as_deref(),
    )
    .await?;
    Ok(ToolDispatchResponse {
        status: closed_loop.status.clone(),
        route: tool_route_label(calls_vision, calls_tool).to_string(),
        scenario: Some(scenario.name.to_string()),
        closed_loop: Some(closed_loop),
        dispatch_plan,
        tool_result_text: None,
        notes: vec![
            "该接口可作为 LLM 工具 dispatch 入口；默认 dry-run，真实输入需 execute=true"
                .to_string(),
            "语义路由先识别内视觉/computer-use，再映射到 computer-use regression scenario"
                .to_string(),
        ],
    })
}

