// ── Grounding Router API ──

async fn api_vision_locate(
    Json(req): Json<vision::locate::LocateRequest>,
) -> ApiResult<Json<vision::locate::LocateResponse>> {
    Ok(Json(run_grounding_router(req).await?))
}

async fn run_grounding_router(
    req: vision::locate::LocateRequest,
) -> ApiResult<vision::locate::LocateResponse> {
    let t0 = std::time::Instant::now();
    let config = active_vision_router_config();
    let capture_path = req
        .capture_path
        .as_deref()
        .map(PathBuf::from)
        .unwrap_or_else(default_latest_desktop_capture_path);
    if !capture_path.exists() {
        capture_desktop(&capture_path).await?;
    }
    let screen_dimensions = read_png_dimensions(&capture_path).unwrap_or_else(|_| {
        let (width, height, _) = read_screen_info();
        ScreenDimensions { width, height }
    });
    let (_, _, dpi_scale) = read_screen_info();
    let screen = vision::locate::ScreenInfo {
        logical_width: screen_dimensions.width,
        logical_height: screen_dimensions.height,
        dpi_scale: dpi_scale as f32,
    };

    let mut attempts = Vec::new();
    let mut best: Option<vision::locate::BackendAttempt> = None;
    let effective_min_confidence = effective_locate_min_confidence(&req, &config);

    let pipeline = locate_pipeline(&req, &config);

    for backend in &pipeline {
        let attempt = match backend {
            vision::locate::BackendId::Uia => {
                if !config.uia.enabled {
                    vision::locate::BackendAttempt::skipped(*backend, "uia disabled by config")
                } else if let Some(target) = locate_system_control(&req.target) {
                    let t1 = std::time::Instant::now();
                    match uia_resolver::resolve_system_control(target) {
                        Ok(hit) => uia_hit_to_attempt(t1, hit, effective_min_confidence),
                        Err(e) => uia_error_to_attempt(t1, e),
                    }
                } else if matches!(&req.target, vision::locate::LocateTarget::Uia { .. }) {
                    let t1 = std::time::Instant::now();
                    match locate_uia_target(&req.target) {
                        Ok(hit) => uia_hit_to_attempt(t1, hit, effective_min_confidence),
                        Err(e) => uia_error_to_attempt(t1, e),
                    }
                } else {
                    vision::locate::BackendAttempt::skipped(
                        *backend,
                        "target is neither a known system control nor a UIA query",
                    )
                }
            }
            vision::locate::BackendId::OcrTemplate => {
                template_locate_attempt(
                    &req,
                    &capture_path,
                    screen_dimensions,
                    &config,
                    effective_min_confidence,
                )
                .await
            }
            vision::locate::BackendId::LocalVlm => {
                local_vlm_locate_attempt(
                    &req,
                    &capture_path,
                    screen_dimensions,
                    &config,
                    effective_min_confidence,
                )
                .await
            }
            vision::locate::BackendId::RemoteVlm => {
                remote_vlm_locate_attempt(
                    &req,
                    &capture_path,
                    screen_dimensions,
                    &config,
                    effective_min_confidence,
                )
                .await
            }
        };

        if attempt.status == vision::locate::AttemptStatus::Ok && best.is_none() {
            best = Some(attempt.clone());
        }
        attempts.push(attempt);
        if best.is_some() && !req.cross_verify && !config.cross_verify {
            break;
        }
    }

    let status = locate_status_from_attempts(best.as_ref(), &attempts);
    let degradation_reason = if status == vision::locate::LocateStatus::Ok {
        None
    } else {
        Some("grounding router did not produce a verified high-confidence point; no hardcoded anchor fallback is used".to_string())
    };
    let mut notes = vec![
        "Grounding backend is separate from user-selectable vision understanding agents."
            .to_string(),
        "Real click execution consumes this locate result and does not fall back to taskbar anchors."
            .to_string(),
    ];
    if status != vision::locate::LocateStatus::Ok {
        notes.push(
            "No automatic grounding result is available; keep the action as dry-run and request manual confirmation."
                .to_string(),
        );
    }

    Ok(vision::locate::LocateResponse {
        status,
        target_description: locate_target_text(&req.target),
        point: best.as_ref().and_then(|a| a.point),
        bbox: best.as_ref().and_then(|a| a.bbox),
        confidence: best.as_ref().and_then(|a| a.confidence).unwrap_or(0.0),
        chosen_backend: best.as_ref().map(|a| a.backend),
        attempts,
        capture_path: capture_path.display().to_string(),
        screen,
        elapsed_ms: t0.elapsed().as_millis() as u64,
        degradation_reason,
        notes,
    })
}

fn active_vision_router_config() -> ConfigVisionRouter {
    read_config(|config| config.vision.router.clone().unwrap_or_default())
}

fn configured_local_vlm_base_url(config: &ConfigVisionRouter) -> String {
    config
        .local_vlm
        .base_url
        .clone()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(authoritative_local_vision_base_url)
}

fn effective_locate_min_confidence(
    req: &vision::locate::LocateRequest,
    config: &ConfigVisionRouter,
) -> f32 {
    if (req.min_confidence - default_router_min_confidence()).abs() < f32::EPSILON {
        config.min_confidence
    } else {
        req.min_confidence
    }
    .clamp(0.0, 1.0)
}

fn locate_pipeline(
    req: &vision::locate::LocateRequest,
    config: &ConfigVisionRouter,
) -> Vec<vision::locate::BackendId> {
    req.backends.clone().unwrap_or_else(|| {
        let parsed = config
            .pipeline
            .iter()
            .filter_map(|name| parse_locate_backend_id(name))
            .collect::<Vec<_>>();
        if parsed.is_empty() {
            default_router_pipeline()
                .iter()
                .filter_map(|name| parse_locate_backend_id(name))
                .collect()
        } else {
            parsed
        }
    })
}

fn parse_locate_backend_id(name: &str) -> Option<vision::locate::BackendId> {
    match name.trim().to_ascii_lowercase().replace('-', "_").as_str() {
        "uia" | "ui_automation" => Some(vision::locate::BackendId::Uia),
        "ocr" | "ocr_template" | "template" | "template_match" => {
            Some(vision::locate::BackendId::OcrTemplate)
        }
        "local_vlm" | "local" | "showui" => Some(vision::locate::BackendId::LocalVlm),
        "remote_vlm" | "remote" => Some(vision::locate::BackendId::RemoteVlm),
        _ => None,
    }
}

fn inferred_point_only_confidence(
    point_found: bool,
    clustered: bool,
    accepted_points: usize,
    sample_count: usize,
) -> f32 {
    if !point_found {
        return 0.0;
    }
    if clustered && accepted_points >= 2 {
        return 0.56;
    }
    if sample_count == 1 && accepted_points == 1 {
        return 0.35;
    }
    0.35
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum VisualColorHint {
    Green,
    Gold,
}

impl VisualColorHint {
    fn as_str(self) -> &'static str {
        match self {
            Self::Green => "green",
            Self::Gold => "gold",
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct ColorRegionGrounding {
    point: vision::locate::PointPx,
    bbox: vision::locate::BBoxPx,
    pixel_count: u32,
}

fn colored_button_hint(target: &str) -> Option<VisualColorHint> {
    let target = target.to_ascii_lowercase();
    let button_like = target.contains("button")
        || target.contains("confirm")
        || target.contains("target")
        || target.contains("按钮")
        || target.contains("确认");
    if !button_like {
        return None;
    }
    if target.contains("green") || target.contains("绿色") {
        return Some(VisualColorHint::Green);
    }
    if target.contains("gold")
        || target.contains("yellow")
        || target.contains("金色")
        || target.contains("黄色")
    {
        return Some(VisualColorHint::Gold);
    }
    None
}

fn parse_color_region_scan_output(output: &str) -> Option<ColorRegionGrounding> {
    let line = output
        .lines()
        .map(str::trim)
        .find(|line| line.starts_with("hit|"))?;
    let mut parts = line.split('|');
    if parts.next()? != "hit" {
        return None;
    }
    let x = parts.next()?.parse::<i32>().ok()?;
    let y = parts.next()?.parse::<i32>().ok()?;
    let width = parts.next()?.parse::<i32>().ok()?;
    let height = parts.next()?.parse::<i32>().ok()?;
    let pixel_count = parts.next()?.parse::<u32>().ok()?;
    if width <= 0 || height <= 0 || pixel_count == 0 {
        return None;
    }
    Some(ColorRegionGrounding {
        point: vision::locate::PointPx {
            x: x + width / 2,
            y: y + height / 2,
        },
        bbox: vision::locate::BBoxPx {
            x,
            y,
            width,
            height,
        },
        pixel_count,
    })
}

fn point_in_bbox(point: PointDto, bbox: vision::locate::BBoxPx, padding: i32) -> bool {
    point.x >= bbox.x.saturating_sub(padding)
        && point.x <= bbox.x.saturating_add(bbox.width).saturating_add(padding)
        && point.y >= bbox.y.saturating_sub(padding)
        && point.y <= bbox.y.saturating_add(bbox.height).saturating_add(padding)
}

async fn locate_colored_button_region(
    capture_path: &Path,
    color_hint: VisualColorHint,
    screen: ScreenDimensions,
    region_hint: Option<RoiDto>,
) -> Option<ColorRegionGrounding> {
    let path = escape_powershell_single_quoted(&capture_path.display().to_string());
    let color = color_hint.as_str();
    let (roi_x, roi_y, roi_w, roi_h) = region_hint
        .map(|roi| (roi.left, roi.top, roi.width, roi.height))
        .unwrap_or((-1, -1, -1, -1));
    let script = r#"
Add-Type -AssemblyName System.Drawing
$source = @'
using System;
using System.Drawing;
using System.Drawing.Imaging;

public static class ColorRegionScanner {
    private static bool IsMatch(byte r, byte g, byte b, string color) {
        if (color == "green") {
            return g >= 95 && g >= r + 20 && g >= b + 10 && r <= 150 && b <= 170;
        }
        if (color == "gold") {
            return r >= 170 && g >= 140 && b <= 120 && r >= g && g >= b + 35;
        }
        return false;
    }

    public static string Scan(string path, string color, int roiX, int roiY, int roiW, int roiH) {
        using (var source = new Bitmap(path))
        using (var bitmap = source.Clone(new Rectangle(0, 0, source.Width, source.Height), PixelFormat.Format32bppArgb)) {
            int width = bitmap.Width;
            int height = bitmap.Height;
            int startX = roiW > 0 ? Math.Max(0, roiX) : 0;
            int startY = roiH > 0 ? Math.Max(0, roiY) : 0;
            int endX = roiW > 0 ? Math.Min(width, roiX + roiW) : width;
            int endY = roiH > 0 ? Math.Min(height, roiY + roiH) : height;
            var rect = new Rectangle(0, 0, width, height);
            var data = bitmap.LockBits(rect, ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
            try {
                int stride = data.Stride;
                int byteCount = Math.Abs(stride) * height;
                byte[] bytes = new byte[byteCount];
                System.Runtime.InteropServices.Marshal.Copy(data.Scan0, bytes, 0, byteCount);
                bool[] match = new bool[width * height];
                for (int y = startY; y < endY; y++) {
                    int row = y * Math.Abs(stride);
                    for (int x = startX; x < endX; x++) {
                        int offset = row + (x * 4);
                        byte b = bytes[offset];
                        byte g = bytes[offset + 1];
                        byte r = bytes[offset + 2];
                        match[(y * width) + x] = IsMatch(r, g, b, color);
                    }
                }

                bool[] visited = new bool[width * height];
                int bestX = 0, bestY = 0, bestW = 0, bestH = 0, bestCount = 0;
                double bestScore = 0.0;
                int[] queue = new int[width * height];
                int[] dx = new int[] { 1, -1, 0, 0 };
                int[] dy = new int[] { 0, 0, 1, -1 };

                for (int i = 0; i < match.Length; i++) {
                    if (!match[i] || visited[i]) {
                        continue;
                    }
                    int head = 0, tail = 0;
                    queue[tail++] = i;
                    visited[i] = true;
                    int minX = i % width, maxX = minX;
                    int minY = i / width, maxY = minY;
                    int count = 0;

                    while (head < tail) {
                        int current = queue[head++];
                        count++;
                        int cx = current % width;
                        int cy = current / width;
                        if (cx < minX) minX = cx;
                        if (cx > maxX) maxX = cx;
                        if (cy < minY) minY = cy;
                        if (cy > maxY) maxY = cy;

                        for (int n = 0; n < 4; n++) {
                            int nx = cx + dx[n];
                            int ny = cy + dy[n];
                            if (nx < 0 || ny < 0 || nx >= width || ny >= height) {
                                continue;
                            }
                            int next = (ny * width) + nx;
                            if (match[next] && !visited[next]) {
                                visited[next] = true;
                                queue[tail++] = next;
                            }
                        }
                    }

                    int componentW = maxX - minX + 1;
                    int componentH = maxY - minY + 1;
                    if (componentW < 80 || componentH < 45 || count < 1200) {
                        continue;
                    }
                    double fill = count / (double)(componentW * componentH);
                    double aspect = componentW / (double)componentH;
                    if (fill < 0.35 || aspect < 1.0 || aspect > 8.0) {
                        continue;
                    }
                    double score = count * fill;
                    if (score > bestScore) {
                        bestScore = score;
                        bestX = minX;
                        bestY = minY;
                        bestW = componentW;
                        bestH = componentH;
                        bestCount = count;
                    }
                }

                if (bestCount <= 0) {
                    return "miss";
                }
                return "hit|" + bestX + "|" + bestY + "|" + bestW + "|" + bestH + "|" + bestCount;
            } finally {
                bitmap.UnlockBits(data);
            }
        }
    }
}
'@
Add-Type -TypeDefinition $source -ReferencedAssemblies System.Drawing
[ColorRegionScanner]::Scan('__CAPTURE_PATH__', '__COLOR_HINT__', __ROI_X__, __ROI_Y__, __ROI_W__, __ROI_H__)
"#
    .replace("__CAPTURE_PATH__", &path)
    .replace("__COLOR_HINT__", color)
    .replace("__ROI_X__", &roi_x.to_string())
    .replace("__ROI_Y__", &roi_y.to_string())
    .replace("__ROI_W__", &roi_w.to_string())
    .replace("__ROI_H__", &roi_h.to_string());

    let mut command = Command::new("powershell.exe");
    command
        .arg("-NoLogo")
        .arg("-NoProfile")
        .arg("-ExecutionPolicy")
        .arg("Bypass")
        .arg("-Command")
        .arg(script)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .kill_on_drop(true);

    let child = match command.spawn() {
        Ok(child) => child,
        Err(error) => {
            diag!("[GROUNDING] color region scanner failed to start: {error}");
            return None;
        }
    };
    let output = match tokio::time::timeout(Duration::from_secs(5), child.wait_with_output()).await
    {
        Ok(Ok(output)) => output,
        Ok(Err(error)) => {
            diag!("[GROUNDING] color region scanner failed: {error}");
            return None;
        }
        Err(_) => {
            diag!("[GROUNDING] color region scanner timed out");
            return None;
        }
    };
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        diag!("[GROUNDING] color region scanner stderr: {stderr}");
        return None;
    }
    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut grounding = parse_color_region_scan_output(&stdout)?;
    grounding.point.x = grounding
        .point
        .x
        .clamp(0, screen.width.saturating_sub(1) as i32);
    grounding.point.y = grounding
        .point
        .y
        .clamp(0, screen.height.saturating_sub(1) as i32);
    Some(grounding)
}

fn locate_status_from_attempts(
    best: Option<&vision::locate::BackendAttempt>,
    attempts: &[vision::locate::BackendAttempt],
) -> vision::locate::LocateStatus {
    if best.is_some() {
        vision::locate::LocateStatus::Ok
    } else if attempts
        .iter()
        .any(|a| a.status == vision::locate::AttemptStatus::LowConfidence)
    {
        vision::locate::LocateStatus::LowConfidence
    } else if attempts
        .iter()
        .any(|a| a.status == vision::locate::AttemptStatus::Failed)
    {
        vision::locate::LocateStatus::NotFound
    } else {
        vision::locate::LocateStatus::Unavailable
    }
}

fn extract_system_control(
    target: &vision::locate::LocateTarget,
) -> Option<vision::locate::SystemControlId> {
    match target {
        vision::locate::LocateTarget::System { id } => Some(*id),
        _ => None,
    }
}

fn locate_system_control(
    target: &vision::locate::LocateTarget,
) -> Option<vision::locate::SystemControlId> {
    extract_system_control(target)
        .or_else(|| detect_system_control_from_target(&locate_target_text(target)))
}

fn locate_target_text(target: &vision::locate::LocateTarget) -> String {
    match target {
        vision::locate::LocateTarget::Natural { text } => text.clone(),
        vision::locate::LocateTarget::System { id } => format!("{id:?}"),
        vision::locate::LocateTarget::Uia {
            process_id,
            window_name,
            automation_id,
            class_name,
            name,
            control_type,
        } => [
            process_id.map(|id| id.to_string()),
            window_name.clone(),
            automation_id.clone(),
            class_name.clone(),
            name.clone(),
            control_type.clone(),
        ]
        .into_iter()
        .flatten()
        .filter(|value| !value.trim().is_empty())
        .collect::<Vec<_>>()
        .join(" "),
    }
}

fn uia_hit_to_attempt(
    started: std::time::Instant,
    hit: uia_resolver::UiaHit,
    min_confidence: f32,
) -> vision::locate::BackendAttempt {
    let status = if hit.confidence >= min_confidence {
        vision::locate::AttemptStatus::Ok
    } else {
        vision::locate::AttemptStatus::LowConfidence
    };
    vision::locate::BackendAttempt {
        backend: vision::locate::BackendId::Uia,
        status,
        point: Some(vision::locate::PointPx {
            x: hit.bounding_rect.x + hit.bounding_rect.width / 2,
            y: hit.bounding_rect.y + hit.bounding_rect.height / 2,
        }),
        bbox: Some(hit.bounding_rect),
        confidence: Some(hit.confidence),
        raw_response: Some(format!(
            "uia target name={:?} automation_id={:?} control_type={}",
            hit.name, hit.automation_id, hit.control_type
        )),
        model: Some("windows-uiautomation".to_string()),
        base_url: None,
        elapsed_ms: started.elapsed().as_millis() as u64,
        error: None,
    }
}

fn uia_error_to_attempt(
    started: std::time::Instant,
    error: uia_resolver::UiaError,
) -> vision::locate::BackendAttempt {
    vision::locate::BackendAttempt {
        backend: vision::locate::BackendId::Uia,
        status: vision::locate::AttemptStatus::Failed,
        point: None,
        bbox: None,
        confidence: None,
        raw_response: None,
        model: None,
        base_url: None,
        elapsed_ms: started.elapsed().as_millis() as u64,
        error: Some(error.to_string()),
    }
}

fn locate_uia_target(
    target: &vision::locate::LocateTarget,
) -> Result<uia_resolver::UiaHit, uia_resolver::UiaError> {
    let vision::locate::LocateTarget::Uia {
        process_id,
        window_name,
        automation_id,
        class_name,
        name,
        control_type,
    } = target
    else {
        return Err(uia_resolver::UiaError::ElementNotFound);
    };

    let snapshot = uia_resolver::snapshot_foreground_window(512)?;
    let element = uia_resolver::resolve_query(
        &snapshot,
        &uia_resolver::UiaQuery {
            process_id: *process_id,
            window_name: window_name.clone(),
            element_name: name.clone(),
            automation_id: automation_id.clone(),
            class_name: class_name.clone(),
            control_type: control_type.clone(),
        },
    )?;

    let mut confidence: f32 = 0.55;
    if automation_id.is_some() {
        confidence += 0.22;
    }
    if class_name.is_some() {
        confidence += 0.08;
    }
    if name.is_some() {
        confidence += 0.08;
    }
    if control_type.is_some() {
        confidence += 0.05;
    }
    confidence = confidence.min(0.99);

    Ok(uia_resolver::UiaHit {
        automation_id: element.automation_id,
        class_name: element.class_name,
        name: element.name,
        control_type: element.control_type,
        bounding_rect: element.bounding_rect,
        is_offscreen: element.is_offscreen,
        is_enabled: element.is_enabled,
        confidence,
    })
}

async fn template_locate_attempt(
    req: &vision::locate::LocateRequest,
    capture_path: &Path,
    screen: ScreenDimensions,
    config: &ConfigVisionRouter,
    min_confidence: f32,
) -> vision::locate::BackendAttempt {
    let backend = vision::locate::BackendId::OcrTemplate;
    if !config.ocr_template.enabled {
        return vision::locate::BackendAttempt::skipped(
            backend,
            "ocr/template backend disabled by config",
        );
    }
    if !cfg!(windows) {
        return vision::locate::BackendAttempt::skipped(
            backend,
            "ocr/template backend requires Windows screenshot tooling",
        );
    }

    let target = locate_target_text(&req.target);
    let Some(color_hint) = colored_button_hint(&target) else {
        return vision::locate::BackendAttempt::skipped(
            backend,
            "no deterministic color/template hint; OCR provider is not configured",
        );
    };
    let started = std::time::Instant::now();
    let threshold = min_confidence.max(config.ocr_template.confidence_floor.clamp(0.0, 1.0));
    match locate_colored_button_region(capture_path, color_hint, screen, None).await {
        Some(region) => {
            let confidence = 0.72;
            let status = if confidence >= threshold {
                vision::locate::AttemptStatus::Ok
            } else {
                vision::locate::AttemptStatus::LowConfidence
            };
            vision::locate::BackendAttempt {
                backend,
                status,
                point: Some(region.point),
                bbox: Some(region.bbox),
                confidence: Some(confidence),
                raw_response: Some(format!(
                    "template color={} pixels={} bbox=({},{} {}x{})",
                    color_hint.as_str(),
                    region.pixel_count,
                    region.bbox.x,
                    region.bbox.y,
                    region.bbox.width,
                    region.bbox.height
                )),
                model: Some("system-drawing-color-template".to_string()),
                base_url: None,
                elapsed_ms: started.elapsed().as_millis() as u64,
                error: None,
            }
        }
        None => vision::locate::BackendAttempt {
            backend,
            status: vision::locate::AttemptStatus::Failed,
            point: None,
            bbox: None,
            confidence: None,
            raw_response: None,
            model: Some("system-drawing-color-template".to_string()),
            base_url: None,
            elapsed_ms: started.elapsed().as_millis() as u64,
            error: Some(format!("no {} template region found", color_hint.as_str())),
        },
    }
}

async fn local_vlm_locate_attempt(
    req: &vision::locate::LocateRequest,
    capture_path: &Path,
    screen: ScreenDimensions,
    config: &ConfigVisionRouter,
    min_confidence: f32,
) -> vision::locate::BackendAttempt {
    if !config.local_vlm.enabled {
        return vision::locate::BackendAttempt::skipped(
            vision::locate::BackendId::LocalVlm,
            "local_vlm disabled by config",
        );
    }
    let base_url = configured_local_vlm_base_url(config);
    if !local_vision_endpoint_reachable(&base_url) {
        return vision::locate::BackendAttempt::skipped(
            vision::locate::BackendId::LocalVlm,
            &format!("local VLM endpoint is not reachable: {base_url}"),
        );
    }
    let model = config
        .local_vlm
        .model
        .clone()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(authoritative_local_vision_model);
    let api_key = authoritative_local_vision_api_key();
    let health_url = local_vlm_health_url(&base_url);
    let models_url = local_vlm_models_url(&base_url);
    let model_path = configured_local_vlm_model_path(&model);
    let readiness_started = std::time::Instant::now();
    let readiness = probe_local_vlm_readiness(
        true,
        &health_url,
        &models_url,
        &model,
        &model_path,
        api_key.as_deref(),
    )
    .await;
    if let Some(attempt) = local_vlm_unready_attempt(
        &readiness,
        &base_url,
        &model,
        &health_url,
        &models_url,
        &model_path,
        readiness_started.elapsed().as_millis() as u64,
    ) {
        return attempt;
    }
    let timeout_seconds = config.local_vlm.timeout_seconds.clamp(5, 180);
    let sample_count = config.local_vlm.sample_count.clamp(1, 5);
    let threshold = min_confidence.max(config.local_vlm.confidence_floor.clamp(0.0, 1.0));
    let target = locate_target_text(&req.target);
    let t0 = std::time::Instant::now();
    let mut points = Vec::new();
    let mut bbox: Option<vision::locate::BBoxPx> = None;
    let mut best_confidence: Option<f32> = None;
    let mut last_error = None;

    let variants = vision::local_backend::prompt_variants(&target);
    for index in 0..sample_count as usize {
        let prompt = variants
            .get(index % variants.len())
            .cloned()
            .unwrap_or_else(|| target.clone());
        match run_vision_find_target(VisionFindTargetRequest {
            target: Some(prompt),
            use_model: Some(true),
            use_latest_capture: Some(false),
            raw_response: None,
            capture_path: Some(capture_path.display().to_string()),
            model: Some(model.clone()),
            base_url: Some(base_url.clone()),
            api_key: api_key.clone(),
            timeout_seconds: Some(timeout_seconds),
            readiness_verified: true,
        })
        .await
        {
            Ok(response) => {
                if let Some(grounding) = response.grounding {
                    if let Some(point) = grounding.point {
                        points.push(vision::locate::PointPx {
                            x: point.x,
                            y: point.y,
                        });
                    }
                    bbox = bbox.or_else(|| {
                        grounding.bbox.map(|roi| vision::locate::BBoxPx {
                            x: roi.left,
                            y: roi.top,
                            width: roi.width,
                            height: roi.height,
                        })
                    });
                    if let Some(confidence) = grounding.confidence {
                        best_confidence = Some(
                            best_confidence.map_or(confidence, |best: f32| best.max(confidence)),
                        );
                    }
                }
                if let Some(error) = response.backend.and_then(|trace| trace.error) {
                    last_error = Some(error);
                }
            }
            Err(error) => {
                let (_, Json(err)) = error;
                last_error = Some(err.error);
            }
        }
    }

    let clustered_point =
        vision::local_backend::cluster_median(&points, 48.0, if sample_count >= 2 { 2 } else { 1 });
    let mut point = clustered_point.or_else(|| points.first().copied());
    let mut bbox = bbox;
    let mut confidence = best_confidence.unwrap_or_else(|| {
        inferred_point_only_confidence(
            point.is_some(),
            clustered_point.is_some(),
            points.len(),
            sample_count as usize,
        )
    });
    let mut grounding_note = format!(
        "samples={}, accepted_points={}, inferred_confidence={:.2}",
        sample_count,
        points.len(),
        confidence
    );
    if confidence < threshold {
        if let Some(color_hint) = colored_button_hint(&target) {
            if let Some(region) =
                locate_colored_button_region(capture_path, color_hint, screen, None).await
            {
                point = Some(region.point);
                bbox = Some(region.bbox);
                confidence = confidence.max(0.72);
                grounding_note.push_str(&format!(
                    ", color_region_fallback={}, bbox=({},{} {}x{}), pixels={}",
                    color_hint.as_str(),
                    region.bbox.x,
                    region.bbox.y,
                    region.bbox.width,
                    region.bbox.height,
                    region.pixel_count
                ));
            }
        }
    }
    let status = if point.is_some() && confidence >= threshold {
        vision::locate::AttemptStatus::Ok
    } else if point.is_some() {
        vision::locate::AttemptStatus::LowConfidence
    } else {
        vision::locate::AttemptStatus::Failed
    };

    vision::locate::BackendAttempt {
        backend: vision::locate::BackendId::LocalVlm,
        status,
        point,
        bbox,
        confidence: point.map(|_| confidence),
        raw_response: Some(grounding_note),
        model: Some(model),
        base_url: Some(base_url),
        elapsed_ms: t0.elapsed().as_millis() as u64,
        error: last_error,
    }
}

async fn remote_vlm_locate_attempt(
    req: &vision::locate::LocateRequest,
    capture_path: &Path,
    _screen: ScreenDimensions,
    config: &ConfigVisionRouter,
    min_confidence: f32,
) -> vision::locate::BackendAttempt {
    if !config.remote_vlm.enabled {
        return vision::locate::BackendAttempt::skipped(
            vision::locate::BackendId::RemoteVlm,
            "remote_vlm disabled by config",
        );
    }
    let Some(provider) = config.remote_vlm.providers.first() else {
        return vision::locate::BackendAttempt::skipped(
            vision::locate::BackendId::RemoteVlm,
            "no remote_vlm providers configured",
        );
    };
    let Some(base_url) = provider
        .base_url
        .clone()
        .filter(|value| !value.trim().is_empty())
    else {
        return vision::locate::BackendAttempt::skipped(
            vision::locate::BackendId::RemoteVlm,
            "remote_vlm provider has no base_url",
        );
    };
    let api_key = provider
        .api_key_ref
        .as_deref()
        .and_then(resolve_api_key_ref);
    let threshold = min_confidence.max(provider.confidence_floor.clamp(0.0, 1.0));
    let t0 = std::time::Instant::now();
    match run_vision_find_target(VisionFindTargetRequest {
        target: Some(locate_target_text(&req.target)),
        use_model: Some(true),
        use_latest_capture: Some(false),
        raw_response: None,
        capture_path: Some(capture_path.display().to_string()),
        model: Some(provider.model.clone()),
        base_url: Some(base_url.clone()),
        api_key,
        timeout_seconds: Some(config.timeout_ms.saturating_div(1000).clamp(5, 180)),
        // remote_vlm 有独立 Provider 配置，不应套用本地模型目录门禁。
        readiness_verified: true,
    })
    .await
    {
        Ok(response) => {
            let grounding = response.grounding;
            let point = grounding
                .as_ref()
                .and_then(|grounding| grounding.point)
                .map(|point| vision::locate::PointPx {
                    x: point.x,
                    y: point.y,
                });
            let bbox = grounding.as_ref().and_then(|grounding| {
                grounding.bbox.map(|roi| vision::locate::BBoxPx {
                    x: roi.left,
                    y: roi.top,
                    width: roi.width,
                    height: roi.height,
                })
            });
            let confidence = grounding
                .as_ref()
                .and_then(|grounding| grounding.confidence)
                .unwrap_or(if point.is_some() { 0.35 } else { 0.0 });
            let status = if point.is_some() && confidence >= threshold {
                vision::locate::AttemptStatus::Ok
            } else if point.is_some() {
                vision::locate::AttemptStatus::LowConfidence
            } else {
                vision::locate::AttemptStatus::Failed
            };
            vision::locate::BackendAttempt {
                backend: vision::locate::BackendId::RemoteVlm,
                status,
                point,
                bbox,
                confidence: point.map(|_| confidence),
                raw_response: None,
                model: Some(provider.model.clone()),
                base_url: Some(base_url),
                elapsed_ms: t0.elapsed().as_millis() as u64,
                error: response.backend.and_then(|trace| trace.error),
            }
        }
        Err(error) => {
            let (_, Json(err)) = error;
            vision::locate::BackendAttempt {
                backend: vision::locate::BackendId::RemoteVlm,
                status: vision::locate::AttemptStatus::Failed,
                point: None,
                bbox: None,
                confidence: None,
                raw_response: None,
                model: Some(provider.model.clone()),
                base_url: Some(base_url),
                elapsed_ms: t0.elapsed().as_millis() as u64,
                error: Some(err.error),
            }
        }
    }
}

fn configured_local_vlm_install_root() -> PathBuf {
    config_local_vlm_root()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
        .or_else(|| {
            env::var_os("COOLZHU_LOCAL_VLM_ROOT")
                .filter(|value| !value.is_empty())
                .map(PathBuf::from)
        })
        // 与 resources/local-vlm/start-local-vlm.ps1 的默认安装根保持一致。
        .or_else(|| user_home_dir().map(|home| home.join(".claw").join("local-vlm")))
        .unwrap_or_else(|| env::temp_dir().join("coolzhu-local-vlm"))
}

fn local_vlm_model_directory_name(model: &str) -> &str {
    let model = model.trim();
    // API model id 与资源包目录名不同；保持与打包/迁移文档中的真实目录一致。
    if model.eq_ignore_ascii_case("qwen2.5-vl-3b") {
        "Qwen2.5-VL-3B-Instruct"
    } else {
        model
    }
}

fn configured_local_vlm_model_path(model: &str) -> PathBuf {
    configured_local_vlm_install_root()
        .join("models")
        .join(local_vlm_model_directory_name(model))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct LocalVlmReadiness {
    health_reachable: bool,
    model_path_required: bool,
    model_path_exists: bool,
    models_reachable: bool,
    model_catalog_valid: bool,
    configured_model_available: bool,
    status: &'static str,
    ready: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct LocalVlmModelsProbe {
    reachable: bool,
    catalog_valid: bool,
    configured_model_available: bool,
}

fn local_vlm_readiness_status(
    enabled: bool,
    health_required: bool,
    health_reachable: bool,
    model_path_required: bool,
    model_path_exists: bool,
    models_reachable: bool,
    model_catalog_valid: bool,
    configured_model_available: bool,
) -> (&'static str, bool) {
    if !enabled {
        return ("disabled", false);
    }
    if model_path_required && !model_path_exists {
        return if health_reachable {
            ("model_missing", false)
        } else {
            ("service_unavailable_and_model_missing", false)
        };
    }
    if health_required && !health_reachable {
        return ("service_unavailable", false);
    }
    if !models_reachable {
        return ("model_catalog_unavailable", false);
    }
    if !model_catalog_valid {
        return ("model_catalog_invalid", false);
    }
    if !configured_model_available {
        return ("configured_model_unavailable", false);
    }
    ("ready", true)
}

fn local_vlm_readiness(
    enabled: bool,
    health_required: bool,
    health_reachable: bool,
    model_path_required: bool,
    model_path_exists: bool,
    models_probe: LocalVlmModelsProbe,
) -> LocalVlmReadiness {
    let (status, ready) = local_vlm_readiness_status(
        enabled,
        health_required,
        health_reachable,
        model_path_required,
        model_path_exists,
        models_probe.reachable,
        models_probe.catalog_valid,
        models_probe.configured_model_available,
    );
    LocalVlmReadiness {
        health_reachable,
        model_path_required,
        model_path_exists,
        models_reachable: models_probe.reachable,
        model_catalog_valid: models_probe.catalog_valid,
        configured_model_available: models_probe.configured_model_available,
        status,
        ready,
    }
}

fn local_vlm_models_url(base_url: &str) -> String {
    let trimmed = base_url.trim().trim_end_matches('/');
    if trimmed.ends_with("/models") {
        return trimmed.to_string();
    }
    if let Some(service_base) = trimmed.strip_suffix("/chat/completions") {
        return format!("{service_base}/models");
    }
    if trimmed.ends_with("/v1") {
        format!("{trimmed}/models")
    } else {
        format!("{trimmed}/v1/models")
    }
}

fn canonical_local_vlm_model_id(model: &str) -> String {
    let normalized = model.trim().to_ascii_lowercase();
    match normalized.as_str() {
        "qwen2.5-vl-3b" | "qwen2.5-vl-3b-instruct" => "qwen2.5-vl-3b".to_string(),
        _ => normalized,
    }
}

fn local_vlm_model_ids_match(configured: &str, advertised: &str) -> bool {
    canonical_local_vlm_model_id(configured) == canonical_local_vlm_model_id(advertised)
}

fn local_vlm_model_catalog_ids(payload: &JsonValue) -> Option<Vec<&str>> {
    let entries = if let Some(entries) = payload.as_array() {
        entries
    } else {
        payload
            .get("data")
            .or_else(|| payload.get("models"))?
            .as_array()?
    };
    Some(
        entries
            .iter()
            .filter_map(|entry| {
                entry.as_str().or_else(|| {
                    entry
                        .get("id")
                        .or_else(|| entry.get("model"))
                        .and_then(JsonValue::as_str)
                })
            })
            .collect(),
    )
}

async fn probe_local_vlm_models(
    models_url: &str,
    configured_model: &str,
    api_key: Option<&str>,
) -> LocalVlmModelsProbe {
    let client = match reqwest::Client::builder()
        .connect_timeout(Duration::from_millis(400))
        .timeout(Duration::from_millis(900))
        .build()
    {
        Ok(client) => client,
        Err(_) => {
            return LocalVlmModelsProbe {
                reachable: false,
                catalog_valid: false,
                configured_model_available: false,
            };
        }
    };
    let mut request = client.get(models_url);
    if let Some(api_key) = api_key.filter(|value| !value.trim().is_empty()) {
        request = request.bearer_auth(api_key);
    }
    let response = match request
        .send()
        .await
        .and_then(reqwest::Response::error_for_status)
    {
        Ok(response) => response,
        Err(_) => {
            return LocalVlmModelsProbe {
                reachable: false,
                catalog_valid: false,
                configured_model_available: false,
            };
        }
    };
    let payload = match response.json::<JsonValue>().await {
        Ok(payload) => payload,
        Err(_) => {
            return LocalVlmModelsProbe {
                reachable: true,
                catalog_valid: false,
                configured_model_available: false,
            };
        }
    };
    let Some(model_ids) = local_vlm_model_catalog_ids(&payload) else {
        return LocalVlmModelsProbe {
            reachable: true,
            catalog_valid: false,
            configured_model_available: false,
        };
    };
    LocalVlmModelsProbe {
        reachable: true,
        catalog_valid: true,
        configured_model_available: model_ids
            .into_iter()
            .any(|advertised| local_vlm_model_ids_match(configured_model, advertised)),
    }
}

async fn probe_local_vlm_health(health_url: &str) -> bool {
    let client = match reqwest::Client::builder()
        .connect_timeout(Duration::from_millis(400))
        .timeout(Duration::from_millis(900))
        .build()
    {
        Ok(client) => client,
        Err(_) => return false,
    };
    client
        .get(health_url)
        .send()
        .await
        .and_then(reqwest::Response::error_for_status)
        .is_ok()
}

async fn probe_local_vlm_readiness(
    enabled: bool,
    health_url: &str,
    models_url: &str,
    configured_model: &str,
    model_path: &Path,
    api_key: Option<&str>,
) -> LocalVlmReadiness {
    probe_openai_compatible_vlm_readiness(
        enabled,
        true,
        health_url,
        models_url,
        configured_model,
        Some(model_path),
        api_key,
    )
    .await
}

async fn probe_openai_compatible_vlm_readiness(
    enabled: bool,
    health_required: bool,
    health_url: &str,
    models_url: &str,
    configured_model: &str,
    required_model_path: Option<&Path>,
    api_key: Option<&str>,
) -> LocalVlmReadiness {
    let model_path_required = required_model_path.is_some();
    let model_path_exists = required_model_path.map_or(true, Path::is_dir);
    if !enabled {
        return local_vlm_readiness(
            false,
            health_required,
            false,
            model_path_required,
            model_path_exists,
            LocalVlmModelsProbe {
                reachable: false,
                catalog_valid: false,
                configured_model_available: false,
            },
        );
    }
    let (health_reachable, models_probe) = tokio::join!(
        probe_local_vlm_health(health_url),
        probe_local_vlm_models(models_url, configured_model, api_key)
    );
    local_vlm_readiness(
        true,
        health_required,
        health_reachable,
        model_path_required,
        model_path_exists,
        models_probe,
    )
}

fn local_vlm_unready_attempt(
    readiness: &LocalVlmReadiness,
    base_url: &str,
    model: &str,
    health_url: &str,
    models_url: &str,
    model_path: &Path,
    elapsed_ms: u64,
) -> Option<vision::locate::BackendAttempt> {
    if readiness.ready {
        return None;
    }
    Some(vision::locate::BackendAttempt {
        backend: vision::locate::BackendId::LocalVlm,
        status: vision::locate::AttemptStatus::Skipped,
        point: None,
        bbox: None,
        confidence: None,
        raw_response: None,
        model: Some(model.to_string()),
        base_url: Some(base_url.to_string()),
        elapsed_ms,
        error: Some(local_vlm_unready_reason(
            readiness,
            health_url,
            models_url,
            Some(model_path),
            model,
        )),
    })
}

fn local_vlm_unready_reason(
    readiness: &LocalVlmReadiness,
    health_url: &str,
    models_url: &str,
    model_path: Option<&Path>,
    model: &str,
) -> String {
    let model_path = model_path
        .map(|path| path.display().to_string())
        .unwrap_or_else(|| "not-required-for-explicit-endpoint".to_string());
    format!(
        "local_vlm not ready: status={}, health_url={}, models_url={}, model_path={}, configured_model={}",
        readiness.status,
        health_url,
        models_url,
        model_path,
        model
    )
}

async fn ensure_local_vlm_ready(
    base_url: &str,
    model: &str,
    api_key: Option<&str>,
) -> Result<(), String> {
    let health_url = local_vlm_health_url(base_url);
    let models_url = local_vlm_models_url(base_url);
    let model_path = configured_local_vlm_model_path(model);
    let readiness = probe_local_vlm_readiness(
        active_vision_router_config().local_vlm.enabled,
        &health_url,
        &models_url,
        model,
        &model_path,
        api_key,
    )
    .await;
    if readiness.ready {
        Ok(())
    } else {
        Err(local_vlm_unready_reason(
            &readiness,
            &health_url,
            &models_url,
            Some(&model_path),
            model,
        ))
    }
}

fn local_vlm_backend_status_json(
    config: &LocalVlmRouterConfig,
    base_url: String,
    model: String,
    health_url: String,
    models_url: String,
    model_path: &Path,
    readiness: &LocalVlmReadiness,
) -> JsonValue {
    json!({
        "id": "local_vlm",
        "enabled": config.enabled,
        "ready": readiness.ready,
        "status": readiness.status,
        "base_url": base_url,
        "health_url": health_url,
        "health_reachable": readiness.health_reachable,
        "models_url": models_url,
        "models_reachable": readiness.models_reachable,
        "model_catalog_valid": readiness.model_catalog_valid,
        "configured_model_available": readiness.configured_model_available,
        "model": model,
        "model_path": model_path.display().to_string(),
        "model_path_required": readiness.model_path_required,
        "model_path_exists": readiness.model_path_exists,
        "fix_hint": match readiness.status {
            "ready" => "No action required.",
            "disabled" => "Enable local_vlm before using local grounding.",
            "service_unavailable_and_model_missing" => "Install the configured local VLM model and start its health service.",
            "service_unavailable" => "Start the configured local VLM service and verify its /health endpoint returns HTTP 2xx.",
            "model_missing" => "Install the configured local VLM model under <local_vlm_root>/models/<model>.",
            "model_catalog_unavailable" => "Verify the configured local VLM service exposes an authenticated OpenAI-compatible /v1/models endpoint.",
            "model_catalog_invalid" => "Make /v1/models return an OpenAI-compatible model list such as {data:[{id:...}]}.",
            "configured_model_unavailable" => "Load the configured model in the local VLM service and expose its id from /v1/models.",
            _ => "Check the local VLM service and model installation.",
        },
    })
}

async fn api_vision_locate_backends() -> Json<serde_json::Value> {
    let config = active_vision_router_config();
    let local_base_url = config
        .local_vlm
        .base_url
        .clone()
        .unwrap_or_else(authoritative_local_vision_base_url);
    let local_model = config
        .local_vlm
        .model
        .clone()
        .unwrap_or_else(authoritative_local_vision_model);
    let local_health_url = local_vlm_health_url(&local_base_url);
    let local_models_url = local_vlm_models_url(&local_base_url);
    let local_model_path = configured_local_vlm_model_path(&local_model);
    let local_api_key = authoritative_local_vision_api_key();
    let local_readiness = probe_local_vlm_readiness(
        config.local_vlm.enabled,
        &local_health_url,
        &local_models_url,
        &local_model,
        &local_model_path,
        local_api_key.as_deref(),
    )
    .await;
    let local_vlm = local_vlm_backend_status_json(
        &config.local_vlm,
        local_base_url,
        local_model,
        local_health_url,
        local_models_url,
        &local_model_path,
        &local_readiness,
    );
    Json(json!({
        "backends": [
            { "id": "uia", "enabled": config.uia.enabled, "status": if config.uia.enabled { "ready" } else { "disabled" }, "platform_supported": true,
              "version": "Windows" },
            local_vlm,
            { "id": "remote_vlm", "enabled": config.remote_vlm.enabled,
              "status": if config.remote_vlm.providers.is_empty() { "unconfigured" } else { "ready" },
              "providers": config.remote_vlm.providers.iter().map(|provider| json!({
                  "name": provider.name.clone(),
                  "provider": provider.provider.clone(),
                  "model": provider.model.clone(),
                  "base_url": provider.base_url.clone(),
                  "has_key_ref": provider.api_key_ref.as_ref().map(|value| !value.trim().is_empty()).unwrap_or(false)
              })).collect::<Vec<_>>() }
        ],
        "pipeline": config.pipeline,
        "min_confidence": config.min_confidence,
        "cross_verify": config.cross_verify
    }))
}

fn detection_model_path_exists(config: &ConfigVisionDetection) -> bool {
    config
        .model_path
        .as_deref()
        .map(str::trim)
        .filter(|path| !path.is_empty())
        .map(|path| Path::new(path).is_file())
        .unwrap_or(false)
}

fn detection_service_health_url(base_url: Option<&str>) -> Option<String> {
    let trimmed = base_url?.trim();
    if trimmed.is_empty() {
        return None;
    }
    let without_query = trimmed
        .split('?')
        .next()
        .unwrap_or(trimmed)
        .trim_end_matches('/');
    let lower = without_query.to_ascii_lowercase();
    if lower.ends_with("/health") {
        return Some(without_query.to_string());
    }
    if lower.ends_with("/detect") {
        let prefix_len = without_query.len().saturating_sub("/detect".len());
        return Some(format!("{}/health", &without_query[..prefix_len]));
    }
    Some(format!("{}/health", without_query))
}

async fn probe_detection_service(base_url: Option<&str>) -> bool {
    let Some(health_url) = detection_service_health_url(base_url) else {
        return false;
    };
    let client = match reqwest::Client::builder()
        .connect_timeout(Duration::from_millis(500))
        .timeout(Duration::from_millis(900))
        .build()
    {
        Ok(client) => client,
        Err(_) => return false,
    };
    client
        .get(health_url)
        .send()
        .await
        .map(|response| response.status().is_success())
        .unwrap_or(false)
}

fn detection_health_cache() -> &'static Mutex<DetectionHealthSnapshot> {
    static CACHE: OnceLock<Mutex<DetectionHealthSnapshot>> = OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(DetectionHealthSnapshot::default()))
}

async fn detection_health_snapshot(config: &ConfigVisionDetection) -> DetectionHealthSnapshot {
    let base_url = config
        .base_url
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let health_url = detection_service_health_url(base_url.as_deref());
    let now = uuid_timestamp();
    if let Ok(cache) = detection_health_cache().lock() {
        if cache.base_url == base_url
            && now.saturating_sub(cache.checked_at_ms) <= DETECTION_HEALTH_CACHE_TTL_MS
        {
            return cache.clone();
        }
    }
    let reachable = probe_detection_service(base_url.as_deref()).await;
    let snapshot = DetectionHealthSnapshot {
        base_url,
        health_url,
        reachable,
        checked_at_ms: now,
    };
    if let Ok(mut cache) = detection_health_cache().lock() {
        *cache = snapshot.clone();
    }
    snapshot
}

fn detection_launcher_hint(config: &ConfigVisionDetection) -> Option<String> {
    let backend = config.backend.trim().to_ascii_lowercase();
    if !backend.contains("uidetr") && !backend.contains("ui-detr") && !backend.contains("rf-detr") {
        return None;
    }
    let model_arg = config
        .model_path
        .as_deref()
        .map(str::trim)
        .filter(|path| !path.is_empty())
        .unwrap_or("<path-to-ui-detr-checkpoint>");
    Some(format!(
        "python modules/vision/resources/uidetr/uidetr_service.py --model \"{}\" --host 127.0.0.1 --port 7860",
        model_arg.replace('"', "\\\"")
    ))
}

async fn api_vision_realtime_status() -> Json<VisionRealtimeStatusResponse> {
    let config = active_vision_router_config();
    let state = vision_realtime_state()
        .lock()
        .map(|state| state.clone())
        .unwrap_or_default();
    let resource_switch = vision_resource_switch_dto(&config);
    let active_loop = if !config.detection.enabled {
        "disabled"
    } else if state.loop_running {
        "running_realtime_perception"
    } else if state.loop_requested {
        "waiting_for_detection_backend"
    } else if state.updated_at_ms.is_some() {
        "element_table_ready"
    } else {
        "reserved_realtime_perception"
    };
    let detection_model_path_exists = detection_model_path_exists(&config.detection);
    let detection_health = detection_health_snapshot(&config.detection).await;
    let detection_service_health_url = detection_health.health_url.clone();
    let detection_service_reachable = detection_health.reachable;
    let detection_launcher_hint = detection_launcher_hint(&config.detection);
    let mut notes = vec![
        "ShowUI remains the default natural-language grounding backend.".to_string(),
        "UI-DETR-1 is modeled as a detection backend that outputs element boxes for the fast perception loop.".to_string(),
    ];
    if config.detection.base_url.is_none() {
        notes.push(
            "Configure vision.router.detection.base_url to enable the background detector polling loop."
                .to_string(),
        );
    } else if !detection_service_reachable {
        notes.push(
            "Detection service is offline; start the detector wrapper before realtime UI element polling."
                .to_string(),
        );
    }
    if config.detection.model_path.is_none() {
        notes.push(
            "Configure vision.router.detection.model_path with the UI-DETR/RF-DETR checkpoint path for local service launch."
                .to_string(),
        );
    } else if !detection_model_path_exists {
        notes.push(
            "Configured detection model_path does not point to an existing file.".to_string(),
        );
    }

    Json(VisionRealtimeStatusResponse {
        status: active_loop.to_string(),
        enabled: config.detection.enabled,
        active_loop: active_loop.to_string(),
        loop_requested: state.loop_requested,
        loop_running: state.loop_running,
        frames_processed: state.frames_processed,
        fps: config.detection.fps,
        detection_backend: config.detection.backend.clone(),
        detection_model: config.detection.model.clone(),
        detection_model_path: config.detection.model_path.clone(),
        detection_model_path_exists,
        detection_base_url: config.detection.base_url.clone(),
        detection_service_reachable,
        detection_service_health_url,
        detection_launcher_hint,
        element_count: state.elements.len(),
        last_frame_ms: state.updated_at_ms,
        started_at_ms: state.started_at_ms,
        stopped_at_ms: state.stopped_at_ms,
        last_error: state.last_error.clone(),
        last_capture_path: state.last_capture_path.clone(),
        showui_role: "on_demand_grounding".to_string(),
        uidetr_role: "realtime_detection_element_table".to_string(),
        resource_switch,
        notes,
    })
}

