async fn api_vision_realtime_events(
) -> Sse<impl futures_core::Stream<Item = Result<Event, std::convert::Infallible>>> {
    let mut rx = vision_realtime_event_bus().subscribe();
    let stream = async_stream::stream! {
        yield Ok::<Event, std::convert::Infallible>(
            Event::default().event("hello").data("{\"ok\":true,\"service\":\"vision-realtime\"}"),
        );
        loop {
            match rx.recv().await {
                Ok(event) => {
                    yield Ok(sse_json_event("element-table-updated", &event));
                }
                Err(broadcast::error::RecvError::Lagged(n)) => {
                    let payload = format!(r#"{{"skipped":{n}}}"#);
                    yield Ok(Event::default().event("lagged").data(payload));
                }
                Err(broadcast::error::RecvError::Closed) => break,
            }
        }
    };
    Sse::new(stream)
}

async fn api_vision_realtime_start(
    payload: Option<Json<VisionRealtimeControlRequest>>,
) -> Json<VisionRealtimeStatusResponse> {
    let config = active_vision_router_config();
    let use_latest_capture = payload
        .map(|Json(payload)| payload.use_latest_capture.unwrap_or(true))
        .unwrap_or(true);
    let now = unix_timestamp_millis();

    if !config.detection.enabled {
        update_vision_realtime_loop_state(
            false,
            false,
            Some("detection backend disabled".to_string()),
        );
        return api_vision_realtime_status().await;
    }

    let Some(base_url) = config
        .detection
        .base_url
        .clone()
        .filter(|value| !value.trim().is_empty())
    else {
        if let Ok(mut state) = vision_realtime_state().lock() {
            state.loop_requested = true;
            state.loop_running = false;
            state.started_at_ms = Some(now);
            state.stopped_at_ms = None;
            state.last_error = Some(
                "vision.router.detection.base_url is not configured; waiting for UI-DETR service"
                    .to_string(),
            );
        }
        return api_vision_realtime_status().await;
    };

    let already_running = vision_realtime_loop_handle()
        .lock()
        .ok()
        .and_then(|handle| handle.as_ref().map(|task| !task.is_finished()))
        .unwrap_or(false);
    if !already_running {
        let mut loop_config = config.clone();
        loop_config.detection.base_url = Some(base_url);
        let handle = tokio::spawn(async move {
            vision_realtime_loop_task(loop_config, use_latest_capture).await;
        });
        if let Ok(mut stored) = vision_realtime_loop_handle().lock() {
            if let Some(previous) = stored.replace(handle) {
                previous.abort();
            }
        }
    }
    if let Ok(mut state) = vision_realtime_state().lock() {
        state.loop_requested = true;
        state.loop_running = true;
        state.started_at_ms = Some(now);
        state.stopped_at_ms = None;
        state.last_error = None;
    }
    api_vision_realtime_status().await
}

async fn api_vision_realtime_stop() -> Json<VisionRealtimeStatusResponse> {
    if let Ok(mut handle) = vision_realtime_loop_handle().lock() {
        if let Some(task) = handle.take() {
            task.abort();
        }
    }
    if let Ok(mut state) = vision_realtime_state().lock() {
        state.loop_requested = false;
        state.loop_running = false;
        state.stopped_at_ms = Some(unix_timestamp_millis());
        state.last_error = None;
    }
    api_vision_realtime_status().await
}

#[derive(Debug, Default, Deserialize)]
struct VisionRealtimeUnderstandRequest {
    /// 自定义问题；缺省为"描述当前屏幕的主要内容与可执行的下一步操作"。
    #[serde(default)]
    question: Option<String>,
    /// 拼入 prompt 的元素表上限（默认 12）。
    #[serde(default)]
    max_elements: Option<usize>,
}

#[derive(Debug, Serialize)]
struct VisionRealtimeUnderstandResponse {
    status: String,
    summary: String,
    element_count: usize,
    session_id: String,
    model: String,
    elapsed_ms: u64,
}

/// 实时视觉理解联动（P1）：UI-DETR 元素表（坐标，实时）× 当前选中的视觉理解会话（语义，按需）。
/// 截当前桌面 → 拼元素表摘要 → 调 active_vision_session_id 多模态会话理解 → SSE 广播 + 返回。
/// 理解模型完全由总览选择器决定（agnes / glm / 任意多模态会话），不固化。
async fn api_vision_realtime_understand(
    payload: Option<Json<VisionRealtimeUnderstandRequest>>,
) -> ApiResult<Json<VisionRealtimeUnderstandResponse>> {
    let started = Instant::now();
    let request = payload.map(|Json(p)| p).unwrap_or_default();
    let active_id = session_store()
        .lock()
        .ok()
        .and_then(|store| store.state.active_vision_session_id.clone())
        .ok_or_else(|| {
            api_error(
                StatusCode::BAD_REQUEST,
                "未选中视觉理解模型：请在总览或设置中选择一个多模态会话",
            )
        })?;
    let agent = default_agent_sessions()
        .into_iter()
        .find(|agent| agent.id == active_id)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "选中的视觉理解会话不存在"))?;

    // 截当前桌面并转 data URI（多模态消息直接携带，无需公网可达）。
    // 路径与 computer-use 闭环同源（closed_loop_capture_path），避免 workspace 路径差异。
    let shot_path = closed_loop_capture_path(unix_timestamp_millis(), "understand");
    capture_desktop(&shot_path).await?;
    let shot_bytes = tokio::fs::read(&shot_path).await.map_err(io_api_error)?;
    let image_data_uri = format!("data:image/png;base64,{}", base64_encode(&shot_bytes));

    // UI-DETR 实时元素表摘要（label/kind/相对 bbox），给理解模型提供坐标语义线索。
    let max_elements = request.max_elements.unwrap_or(12).clamp(1, 50);
    let (element_count, element_summary) = {
        let state = vision_realtime_state()
            .lock()
            .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "视觉实时状态锁已损坏"))?;
        let total = state.elements.len();
        let lines = state
            .elements
            .iter()
            .take(max_elements)
            .map(|element| {
                let name = element
                    .label
                    .as_deref()
                    .or(element.text.as_deref())
                    .unwrap_or(element.kind.as_str());
                format!(
                    "- {name} [{}] bbox=({:.2},{:.2},{:.2},{:.2})",
                    element.kind,
                    element.bbox.x1,
                    element.bbox.y1,
                    element.bbox.x2,
                    element.bbox.y2
                )
            })
            .collect::<Vec<_>>()
            .join("\n");
        (total, lines)
    };

    let question = request
        .question
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("描述当前屏幕的主要内容与可执行的下一步操作");
    let element_section = if element_count > 0 {
        format!("UI-DETR 检测到 {element_count} 个元素（相对坐标 0-1）：\n{element_summary}")
    } else {
        "UI-DETR 元素表为空（检测循环未运行或当前帧无元素）。".to_string()
    };
    let prompt = format!(
        "【实时视觉理解】{question}\n\n{element_section}\n\n请结合截图与元素表，用中文简洁回答（120 字以内）。"
    );

    diag!(
        "[VISION-UNDERSTAND] session={} model={} elements={} prompt_len={}",
        agent.id,
        agent.model,
        element_count,
        prompt.len()
    );
    let response = call_agent_model(&agent, &prompt, &[image_data_uri], &[], None)
        .await
        .map_err(|error| {
            api_error(
                StatusCode::BAD_GATEWAY,
                &format!("视觉理解模型调用失败: {error:?}"),
            )
        })?;
    let summary = response.answer_text.trim().to_string();
    let elapsed_ms = elapsed_millis(started);

    emit_realtime_session_event(
        "vision_understanding",
        realtime_session_state()
            .lock()
            .ok()
            .and_then(|state| state.session_id.clone()),
        json!({
            "session_id": agent.id.clone(),
            "model": agent.model.clone(),
            "element_count": element_count,
            "summary": summary.clone(),
            "elapsed_ms": elapsed_ms,
        }),
    );

    Ok(Json(VisionRealtimeUnderstandResponse {
        status: if summary.is_empty() { "empty" } else { "ok" }.to_string(),
        summary,
        element_count,
        session_id: agent.id,
        model: agent.model,
        elapsed_ms,
    }))
}

async fn api_vision_realtime_frame(
    Json(payload): Json<VisionRealtimeFrameRequest>,
) -> Json<VisionRealtimeFrameResponse> {
    let config = active_vision_router_config();
    if let Ok(mut handle) = vision_realtime_loop_handle().lock() {
        if let Some(task) = handle.take() {
            task.abort();
        }
    }
    let raw_response = payload.raw_response.unwrap_or_default();
    let min_confidence = payload
        .min_confidence
        .unwrap_or(config.detection.min_confidence)
        .clamp(0.0, 1.0);
    let max_elements = payload
        .max_elements
        .unwrap_or(config.detection.max_elements)
        .min(config.detection.max_elements.max(1));
    let elements = parse_detection_elements(&raw_response, min_confidence, max_elements)
        .into_iter()
        .map(vision_realtime_element_dto)
        .collect::<Vec<_>>();
    let updated_at_ms = unix_timestamp_millis();
    let resource_switch = vision_resource_switch_dto(&config);
    let response = VisionRealtimeFrameResponse {
        status: if elements.is_empty() {
            "no-elements"
        } else {
            "parsed"
        }
        .to_string(),
        accepted: elements.len(),
        backend: config.detection.backend.clone(),
        model: config.detection.model.clone(),
        elements: elements.clone(),
        notes: vec![
            "Parsed UI-DETR-style detection output without invoking a model.".to_string(),
            "A real detector process can feed this endpoint until the realtime service loop is enabled.".to_string(),
        ],
    };
    if let Ok(mut state) = vision_realtime_state().lock() {
        state.updated_at_ms = Some(updated_at_ms);
        state.backend = Some(config.detection.backend.clone());
        state.model = Some(config.detection.model.clone());
        state.source = payload.source;
        state.elements = elements;
        state.frames_processed = state.frames_processed.saturating_add(1);
        state.last_error = None;
        state.loop_requested = false;
        state.loop_running = false;
    }
    broadcast_vision_realtime_event(VisionRealtimeEventDto {
        event_type: "element-table-updated".to_string(),
        updated_at_ms,
        status: response.status.clone(),
        active_loop: "element_table_ready".to_string(),
        fps: config.detection.fps,
        backend: response.backend.clone(),
        model: response.model.clone(),
        element_count: response.accepted,
        resource_switch,
        elements: response.elements.clone(),
    });
    emit_realtime_session_event(
        "vision_frame",
        realtime_session_state()
            .lock()
            .ok()
            .and_then(|state| state.session_id.clone()),
        json!({
            "updated_at_ms": updated_at_ms,
            "status": response.status.clone(),
            "active_loop": "element_table_ready",
            "backend": response.backend.clone(),
            "model": response.model.clone(),
            "element_count": response.accepted
        }),
    );
    Json(response)
}

async fn vision_realtime_loop_task(config: ConfigVisionRouter, use_latest_capture: bool) {
    let fps = config.detection.fps.clamp(0.2, 8.0);
    let interval = Duration::from_millis((1000.0 / fps).round() as u64);
    loop {
        let capture_path = default_latest_desktop_capture_path();
        let result =
            vision_realtime_capture_and_detect(&config, &capture_path, use_latest_capture).await;
        match result {
            Ok(elements) => {
                let updated_at_ms = unix_timestamp_millis();
                let source = capture_path.display().to_string();
                let dtos = elements
                    .into_iter()
                    .map(vision_realtime_element_dto)
                    .collect::<Vec<_>>();
                if let Ok(mut state) = vision_realtime_state().lock() {
                    state.updated_at_ms = Some(updated_at_ms);
                    state.backend = Some(config.detection.backend.clone());
                    state.model = Some(config.detection.model.clone());
                    state.source = Some(source.clone());
                    state.last_capture_path = Some(source);
                    state.elements = dtos.clone();
                    state.frames_processed = state.frames_processed.saturating_add(1);
                    state.loop_requested = true;
                    state.loop_running = true;
                    state.last_error = None;
                }
                broadcast_vision_realtime_event(VisionRealtimeEventDto {
                    event_type: "element-table-updated".to_string(),
                    updated_at_ms,
                    status: "detected".to_string(),
                    active_loop: "running_realtime_perception".to_string(),
                    fps: config.detection.fps,
                    backend: config.detection.backend.clone(),
                    model: config.detection.model.clone(),
                    element_count: dtos.len(),
                    resource_switch: vision_resource_switch_dto(&config),
                    elements: dtos,
                });
                emit_realtime_session_event(
                    "vision_frame",
                    realtime_session_state()
                        .lock()
                        .ok()
                        .and_then(|state| state.session_id.clone()),
                    json!({
                        "updated_at_ms": updated_at_ms,
                        "status": "detected",
                        "active_loop": "running_realtime_perception",
                        "backend": config.detection.backend.clone(),
                        "model": config.detection.model.clone(),
                        "element_count": vision_realtime_state()
                            .lock()
                            .ok()
                            .map(|state| state.elements.len())
                            .unwrap_or(0)
                    }),
                );
            }
            Err(error) => {
                update_vision_realtime_loop_state(
                    true,
                    true,
                    Some(classify_vision_error(&error.to_string())),
                );
            }
        }
        tokio::time::sleep(interval).await;
    }
}

async fn vision_realtime_capture_and_detect(
    config: &ConfigVisionRouter,
    capture_path: &Path,
    use_latest_capture: bool,
) -> Result<Vec<vision::DetectionElement>, String> {
    if use_latest_capture || !capture_path.exists() {
        capture_desktop(capture_path)
            .await
            .map_err(|error| format!("{error:?}"))?;
    }
    let base_url = config
        .detection
        .base_url
        .clone()
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| "vision.router.detection.base_url is not configured".to_string())?;
    let backend = HttpDetectionBackend::new(base_url, config.detection.model.clone())
        .with_timeout_seconds((config.timeout_ms / 1000).max(5));
    let request = DetectionRequest {
        image: VisionImageSource::Path(capture_path.to_path_buf()),
        min_confidence: config.detection.min_confidence,
        max_elements: config.detection.max_elements,
    };
    tokio::task::spawn_blocking(move || backend.detect(&request).map(|frame| frame.elements))
        .await
        .map_err(|error| format!("detection task failed: {error}"))?
        .map_err(|error| error.to_string())
}

fn update_vision_realtime_loop_state(requested: bool, running: bool, error: Option<String>) {
    if let Ok(mut state) = vision_realtime_state().lock() {
        state.loop_requested = requested;
        state.loop_running = running;
        state.last_error = error;
    }
}

fn vision_resource_switch_dto(config: &ConfigVisionRouter) -> VisionResourceSwitchDto {
    let switch = &config.resource_switch;
    let allow_concurrent = switch.allow_concurrent;
    let uidetr_active = switch
        .active_profile
        .to_ascii_lowercase()
        .contains("uidetr");
    VisionResourceSwitchDto {
        mode: switch.mode.clone(),
        active_profile: switch.active_profile.clone(),
        allow_concurrent,
        vram_budget_mb: switch.vram_budget_mb,
        showui_state: if allow_concurrent || !uidetr_active {
            "on_demand_available"
        } else {
            "standby_for_vram"
        }
        .to_string(),
        uidetr_state: if !config.detection.enabled {
            "disabled"
        } else if allow_concurrent || uidetr_active {
            "reserved_active"
        } else {
            "reserved_standby"
        }
        .to_string(),
        reason: if allow_concurrent {
            "concurrent local vision models allowed by resource profile"
        } else {
            "single active local vision model; ShowUI grounding and UI-DETR perception switch by task role"
        }
        .to_string(),
    }
}

fn vision_realtime_element_dto(element: vision::DetectionElement) -> VisionRealtimeElementDto {
    VisionRealtimeElementDto {
        id: element.id,
        kind: detection_element_kind_label(element.kind).to_string(),
        label: element.label,
        text: element.text,
        bbox: VisionRelativeBBoxDto {
            x1: element.bbox.x1,
            y1: element.bbox.y1,
            x2: element.bbox.x2,
            y2: element.bbox.y2,
        },
        confidence: element.confidence,
    }
}

fn detection_element_kind_label(kind: DetectionElementKind) -> &'static str {
    match kind {
        DetectionElementKind::Button => "button",
        DetectionElementKind::Icon => "icon",
        DetectionElementKind::Text => "text",
        DetectionElementKind::Input => "input",
        DetectionElementKind::Menu => "menu",
        DetectionElementKind::Window => "window",
        DetectionElementKind::Checkbox => "checkbox",
        DetectionElementKind::Slider => "slider",
        DetectionElementKind::Unknown => "unknown",
    }
}

async fn api_vision_locate_verify(
    Json(payload): Json<serde_json::Value>,
) -> ApiResult<Json<serde_json::Value>> {
    let point_x = payload["point"]["x"].as_i64().unwrap_or(0) as i32;
    let point_y = payload["point"]["y"].as_i64().unwrap_or(0) as i32;
    let target = payload["target"].as_str().unwrap_or("unknown");

    // Re-use verify_cursor_on_target
    let ok = verify_cursor_on_target(point_x, point_y, target).await;
    Ok(Json(json!({
        "verdict": if ok { "pass" } else { "fail" },
        "confidence": if ok { 0.9 } else { 0.0 },
        "reasoning": if ok { "LLM confirmed cursor on target" } else { "LLM could not confirm" },
        "elapsed_ms": 0
    })))
}

