fn webview2_runtime_check() -> DiagnosticsCheck {
    let candidates = webview2_runtime_candidates();
    webview2_runtime_check_for(&candidates)
}

fn webview2_runtime_candidates() -> Vec<PathBuf> {
    let mut candidates = Vec::new();
    if let Ok(folder) = env::var("WEBVIEW2_BROWSER_EXECUTABLE_FOLDER") {
        let trimmed = folder.trim();
        if !trimmed.is_empty() {
            let override_path = PathBuf::from(trimmed);
            candidates.push(override_path.join("msedgewebview2.exe"));
            candidates.push(override_path);
        }
    }
    #[cfg(windows)]
    {
        let roots = vec![
            PathBuf::from(r"C:\Program Files (x86)\Microsoft\EdgeWebView\Application"),
            PathBuf::from(r"C:\Program Files\Microsoft\EdgeWebView\Application"),
        ];
        candidates.extend(webview2_runtime_candidates_for_roots(&roots));
    }
    candidates
}

/// 为已知的 WebView2 Application 根目录生成候选，不做全盘或递归搜索。
/// 标准安装通常把真实 exe 放在 Application\\<版本>\\ 下，同时保留根目录直放候选以兼容既有布局。
fn webview2_runtime_candidates_for_roots(roots: &[PathBuf]) -> Vec<PathBuf> {
    let mut candidates = Vec::new();
    for root in roots {
        candidates.push(root.join("msedgewebview2.exe"));

        let mut version_dirs = std::fs::read_dir(root)
            .ok()
            .into_iter()
            .flatten()
            .filter_map(Result::ok)
            .map(|entry| entry.path())
            .filter(|path| path.is_dir())
            .collect::<Vec<_>>();
        version_dirs.sort();
        candidates.extend(
            version_dirs
                .into_iter()
                .map(|version_dir| version_dir.join("msedgewebview2.exe")),
        );
    }
    candidates
}

fn webview2_runtime_check_for(candidates: &[PathBuf]) -> DiagnosticsCheck {
    if let Some(path) = candidates.iter().find(|path| path.is_file()) {
        diagnostics_check(
            "desktop.webview2",
            "WebView2 Runtime",
            "ok",
            &format!("WebView2 Runtime candidate found at {}.", path.display()),
            Some("No action required."),
        )
    } else {
        diagnostics_check(
            "desktop.webview2",
            "WebView2 Runtime",
            "warn",
            "WebView2 Runtime was not found in common install paths.",
            Some(
                "Install Microsoft Edge WebView2 Runtime or set WEBVIEW2_BROWSER_EXECUTABLE_FOLDER to the runtime folder before launching the Tauri shell.",
            ),
        )
    }
}

fn agent_health(agent: &AgentSessionDto) -> AgentHealthDto {
    let diagnostics = agent_diagnostics(agent);
    AgentHealthDto {
        agent_id: diagnostics.agent_id,
        name: agent.name.clone(),
        provider_label: diagnostics.provider_label,
        provider_kind: diagnostics.provider_kind,
        selected_provider_kind: diagnostics.selected_provider_kind,
        detected_provider_kind: diagnostics.detected_provider_kind,
        provider_match: diagnostics.provider_match,
        provider_slug: diagnostics.provider_slug,
        model: diagnostics.model,
        canonical_model: diagnostics.canonical_model,
        api_model_id: diagnostics.api_model_id,
        base_url: diagnostics.base_url,
        base_url_default: diagnostics.base_url_default,
        base_url_env: diagnostics.base_url_env,
        base_url_env_present: diagnostics.base_url_env_present,
        base_url_source: diagnostics.base_url_source,
        base_url_matches_default: diagnostics.base_url_matches_default,
        api_key_present: diagnostics.api_key_present,
        api_key_source: diagnostics.api_key_source,
        api_key_status: diagnostics.api_key_status,
        env_keys: diagnostics.env_keys,
        recommended_models: diagnostics.recommended_models,
        provider_status: diagnostics.provider_status,
        provider_issue: diagnostics.provider_issue,
    }
}

fn aggregate_health_status(checks: &[DiagnosticsCheck]) -> String {
    if checks.iter().any(|check| check.status == "error") {
        "error".to_string()
    } else if checks.iter().any(|check| check.status == "warn") {
        "warn".to_string()
    } else {
        "ok".to_string()
    }
}

fn session_api_key(session_id: &str) -> Option<String> {
    let started = Instant::now();
    diag!("[API-KEY] session={session_id} lock start");
    let api_key_ref = {
        let store = session_store().lock().ok()?;
        diag!(
            "[API-KEY] session={session_id} lock acquired: elapsed_ms={}",
            elapsed_millis(started)
        );
        store
            .state
            .sessions
            .iter()
            .find(|session| session.id == session_id)
            .map(|session| session.api_key_ref.clone())?
    };
    diag!(
        "{}",
        api_key_reference_presence_log(session_id, &api_key_ref)
    );
    let result = resolve_api_key_ref(&api_key_ref);
    diag!("[API-KEY] resolved: has_key={}", result.is_some());
    result
}

fn api_key_reference_presence_log(session_id: &str, api_key_ref: &str) -> String {
    format!(
        "[API-KEY] session={session_id}, reference_present={}",
        !api_key_ref.trim().is_empty()
    )
}

fn resolve_api_key_ref(value: &str) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return None;
    }
    if looks_like_secret(trimmed) {
        return Some(trimmed.to_string());
    }

    let path = PathBuf::from(trimmed);
    let candidates = if path.is_absolute() {
        vec![path]
    } else {
        let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let workspace = active_workspace_path();
        let store_parent = workspace.join(".coolzhu");
        vec![
            cwd.join(trimmed),
            store_parent.join(trimmed),
            workspace.join(trimmed),
            cwd.join(".coolzhu").join(trimmed),
        ]
    };

    candidates
        .into_iter()
        .find_map(|candidate| std::fs::read_to_string(candidate).ok())
        .map(|content| content.trim().trim_start_matches('\u{feff}').to_string())
        .filter(|content| !content.is_empty())
}

fn looks_like_secret(value: &str) -> bool {
    let lower = value.to_ascii_lowercase();
    lower.starts_with("sk-")
        || lower.starts_with("sk_")
        || lower.starts_with("dashscope-")
        || value.len() >= 32 && !value.contains(['/', '\\']) && !value.ends_with(".txt")
}

fn persist_auto_memory_beads(messages: &[ChatMessageDto]) {
    persist_auto_memory_beads_at_path(None, messages);
}

/// Goal 自动结果的 memory 写入必须再次确认当前 store 仍指向模型调用前捕获的 DB，
/// 避免 workspace reload 后把旧结果沉淀到新 workspace。
fn persist_auto_memory_beads_at_path(expected_path: Option<&Path>, messages: &[ChatMessageDto]) {
    let Ok(mut store) = session_store().lock() else {
        return;
    };
    if expected_path.is_some_and(|path| store.path != path) {
        return;
    }
    let mut write_span = diagnostics::start_span("memory.write", "memory");
    diagnostics::info(
        "memory",
        "write.begin",
        "自动沉淀记忆",
        &[("messages", messages.len().to_string())],
    );
    let mut written = 0usize;
    let session_targets = store
        .state
        .sessions
        .iter()
        .map(|session| {
            (
                session.id.clone(),
                session.name.clone(),
                session.summary(false).display_name,
            )
        })
        .collect::<Vec<_>>();

    for message in messages {
        let Some(decision) = evaluate_auto_memory_candidate(message) else {
            continue;
        };
        let Some((target_id, _, _)) = session_targets.iter().find(|(_, name, display_name)| {
            message.author.starts_with(name)
                || message.author.starts_with(display_name)
                || message.target.contains(name)
                || message.target.contains(display_name)
        }) else {
            continue;
        };
        // G 写入策略：过滤低价值（噪声：空/纯标点/极短）内容，不自动沉淀为记忆。
        if runtime::is_low_value_memory(&message.content) {
            continue;
        }
        let summary = format!(
            "{}: {}",
            message.author,
            message.content.chars().take(220).collect::<String>()
        );
        // REQ-MEM-006：自动沉淀时携"origin 归因；消息后续被删除时触发连带删除。
        let token_count = estimate_bead_tokens(&summary);
        let _ = store.add_memory_bead(
            target_id,
            AddMemoryBeadRequest {
                summary,
                kind: Some(decision.kind.to_string()),
                source: Some("chat-room:auto-extract".to_string()),
                pinned: Some(false),
                layer: Some(decision.layer.to_string()),
                confidence: Some(decision.confidence),
                origin_message_id: Some(message.id.clone()),
                origin_table: Some("chat_room_messages".to_string()),
                token_count: Some(token_count),
                entity_key: None,
            },
        );
        written += 1;
    }
    write_span.record("outcome", "ok");
    diagnostics::info(
        "memory",
        "write.ok",
        "自动记忆沉淀完成",
        &[
            ("written", written.to_string()),
            ("messages", messages.len().to_string()),
        ],
    );
}

/// REQ-WEB-CTX-001：Bead 文本 token 数估算。
///
/// 默认采用字符 × 系数的粗估（中文 "0.55 tok/char、英""0.25 tok/char。
/// 混合 "0.40 tok/char）。`ContextBuilder` 用此字段做预算分配，精度不敏感；
/// Phase C 可替换为 provider-specific tokenizer。
fn estimate_bead_tokens(text: &str) -> u32 {
    if text.is_empty() {
        return 0;
    }
    let mut cjk = 0usize;
    let mut ascii = 0usize;
    for ch in text.chars() {
        if ch.is_ascii() {
            ascii += 1;
        } else if ('\u{4E00}'..='\u{9FFF}').contains(&ch)
            || ('\u{3040}'..='\u{30FF}').contains(&ch)
            || ('\u{AC00}'..='\u{D7A3}').contains(&ch)
        {
            cjk += 1;
        } else {
            ascii += 1;
        }
    }
    let estimate = ((cjk as f32) * 0.55 + (ascii as f32) * 0.25).ceil() as u32;
    estimate.max(1)
}

fn persist_reference_forward_memory(
    reference_context: &ChatReferenceContext,
    targets: &[AgentSessionDto],
) {
    if reference_context.is_empty() {
        return;
    }
    let Ok(mut store) = session_store().lock() else {
        return;
    };
    for agent in targets {
        let Some(summary) = reference_context.memory_summary_for(agent) else {
            continue;
        };
        let _ = store.add_memory_bead(
            &agent.id,
            AddMemoryBeadRequest {
                summary,
                kind: Some("chat-room".to_string()),
                source: Some("chat-room:reference-forward".to_string()),
                pinned: Some(false),
                layer: Some("L2".to_string()),
                confidence: Some(if reference_context.is_forward() {
                    0.78
                } else {
                    0.7
                }),
                ..AddMemoryBeadRequest::default()
            },
        );
    }
}

fn persist_group_send_shared_memory(
    reference_context: &ChatReferenceContext,
    targets: &[AgentSessionDto],
) {
    let Some(summary) = reference_context.shared_memory_summary() else {
        return;
    };
    let token_count = estimate_bead_tokens(&summary);
    let Ok(mut store) = session_store().lock() else {
        return;
    };
    for agent in targets {
        let _ = store.add_memory_bead(
            &agent.id,
            AddMemoryBeadRequest {
                summary: summary.clone(),
                kind: Some("chat-room-shared".to_string()),
                source: Some("chat-room:group-send".to_string()),
                pinned: Some(false),
                layer: Some("L2".to_string()),
                confidence: Some(0.76),
                token_count: Some(token_count),
                ..AddMemoryBeadRequest::default()
            },
        );
    }
}

async fn latest_capture_metadata() -> CaptureMetadata {
    let path = default_latest_desktop_capture_path();
    let metadata = tokio::fs::metadata(&path).await.ok();
    CaptureMetadata {
        path: path.display().to_string(),
        exists: metadata.is_some(),
        bytes: metadata.as_ref().map(std::fs::Metadata::len).unwrap_or(0),
        modified_at: metadata
            .and_then(|metadata| metadata.modified().ok())
            .and_then(system_time_millis),
        preview_url: "/api/capture/latest/image".to_string(),
    }
}

