#[derive(Debug, Clone, Copy)]
struct ContextLifecyclePolicy {
    warning_percent: u32,
    auto_compact_percent: u32,
    history_budget_percent: u32,
    memory_budget_percent: u32,
    output_reserve_percent: u32,
    prompt_safety_tokens: u32,
    image_token_estimate: u32,
    model_budget_min_tokens: u32,
    compact_summary_max_messages: usize,
    compact_summary_max_chars: usize,
    cleanup_goal_scratch_on_compact: bool,
}

impl Default for ContextLifecyclePolicy {
    fn default() -> Self {
        ConfigContextLifecycle::default().into()
    }
}

impl From<ConfigContextLifecycle> for ContextLifecyclePolicy {
    fn from(config: ConfigContextLifecycle) -> Self {
        let warning_percent = config.warning_percent.clamp(1, 100);
        let auto_compact_percent = config.auto_compact_percent.clamp(warning_percent, 100);
        Self {
            warning_percent,
            auto_compact_percent,
            history_budget_percent: config.history_budget_percent.clamp(1, 95),
            memory_budget_percent: config.memory_budget_percent.clamp(1, 50),
            output_reserve_percent: config.output_reserve_percent.clamp(0, 50),
            prompt_safety_tokens: config.prompt_safety_tokens.clamp(0, 16_384),
            image_token_estimate: config.image_token_estimate.clamp(64, 8_192),
            model_budget_min_tokens: config.model_budget_min_tokens.max(1),
            compact_summary_max_messages: config.compact_summary_max_messages.clamp(1, 100),
            compact_summary_max_chars: config.compact_summary_max_chars.clamp(240, 12_000),
            cleanup_goal_scratch_on_compact: config.cleanup_goal_scratch_on_compact,
        }
    }
}

