fn append_goal_trigger_consultation(
    db_path: &Path,
    workspace_id: &str,
    result: &PreparedChatDispatch,
    messages: &mut Vec<ChatMessageDto>,
    tasks: &mut Vec<AgentTaskDto>,
) -> ApiResult<Vec<ChatMessageDto>> {
    let Some(trigger) = result.goal_trigger.as_ref() else {
        return Ok(Vec::new());
    };
    let mut goal = create_goal_sqlite(
        db_path,
        workspace_id,
        &result.chat_room_id,
        CreateGoalRequest {
            title: trigger.title.clone(),
            chat_room_id: Some(result.chat_room_id.clone()),
            max_iterations: Some(20),
            background: Some(true),
            originating_user_msg_id: result.messages.first().map(|message| message.id.clone()),
            completion_condition: Some(json!({ "type": "UserConfirm" })),
        },
    )?;
    ensure_goal_trigger_commander_config(db_path, trigger)?;
    let roles_ready = goal_trigger_role_config_ready(db_path, trigger);
    let status = if roles_ready {
        "goal-ready"
    } else {
        "goal-consult"
    };
    if roles_ready {
        goal = set_goal_plan_sqlite(
            db_path,
            workspace_id,
            &goal.id,
            default_goal_trigger_plan(&goal.title),
        )?;
    }
    let candidate_labels = trigger
        .candidate_sessions
        .iter()
        .map(|session| session.display_name.as_str())
        .collect::<Vec<_>>()
        .join(", ");
    let role_line = if roles_ready {
        "Goal role config is already available; reverse consultation is skipped.".to_string()
    } else {
        format!(
            "Please assign temporary Goal roles before dispatch. Candidates: {}.",
            if candidate_labels.is_empty() {
                "none"
            } else {
                candidate_labels.as_str()
            }
        )
    };
    let content = format!(
        "Goal role consultation\nGoal: {}\nCommander: {} ({})\nReason: {}\n{}",
        goal.title,
        trigger.commander_display_name,
        trigger.commander_session_id,
        trigger.reason,
        role_line
    );
    let message = ChatMessageDto {
        id: format!("msg-{}-goal-consult", unix_timestamp_millis()),
        author: "Goal 角色咨询".to_string(),
        role: "assistant".to_string(),
        target: trigger.commander_display_name.clone(),
        content,
        kind: "task-summary".to_string(),
        attachments: Vec::new(),
    };
    messages.push(message.clone());
    tasks.push(AgentTaskDto {
        id: format!("{}-role-consult", goal.id),
        owner_agent: trigger.commander_display_name.clone(),
        executor_agent: "Goal roles".to_string(),
        status: status.to_string(),
        visible_in_chat: true,
        timeout_ms: 600_000,
        summary: format!(
            "{}; consultation_required={}",
            goal.title,
            trigger.consultation_required && !roles_ready
        ),
    });
    record_goal_trigger_consultation_event(db_path, &goal.id, trigger, roles_ready);
    Ok(vec![message])
}

fn ensure_goal_trigger_commander_config(
    db_path: &Path,
    trigger: &PreparedGoalTrigger,
) -> ApiResult<()> {
    let connection = open_session_connection(db_path).map_err(sqlite_api_error)?;
    initialize_session_schema(&connection).map_err(sqlite_api_error)?;
    let configs = read_goal_role_config_map(&connection).map_err(sqlite_api_error)?;
    let existing_role = configs
        .get(&trigger.commander_session_id)
        .and_then(|config| config.role.as_deref());
    let mut roles = split_goal_role_config(existing_role);
    if !roles.iter().any(|role| role == "commander") {
        roles.push("commander".to_string());
    }
    upsert_goal_role_config_sqlite(
        db_path,
        &trigger.commander_session_id,
        GoalRoleConfigUpdateRequest {
            role: Some(roles.join(",")),
            responsibility: None,
            commander: Some(true),
            heartbeat_timeout_ms: None,
            task_timeout_ms: None,
        },
    )
}

fn default_goal_trigger_plan(title: &str) -> GoalPlanRequest {
    let output_artifacts = default_goal_trigger_output_artifacts(title);
    let verification = if output_artifacts.is_empty() {
        json!({ "type": "UserConfirm" })
    } else {
        json!({ "type": "FilesExist", "paths": output_artifacts.clone() })
    };
    GoalPlanRequest {
        phases: vec![
            GoalPlanPhaseRequest {
                id: "plan".to_string(),
                title: format!("Plan: {title}"),
                assigned_role: Some("planner".to_string()),
                depends_on: Vec::new(),
                skills_required: vec!["plan".to_string(), "decompose".to_string()],
                output_artifacts: Vec::new(),
                verification: Some(json!({ "type": "UserConfirm" })),
                requires_human_ack: false,
            },
            GoalPlanPhaseRequest {
                id: "implement".to_string(),
                title: format!("Implement: {title}"),
                assigned_role: Some("implementer".to_string()),
                depends_on: vec!["plan".to_string()],
                skills_required: vec!["implement".to_string(), "test".to_string()],
                output_artifacts: output_artifacts.clone(),
                verification: Some(verification.clone()),
                requires_human_ack: false,
            },
            GoalPlanPhaseRequest {
                id: "verify".to_string(),
                title: format!("Verify: {title}"),
                assigned_role: Some("verifier".to_string()),
                depends_on: vec!["implement".to_string()],
                skills_required: vec!["verify".to_string()],
                output_artifacts,
                verification: Some(verification),
                requires_human_ack: false,
            },
        ],
    }
}

fn default_goal_trigger_output_artifacts(title: &str) -> Vec<String> {
    let lower = title.to_ascii_lowercase();
    let wants_html = lower.contains("html")
        || lower.contains("web page")
        || lower.contains("webpage")
        || title.contains("网页");
    if wants_html {
        vec![format!(
            "goal-artifacts/{}-goal-output.html",
            goal_task_memory_slug(title)
        )]
    } else {
        Vec::new()
    }
}

fn append_goal_trigger_error_message(
    error: &ApiError,
    messages: &mut Vec<ChatMessageDto>,
    tasks: &mut Vec<AgentTaskDto>,
) -> ChatMessageDto {
    let message = ChatMessageDto {
        id: format!("msg-{}-goal-error", unix_timestamp_millis()),
        author: "Goal 角色咨询".to_string(),
        role: "assistant".to_string(),
        target: "Goal".to_string(),
        content: format!("Goal trigger failed: {}", error.1.error),
        kind: "task-summary".to_string(),
        attachments: Vec::new(),
    };
    messages.push(message.clone());
    tasks.push(AgentTaskDto {
        id: format!("task-{}-goal-error", unix_timestamp_millis()),
        owner_agent: "Goal".to_string(),
        executor_agent: "Goal roles".to_string(),
        status: "goal-error".to_string(),
        visible_in_chat: true,
        timeout_ms: 0,
        summary: error.1.error.clone(),
    });
    message
}

fn goal_trigger_role_config_ready(db_path: &Path, trigger: &PreparedGoalTrigger) -> bool {
    let candidate_ids = trigger
        .candidate_sessions
        .iter()
        .map(|session| session.session_id.as_str())
        .collect::<HashSet<_>>();
    let Ok(connection) = open_session_connection(db_path) else {
        return false;
    };
    if initialize_session_schema(&connection).is_err() {
        return false;
    }
    let Ok(configs) = read_goal_role_config_map(&connection) else {
        return false;
    };
    let mut has_commander = false;
    let mut roles = HashSet::new();
    for (session_id, config) in configs {
        if !candidate_ids.contains(session_id.as_str()) {
            continue;
        }
        if config.commander {
            has_commander = true;
        }
        for role in split_goal_role_config(config.role.as_deref()) {
            roles.insert(role);
        }
    }
    has_commander
        && ["planner", "implementer", "verifier"]
            .iter()
            .all(|role| roles.contains(*role))
}

fn record_goal_trigger_consultation_event(
    db_path: &Path,
    goal_id: &str,
    trigger: &PreparedGoalTrigger,
    roles_ready: bool,
) {
    let Ok(connection) = open_session_connection(db_path) else {
        return;
    };
    if initialize_session_schema(&connection).is_err() {
        return;
    }
    let _ = insert_goal_event_connection(
        &connection,
        goal_id,
        "goal-role-consultation",
        "Goal role consultation prepared from chat trigger.",
        json!({
            "commander_session_id": trigger.commander_session_id,
            "commander_display_name": trigger.commander_display_name,
            "candidate_sessions": trigger.candidate_sessions,
            "roles_ready": roles_ready,
            "reason": trigger.reason,
        }),
    );
}

async fn run_tool_intent_message(agent: &AgentSessionDto, prompt: &str) -> Option<ChatMessageDto> {
    let computer_use_execute = is_computer_use_execution_allowed();
    let dispatch = if dev_open_tool_permissions_enabled() {
        if let Some(input) = file_write_runtime_input_from_intent(prompt) {
            diag!(
                "[TOOL-CHAIN] run_tool_intent_message: dev-open file-write fallback -> runtime write_file"
            );
            execute_authorized_webui_runtime_dispatch("write_file", input).await
        } else {
            diag!(
                "[TOOL-CHAIN] run_tool_intent_message: dev-open no direct runtime mapping, using semantic dispatch"
            );
            run_tool_dispatch(ToolDispatchRequest {
                intent: prompt.to_string(),
                execute: Some(computer_use_execute),
                confirm_after: Some(!computer_use_execute),
                roi_radius: Some(64),
                text: None,
                target: None,
                menu_item: None,
                raw_response: None,
                capture_path: None,
                use_latest_capture: None,
                use_model: None,
                system_control: None,
            })
            .await
            .ok()?
        }
    } else {
        run_tool_dispatch(ToolDispatchRequest {
            intent: prompt.to_string(),
            execute: Some(computer_use_execute),
            confirm_after: if computer_use_execute {
                None
            } else {
                Some(true)
            },
            roi_radius: Some(64),
            text: None,
            target: None,
            menu_item: None,
            raw_response: None,
            capture_path: None,
            use_latest_capture: None,
            use_model: None,
            system_control: None,
        })
        .await
        .ok()?
    };

    if dispatch.route == "none" && dispatch.dispatch_plan.is_none() {
        return None;
    }

    let plan_text = dispatch_plan_chat_summary(&dispatch);

    Some(ChatMessageDto {
        id: format!("msg-{}-tool", unix_timestamp_millis()),
        author: "系统工具执行 Agent".to_string(),
        role: "assistant".to_string(),
        target: agent.display_name.clone(),
        content: plan_text,
        kind: "tool-summary".to_string(),
        attachments: Vec::new(),
    })
}

fn tool_messages_from_summary(
    agent: &AgentSessionDto,
    tool_use_id: &str,
    dispatch_turn_id: &str,
    name: &str,
    call_summary: String,
    result_summary: String,
    status: &str,
    route: &str,
) -> Vec<ChatMessageDto> {
    let tool_call_id = format!(
        "tool-call-{:016x}",
        hash_bytes(
            format!(
                "{}\u{1f}{}\u{1f}{}",
                agent.id, dispatch_turn_id, tool_use_id
            )
            .as_bytes(),
        )
    );
    let result_id = tool_call_id.replacen("tool-call-", "tool-result-", 1);
    let result_content = format!(
        "tool_call_id: {tool_call_id}\ntool_name: {name}\nroute: {route}\nstatus: {status}\nsummary: {}",
        compact_message_snippet(&result_summary, 1200)
    );
    vec![
        ChatMessageDto {
            id: tool_call_id,
            author: "系统工具执行 Agent".to_string(),
            role: "assistant".to_string(),
            target: agent.display_name.clone(),
            content: call_summary,
            kind: "tool-summary".to_string(),
            attachments: Vec::new(),
        },
        ChatMessageDto {
            id: result_id,
            author: "工具结果".to_string(),
            role: "assistant".to_string(),
            target: agent.display_name.clone(),
            content: result_content,
            kind: "tool-result".to_string(),
            attachments: Vec::new(),
        },
    ]
}

async fn run_model_tool_use_messages(
    agent: &AgentSessionDto,
    tool_use_id: &str,
    name: &str,
    input: &JsonValue,
    turn_id: Option<&str>,
    chat_room_id: Option<&str>,
) -> Vec<ChatMessageDto> {
    diag!(
        "[TOOL-CHAIN] run_model_tool_use_message: agent={}, tool={name}, tool_use_id={tool_use_id}, input={input}",
        agent.name
    );
    let scoped_turn_id = current_turn_trace();
    let dispatch_turn_id = turn_id
        .map(str::to_string)
        .or_else(|| scoped_turn_id.clone())
        .unwrap_or_else(|| diagnostics::TraceIdType::generate().to_hex());
    let tool_trace = turn_id
        .map(str::to_string)
        .or_else(|| scoped_turn_id.clone())
        .unwrap_or_else(|| dispatch_turn_id.clone());
    let tool_started = std::time::Instant::now();
    diagnostics::info(
        "tool",
        "invoke.begin",
        "执行模型工具调用",
        &[("trace", tool_trace.clone()), ("tool", name.to_string())],
    );
    // 关键：把当前 agent 的会话 id 作为 caller_session_id 传入，否则工具权限按 None 会话评估，
    // 查不到该会话的 full-access 授权 → 写/工具操作被 gate 拦截（goal/聊天 model tool_use 失效）。
    // 同时保留 provider tool id；computer_use 的 run store 以 provider/session/turn 组合做幂等身份，
    // 丢失 provider id 会退成 provider-call-missing，并可能误复用上一轮同 session/turn 的旧终态。
    let response = run_model_tool_dispatch_for_session_with_identity(
        name,
        input,
        Some(&agent.id),
        Some(tool_use_id),
        Some(&dispatch_turn_id),
        chat_room_id,
    )
    .await;
    let (content, result_content, result_status, result_route) = match response {
        Ok(dispatch) => {
            diagnostics::info(
                "tool",
                "invoke.ok",
                "工具调用完成",
                &[
                    ("trace", tool_trace.clone()),
                    ("tool", name.to_string()),
                    ("latency_ms", tool_started.elapsed().as_millis().to_string()),
                ],
            );
            let summary = dispatch_plan_chat_summary(&dispatch);
            let result_text = dispatch
                .tool_result_text
                .clone()
                .unwrap_or_else(|| dispatch_plan_detail(&dispatch));
            (
                summary,
                compact_message_snippet(&result_text, 1200),
                dispatch.status,
                dispatch.route,
            )
        }
        Err(error) => {
            let detail = error.1.error.to_string();
            diagnostics::error(
                "tool",
                "invoke.error",
                "工具 dry-run 转换失败",
                &[
                    ("trace", tool_trace.clone()),
                    ("tool", name.to_string()),
                    ("err_kind", "dispatch".to_string()),
                    ("hint", compact_message_snippet(&detail, 160)),
                    ("latency_ms", tool_started.elapsed().as_millis().to_string()),
                ],
            );
            (
                format!("工具 `{name}` 调用失败：{detail}"),
                compact_message_snippet(&detail, 1200),
                "failed".to_string(),
                "runtime-failed".to_string(),
            )
        }
    };

    tool_messages_from_summary(
        agent,
        tool_use_id,
        &dispatch_turn_id,
        name,
        content,
        result_content,
        &result_status,
        &result_route,
    )
}

async fn run_model_tool_dispatch(name: &str, input: &JsonValue) -> ApiResult<ToolDispatchResponse> {
    run_model_tool_dispatch_for_session(name, input, None).await
}

async fn run_model_tool_dispatch_for_session(
    name: &str,
    input: &JsonValue,
    caller_session_id: Option<&str>,
) -> ApiResult<ToolDispatchResponse> {
    let turn_id = current_turn_trace();
    run_model_tool_dispatch_for_session_with_identity(
        name,
        input,
        caller_session_id,
        None,
        turn_id.as_deref(),
        None,
    )
    .await
}

async fn run_model_tool_dispatch_for_session_with_identity(
    name: &str,
    input: &JsonValue,
    caller_session_id: Option<&str>,
    provider_tool_call_id: Option<&str>,
    turn_id: Option<&str>,
    chat_room_id: Option<&str>,
) -> ApiResult<ToolDispatchResponse> {
    diag!("[TOOL-CHAIN] run_model_tool_dispatch: name={name}, input={input}");
    let normalized = name.replace('-', "_");

    if normalized == "computer_use.perform" || normalized == "computer_use_perform" {
        let generated_turn_id;
        let effective_turn_id = match turn_id {
            Some(turn_id) => turn_id,
            None => {
                generated_turn_id = diagnostics::TraceIdType::generate().to_hex();
                &generated_turn_id
            }
        };
        let identity = tool_loop_coordinator::ToolCallIdentity::from_provider(
            provider_tool_call_id.unwrap_or("provider-call-missing"),
            caller_session_id.unwrap_or("session-missing"),
            effective_turn_id,
        );
        let result =
            computer_use_executor::execute_with_current_runtime(input, &identity, chat_room_id)
                .await;
        return Ok(computer_use_dispatch_response(result));
    }

    // 路径 A：元工具 `tools_semantic_dispatch` 默认保持 legacy 路径（computer-use dry-run plan）。
    // 但开发开放模式下，如果模型把文件写入请求包进语义入口，也要落到真"runtime。
    if normalized == "tools.semantic_dispatch" || normalized == "tools_semantic_dispatch" {
        if dev_open_tool_permissions_enabled() {
            if let Some(runtime_input) =
                file_write_runtime_input_from_semantic_dispatch_input(input)
            {
                diag!("[TOOL-CHAIN] semantic_dispatch dev-open file-write -> runtime write_file");
                let outcome = invoke_through_runtime_for_session(
                    "write_file",
                    &runtime_input,
                    caller_session_id,
                    chat_room_id,
                )
                .await;
                return Ok(tool_outcome_to_dispatch_response(
                    "write_file",
                    &runtime_input,
                    outcome,
                ));
            }
        }
        return legacy_semantic_dispatch(input).await;
    }

    if normalized == "chat_handoff" || normalized == "chat.handoff" {
        return run_chat_handoff_tool_dispatch_for_session(input, caller_session_id).await;
    }

    // 路径 B：其"registry 工具"runtime_tool_execute，复"Phase C-2~C-6 的审"审计链。
    // 白名单外"registry 未实现的工具命中 `runtime_tool_execute` "unknown tool
    // 分支 "Failed，模型可据此纠正。
    let runtime_input = runtime_tool_input_with_defaults(name, input);
    diag!("[TOOL-CHAIN] registry path: name={name}, runtime_input={runtime_input}");
    let outcome =
        invoke_through_runtime_for_session(name, &runtime_input, caller_session_id, chat_room_id)
            .await;
    Ok(tool_outcome_to_dispatch_response(
        name,
        &runtime_input,
        outcome,
    ))
}

async fn run_chat_handoff_tool_dispatch(input: &JsonValue) -> ApiResult<ToolDispatchResponse> {
    run_chat_handoff_tool_dispatch_for_session(input, None).await
}

fn computer_use_dispatch_response(result: computer_use::ComputerUseResult) -> ToolDispatchResponse {
    let status = match result.status {
        computer_use::ComputerUseTerminalStatus::Succeeded => "ok",
        computer_use::ComputerUseTerminalStatus::Failed => "failed",
        computer_use::ComputerUseTerminalStatus::Blocked => "blocked",
        computer_use::ComputerUseTerminalStatus::Cancelled => "cancelled",
        computer_use::ComputerUseTerminalStatus::TimedOut => "timed_out",
    };
    ToolDispatchResponse {
        status: status.to_string(),
        route: "computer-use-task-controller".to_string(),
        scenario: None,
        closed_loop: None,
        dispatch_plan: None,
        tool_result_text: Some(
            serde_json::to_string(&result).unwrap_or_else(|_| result.summary.clone()),
        ),
        notes: vec![result.summary],
    }
}

fn is_computer_use_tool_family(name: &str) -> bool {
    let normalized = name.trim().to_ascii_lowercase().replace('-', "_");
    normalized == "computer_use.perform"
        || normalized == "computer_use_perform"
        || normalized == "tools.semantic_dispatch"
        || normalized == "tools_semantic_dispatch"
        || normalized.starts_with("computer.")
        || normalized.starts_with("computer_")
}

fn computer_use_recursive_call_blocked_feedback(last_summary: &str) -> String {
    format!(
        "Computer Use 已在本轮以错误终态结束；运行时已阻止模型改用其它 UI 工具继续调用。status=blocked, error_code=recursive_call_blocked, retry_owner=user, last_result={}",
        compact_message_snippet(last_summary, 320)
    )
}

fn tool_feedback_watchdog_message(max_rounds: usize, pending_tool_calls: usize) -> String {
    format!(
        "工具反馈循环已由运行时看护终止。status=blocked, error_code=tool_feedback_round_limit, max_feedback_rounds={max_rounds}, pending_tool_calls={pending_tool_calls}。这些超限工具请求未执行；已完成的操作以此前工具结果为准。请缩小任务范围或在确认当前结果后继续。"
    )
}

async fn run_chat_handoff_tool_dispatch_for_session(
    input: &JsonValue,
    caller_session_id: Option<&str>,
) -> ApiResult<ToolDispatchResponse> {
    let start = Instant::now();
    let call_id = format!("llm-{}", unix_timestamp_millis());
    let workspace_root = active_workspace_path();
    let workspace_id = workspace_identity(&workspace_root);
    let session_id = caller_session_id.map(str::to_string).or_else(|| {
        session_store()
            .lock()
            .ok()
            .and_then(|store| store.state.active_session_id.clone())
    });
    let invoke = ToolInvoke {
        call_id,
        tool_name: "chat_handoff".to_string(),
        input: input.clone(),
        caller: ToolCaller::Llm,
        workspace_id,
        session_id,
        user_authorized: false,
        user_confirmed_twice: false,
    };
    let outcome = chat_handoff_tool_outcome(&invoke, start);
    append_tool_audit_record(&invoke, &outcome);
    emit_pet_event_for_tool_outcome(&invoke.tool_name, &outcome);
    Ok(chat_handoff_outcome_to_dispatch_response(input, outcome))
}

fn chat_handoff_tool_outcome(invoke: &ToolInvoke, start: Instant) -> ToolOutcome {
    match create_chat_handoff_from_tool_input(&invoke.input, invoke.session_id.as_deref()) {
        Ok(response) => {
            let handoff = &response.handoff;
            let status = if handoff.status == "delivered" {
                ToolOutcomeStatus::Ok
            } else {
                ToolOutcomeStatus::Rejected
            };
            let summary_text = if status == ToolOutcomeStatus::Ok {
                format!(
                    "chat_handoff delivered from {} to {}: {}",
                    handoff.from_agent_id, handoff.to_agent_id, handoff.intent
                )
            } else {
                format!(
                    "chat_handoff rejected from {} to {}: {} ({})",
                    handoff.from_agent_id,
                    handoff.to_agent_id,
                    handoff.intent,
                    handoff
                        .rejected_reason
                        .as_deref()
                        .unwrap_or("handoff gate rejected")
                )
            };
            ToolOutcome {
                call_id: invoke.call_id.clone(),
                tool_name: invoke.tool_name.clone(),
                status,
                output: json!({
                    "handoff": &response.handoff,
                    "inbound_message": &response.inbound_message,
                }),
                summary_text,
                elapsed_ms: elapsed_millis(start),
                permission_gate: runtime::PermissionGateReport::allow_auto(
                    PermissionMode::WorkspaceWrite,
                    "internal chat handoff",
                ),
                evidence: None,
            }
        }
        Err(message) => ToolOutcome {
            call_id: invoke.call_id.clone(),
            tool_name: invoke.tool_name.clone(),
            status: ToolOutcomeStatus::Failed,
            output: json!({ "error": message }),
            summary_text: message,
            elapsed_ms: elapsed_millis(start),
            permission_gate: runtime::PermissionGateReport::allow_auto(
                PermissionMode::WorkspaceWrite,
                "internal chat handoff failed before persistence",
            ),
            evidence: None,
        },
    }
}

fn create_chat_handoff_from_tool_input(
    input: &JsonValue,
    caller_session_id: Option<&str>,
) -> Result<ManualHandoffResponse, String> {
    let to = input_string(input, "to")
        .or_else(|| input_string(input, "target"))
        .or_else(|| input_string(input, "target_agent"))
        .ok_or_else(|| "chat_handoff requires a non-empty `to` target".to_string())?;
    let intent = input_string(input, "intent")
        .or_else(|| input_string(input, "task"))
        .ok_or_else(|| "chat_handoff requires a non-empty `intent` task".to_string())?;
    let attach_message_ids = input_string_array(input, "attach_message_ids");
    let depth = input_u64(input, "depth").and_then(|value| u8::try_from(value).ok());
    let mut store = session_store()
        .lock()
        .map_err(|_| "chat_handoff could not lock session store".to_string())?;
    let room_id = input_string(input, "chat_room_id")
        .or_else(|| input_string(input, "room_id"))
        .or_else(|| store.active_chat_room_id())
        .unwrap_or_else(|| DEFAULT_CHAT_ROOM_ID.to_string());
    let from_agent_id = input_string(input, "from_agent_id")
        .or_else(|| input_string(input, "from"))
        .or_else(|| caller_session_id.map(str::to_string))
        .or_else(|| store.state.active_session_id.clone())
        .ok_or_else(|| "chat_handoff requires an active source agent".to_string())?;
    let response = store
        .create_manual_handoff(
            &room_id,
            ManualHandoffRequest {
                from_agent_id,
                to,
                intent,
                attach: input_string(input, "attach"),
                attach_message_ids,
                originating_user_msg_id: input_string(input, "originating_user_msg_id")
                    .or_else(|| input_string(input, "originating_message_id")),
                depth,
                contract: None,
            },
        )
        .map_err(api_error_message)?
        .0;
    Ok(response)
}

fn api_error_message(error: ApiError) -> String {
    let (_, Json(body)) = error;
    body.error
}

fn chat_handoff_outcome_to_dispatch_response(
    input: &JsonValue,
    outcome: ToolOutcome,
) -> ToolDispatchResponse {
    let route = match outcome.status {
        ToolOutcomeStatus::Ok => "chat-handoff",
        ToolOutcomeStatus::DryRunOnly => "chat-handoff-dry-run",
        ToolOutcomeStatus::Rejected => "chat-handoff-rejected",
        ToolOutcomeStatus::Failed => "chat-handoff-failed",
        ToolOutcomeStatus::Timeout => "chat-handoff-timeout",
    }
    .to_string();
    let execute_allowed = matches!(outcome.status, ToolOutcomeStatus::Ok);
    let safety_gate = outcome.permission_gate.decision.as_str().to_string();
    let rationale = outcome.summary_text.clone();
    let tool_result_text = tool_outcome_model_result_text("chat_handoff", input, &outcome, &route);
    let plan = ToolDispatchPlan {
        tool_id: "chat_handoff".to_string(),
        action: outcome.status.as_str().to_string(),
        target: outcome.summary_text.clone(),
        dry_run_input: outcome.output.clone(),
        llm_tool_call: ToolCallPreview {
            name: "chat_handoff".to_string(),
            arguments: input.clone(),
            mode: "handoff".to_string(),
        },
        action_plan: None,
        visual_action: None,
        audit: ComputerUseAuditRecord {
            audit_id: outcome.call_id.clone(),
            mode: "handoff".to_string(),
            execute_requested: true,
            execute_allowed,
            executed: execute_allowed,
            requires_human_confirmation: outcome.permission_gate.decision.requires_ui(),
            requires_screenshot_evidence: false,
            screenshot_path: None,
            permission_gate: safety_gate.clone(),
            log_path: tool_audit_log_path().display().to_string(),
        },
        requires_visual_grounding: false,
        execute_allowed,
        safety_gate,
        rationale,
    };
    ToolDispatchResponse {
        status: outcome.status.as_str().to_string(),
        route,
        scenario: None,
        closed_loop: None,
        dispatch_plan: Some(plan),
        tool_result_text: Some(tool_result_text),
        notes: vec![outcome.summary_text],
    }
}

/// Phase C-11：元工具 `tools_semantic_dispatch` "dispatch 路径。
async fn legacy_semantic_dispatch(input: &JsonValue) -> ApiResult<ToolDispatchResponse> {
    let intent = input_string(input, "intent")
        .or_else(|| input_string(input, "query"))
        .or_else(|| input_string(input, "target"))
        .unwrap_or_else(|| input.to_string());
    diag!("[TOOL-CHAIN] legacy semantic_dispatch intent='{intent}'...");
    let execute = is_computer_use_execution_allowed();
    let dispatch = run_tool_dispatch(ToolDispatchRequest {
        intent,
        execute: Some(execute),
        confirm_after: Some(!execute),
        roi_radius: input_u32(input, "roi_radius").or(Some(64)),
        text: input_string(input, "text"),
        target: input_string(input, "target"),
        menu_item: input_string(input, "menu_item"),
        raw_response: input_string(input, "raw_response"),
        capture_path: input_string(input, "capture_path"),
        use_latest_capture: input_bool(input, "use_latest_capture"),
        use_model: input_bool(input, "use_model"),
        system_control: None,
    })
    .await;
    match &dispatch {
        Ok(resp) => diag!(
            "[TOOL-CHAIN] legacy dispatch OK: route={}, status={}, execute_allowed={}",
            resp.route,
            resp.status,
            resp.dispatch_plan
                .as_ref()
                .map(|p| p.execute_allowed)
                .unwrap_or(false)
        ),
        Err(e) => diag!("[TOOL-CHAIN] legacy dispatch FAILED: {}", e.1.error),
    }
    dispatch
}

/// Phase C-11：把 LLM tool_use 转交"`runtime_tool_execute`。
///
/// 构造和 `/api/tools/runtime-execute` handler 等价"`ToolInvoke` + `RuntimeToolContext`。
/// 保证 LLM 触发的工具调用经过：权限闸门 / pending 登记 / SSE 事件 / 审计 jsonl 全链路。
async fn invoke_through_runtime(name: &str, input: &JsonValue) -> ToolOutcome {
    invoke_through_runtime_for_session(name, input, None, None).await
}

async fn invoke_through_runtime_for_session(
    name: &str,
    input: &JsonValue,
    caller_session_id: Option<&str>,
    chat_room_id: Option<&str>,
) -> ToolOutcome {
    let call_id = format!("llm-{}", unix_timestamp_millis());
    let workspace_root = active_workspace_path();
    let workspace_id = workspace_identity(&workspace_root);
    let session_id = caller_session_id.map(str::to_string).or_else(|| {
        session_store()
            .lock()
            .ok()
            .and_then(|store| store.state.active_session_id.clone())
    });

    let invoke = ToolInvoke {
        call_id: call_id.clone(),
        tool_name: name.to_string(),
        input: input.clone(),
        caller: ToolCaller::Llm,
        workspace_id: workspace_id.clone(),
        session_id: session_id.clone(),
        user_authorized: false,
        user_confirmed_twice: false,
    };

    let timeout_ms = tool_timeout_ms_for(name, input);
    let outcome = execute_runtime_tool_with_timeout(
        invoke.clone(),
        workspace_root.clone(),
        timeout_ms,
        chat_room_id.map(str::to_string),
    )
    .await;

    diagnostics::info(
        "perm",
        "check",
        "工具权限评估",
        &[
            ("trace", current_turn_trace().unwrap_or_default()),
            ("tool", name.to_string()),
            (
                "decision",
                outcome.permission_gate.decision.as_str().to_string(),
            ),
            (
                "required",
                outcome.permission_gate.required.as_str().to_string(),
            ),
            (
                "requires_ui",
                outcome.permission_gate.decision.requires_ui().to_string(),
            ),
            ("status", outcome.status.as_str().to_string()),
        ],
    );

    // "/api/tools/runtime-execute 一致：DryRunOnly + 需 UI "pending 登记 + SSE 广播。
    if matches!(outcome.status, ToolOutcomeStatus::DryRunOnly)
        && outcome.permission_gate.decision.requires_ui()
    {
        enqueue_pending_approval_for_room(
            &call_id,
            &invoke,
            &outcome.permission_gate,
            chat_room_id,
        );
        info!(
            "[TOOL-GATE] llm tool='{}' decision={} enqueued pending call_id={}",
            invoke.tool_name,
            outcome.permission_gate.decision.as_str(),
            call_id
        );
    } else {
        info!(
            "[TOOL-EXEC] llm tool='{}' status={} elapsed_ms={}",
            invoke.tool_name,
            outcome.status.as_str(),
            outcome.elapsed_ms
        );
    }

    append_tool_audit_record(&invoke, &outcome);
    emit_pet_event_for_tool_outcome(&invoke.tool_name, &outcome);
    outcome
}

async fn execute_runtime_tool_with_timeout(
    invoke: ToolInvoke,
    workspace_root: PathBuf,
    timeout_ms: u64,
    chat_room_id: Option<String>,
) -> ToolOutcome {
    let invoke_for_task = invoke.clone();
    let task = tokio::task::spawn_blocking(move || {
        execute_runtime_tool_blocking(invoke_for_task, workspace_root, chat_room_id)
    });
    match tokio::time::timeout(Duration::from_millis(timeout_ms), task).await {
        Ok(Ok(outcome)) => outcome,
        Ok(Err(error)) => runtime_tool_failed_outcome(
            &invoke,
            format!("tool '{}' join failed: {error}", invoke.tool_name),
        ),
        Err(_) => runtime_tool_timeout_outcome(&invoke, timeout_ms),
    }
}

fn execute_runtime_tool_blocking(
    mut invoke: ToolInvoke,
    workspace_root: PathBuf,
    chat_room_id: Option<String>,
) -> ToolOutcome {
    tools::set_project_config_root(Some(workspace_root.clone()));
    let dev_open = dev_open_tool_permissions_enabled();
    if dev_open {
        invoke.user_authorized = true;
        invoke.user_confirmed_twice = true;
    }
    let grant = if dev_open {
        dev_open_session_grant()
    } else {
        let room_grant = room_permission_grant_view_for_path(
            &default_session_sqlite_path(),
            chat_room_id.as_deref(),
        );
        if room_grant.session_authorized {
            room_grant
        } else if chat_room_id.is_some() {
            session_tool_grant_view_for(
                &invoke.workspace_id,
                invoke.session_id.as_deref(),
                &invoke.tool_name,
            )
        } else {
            session_grant_view_for(
                &invoke.workspace_id,
                invoke.session_id.as_deref(),
                &invoke.tool_name,
            )
        }
    };
    let required = required_permission_for_tool(&invoke.tool_name);
    let path_targets = extract_path_targets(&invoke.tool_name, &invoke.input);
    let rules: Vec<ProtectedRule> = if dev_open {
        Vec::new()
    } else {
        effective_protected_rules()
    };

    let exec = RegistryExecutor::from_registry();
    let executors: [&dyn ToolInvocationExecutor; 1] = [&exec];
    let profile = if dev_open {
        runtime::PermissionProfile::FullAccess
    } else {
        active_permission_profile()
    };
    let ctx = RuntimeToolContext {
        workspace_root: &workspace_root,
        required_permission: required,
        path_targets,
        protected_rules: &rules,
        session_grant: grant,
        executors: &executors,
        profile,
    };
    runtime_tool_execute(invoke, &ctx)
}

fn runtime_tool_timeout_outcome(invoke: &ToolInvoke, timeout_ms: u64) -> ToolOutcome {
    ToolOutcome {
        call_id: invoke.call_id.clone(),
        tool_name: invoke.tool_name.clone(),
        status: ToolOutcomeStatus::Timeout,
        output: json!({ "timeout_ms": timeout_ms }),
        summary_text: format!(
            "tool '{}' exceeded {}ms runtime deadline",
            invoke.tool_name, timeout_ms
        ),
        elapsed_ms: timeout_ms,
        permission_gate: runtime::PermissionGateReport::allow_auto(
            required_permission_for_tool(&invoke.tool_name),
            "runtime deadline exceeded",
        ),
        evidence: None,
    }
}

fn runtime_tool_failed_outcome(invoke: &ToolInvoke, message: String) -> ToolOutcome {
    ToolOutcome {
        call_id: invoke.call_id.clone(),
        tool_name: invoke.tool_name.clone(),
        status: ToolOutcomeStatus::Failed,
        output: json!({ "error": message }),
        summary_text: message,
        elapsed_ms: 0,
        permission_gate: runtime::PermissionGateReport::allow_auto(
            required_permission_for_tool(&invoke.tool_name),
            "runtime task failed",
        ),
        evidence: None,
    }
}

fn tool_outcome_model_result_text(
    name: &str,
    input: &JsonValue,
    outcome: &ToolOutcome,
    route: &str,
) -> String {
    let input_text = serde_json::to_string(input).unwrap_or_else(|_| input.to_string());
    let output_text = match &outcome.output {
        JsonValue::Null => String::new(),
        JsonValue::String(text) => text.clone(),
        other => serde_json::to_string_pretty(other).unwrap_or_else(|_| other.to_string()),
    };
    let mut lines = vec![
        format!("tool_name: {name}"),
        format!("route: {route}"),
        format!("status: {}", outcome.status.as_str()),
        format!(
            "permission_gate: {}",
            outcome.permission_gate.decision.as_str()
        ),
        format!("elapsed_ms: {}", outcome.elapsed_ms),
        format!("input: {input_text}"),
        format!("summary: {}", outcome.summary_text),
    ];
    if !output_text.trim().is_empty() {
        lines.push("output:".to_string());
        lines.push(output_text);
    }
    if let Some(evidence) = &outcome.evidence {
        let evidence_text =
            serde_json::to_string_pretty(evidence).unwrap_or_else(|_| evidence.to_string());
        if !evidence_text.trim().is_empty() {
            lines.push("evidence:".to_string());
            lines.push(evidence_text);
        }
    }
    lines.join("\n")
}

/// Phase C-11：把 `ToolOutcome` 映射"`ToolDispatchResponse`，保持上层调用。
/// （Tool Loop / `run_model_tool_use_message`）无需改动。
fn tool_outcome_to_dispatch_response(
    name: &str,
    input: &JsonValue,
    outcome: ToolOutcome,
) -> ToolDispatchResponse {
    let route = match outcome.status {
        ToolOutcomeStatus::Ok => "runtime-executed",
        ToolOutcomeStatus::DryRunOnly => "runtime-dry-run",
        ToolOutcomeStatus::Rejected => "runtime-rejected",
        ToolOutcomeStatus::Failed => "runtime-failed",
        ToolOutcomeStatus::Timeout => "runtime-timeout",
    }
    .to_string();
    let tool_result_text = tool_outcome_model_result_text(name, input, &outcome, &route);
    let execute_allowed = matches!(outcome.status, ToolOutcomeStatus::Ok);
    let safety_gate = outcome.permission_gate.decision.as_str().to_string();
    let dry_run_input = outcome.output.clone();
    let rationale = outcome.summary_text.clone();
    let plan = ToolDispatchPlan {
        tool_id: name.to_string(),
        action: outcome.status.as_str().to_string(),
        target: outcome.summary_text.clone(),
        dry_run_input,
        llm_tool_call: ToolCallPreview {
            name: name.to_string(),
            arguments: input.clone(),
            mode: "runtime".to_string(),
        },
        action_plan: None,
        visual_action: None,
        audit: ComputerUseAuditRecord {
            audit_id: outcome.call_id.clone(),
            mode: "runtime".to_string(),
            execute_requested: execute_allowed,
            execute_allowed,
            executed: execute_allowed,
            requires_human_confirmation: outcome.permission_gate.decision.requires_ui(),
            requires_screenshot_evidence: false,
            screenshot_path: None,
            permission_gate: safety_gate.clone(),
            log_path: tool_audit_log_path().display().to_string(),
        },
        requires_visual_grounding: false,
        execute_allowed,
        safety_gate,
        rationale,
    };
    ToolDispatchResponse {
        status: outcome.status.as_str().to_string(),
        route,
        scenario: None,
        closed_loop: None,
        dispatch_plan: Some(plan),
        tool_result_text: Some(tool_result_text),
        notes: vec![outcome.summary_text],
    }
}

/// 工具调度详情（多行）：路由 / LLM tool call / 动作计划 / 安全闸门 / steps / 闭环。
/// 供诊断日志与"喂模型的 tool_result 兜底"使用，**不直接进聊天室**（#3）。
fn dispatch_plan_detail(dispatch: &ToolDispatchResponse) -> String {
    let mut lines = Vec::new();
    lines.push(format!(
        "语义工具调度：{} / {}",
        dispatch.route, dispatch.status
    ));
    if let Some(plan) = &dispatch.dispatch_plan {
        let actually_executed = plan.execute_allowed
            || (dispatch.route.starts_with("runtime-") && dispatch.route != "runtime-dry-run");
        let call_label = if actually_executed {
            "LLM tool call 执行"
        } else {
            "LLM tool call dry-run"
        };
        lines.push(format!(
            "{call_label}：{}，action={}，execute_allowed={}",
            plan.llm_tool_call.name, plan.action, plan.execute_allowed
        ));
        lines.push(format!("安全闸门：{}", plan.safety_gate));
        if let Some(action_plan) = &plan.action_plan {
            let point = if action_plan.path.is_empty() {
                "无坐标动".to_string()
            } else {
                format!("({}, {})", action_plan.point.x, action_plan.point.y)
            };
            lines.push(format!(
                "动作计划：target={}，point={}，steps={}，requires_visual_grounding={}",
                action_plan.target,
                point,
                action_plan.action_steps.len(),
                action_plan.requires_visual_grounding
            ));
            for (index, step) in action_plan.action_steps.iter().take(4).enumerate() {
                lines.push(format!("{}. {}", index + 1, step));
            }
        }
    } else {
        lines.push("已识别工具意图，但暂未生成可执行 dry-run tool call".to_string());
    }

    if let Some(closed_loop) = &dispatch.closed_loop {
        lines.push(format!(
            "闭环截图：before={}，screen={}x{}，scenario={}",
            closed_loop.before_capture.path,
            closed_loop.screen.width,
            closed_loop.screen.height,
            closed_loop.scenario
        ));
    }

    if dispatch.route.starts_with("runtime-") {
        if dispatch.route == "runtime-executed" {
            lines.push("已执行真实 runtime 工具调用。".to_string());
        } else if dispatch.route == "runtime-dry-run" {
            lines.push("runtime 工具链已生成待授权预览，尚未执行真实写入或命令".to_string());
        } else {
            lines.push("runtime 工具链已返回执行结果，请查看上方状态和安全闸门".to_string());
        }
    } else if dispatch
        .dispatch_plan
        .as_ref()
        .is_some_and(|plan| plan.execute_allowed)
    {
        lines.push("已执行真实计算机操作。".to_string());
    } else {
        lines.push("当前只展示 dry-run 计划，不执行真实键鼠、插件脚本或文件写入。".to_string());
    }
    lines.join("\n")
}

/// 聊天室工具消息（#3）：只显示"工具结果 + 失败原因"，调用过程（路由 / 动作计划 / 安全闸门 / steps）移诊断日志。
fn dispatch_plan_chat_summary(dispatch: &ToolDispatchResponse) -> String {
    diag!(
        "[TOOL-CHAIN] dispatch detail: route={}, status={}\n{}",
        dispatch.route,
        dispatch.status,
        dispatch_plan_detail(dispatch)
    );

    let tool_name = dispatch
        .dispatch_plan
        .as_ref()
        .map(|plan| plan.llm_tool_call.name.clone())
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| dispatch.route.clone());

    // 概要文本：notes[0]（运行时 = outcome.summary_text）是最简洁的结果 / 失败原因。
    let concise = dispatch
        .notes
        .iter()
        .map(|note| note.trim())
        .find(|note| !note.is_empty())
        .map(str::to_string);

    if tool_loop_coordinator::terminal_status_is_error(&dispatch.status) {
        let reason = concise.unwrap_or_else(|| dispatch.status.clone());
        return format!("工具 `{tool_name}` 失败：{reason}");
    }

    let executed = dispatch.route == "computer-use-task-controller"
        || (dispatch.route.starts_with("runtime-") && dispatch.route != "runtime-dry-run")
        || dispatch
            .dispatch_plan
            .as_ref()
            .is_some_and(|plan| plan.execute_allowed);
    match concise {
        Some(text) if executed => format!("工具 `{tool_name}` 已执行：{text}"),
        Some(text) => format!("工具 `{tool_name}`（预览，未执行真实操作）：{text}"),
        None if executed => format!("工具 `{tool_name}` 已执行。"),
        None => format!("工具 `{tool_name}`：已生成待授权预览，未执行真实操作。"),
    }
}

fn scenario_from_tool_intent(prompt: &str) -> Option<&'static InteractionScenario> {
    let lower = prompt.to_ascii_lowercase();
    let preferred = if lower.contains("地址") || lower.contains("address") || lower.contains("url")
    {
        "browser-address-search"
    } else if lower.contains("右键菜单")
        || lower.contains("上下文菜")
        || lower.contains("context menu")
    {
        "desktop-icon-context-menu"
    } else if lower.contains("搜索") || lower.contains("search") {
        "browser-page-search-icon"
    } else if lower.contains("任务") || lower.contains("taskbar") {
        "taskbar-shortcut-left-click"
    } else if lower.contains("关闭") || lower.contains("close") {
        "window-close-control"
    } else {
        "desktop-icon-left-click"
    };
    default_regression_scenarios()
        .iter()
        .find(|scenario| scenario.name == preferred)
}

fn sse_json_event<T: Serialize>(name: &str, value: &T) -> Event {
    Event::default().event(name).data(
        serde_json::to_string(value)
            .unwrap_or_else(|error| format!(r#"{{"error":"failed to serialize event: {error}"}}"#)),
    )
}

async fn capture_desktop(path: &Path) -> ApiResult<()> {
    let Some(parent) = path.parent() else {
        return Err(api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "截图路径缺少父目录",
        ));
    };
    tokio::fs::create_dir_all(parent)
        .await
        .map_err(io_api_error)?;

    #[cfg(test)]
    {
        let mut bytes = vec![
            0x89, b'P', b'N', b'G', b'\r', b'\n', 0x1A, b'\n', 0, 0, 0, 13, b'I', b'H', b'D', b'R',
        ];
        bytes.extend_from_slice(&1920_u32.to_be_bytes());
        bytes.extend_from_slice(&1080_u32.to_be_bytes());
        bytes.extend_from_slice(&[8, 6, 0, 0, 0]);
        tokio::fs::write(path, bytes).await.map_err(io_api_error)?;
        return Ok(());
    }

    #[cfg(all(windows, not(test)))]
    {
        let script = format!(
            r#"
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
$bounds = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
$bitmap = New-Object System.Drawing.Bitmap $bounds.Width, $bounds.Height
$graphics = [System.Drawing.Graphics]::FromImage($bitmap)
$graphics.CopyFromScreen($bounds.Location, [System.Drawing.Point]::Empty, $bounds.Size)
$bitmap.Save('{}', [System.Drawing.Imaging.ImageFormat]::Png)
$graphics.Dispose()
$bitmap.Dispose()
"#,
            path.display().to_string().replace('\'', "''")
        );
        let mut command = Command::new("powershell.exe");
        command
            .arg("-NoLogo")
            .arg("-NoProfile")
            .arg("-NonInteractive")
            .arg("-ExecutionPolicy")
            .arg("Bypass")
            .arg("-Command")
            .arg(script);
        command.creation_flags(CREATE_NO_WINDOW);

        let output = command.output().await.map_err(io_api_error)?;
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            return Err(api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                &format!("桌面截图失败: {}", stderr.trim()),
            ));
        }
        Ok(())
    }

    #[cfg(all(not(windows), not(test)))]
    {
        Err(api_error(
            StatusCode::NOT_IMPLEMENTED,
            "当前桌面截图接口只实现了 Windows",
        ))
    }
}

fn build_stability_matrix() -> StabilityMatrixResponse {
    let resolutions = standard_resolution_cases()
        .iter()
        .copied()
        .map(ResolutionCaseDto::from)
        .collect::<Vec<_>>();
    let scenarios = default_regression_scenarios()
        .iter()
        .map(scenario_report)
        .collect::<Vec<_>>();

    StabilityMatrixResponse {
        generated_at: unix_timestamp_millis(),
        resolutions,
        scenarios,
    }
}

fn scenario_report(scenario: &InteractionScenario) -> ScenarioReport {
    ScenarioReport {
        name: scenario.name.to_string(),
        target: target_name(scenario.target).to_string(),
        action: action_name(scenario.action).to_string(),
        intent: scenario.intent.to_string(),
        anchor: AnchorDto {
            x: scenario.anchor.x,
            y: scenario.anchor.y,
        },
        points: standard_resolution_cases()
            .iter()
            .copied()
            .filter_map(|resolution| {
                anchor_to_physical_pixel(scenario.anchor, resolution).map(|(x, y)| PointReport {
                    resolution: resolution.name.to_string(),
                    x,
                    y,
                    scale_factor: resolution.scale_factor,
                })
            })
            .collect(),
    }
}

fn find_scenario(name: Option<&str>) -> ApiResult<&'static InteractionScenario> {
    let scenario_name = name
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("desktop-icon-left-click");
    default_regression_scenarios()
        .iter()
        .find(|scenario| scenario.name == scenario_name)
        .ok_or_else(|| {
            api_error(
                StatusCode::BAD_REQUEST,
                &format!("未找到键鼠测试场景: {scenario_name}"),
            )
        })
}

fn build_closed_loop_plan(
    scenario: &InteractionScenario,
    screen: ScreenDimensions,
    roi_radius: u32,
) -> ApiResult<ClosedLoopPlan> {
    let resolution = ResolutionCase {
        name: "current-screen",
        width: screen.width,
        height: screen.height,
        scale_factor: 1.0,
    };
    let Some((x, y)) = anchor_to_physical_pixel(scenario.anchor, resolution) else {
        return Err(api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "无法将锚点映射到当前屏幕坐标",
        ));
    };

    Ok(ClosedLoopPlan {
        point: PointDto { x, y },
        roi: clip_roi(x, y, screen.width, screen.height, roi_radius),
    })
}

fn clip_roi(x: i32, y: i32, screen_width: u32, screen_height: u32, radius: u32) -> RoiDto {
    let radius = i32::try_from(radius).unwrap_or(48);
    let screen_width = i32::try_from(screen_width).unwrap_or(i32::MAX);
    let screen_height = i32::try_from(screen_height).unwrap_or(i32::MAX);
    let left = (x - radius).clamp(0, screen_width.saturating_sub(1));
    let top = (y - radius).clamp(0, screen_height.saturating_sub(1));
    let right = (x + radius).clamp(left, screen_width.saturating_sub(1));
    let bottom = (y + radius).clamp(top, screen_height.saturating_sub(1));
    RoiDto {
        left,
        top,
        width: right.saturating_sub(left).saturating_add(1),
        height: bottom.saturating_sub(top).saturating_add(1),
    }
}

fn closed_loop_capture_path(timestamp: u64, phase: &str) -> PathBuf {
    default_latest_desktop_capture_path()
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(env::temp_dir)
        .join("closed-loop")
        .join(format!("{timestamp}-{phase}.png"))
}

fn read_png_dimensions(path: &Path) -> ApiResult<ScreenDimensions> {
    let bytes = std::fs::read(path).map_err(io_api_error)?;
    parse_png_dimensions(&bytes).ok_or_else(|| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("无法解析截图尺寸: {}", path.display()),
        )
    })
}

fn parse_png_dimensions(bytes: &[u8]) -> Option<ScreenDimensions> {
    let signature = [0x89, b'P', b'N', b'G', b'\r', b'\n', 0x1A, b'\n'];
    if bytes.len() < 24 || bytes[..8] != signature {
        return None;
    }
    if &bytes[12..16] != b"IHDR" {
        return None;
    }
    let width = u32::from_be_bytes(bytes[16..20].try_into().ok()?);
    let height = u32::from_be_bytes(bytes[20..24].try_into().ok()?);
    if width == 0 || height == 0 {
        return None;
    }
    Some(ScreenDimensions { width, height })
}

async fn capture_file_info(path: &Path) -> ApiResult<CaptureFileInfo> {
    let bytes = tokio::fs::read(path).await.map_err(io_api_error)?;
    let metadata = tokio::fs::metadata(path).await.map_err(io_api_error)?;
    Ok(CaptureFileInfo {
        path: path.display().to_string(),
        bytes: metadata.len(),
        modified_at: metadata.modified().ok().and_then(system_time_millis),
        hash: hash_bytes(&bytes),
    })
}

fn hash_bytes(bytes: &[u8]) -> u64 {
    let mut hasher = DefaultHasher::new();
    bytes.hash(&mut hasher);
    hasher.finish()
}

async fn execute_mouse_action(
    scenario: &InteractionScenario,
    x: i32,
    y: i32,
    text: Option<&str>,
) -> Result<(), String> {
    match scenario.action {
        MouseActionKind::LeftClick => send_mouse_action(x, y, MouseButtonAction::LeftClick).await,
        MouseActionKind::RightClick => send_mouse_action(x, y, MouseButtonAction::RightClick).await,
        MouseActionKind::LeftRightChord => {
            send_mouse_action(x, y, MouseButtonAction::LeftRightChord).await
        }
        MouseActionKind::DoubleClick => {
            send_mouse_action(x, y, MouseButtonAction::DoubleClick).await
        }
        MouseActionKind::TextInput => {
            let Some(text) = text.filter(|value| !value.is_empty()) else {
                return Err("文本输入场景需要传 text，避免误输入。".to_string());
            };
            send_mouse_action(x, y, MouseButtonAction::LeftClick).await?;
            send_text_input(text.to_string()).await
        }
        MouseActionKind::Drag => Err("拖拽动作尚未开放真实执行".to_string()),
        MouseActionKind::KeyPress
        | MouseActionKind::Hotkey
        | MouseActionKind::VerticalScroll
        | MouseActionKind::HorizontalScroll => {
            Err("该评测动作尚未在 closed-loop 执行器开放真实执行".to_string())
        }
    }
}

async fn send_mouse_action(x: i32, y: i32, action: MouseButtonAction) -> Result<(), String> {
    run_blocking_input(move || mouse_button_action_point(x, y, action, Duration::from_secs(6)))
        .await
}

async fn send_drag_action(start: PointDto, end: PointDto) -> Result<(), String> {
    run_blocking_input(move || {
        drag_point(
            MousePoint {
                x: start.x,
                y: start.y,
            },
            MousePoint { x: end.x, y: end.y },
            16,
            Duration::from_millis(18),
            Duration::from_secs(8),
        )
    })
    .await
}

async fn send_escape_key() -> Result<(), String> {
    run_blocking_input(move || press_escape(Duration::from_secs(3))).await
}

async fn send_text_input(text: String) -> Result<(), String> {
    run_blocking_input(move || input_type_text(&text, Duration::from_secs(8))).await
}

async fn run_blocking_input<F>(operation: F) -> Result<(), String>
where
    F: FnOnce() -> Result<(), String> + Send + 'static,
{
    // 先排队拿到全局输入闸门，确保任意时刻只有一个 compute-use 动作在真实操作键鼠，
    // 避免多会话并发注入冲突。锁在本次注入完成（spawn_blocking 结束）后自动释放。
    let _guard = compute_use_input_gate().lock().await;
    tokio::task::spawn_blocking(operation)
        .await
        .map_err(|error| format!("input backend task failed: {error}"))?
}

fn closed_loop_notes(execute: bool, action: MouseActionKind) -> Vec<String> {
    let mut notes = vec![
        "执行前截图使用原始分辨率，避免缩略图缩放误差".to_string(),
        "ROI 是围绕锚点的小区域，可作为后续本地 VLM 或模板确认输入。".to_string(),
        "执行后截图会通过文件哈希和大小判断画面是否变化".to_string(),
    ];
    if !execute {
        notes.push("当前 dry-run，未触发真实鼠标或键盘输入。".to_string());
    }
    if action == MouseActionKind::RightClick {
        notes.push("右键场景真实执行后可能留下上下文菜单，后续可增加恢复动作".to_string());
    }
    notes
}

fn safe_click_window(
    screen: ScreenDimensions,
    requested_width: u32,
    requested_height: u32,
) -> SafeClickWindow {
    let width = requested_width.clamp(320, 640);
    let height = requested_height.clamp(220, 420);
    let screen_width = i32::try_from(screen.width).unwrap_or(i32::MAX);
    let screen_height = i32::try_from(screen.height).unwrap_or(i32::MAX);
    let width_i32 = i32::try_from(width).unwrap_or(420);
    let height_i32 = i32::try_from(height).unwrap_or(260);
    let left = ((screen_width - width_i32) / 2).max(0);
    let top = ((screen_height - height_i32) / 2).max(0);
    SafeClickWindow {
        left,
        top,
        width: width_i32,
        height: height_i32,
        click_point: PointDto {
            x: left + width_i32 / 2,
            y: top + height_i32 / 2 + 8,
        },
    }
}

fn safe_click_window_for_layout(
    screen: ScreenDimensions,
    requested_width: u32,
    requested_height: u32,
    layout: &str,
) -> SafeClickWindow {
    if layout.eq_ignore_ascii_case("center") {
        return safe_click_window(screen, requested_width, requested_height);
    }

    let width = requested_width.clamp(320, 640);
    let height = requested_height.clamp(220, 420);
    let screen_width = i32::try_from(screen.width).unwrap_or(i32::MAX);
    let screen_height = i32::try_from(screen.height).unwrap_or(i32::MAX);
    let width_i32 = i32::try_from(width).unwrap_or(420);
    let height_i32 = i32::try_from(height).unwrap_or(260);
    let margin = 16;
    let max_left = screen_width
        .saturating_sub(width_i32)
        .saturating_sub(margin);
    let max_top = screen_height
        .saturating_sub(height_i32)
        .saturating_sub(margin);
    let left = if max_left <= margin {
        0
    } else {
        random_range_i32(margin, max_left)
    };
    let top = if max_top <= margin {
        0
    } else {
        random_range_i32(margin, max_top)
    };

    SafeClickWindow {
        left,
        top,
        width: width_i32,
        height: height_i32,
        click_point: PointDto {
            x: left + width_i32 / 2,
            y: top + height_i32 / 2 + 8,
        },
    }
}

fn random_target_number() -> u16 {
    u16::try_from(random_range_u32(100, 999)).unwrap_or(777)
}

fn random_range_i32(min: i32, max: i32) -> i32 {
    if max <= min {
        return min;
    }
    let span = u32::try_from(max - min + 1).unwrap_or(1);
    min + i32::try_from(random_u32() % span).unwrap_or(0)
}

fn random_range_u32(min: u32, max: u32) -> u32 {
    if max <= min {
        return min;
    }
    min + random_u32() % (max - min + 1)
}

fn random_u32() -> u32 {
    let mut bytes = [0_u8; 4];
    if getrandom::fill(&mut bytes).is_ok() {
        return u32::from_le_bytes(bytes);
    }
    (unix_timestamp_millis() & u64::from(u32::MAX)) as u32
}

