/// REQ-WEB-SESSION-007 / REQ-MEM-006：Schema v2 迁移。
///
/// - `memory_beads` 增加 `origin_message_id / origin_table / token_count`。
///   为删除消息时连带删除衍生 bead 做准备（trigger 自动执行）。
/// - 新增 `attachment_refs` 表，登记消息 "附件文件名映射，配合未来附件 GC。
///
/// 幂等：通过 `PRAGMA user_version` + `ensure_memory_bead_column` 保护。
/// 不破"v1 读写路径：全表重"`save_session_state_to_sqlite` 不触及新"新表
/// （不"DELETE/INSERT 列表），已有数据通过 ALTER 原地保留。
fn apply_session_migration_v2(connection: &Connection) -> rusqlite::Result<()> {
    let current: i64 = connection.query_row("PRAGMA user_version", [], |row| row.get(0))?;

    ensure_memory_bead_column(connection, "origin_message_id", "TEXT")?;
    ensure_memory_bead_column(connection, "origin_table", "TEXT")?;
    ensure_memory_bead_column(connection, "token_count", "INTEGER")?;

    connection.execute_batch(
        r#"
        CREATE TABLE IF NOT EXISTS attachment_refs (
            id           TEXT PRIMARY KEY,
            message_id   TEXT NOT NULL,
            message_tbl  TEXT NOT NULL
                CHECK (message_tbl IN ('session_messages','chat_room_messages')),
            file_name    TEXT NOT NULL,
            byte_size    INTEGER NOT NULL DEFAULT 0,
            created_at   INTEGER NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_attachment_refs_message
            ON attachment_refs(message_id);
        CREATE INDEX IF NOT EXISTS idx_attachment_refs_filename
            ON attachment_refs(file_name);
        CREATE TRIGGER IF NOT EXISTS trg_session_msg_cascade_beads
        AFTER DELETE ON session_messages
        BEGIN
            DELETE FROM memory_beads
            WHERE origin_table = 'session_messages'
              AND origin_message_id = OLD.id;
        END;
        CREATE TRIGGER IF NOT EXISTS trg_room_msg_cascade_beads
        AFTER DELETE ON chat_room_messages
        BEGIN
            DELETE FROM memory_beads
            WHERE origin_table = 'chat_room_messages'
              AND origin_message_id = OLD.id;
        END;
        "#,
    )?;

    if current < 2 {
        connection.execute_batch("PRAGMA user_version = 2;")?;
    }
    Ok(())
}

fn ensure_memory_bead_column(
    connection: &Connection,
    column: &str,
    column_type: &str,
) -> rusqlite::Result<()> {
    let exists = connection
        .prepare("PRAGMA table_info(memory_beads)")?
        .query_map([], |row| row.get::<_, String>(1))?
        .filter_map(Result::ok)
        .any(|name| name == column);
    if !exists {
        connection.execute(
            &format!("ALTER TABLE memory_beads ADD COLUMN {column} {column_type}"),
            [],
        )?;
    }
    Ok(())
}

fn apply_session_migration_v3(connection: &Connection) -> rusqlite::Result<()> {
    connection.execute_batch(
        r#"
        CREATE TABLE IF NOT EXISTS chat_handoffs (
            id TEXT PRIMARY KEY,
            chat_room_id TEXT NOT NULL,
            from_agent_id TEXT NOT NULL,
            to_agent_id TEXT NOT NULL,
            intent TEXT NOT NULL,
            intent_hash TEXT NOT NULL,
            attach TEXT NOT NULL,
            attach_message_ids_json TEXT NOT NULL,
            originating_user_msg_id TEXT NOT NULL,
            depth INTEGER NOT NULL,
            status TEXT NOT NULL,
            rejected_reason TEXT,
            created_at INTEGER NOT NULL,
            delivered_at INTEGER,
            completed_at INTEGER,
            FOREIGN KEY (chat_room_id) REFERENCES chat_rooms(id) ON DELETE CASCADE
        );
        CREATE INDEX IF NOT EXISTS idx_chat_handoffs_room_created
            ON chat_handoffs(chat_room_id, created_at DESC);
        CREATE INDEX IF NOT EXISTS idx_chat_handoffs_chain
            ON chat_handoffs(originating_user_msg_id, depth);
        "#,
    )?;
    let current: i64 = connection.query_row("PRAGMA user_version", [], |row| row.get(0))?;
    if current < 3 {
        connection.execute_batch("PRAGMA user_version = 3;")?;
    }
    Ok(())
}

