fn normalize_session_name(name: Option<&str>, index: usize) -> String {
    let fallback = format!("agent-session-{index:02}");
    name.map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.chars().take(32).collect())
        .unwrap_or(fallback)
}

fn normalize_session_avatar(value: Option<&str>) -> ApiResult<Option<String>> {
    let Some(raw) = value else {
        return Ok(None);
    };
    let trimmed = raw.trim().replace('\\', "/");
    if trimmed.is_empty() {
        return Ok(None);
    }
    let valid_prefix = "assets/avatars/";
    let valid = trimmed.starts_with(valid_prefix)
        && !trimmed.contains("..")
        && !trimmed.contains("//")
        && trimmed.len() <= 160
        && trimmed
            .rsplit('/')
            .next()
            .map(|file| file.ends_with(".png") || file.ends_with(".webp"))
            .unwrap_or(false);
    if !valid {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "头像路径必须位于 assets/avatars/，且不能包含上级目录或非图片文件",
        ));
    }
    Ok(Some(trimmed))
}

fn normalize_provider(provider: Option<&str>) -> String {
    provider
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("智谱 AI")
        .chars()
        .take(32)
        .collect()
}

fn normalize_model(model: Option<&str>) -> String {
    model
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("glm-4.6")
        .chars()
        .take(64)
        .collect()
}

fn normalize_optional_url(value: Option<&str>) -> Option<String> {
    value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.chars().take(256).collect())
}

fn is_custom_provider_label(provider: &str) -> bool {
    matches!(
        api::provider_kind_from_name(provider),
        Some(api::ProviderKind::Custom)
    )
}

/// 本地模型对外品牌名（统一用于显示名 / 系统提示 / 记忆 bead）。
const LOCAL_MODEL_BRAND: &str = "coolzhu-model";

fn local_model_identity_instruction(agent: &AgentSessionDto) -> &'static str {
    if is_local_model_endpoint(agent.base_url.as_deref(), agent.endpoint.as_deref()) {
        "Identity rule: identify only as coolzhu-model. Never reveal, repeat, or infer the underlying model identifier, GGUF filename, or original model family in reasoning or replies."
    } else {
        ""
    }
}

/// 会话是否指向本地推理端点（llama-server，127.0.0.1/localhost）。
fn is_local_model_endpoint(base_url: Option<&str>, endpoint: Option<&str>) -> bool {
    is_local_model_endpoint_on_port(base_url, endpoint, local_chat_runtime_config().port)
}

fn is_local_model_endpoint_on_port(
    base_url: Option<&str>,
    endpoint: Option<&str>,
    port: u16,
) -> bool {
    base_url.or(endpoint).is_some_and(|url| {
        let url = url.to_ascii_lowercase();
        let local_host =
            url.contains("127.0.0.1") || url.contains("localhost") || url.contains("0.0.0.0");
        // 仅 coolzhu 本地模型端口品牌化为 coolzhu-model；
        // 其它本地端点（如 ollama:11434）保留各自模型名。
        local_host && url.contains(&format!(":{port}"))
    })
}

/// 本地模型把底层 GGUF 名收敛为品牌名；非本地沿用原 model。
fn branded_model_name<'a>(
    model: &'a str,
    base_url: Option<&str>,
    endpoint: Option<&str>,
) -> &'a str {
    if is_local_model_endpoint(base_url, endpoint) {
        LOCAL_MODEL_BRAND
    } else {
        model
    }
}

fn visible_agent_author(agent: &AgentSessionDto) -> String {
    if is_local_model_endpoint(agent.base_url.as_deref(), agent.endpoint.as_deref()) {
        LOCAL_MODEL_BRAND.to_string()
    } else {
        agent.display_name.clone()
    }
}

fn visible_reasoning_author(agent: &AgentSessionDto) -> String {
    format!("{} 推理", visible_agent_author(agent))
}

fn sanitize_visible_model_text(agent: &AgentSessionDto, text: &str) -> String {
    if !is_local_model_endpoint(agent.base_url.as_deref(), agent.endpoint.as_deref()) {
        return text.to_string();
    }
    let mut visible = text.to_string();
    let mut sensitive = vec![agent.model.trim().to_string()];
    if let Some(path) = configured_local_chat_model_path() {
        if let Some(file_name) = path.file_name().and_then(|value| value.to_str()) {
            sensitive.push(file_name.to_string());
        }
        if let Some(stem) = path.file_stem().and_then(|value| value.to_str()) {
            sensitive.push(stem.to_string());
        }
    }
    sensitive.sort_by_key(|value| std::cmp::Reverse(value.len()));
    sensitive.dedup();
    for label in sensitive {
        if !label.is_empty() && label != LOCAL_MODEL_BRAND {
            visible = visible.replace(&label, LOCAL_MODEL_BRAND);
        }
    }
    visible
}

fn session_display_name_for(
    name: &str,
    provider: &str,
    model: &str,
    base_url: Option<&str>,
    endpoint: Option<&str>,
) -> String {
    let name = name.trim();
    let model = branded_model_name(model, base_url, endpoint).trim();
    if is_custom_provider_label(provider) {
        if model.is_empty() {
            name.to_string()
        } else if name.is_empty() {
            model.to_string()
        } else {
            format!("{name}({model})")
        }
    } else if model.is_empty() {
        name.to_string()
    } else {
        format!("{name} ({model})")
    }
}

fn goal_role_session_display_name_for(name: &str, model: &str) -> String {
    let name = name.trim();
    let model = model.trim();
    if model.is_empty() {
        name.to_string()
    } else {
        format!("{name} ({model})")
    }
}

fn custom_provider_urls(
    provider: &str,
    base_url: Option<&str>,
    endpoint: Option<&str>,
) -> (Option<String>, Option<String>) {
    if is_custom_provider_label(provider) {
        (
            normalize_optional_url(base_url),
            normalize_optional_url(endpoint),
        )
    } else {
        (None, None)
    }
}

fn default_reasoning_effort() -> String {
    "auto".to_string()
}

fn validate_reasoning_effort(value: Option<&str>) -> ApiResult<()> {
    api::parse_reasoning_effort(value)
        .map(|_| ())
        .map_err(|error| {
            api_error(
                StatusCode::BAD_REQUEST,
                &format!(
                    "reasoning_effort 非法值 {:?}，允许值：auto、none、minimal、low、medium、high、xhigh、max",
                    error.raw
                ),
            )
        })
}

/// 供 reasoning resolver 使用的最小 provider 迁移映射。
/// 持久层仍保留原始 provider 字符串；只有解析边界 canonicalize。
fn canonical_provider_id_for_reasoning(provider: &str) -> String {
    let normalized = provider
        .trim()
        .to_ascii_lowercase()
        .replace([' ', '_', '-', '(', ')', '.'], "");
    match normalized.as_str() {
        "deepseek" | "深度求索" => "deepseek".to_string(),
        "zhipuai" | "zhipu" | "zai" | "bigmodel" | "zhupuai" | "智谱ai" | "智谱" => {
            "zhipuai".to_string()
        }
        "openai" => "openai".to_string(),
        "anthropic" | "clawapi" | "claw" => "clawapi".to_string(),
        "xai" | "grok" => "xai".to_string(),
        "alibababailian" | "alibaba" | "aliyun" | "bailian" | "dashscope" => {
            "alibaba-bailian".to_string()
        }
        "bytedance" | "bytedanceark" | "ark" | "volcengine" | "doubao" => {
            "bytedance".to_string()
        }
        "baidu" | "baiduqianfan" | "qianfan" | "wenxin" => "baidu".to_string(),
        "custom" | "customopenai" | "customopenaicompatible" | "ollama" | "本地" => {
            "custom".to_string()
        }
        _ => api::provider_kind_from_name(provider)
            .map(|kind| match kind {
                api::ProviderKind::ClawApi | api::ProviderKind::Anthropic => "clawapi",
                api::ProviderKind::OpenAi => "openai",
                api::ProviderKind::Xai => "xai",
                api::ProviderKind::ZhipuAi => "zhipuai",
                api::ProviderKind::AlibabaBailian => "alibaba-bailian",
                api::ProviderKind::BaiduQianfan => "baidu",
                api::ProviderKind::ByteDanceArk => "bytedance",
                api::ProviderKind::DeepSeek => "deepseek",
                api::ProviderKind::Custom => "custom",
            })
            .map(str::to_string)
            .unwrap_or_else(|| provider.trim().to_string()),
    }
}

fn reasoning_resolution_for_session(
    provider: &str,
    model: &str,
    raw_reasoning_effort: Option<&str>,
) -> api::ReasoningResolution {
    let provider_id = canonical_provider_id_for_reasoning(provider);
    api::resolve_legacy_reasoning(&provider_id, model, raw_reasoning_effort)
}

fn default_model_type() -> String {
    "text".to_string()
}

fn normalize_model_type(value: Option<&str>) -> String {
    match value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("text")
        .to_ascii_lowercase()
        .as_str()
    {
        "vision" | "视觉" => "vision".to_string(),
        "multimodal" | "multi-modal" | "多模" => "multimodal".to_string(),
        "image" | "图像" | "图片" => "image".to_string(),
        "video" | "视频" => "video".to_string(),
        "audio" | "音频" => "audio".to_string(),
        "embedding" | "embed" | "嵌入" => "embedding".to_string(),
        _ => "text".to_string(),
    }
}

fn resolve_model_type(model: &str) -> String {
    let lower = model.to_ascii_lowercase();
    if lower.contains("vl") || lower.contains("vision") {
        return "vision".to_string();
    }
    if lower.contains("video") {
        return "video".to_string();
    }
    if lower.contains("image")
        || lower.contains("dall-e")
        || lower.contains("flux")
        || lower.contains("imagen")
    {
        return "image".to_string();
    }
    if lower.contains("audio") || lower.contains("whisper") || lower.contains("speech") {
        return "audio".to_string();
    }
    if lower.contains("embedding") || lower.contains("embed") {
        return "embedding".to_string();
    }
    "text".to_string()
}

fn vision_session_config() -> VisionSessionConfig {
    let store = session_store().lock().ok();
    let session = store
        .as_ref()
        .and_then(|store| store.state.active_vision_session_id.as_deref())
        .and_then(|id| {
            store
                .as_ref()?
                .state
                .sessions
                .iter()
                .find(|session| session.id == id)
        });
    let Some(session) = session else {
        diag!("[VISION-CFG] no active vision session");
        return VisionSessionConfig::default();
    };
    let base_url = effective_agent_base_url_impl(session.base_url.as_deref(), &session.provider);
    let api_key = resolve_api_key_ref(&session.api_key_ref);
    diag!(
        "[VISION-CFG] session={}, provider={}, model={}, base_url={:?}, has_key={}",
        session.id,
        session.provider,
        session.model,
        base_url,
        api_key.is_some()
    );
    VisionSessionConfig {
        base_url,
        model: Some(session.model.clone()),
        api_key,
    }
}

fn effective_agent_base_url_impl(
    explicit_base_url: Option<&str>,
    provider: &str,
) -> Option<String> {
    if let Some(base_url) = explicit_base_url {
        let trimmed = base_url.trim().trim_end_matches('/');
        if !trimmed.is_empty() {
            return Some(trimmed.to_string());
        }
    }
    let provider_kind = api::provider_kind_from_name(provider)
        .unwrap_or_else(|| api::detect_provider_kind(provider));
    let url = match provider_kind {
        api::ProviderKind::ZhipuAi => "https://open.bigmodel.cn/api/paas/v4",
        api::ProviderKind::AlibabaBailian => "https://dashscope.aliyuncs.com/compatible-mode/v1",
        api::ProviderKind::DeepSeek => "https://api.deepseek.com",
        api::ProviderKind::OpenAi => "https://api.openai.com/v1",
        api::ProviderKind::Xai => "https://api.x.ai/v1",
        api::ProviderKind::BaiduQianfan => "https://qianfan.baidubce.com/v2",
        api::ProviderKind::ByteDanceArk => "https://ark.cn-beijing.volces.com/api/v3",
        api::ProviderKind::Anthropic | api::ProviderKind::ClawApi => "https://api.anthropic.com/v1",
        api::ProviderKind::Custom => "http://127.0.0.1:11434/v1",
    };
    Some(url.to_string())
}

#[derive(Default, Clone)]
struct VisionSessionConfig {
    base_url: Option<String>,
    model: Option<String>,
    api_key: Option<String>,
}

fn effective_agent_base_url(agent: &AgentSessionDto) -> Option<String> {
    let base_url = agent.base_url.as_deref()?.trim().trim_end_matches('/');
    if base_url.is_empty() {
        return None;
    }
    base_url_with_optional_endpoint(base_url, agent.endpoint.as_deref())
}

fn effective_custom_agent_base_url(agent: &AgentSessionDto) -> Option<String> {
    if !is_custom_provider_label(&agent.provider) {
        return effective_agent_base_url(agent);
    }
    let base_url = agent
        .base_url
        .as_deref()
        .map(str::trim)
        .map(|value| value.trim_end_matches('/'))
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .or_else(|| effective_agent_base_url_impl(None, &agent.provider))?;
    base_url_with_optional_endpoint(&base_url, agent.endpoint.as_deref())
}

fn base_url_with_optional_endpoint(base_url: &str, endpoint: Option<&str>) -> Option<String> {
    let base_url = base_url.trim().trim_end_matches('/');
    if base_url.is_empty() {
        return None;
    }
    let endpoint = endpoint.map(str::trim).filter(|value| !value.is_empty());
    Some(match endpoint {
        Some(endpoint) => format!(
            "{}/{}",
            base_url,
            endpoint.trim_start_matches('/').trim_end_matches('/')
        ),
        None => base_url.to_string(),
    })
}

fn api_key_status_label(api_key_ref: &str) -> String {
    let value = api_key_ref.trim();
    if value.is_empty() {
        return "未配置（能力已启用）".to_string();
    }
    let lower = value.to_ascii_lowercase();
    let looks_secret = lower.starts_with("sk-")
        || lower.starts_with("sk_")
        || value.len() >= 32 && !value.contains(['/', '\\']);
    if looks_secret {
        let suffix = value
            .chars()
            .rev()
            .take(4)
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
            .collect::<String>();
        format!("已配置 Key (...{suffix})")
    } else {
        value.chars().take(64).collect()
    }
}

fn api_key_configuration_status(api_key_ref: &str) -> String {
    let value = api_key_ref.trim();
    if value.is_empty() {
        return "未配置（能力已启用）".to_string();
    }
    let label = api_key_status_label(value);
    if resolve_api_key_ref(value).is_none() {
        return format!("未配置（能力已启用；凭据引用 {label} 不可用）");
    }
    if looks_like_secret(value) {
        label
    } else {
        format!("引用 {label}")
    }
}

fn default_agent_sessions() -> Vec<AgentSessionDto> {
    let started = Instant::now();
    diag!("[AGENTS] default_agent_sessions start");
    let locked = session_store().lock();
    diag!(
        "[AGENTS] default_agent_sessions lock result: ok={}, elapsed_ms={}",
        locked.is_ok(),
        elapsed_millis(started)
    );
    let mut agents = locked
        .ok()
        .map(|store| {
            store
                .state
                .sessions
                .iter()
                .map(|session| session.to_agent_session(store.is_active(&session.id)))
                .collect::<Vec<_>>()
        })
        .filter(|agents| !agents.is_empty())
        .unwrap_or_else(|| {
            let seed = seed_session();
            vec![AgentSessionDto {
                id: seed.id.clone(),
                name: seed.name.clone(),
                display_name: session_display_name_for(
                    &seed.name,
                    &seed.provider,
                    &seed.model,
                    seed.base_url.as_deref(),
                    seed.endpoint.as_deref(),
                ),
                avatar: seed.avatar.clone(),
                model: seed.model.clone(),
                model_type: resolve_model_type(&seed.model),
                provider: seed.provider.clone(),
                base_url: seed.base_url.clone(),
                endpoint: seed.endpoint.clone(),
                reasoning_effort: seed.reasoning_effort.clone(),
                api_key_status: api_key_configuration_status(&seed.api_key_ref),
                selectable: true,
                enabled: true,
                system: false,
                default_timeout_ms: 20_000,
                memory_beads: seed.default_memory_beads(),
            }]
        });
    diag!(
        "[AGENTS] default_agent_sessions user agents built: count={}, elapsed_ms={}",
        agents.len(),
        elapsed_millis(started)
    );

    agents.push(AgentSessionDto {
        id: "system-tool-agent".to_string(),
        name: "system-tool-agent".to_string(),
        display_name: "系统工具执行 Agent".to_string(),
        avatar: None,
        model: "local-tool-runtime".to_string(),
        model_type: "text".to_string(),
        provider: "系统内置".to_string(),
        base_url: None,
        endpoint: None,
        reasoning_effort: default_reasoning_effort(),
        api_key_status: "不需".to_string(),
        selectable: false,
        enabled: true,
        system: true,
        default_timeout_ms: 15_000,
        memory_beads: Vec::new(),
    });
    diag!(
        "[AGENTS] default_agent_sessions done: count={}, elapsed_ms={}",
        agents.len(),
        elapsed_millis(started)
    );
    agents
}

fn build_overview_metrics() -> OverviewMetrics {
    let agents = default_agent_sessions();
    let active_agent_count = agents
        .iter()
        .filter(|agent| agent.selectable && agent.enabled && !agent.system)
        .count();
    let vision_agent = session_store().lock().ok().and_then(|store| {
        if let Some(active_id) = store.state.active_vision_session_id.as_deref() {
            if let Some(session) = store.state.sessions.iter().find(|session| {
                session.id == active_id && is_understanding_model_type(&session.model_type)
            }) {
                return Some(overview_vision_agent_from_session(session));
            }
        }
        store
            .state
            .sessions
            .iter()
            .find(|session| is_understanding_model_type(&session.model_type))
            .map(overview_vision_agent_from_session)
    });
    let chat_room_count = session_store()
        .lock()
        .ok()
        .map(|store| store.state.chat_rooms.len())
        .unwrap_or_default();

    OverviewMetrics {
        active_agent_count,
        vision_agent,
        chat_room_count,
    }
}

