fn active_pending_approval_count() -> usize {
    pending_approvals()
        .lock()
        .ok()
        .map(|map| {
            let now = Instant::now();
            map.values()
                .filter(|record| now.duration_since(record.created_at) < PENDING_APPROVAL_TTL)
                .count()
        })
        .unwrap_or_default()
}

fn office_tool_robot_state(pending_count: usize, audit_statuses: &[&str]) -> &'static str {
    if pending_count > 0 {
        return "waiting";
    }
    if audit_statuses.iter().any(|status| {
        let normalized = status.trim().to_ascii_lowercase();
        matches!(
            normalized.as_str(),
            "failed" | "rejected" | "timeout" | "error"
        )
    }) {
        return "warning";
    }
    if audit_statuses.iter().any(|status| {
        let normalized = status.trim().to_ascii_lowercase();
        matches!(normalized.as_str(), "ok" | "dry-run-only" | "success")
    }) {
        return "active";
    }
    "idle"
}

fn chat_room_roster_from_state(
    state: &PersistedSessionState,
    room_id: &str,
    me: Option<&str>,
) -> ApiResult<ChatRosterResponse> {
    let Some(room) = state.chat_rooms.iter().find(|room| room.id == room_id) else {
        return Err(api_error(StatusCode::NOT_FOUND, "聊天室不存在"));
    };
    let me = me.map(str::trim).filter(|value| !value.is_empty());
    let members = state
        .sessions
        .iter()
        .filter(|session| me != Some(session.id.as_str()))
        .map(|session| ChatRosterMemberDto {
            session_id: session.id.clone(),
            name: session.name.clone(),
            display_name: session_display_name_for(
                &session.name,
                &session.provider,
                &session.model,
                session.base_url.as_deref(),
                session.endpoint.as_deref(),
            ),
            provider: session.provider.clone(),
            model: session.model.clone(),
            model_type: normalize_model_type(Some(&session.model_type)),
            active: state.active_session_id.as_deref() == Some(session.id.as_str()),
            available: !session.model.trim().is_empty() && !session.provider.trim().is_empty(),
        })
        .collect::<Vec<_>>();

    Ok(ChatRosterResponse {
        room_id: room.id.clone(),
        room_name: room.name.clone(),
        generated_at: unix_timestamp_millis(),
        members,
    })
}

