fn understanding_agent_from_session(
    session: &PersistedSession,
    active_session_id: Option<&str>,
) -> UnderstandingAgentDto {
    let model_type = normalize_model_type(Some(&session.model_type));
    UnderstandingAgentDto {
        session_id: session.id.clone(),
        display_name: session_display_name_for(
            &session.name,
            &session.provider,
            &session.model,
            session.base_url.as_deref(),
            session.endpoint.as_deref(),
        ),
        provider: session.provider.clone(),
        model: session.model.clone(),
        model_type: model_type.clone(),
        base_url: effective_agent_base_url_impl(session.base_url.as_deref(), &session.provider),
        api_key_status: api_key_configuration_status(&session.api_key_ref),
        capabilities: UnderstandingCapabilities {
            describe_screen: true,
            analyze_image: true,
            analyze_video: model_type == "video",
            multimodal_chat: model_type == "multimodal",
        },
        active: active_session_id == Some(session.id.as_str()),
        updated_at: session.updated_at,
    }
}

fn is_understanding_model_type(model_type: &str) -> bool {
    matches!(
        normalize_model_type(Some(model_type)).as_str(),
        "vision" | "multimodal" | "video"
    )
}

fn is_multimodal_agent(agent: &AgentSessionDto) -> bool {
    if is_understanding_model_type(&agent.model_type) {
        return true;
    }
    let haystack = format!("{} {}", agent.model, agent.model_type).to_lowercase();
    [
        "vision",
        "vl",
        "glm-4.1v",
        "glm-4v",
        "qwen2.5-vl",
        "multimodal",
        "image",
        "视觉",
        "多模",
    ]
    .iter()
    .any(|keyword| haystack.contains(keyword))
}

/// 是否含明确的 GUI 操作动作意图（点击 / 打开 / 拖拽 / 输入 / 选中 / 滚动…）。
/// 用于把"看 / 描述 / 识别屏幕"这类纯视觉理解请求与"对屏幕执行操作"区分开，
/// 避免纯理解请求被误路由到 computer-use 视觉动作侧路而真实点击桌面。
fn vision_request_has_action_intent(text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    contains_any(
        &lower,
        &[
            "点击",
            "单击",
            "双击",
            "右键",
            "点一下",
            "点开",
            "拖",
            "打开",
            "关闭",
            "操作",
            "选中",
            "勾选",
            "按下",
            "输入",
            "键入",
            "打字",
            "滚动",
            "滑动",
            "click",
            "open",
            "close",
            "drag",
            "select",
            "press",
            "type",
            "scroll",
            "tap",
            "operate",
        ],
    )
}

fn should_run_semantic_tool_side_route(calls_vision: bool, calls_tool: bool, text: &str) -> bool {
    !text_explicitly_disables_all_tools(text)
        && (calls_tool || (calls_vision && vision_request_has_action_intent(text)))
}

fn should_route_to_vision_agent(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    [
        "当前桌面",
        "你看",
        "看一",
        "截图",
        "视觉",
        "screen",
        "desktop",
    ]
    .iter()
    .any(|keyword| text.contains(keyword))
}

fn should_route_to_tool_agent(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    [
        "打开", "关闭", "点击", "输入", "执行", "命令", "文件", "鼠标", "键盘", "click", "type",
    ]
    .iter()
    .any(|keyword| text.contains(keyword))
}

type ApiError = (StatusCode, Json<ErrorResponse>);
type ApiResult<T> = Result<T, ApiError>;

#[derive(Debug, Serialize)]
struct ErrorResponse {
    error: String,
}

#[derive(Debug, Serialize)]
struct AgentRegistryResponse {
    agents: Vec<AgentSessionDto>,
    active_agent_ids: Vec<String>,
    memory: MemoryPolicy,
}

#[derive(Debug, Clone)]
struct AgentSessionDto {
    id: String,
    name: String,
    display_name: String,
    avatar: Option<String>,
    model: String,
    model_type: String,
    provider: String,
    base_url: Option<String>,
    endpoint: Option<String>,
    reasoning_effort: String,
    api_key_status: String,
    selectable: bool,
    enabled: bool,
    system: bool,
    default_timeout_ms: u64,
    memory_beads: Vec<MemoryBeadDto>,
}

impl Serialize for AgentSessionDto {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        let resolution = reasoning_resolution_for_session(
            &self.provider,
            &self.model,
            Some(&self.reasoning_effort),
        );
        let resolution_dto = ReasoningResolutionDto::from(&resolution);
        let mut state = serializer.serialize_struct("AgentSessionDto", 17)?;
        state.serialize_field("id", &self.id)?;
        state.serialize_field("name", &self.name)?;
        state.serialize_field("display_name", &self.display_name)?;
        state.serialize_field("avatar", &self.avatar)?;
        state.serialize_field("model", &self.model)?;
        state.serialize_field("model_type", &self.model_type)?;
        state.serialize_field("provider", &self.provider)?;
        state.serialize_field("base_url", &self.base_url)?;
        state.serialize_field("endpoint", &self.endpoint)?;
        state.serialize_field("reasoning_effort", &resolution.requested.as_str())?;
        state.serialize_field("reasoning_resolution", &resolution_dto)?;
        state.serialize_field("api_key_status", &self.api_key_status)?;
        state.serialize_field("selectable", &self.selectable)?;
        state.serialize_field("enabled", &self.enabled)?;
        state.serialize_field("system", &self.system)?;
        state.serialize_field("default_timeout_ms", &self.default_timeout_ms)?;
        state.serialize_field("memory_beads", &self.memory_beads)?;
        state.end()
    }
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
