#[derive(Debug, Clone, Serialize, Deserialize)]
struct PersistedSession {
    id: String,
    name: String,
    provider: String,
    model: String,
    #[serde(default)]
    avatar: Option<String>,
    #[serde(default)]
    base_url: Option<String>,
    #[serde(default)]
    endpoint: Option<String>,
    #[serde(default = "default_reasoning_effort")]
    reasoning_effort: String,
    #[serde(default = "default_model_type")]
    model_type: String,
    api_key_ref: String,
    #[serde(default)]
    memory_beads: Vec<MemoryBeadDto>,
    created_at: u64,
    updated_at: u64,
    #[serde(default)]
    context_reset_at: u64,
    #[serde(default)]
    messages: Vec<PersistedChatMessage>,
}

impl PersistedSession {
    fn summary(&self, active: bool) -> SessionSummaryDto {
        SessionSummaryDto {
            id: self.id.clone(),
            name: self.name.clone(),
            display_name: session_display_name_for(
                &self.name,
                &self.provider,
                &self.model,
                self.base_url.as_deref(),
                self.endpoint.as_deref(),
            ),
            avatar: self.avatar.clone(),
            provider: self.provider.clone(),
            model: self.model.clone(),
            model_type: self.model_type.clone(),
            base_url: self.base_url.clone(),
            endpoint: self.endpoint.clone(),
            reasoning_effort: reasoning_resolution_for_session(
                &self.provider,
                &self.model,
                Some(&self.reasoning_effort),
            )
            .requested
            .as_str()
            .to_string(),
            reasoning_resolution: ReasoningResolutionDto::from(&reasoning_resolution_for_session(
                &self.provider,
                &self.model,
                Some(&self.reasoning_effort),
            )),
            api_key_status: api_key_configuration_status(&self.api_key_ref),
            memory_mode: memory_mode_for_session(&self.id),
            active,
            updated_at: self.updated_at,
        }
    }

    fn to_agent_session(&self, _active: bool) -> AgentSessionDto {
        AgentSessionDto {
            id: self.id.clone(),
            name: self.name.clone(),
            display_name: session_display_name_for(
                &self.name,
                &self.provider,
                &self.model,
                self.base_url.as_deref(),
                self.endpoint.as_deref(),
            ),
            avatar: self.avatar.clone(),
            model: self.model.clone(),
            model_type: normalize_model_type(Some(&self.model_type)),
            provider: self.provider.clone(),
            base_url: self.base_url.clone(),
            endpoint: self.endpoint.clone(),
            // Agent registry 需要保留持久层 raw 值，序列化时再由 legacy resolver
            // 给出 canonical requested 与 legacy_fallback 证据。
            reasoning_effort: self.reasoning_effort.clone(),
            api_key_status: api_key_configuration_status(&self.api_key_ref),
            selectable: true,
            enabled: true,
            system: false,
            default_timeout_ms: 20_000,
            memory_beads: self.default_memory_beads(),
        }
    }

    fn default_memory_beads(&self) -> Vec<MemoryBeadDto> {
        if !self.memory_beads.is_empty() {
            return self.memory_beads.clone();
        }

        // 本地模型在记忆中也用品牌名（与显示名/系统提示一致），避免泄漏底层 GGUF 名。
        let model_label = branded_model_name(
            &self.model,
            self.base_url.as_deref(),
            self.endpoint.as_deref(),
        );
        vec![
            MemoryBeadDto {
                id: format!("{}-person", self.id),
                kind: "person".to_string(),
                layer: "L1".to_string(),
                summary: format!(
                    "会话 {} 使用 {} / {}",
                    self.name, self.provider, model_label
                ),
                source: "session-config".to_string(),
                pinned: true,
                confidence: 1.0,
                created_at: self.created_at,
                origin_message_id: None,
                origin_table: None,
                token_count: None,
            },
            MemoryBeadDto {
                id: format!("{}-task", self.id),
                kind: "task".to_string(),
                layer: "L2".to_string(),
                summary: "聊天室历史会在该会话内连续加载，后续沉淀 beads 记忆".to_string(),
                source: "chat-room".to_string(),
                pinned: false,
                confidence: 0.72,
                created_at: self.created_at,
                origin_message_id: None,
                origin_table: None,
                token_count: None,
            },
        ]
    }

    fn explicit_or_default_memory_beads(&self) -> Vec<MemoryBeadDto> {
        self.default_memory_beads()
    }

    fn query_prompt_memory_beads(&self, query: PromptMemoryQuery) -> Vec<MemoryBeadDto> {
        runtime::query_memory_beads(
            &self.explicit_or_default_memory_beads(),
            &query.to_runtime_options(8, 32),
        )
    }

    fn prune_memory_beads(&mut self) {
        self.prune_memory_beads_to(MAX_MEMORY_BEADS_PER_SESSION);
    }

    fn prune_memory_beads_to(&mut self, max_beads: usize) {
        if self.memory_beads.len() <= max_beads {
            return;
        }
        // 价值感知老化：pinned 永不淘汰；其余按"价值分"降序保留，低价值（简单问答）
        // 先被老化掉，高价值（高关联度的任务步骤/有效结果）留存。
        age_out_memory_beads_by_value(&mut self.memory_beads, max_beads);
    }
}

