fn stt_audio_upload_route() -> MethodRouter {
    post(api_audio_stt_data).layer(DefaultBodyLimit::max(
        DEFAULT_MAX_STT_UPLOAD_BYTES.saturating_add(STT_MULTIPART_OVERHEAD_BYTES),
    ))
}

fn stt_upload_identity(filename: &str) -> Option<(String, &'static str)> {
    let value = filename.strip_prefix("stt_")?;
    for extension in ["wav", "webm"] {
        let suffix = format!(".{extension}");
        if let Some(session_id) = value.strip_suffix(&suffix) {
            if !session_id.is_empty()
                && session_id
                    .chars()
                    .all(|character| character.is_ascii_alphanumeric() || character == '-')
            {
                return Some((session_id.to_string(), extension));
            }
        }
    }
    None
}

#[instrument]
async fn api_audio_stt_data(mut multipart: Multipart) -> Result<Json<SttDataResponse>, ApiError> {
    let mut session_id = String::new();
    let mut bytes_written = 0u64;

    while let Ok(Some(field)) = multipart.next_field().await {
        let name = field.name().unwrap_or("").to_string();
        if name == "audio" {
            let filename = field.file_name().unwrap_or("").to_string();
            let (parsed_session_id, extension) =
                stt_upload_identity(&filename).ok_or_else(|| {
                    api_error(
                        StatusCode::BAD_REQUEST,
                        "Invalid STT audio filename; expected stt_<session-id>.wav or .webm",
                    )
                })?;
            let data = field.bytes().await.map_err(|e| {
                api_error(
                    StatusCode::BAD_REQUEST,
                    &format!("Failed to read audio data: {}", e),
                )
            })?;
            if data.is_empty() {
                return Err(api_error(StatusCode::BAD_REQUEST, "Audio data is empty"));
            }
            session_id = parsed_session_id;
            let audio_path = std::env::temp_dir().join(format!("{session_id}.{extension}"));
            tokio::fs::write(&audio_path, &data).await.map_err(|e| {
                api_error(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    &format!("Failed to write audio file: {}", e),
                )
            })?;
            bytes_written = data.len() as u64;
            info!(
                "Audio data saved: {:?} ({} bytes)",
                audio_path, bytes_written
            );
        }
    }

    if session_id.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "Missing session_id in audio upload",
        ));
    }

    Ok(Json(SttDataResponse {
        session_id,
        bytes_written,
    }))
}

#[cfg(test)]
mod stt_audio_upload_tests {
    use super::*;
    use tower::ServiceExt;

    #[tokio::test]
    async fn stt_audio_upload_route_accepts_long_recording() {
        let session_id = format!("long-recording-{}", super::uuid_timestamp());
        let boundary = "coolzhu-stt-boundary";
        let payload = vec![0x2Au8; 3 * 1024 * 1024];
        let mut body = format!(
            "--{boundary}\r\nContent-Disposition: form-data; name=\"audio\"; filename=\"stt_{session_id}.webm\"\r\nContent-Type: audio/webm\r\n\r\n"
        )
        .into_bytes();
        body.extend_from_slice(&payload);
        body.extend_from_slice(format!("\r\n--{boundary}--\r\n").as_bytes());

        let response = Router::new()
            .route("/upload", super::stt_audio_upload_route())
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/upload")
                    .header(
                        header::CONTENT_TYPE,
                        format!("multipart/form-data; boundary={boundary}"),
                    )
                    .body(Body::from(body))
                    .expect("multipart request"),
            )
            .await
            .expect("upload response");

        assert_eq!(response.status(), StatusCode::OK);
        let audio_path = std::env::temp_dir().join(format!("{session_id}.webm"));
        assert_eq!(
            std::fs::metadata(&audio_path).unwrap().len(),
            payload.len() as u64
        );
        let _ = std::fs::remove_file(audio_path);
    }

    #[tokio::test]
    async fn stt_audio_upload_preserves_wav_extension() {
        let session_id = format!("wav-recording-{}", super::uuid_timestamp());
        let boundary = "coolzhu-stt-wav-boundary";
        let payload = b"RIFF-coolzhu-test-wave";
        let mut body = format!(
            "--{boundary}\r\nContent-Disposition: form-data; name=\"audio\"; filename=\"stt_{session_id}.wav\"\r\nContent-Type: audio/wav\r\n\r\n"
        )
        .into_bytes();
        body.extend_from_slice(payload);
        body.extend_from_slice(format!("\r\n--{boundary}--\r\n").as_bytes());

        let response = Router::new()
            .route("/upload", super::stt_audio_upload_route())
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/upload")
                    .header(
                        header::CONTENT_TYPE,
                        format!("multipart/form-data; boundary={boundary}"),
                    )
                    .body(Body::from(body))
                    .expect("multipart request"),
            )
            .await
            .expect("upload response");

        assert_eq!(response.status(), StatusCode::OK);
        let audio_path = std::env::temp_dir().join(format!("{session_id}.wav"));
        assert_eq!(
            std::fs::metadata(&audio_path).unwrap().len(),
            payload.len() as u64
        );
        let _ = std::fs::remove_file(audio_path);
    }
}

fn audio_tts_config_from_workspace(backend_override: Option<&str>) -> audio::TtsConfig {
    let config = read_config(|workspace| workspace.audio.clone());
    let mut tts = audio::TtsConfig::default();
    tts.backend = backend_override
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .unwrap_or(config.tts_backend);
    tts.index_tts = audio::IndexTtsConfig {
        base_url: config.index_tts.base_url,
        api_key: config.index_tts.api_key,
        default_voice: config.index_tts.default_voice,
        voices_dir: config.index_tts.voices_dir.map(PathBuf::from),
        timeout_seconds: config.index_tts.timeout_seconds,
    };
    for voice in config.voices {
        tts.voice_configs.push(audio::VoiceConfig {
            name: voice.name,
            model_path: voice
                .model_path
                .map(PathBuf::from)
                .unwrap_or_else(|| PathBuf::from("")),
            speed: 1.0,
            pitch: None,
            kind: voice.kind,
            reference_audio_path: voice.reference_audio_path.map(PathBuf::from),
        });
    }
    tts
}

async fn audio_health_snapshot() -> AudioHealthSnapshot {
    let now = uuid_timestamp();
    let cached = audio_health_cache()
        .lock()
        .ok()
        .and_then(|guard| guard.clone());
    if let Some(snapshot) = cached {
        if now.saturating_sub(snapshot.checked_at_ms) <= AUDIO_HEALTH_CACHE_TTL_MS {
            return snapshot;
        }
    }

    let stt_config = audio::SttConfig::default();
    let tts_config = audio_tts_config_from_workspace(None);
    let status = audio::check_audio_status(&stt_config, &tts_config).await;
    let index_tts_available = audio::indextts_available(&tts_config.index_tts).await;
    let snapshot = AudioHealthSnapshot {
        stt_available: status.stt_available,
        tts_available: status.tts_available,
        tts_backend: tts_config.backend,
        index_tts_base_url: tts_config.index_tts.base_url,
        index_tts_available,
        error: status.error,
        checked_at_ms: now,
    };
    if let Ok(mut guard) = audio_health_cache().lock() {
        *guard = Some(snapshot.clone());
    }
    snapshot
}

async fn audio_realtime_status_response() -> AudioRealtimeStatusResponse {
    let health = audio_health_snapshot().await;
    let realtime_config = read_config(|workspace| workspace.audio.realtime.clone());
    let streaming_tts_url = configured_streaming_tts_url(&realtime_config);
    let streaming_tts_url_configured = streaming_tts_url.is_some();
    let streaming_tts_timeout_seconds = realtime_config.streaming_tts_timeout_seconds.max(1);
    let state = audio_realtime_state()
        .lock()
        .map(|guard| guard.clone())
        .unwrap_or_default();
    let stream_session_id = realtime_session_state()
        .lock()
        .ok()
        .and_then(|session| session.session_id.clone())
        .or_else(|| state.session_id.clone())
        .unwrap_or_default();
    let stream_evidence = realtime_voice_stream::evidence_for_session(&stream_session_id);
    let auto_send_transcript = if state.running {
        state.auto_send_transcript
    } else {
        realtime_config.auto_send_transcript
    };
    let auto_tts_reply = if state.running {
        state.auto_tts_reply
    } else {
        realtime_config.auto_tts_reply
    };
    AudioRealtimeStatusResponse {
        available: health.stt_available || health.tts_available,
        running: state.running,
        mode: realtime_config.mode,
        auto_send_transcript,
        auto_tts_reply,
        session_id: state.session_id,
        started_at_ms: state.started_at_ms,
        stopped_at_ms: state.stopped_at_ms,
        updated_at_ms: state.updated_at_ms,
        audio_segments_received: state.audio_segments_received,
        audio_bytes_received: state.audio_bytes_received,
        audio_payload_chunks_received: state.audio_payload_chunks_received,
        last_audio_payload_bytes: state.last_audio_payload_bytes,
        last_audio_chunk_path: state.last_audio_chunk_path,
        active_stt_transport: if state.active_stt_transport.trim().is_empty() {
            "turn_based_mediarecorder".to_string()
        } else {
            state.active_stt_transport
        },
        partial_transcripts_received: state.partial_transcripts_received,
        last_partial_text: state.last_partial_text,
        last_partial_confidence: state.last_partial_confidence,
        last_partial_is_final: state.last_partial_is_final,
        partial_asr_provider: if state.partial_asr_provider.trim().is_empty() {
            "none".to_string()
        } else {
            state.partial_asr_provider
        },
        pcm_frames_sent: stream_evidence.pcm_frames_sent,
        pcm_bytes_sent: stream_evidence.pcm_bytes_sent,
        pcm_partial_events: stream_evidence.partial_events,
        pcm_final_events: stream_evidence.final_events,
        pcm_reconnects: stream_evidence.reconnects,
        pcm_dropped_frames: stream_evidence.dropped_frames,
        pcm_max_frame_gap_ms: stream_evidence.max_frame_gap_ms,
        provider_native_stream_ready: stream_evidence.provider_native_ready(),
        last_text: state.last_text,
        last_error: state.last_error,
        stt_available: health.stt_available,
        tts_available: health.tts_available,
        tts_backend: health.tts_backend,
        index_tts_base_url: health.index_tts_base_url,
        index_tts_available: health.index_tts_available,
        streaming_tts_url,
        streaming_tts_url_configured,
        streaming_tts_timeout_seconds,
    }
}

fn realtime_vision_state_name(vision: &VisionRealtimeElementState) -> String {
    if vision.last_error.is_some() {
        "error".to_string()
    } else if vision.loop_running {
        "running".to_string()
    } else if vision.loop_requested {
        "warming".to_string()
    } else if vision.frames_processed > 0 {
        "degraded".to_string()
    } else {
        "off".to_string()
    }
}

fn realtime_session_vision_state_name(
    session: &RealtimeSessionState,
    vision: &VisionRealtimeElementState,
) -> String {
    let mut vision_state = realtime_vision_state_name(vision);
    if !session.running
        && !vision.loop_running
        && !vision.loop_requested
        && vision.last_error.is_none()
    {
        vision_state = "off".to_string();
    }
    if session.running && session.start_vision && vision_state == "off" {
        vision_state = "warming".to_string();
    }
    vision_state
}

#[derive(Debug, Clone, Default)]
struct RealtimeStreamingCapabilityState {
    stt_transport: String,
    aec_mode: String,
    provider_adapter: String,
    tts_transport: String,
    streaming_tts_url_configured: bool,
    provider_native_partial_asr_ready: bool,
    far_end_reference_aec_ready: bool,
    realtime_model_adapter_ready: bool,
    streaming_tts_ready: bool,
    readiness_source: Option<String>,
}

fn normalize_realtime_capability(value: &str) -> String {
    value
        .trim()
        .to_ascii_lowercase()
        .replace('-', "_")
        .replace(' ', "_")
}

fn first_realtime_capability(values: &[&str], fallback: &str) -> String {
    values
        .iter()
        .map(|value| normalize_realtime_capability(value))
        .find(|value| !value.is_empty())
        .unwrap_or_else(|| fallback.to_string())
}

fn realtime_aec_mode_for_policy(policy: &RealtimeBargeInPolicy) -> String {
    if policy.browser_echo_cancellation && policy.noise_suppression && policy.auto_gain_control {
        REALTIME_AEC_BROWSER_CONSTRAINTS.to_string()
    } else {
        REALTIME_AEC_CONSTRAINTS_DEGRADED.to_string()
    }
}

fn realtime_stt_transport_for_partial_provider(provider: &str) -> String {
    let provider = normalize_realtime_capability(provider);
    if provider == REALTIME_STT_PROVIDER_NATIVE
        || provider.contains("provider_native")
        || provider.contains("native_streaming")
        || provider.contains("realtime_asr")
    {
        REALTIME_STT_PROVIDER_NATIVE.to_string()
    } else if provider.contains("browser") {
        "browser_speech_recognition".to_string()
    } else if provider.is_empty() || provider == "none" {
        REALTIME_STT_TURN_BASED.to_string()
    } else {
        "partial_asr_bridge".to_string()
    }
}

fn realtime_start_capabilities(
    request: &RealtimeSessionControlRequest,
    config: &ConfigAudioRealtime,
    policy: &RealtimeBargeInPolicy,
    start_audio: bool,
) -> RealtimeStreamingCapabilityState {
    let default_stt = if start_audio {
        REALTIME_STT_SEGMENTED_MEDIARECORDER
    } else {
        REALTIME_STT_TURN_BASED
    };
    let default_aec = realtime_aec_mode_for_policy(policy);
    RealtimeStreamingCapabilityState {
        stt_transport: first_realtime_capability(
            &[
                request.stt_transport.as_deref().unwrap_or_default(),
                config.stt_transport.as_str(),
            ],
            default_stt,
        ),
        aec_mode: first_realtime_capability(
            &[
                request.aec_mode.as_deref().unwrap_or_default(),
                config.aec_mode.as_str(),
            ],
            &default_aec,
        ),
        provider_adapter: first_realtime_capability(
            &[
                request.provider_adapter.as_deref().unwrap_or_default(),
                config.provider_adapter.as_str(),
            ],
            REALTIME_PROVIDER_LOCAL_HTTP_BRIDGE,
        ),
        tts_transport: first_realtime_capability(
            &[
                request.tts_transport.as_deref().unwrap_or_default(),
                config.tts_transport.as_str(),
            ],
            REALTIME_TTS_SEGMENTED_QUEUE,
        ),
        streaming_tts_url_configured: configured_streaming_tts_url(config).is_some(),
        ..Default::default()
    }
}

fn realtime_streaming_capabilities_for_session(
    session: &RealtimeSessionState,
    audio_state: &AudioRealtimeState,
    config: &ConfigAudioRealtime,
) -> RealtimeStreamingCapabilityState {
    let default_aec = realtime_aec_mode_for_policy(&session.barge_in_policy);
    let partial_provider = if audio_state.partial_asr_provider.trim().is_empty()
        || audio_state.partial_asr_provider == "none"
    {
        session.partial_asr_provider.as_str()
    } else {
        audio_state.partial_asr_provider.as_str()
    };
    let partial_stt_transport = realtime_stt_transport_for_partial_provider(partial_provider);
    let stream_evidence = session
        .session_id
        .as_deref()
        .map(realtime_voice_stream::evidence_for_session)
        .unwrap_or_default();
    let provider_native_partial_asr_ready = partial_stt_transport == REALTIME_STT_PROVIDER_NATIVE
        && stream_evidence.provider_native_ready();
    let provider_adapter = first_realtime_capability(
        &[
            if session.running {
                session.provider_adapter.as_str()
            } else {
                ""
            },
            config.provider_adapter.as_str(),
        ],
        REALTIME_PROVIDER_LOCAL_HTTP_BRIDGE,
    );
    let realtime_model_adapter_ready = session.running
        && session.realtime_model_adapter_ready
        && provider_adapter == REALTIME_PROVIDER_ADAPTER;
    let tts_transport = first_realtime_capability(
        &[
            if session.running {
                session.tts_transport.as_str()
            } else {
                ""
            },
            config.tts_transport.as_str(),
        ],
        REALTIME_TTS_SEGMENTED_QUEUE,
    );
    let streaming_tts_url_configured = configured_streaming_tts_url(config).is_some();
    let streaming_tts_ready = session.running
        && session.streaming_tts_ready
        && tts_transport == REALTIME_TTS_CHUNKED_STREAM;
    // 远端参考 AEC：前端上报 aec_reference 证据（TTS 播放参考 tap 活跃）后才视为 ready。
    let aec_mode = first_realtime_capability(
        &[
            if session.running {
                session.aec_mode.as_str()
            } else {
                ""
            },
            config.aec_mode.as_str(),
        ],
        &default_aec,
    );
    let far_end_reference_aec_ready = session.running
        && session.far_end_reference_aec_ready
        && aec_mode == REALTIME_AEC_FAR_END_REFERENCE;
    let mut readiness_sources = Vec::new();
    if far_end_reference_aec_ready {
        if let Some(at_ms) = session.last_aec_reference_event_ms {
            readiness_sources.push(format!("aec_reference_at_ms={at_ms}"));
        } else {
            readiness_sources.push("aec_reference=observed".to_string());
        }
    }
    if provider_native_partial_asr_ready {
        readiness_sources.push(format!("partial_asr_provider={partial_provider}"));
    }
    if realtime_model_adapter_ready {
        if let Some(at_ms) = session.last_model_stream_event_ms {
            readiness_sources.push(format!("model_stream_delta_at_ms={at_ms}"));
        } else {
            readiness_sources.push("model_stream_delta=observed".to_string());
        }
    }
    if streaming_tts_ready {
        if let Some(at_ms) = session.last_tts_stream_event_ms {
            readiness_sources.push(format!("tts_stream_chunk_at_ms={at_ms}"));
        } else {
            readiness_sources.push("tts_stream_chunk=observed".to_string());
        }
    }
    RealtimeStreamingCapabilityState {
        stt_transport: first_realtime_capability(
            &[
                if provider_native_partial_asr_ready {
                    partial_stt_transport.as_str()
                } else {
                    ""
                },
                if audio_state.running {
                    audio_state.active_stt_transport.as_str()
                } else {
                    ""
                },
                if session.running {
                    session.active_stt_transport.as_str()
                } else {
                    ""
                },
                config.stt_transport.as_str(),
            ],
            REALTIME_STT_TURN_BASED,
        ),
        aec_mode,
        provider_adapter,
        tts_transport,
        streaming_tts_url_configured,
        provider_native_partial_asr_ready,
        far_end_reference_aec_ready,
        realtime_model_adapter_ready,
        streaming_tts_ready,
        readiness_source: if readiness_sources.is_empty() {
            None
        } else {
            Some(readiness_sources.join("; "))
        },
        ..Default::default()
    }
}

fn realtime_audio_chunks_dir() -> PathBuf {
    let configured = PathBuf::from(config_data_dir());
    let data_dir = if configured.is_absolute() {
        configured
    } else {
        std::env::current_dir()
            .unwrap_or_else(|_| active_workspace_path())
            .join(configured)
    };
    data_dir.join("audio-realtime").join("chunks")
}

fn realtime_audio_safe_session_id(value: Option<&str>) -> String {
    let sanitized = value
        .unwrap_or("audio-rt")
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' {
                ch
            } else {
                '-'
            }
        })
        .collect::<String>();
    let trimmed = sanitized.trim_matches('-');
    if trimmed.is_empty() {
        "audio-rt".to_string()
    } else {
        trimmed.chars().take(80).collect()
    }
}

fn realtime_audio_chunk_extension(mime_type: &str) -> &'static str {
    let normalized = mime_type.trim().to_ascii_lowercase();
    if normalized.contains("webm") {
        "webm"
    } else if normalized.contains("wav") {
        "wav"
    } else if normalized.contains("ogg") || normalized.contains("opus") {
        "ogg"
    } else if normalized.contains("mp3") || normalized.contains("mpeg") {
        "mp3"
    } else if normalized.contains("mp4") || normalized.contains("m4a") {
        "m4a"
    } else {
        "webm"
    }
}

fn decode_realtime_audio_base64(value: Option<&str>) -> Result<Option<Vec<u8>>, String> {
    let Some(raw) = value.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let b64 = raw.rsplit_once(',').map(|(_, tail)| tail).unwrap_or(raw);
    use base64::Engine;
    base64::engine::general_purpose::STANDARD
        .decode(b64.as_bytes())
        .map(Some)
        .map_err(|error| format!("Invalid realtime audio_base64 payload: {error}"))
}

fn persist_realtime_audio_chunk(
    session_id: Option<&str>,
    mime_type: &str,
    now: u64,
    bytes: &[u8],
) -> Result<PathBuf, String> {
    let dir = realtime_audio_chunks_dir();
    std::fs::create_dir_all(&dir)
        .map_err(|error| format!("Failed to create realtime audio chunk directory: {error}"))?;
    let safe_session = realtime_audio_safe_session_id(session_id);
    let extension = realtime_audio_chunk_extension(mime_type);
    let path = dir.join(format!("{safe_session}-{now}.{extension}"));
    std::fs::write(&path, bytes)
        .map_err(|error| format!("Failed to write realtime audio chunk: {error}"))?;
    Ok(path)
}

#[derive(Debug, Clone, Default)]
struct RealtimeSegmentAsrOutcome {
    attempted: bool,
    transcript_received: bool,
    text: Option<String>,
    confidence: Option<f32>,
    provider: Option<String>,
    error: Option<String>,
    duration_ms: Option<u64>,
}

fn realtime_segment_asr_mode(config: &ConfigAudioRealtime) -> String {
    first_realtime_capability(
        &[config.segment_asr_mode.as_str()],
        REALTIME_SEGMENT_ASR_FINAL_STT,
    )
}

fn realtime_segment_should_attempt_asr(
    final_segment: bool,
    payload_path: Option<&str>,
    asr_mode: &str,
) -> bool {
    final_segment
        && payload_path.is_some()
        && normalize_realtime_capability(asr_mode) != REALTIME_SEGMENT_ASR_OFF
}

fn invalid_realtime_audio_payload(path: &Path) -> Option<String> {
    let extension = path
        .extension()
        .and_then(|value| value.to_str())
        .map(|value| value.to_ascii_lowercase())?;
    let bytes = std::fs::read(path).ok()?;
    let valid = match extension.as_str() {
        "webm" => bytes.starts_with(&[0x1a, 0x45, 0xdf, 0xa3]),
        "ogg" | "opus" => bytes.starts_with(b"OggS"),
        "wav" => bytes.len() >= 12 && &bytes[..4] == b"RIFF" && &bytes[8..12] == b"WAVE",
        "flac" => bytes.starts_with(b"fLaC"),
        "mp4" | "m4a" => bytes.len() >= 12 && &bytes[4..8] == b"ftyp",
        "mp3" => bytes.starts_with(b"ID3") || (bytes.len() >= 2 && bytes[0] == 0xff),
        _ => true,
    };
    if valid {
        None
    } else {
        Some(format!(
            "Invalid data: audio payload is not a valid {extension} container"
        ))
    }
}

async fn transcribe_realtime_final_audio_segment(
    payload_path: Option<&str>,
    final_segment: bool,
    asr_mode: &str,
) -> RealtimeSegmentAsrOutcome {
    if !realtime_segment_should_attempt_asr(final_segment, payload_path, asr_mode) {
        return RealtimeSegmentAsrOutcome::default();
    }

    let provider = REALTIME_SEGMENT_ASR_PROVIDER_LOCAL_STT_FINAL.to_string();
    let Some(path) = payload_path else {
        return RealtimeSegmentAsrOutcome::default();
    };
    let audio_path = PathBuf::from(path);
    let engine = audio::SttEngine::new(audio::SttConfig::default());
    if let Some(error) = invalid_realtime_audio_payload(&audio_path) {
        return RealtimeSegmentAsrOutcome {
            attempted: true,
            provider: Some(provider),
            error: Some(format!("No STT backend available. Attempts: {}", error)),
            ..Default::default()
        };
    }
    match engine.transcribe_file(&audio_path).await {
        Ok(result) => {
            let text = result.text.trim().chars().take(512).collect::<String>();
            if text.is_empty() {
                RealtimeSegmentAsrOutcome {
                    attempted: true,
                    provider: Some(provider),
                    error: Some("Local STT returned an empty transcript".to_string()),
                    duration_ms: Some(result.duration_ms),
                    ..Default::default()
                }
            } else {
                RealtimeSegmentAsrOutcome {
                    attempted: true,
                    transcript_received: true,
                    text: Some(text),
                    confidence: result.confidence,
                    provider: Some(provider),
                    duration_ms: Some(result.duration_ms),
                    ..Default::default()
                }
            }
        }
        Err(error) => RealtimeSegmentAsrOutcome {
            attempted: true,
            provider: Some(provider),
            error: Some(error),
            ..Default::default()
        },
    }
}

fn record_audio_realtime_error(error: &str, now: u64) {
    if let Ok(mut state) = audio_realtime_state().lock() {
        if state.running {
            state.last_error = Some(error.chars().take(512).collect());
            state.updated_at_ms = now;
        }
    }
    if let Ok(mut realtime) = realtime_session_state().lock() {
        if realtime.running {
            realtime.last_error = Some(error.chars().take(512).collect());
            realtime.updated_at_ms = now;
        }
    }
}

fn realtime_streaming_risk(
    audio_health: &AudioHealthSnapshot,
    policy: &RealtimeBargeInPolicy,
) -> RealtimeStreamingRiskDto {
    realtime_streaming_risk_with_capabilities(
        audio_health,
        policy,
        &RealtimeStreamingCapabilityState {
            stt_transport: REALTIME_STT_TURN_BASED.to_string(),
            aec_mode: realtime_aec_mode_for_policy(policy),
            provider_adapter: REALTIME_PROVIDER_LOCAL_HTTP_BRIDGE.to_string(),
            tts_transport: REALTIME_TTS_SEGMENTED_QUEUE.to_string(),
            ..Default::default()
        },
    )
}

fn realtime_streaming_risk_with_capabilities(
    audio_health: &AudioHealthSnapshot,
    _policy: &RealtimeBargeInPolicy,
    capabilities: &RealtimeStreamingCapabilityState,
) -> RealtimeStreamingRiskDto {
    let stt_transport = first_realtime_capability(
        &[capabilities.stt_transport.as_str()],
        REALTIME_STT_TURN_BASED,
    );
    let aec_mode = first_realtime_capability(
        &[capabilities.aec_mode.as_str()],
        REALTIME_AEC_CONSTRAINTS_DEGRADED,
    );
    let provider_adapter = first_realtime_capability(
        &[capabilities.provider_adapter.as_str()],
        REALTIME_PROVIDER_LOCAL_HTTP_BRIDGE,
    );
    let tts_transport = first_realtime_capability(
        &[capabilities.tts_transport.as_str()],
        REALTIME_TTS_SEGMENTED_QUEUE,
    );
    let readiness_gates = vec![
        realtime_streaming_gate_with_confirmation(
            "provider_native_partial_asr",
            "Provider-native partial ASR",
            stt_transport == REALTIME_STT_PROVIDER_NATIVE,
            capabilities.provider_native_partial_asr_ready,
            &format!("current STT transport is {stt_transport}"),
        ),
        realtime_streaming_gate_with_confirmation(
            "far_end_reference_aec",
            "Far-end reference AEC",
            aec_mode == REALTIME_AEC_FAR_END_REFERENCE,
            capabilities.far_end_reference_aec_ready,
            &format!("current AEC mode is {aec_mode}"),
        ),
        realtime_streaming_gate_with_confirmation(
            "realtime_model_adapter",
            "Realtime model adapter",
            provider_adapter == REALTIME_PROVIDER_ADAPTER,
            capabilities.realtime_model_adapter_ready,
            &format!("current provider adapter is {provider_adapter}"),
        ),
        {
            let tts_gate_reason = if audio_health.tts_available {
                if tts_transport == REALTIME_TTS_CHUNKED_STREAM
                    && !capabilities.streaming_tts_url_configured
                {
                    "audio.realtime.streaming_tts_url is not configured".to_string()
                } else {
                    format!("current TTS transport is {tts_transport}")
                }
            } else {
                "TTS backend is unavailable".to_string()
            };
            realtime_streaming_gate_with_confirmation(
                "streaming_tts_output",
                "Streaming TTS output",
                audio_health.tts_available
                    && tts_transport == REALTIME_TTS_CHUNKED_STREAM
                    && (capabilities.streaming_tts_url_configured
                        || capabilities.streaming_tts_ready),
                capabilities.streaming_tts_ready,
                &tts_gate_reason,
            )
        },
    ];
    let full_streaming_ready =
        audio_health.tts_available && readiness_gates.iter().all(|gate| gate.ready);
    let recommended_mode = if full_streaming_ready {
        REALTIME_MODE_FULL_STREAMING
    } else if audio_health.tts_available {
        REALTIME_MODE_HALF_DUPLEX_GUARDED
    } else {
        "text_only_guarded"
    };
    let risk_level = if full_streaming_ready {
        "ready"
    } else if aec_mode == REALTIME_AEC_BROWSER_CONSTRAINTS && audio_health.tts_available {
        "guarded"
    } else {
        "degraded"
    };
    let mut notes = Vec::new();
    if stt_transport != REALTIME_STT_PROVIDER_NATIVE {
        notes.push(format!(
            "STT transport is {stt_transport}; provider-native streaming partial ASR is not ready."
        ));
    }
    if aec_mode != REALTIME_AEC_FAR_END_REFERENCE {
        notes.push(format!(
            "AEC mode is {aec_mode}; far-end playback reference AEC is not ready."
        ));
    }
    if provider_adapter != REALTIME_PROVIDER_ADAPTER {
        notes.push(format!(
            "Provider adapter is {provider_adapter}; realtime model adapter is not ready."
        ));
    }
    if tts_transport != REALTIME_TTS_CHUNKED_STREAM {
        notes.push(format!(
            "TTS transport is {tts_transport}; chunk-level streaming TTS output is not ready."
        ));
    } else if !capabilities.streaming_tts_url_configured {
        notes.push(
            "TTS transport is chunked_tts_stream, but audio.realtime.streaming_tts_url is not configured."
                .to_string(),
        );
    }
    if !audio_health.tts_available {
        notes.push(
            "TTS is unavailable, so realtime auto spoken replies fall back to text.".to_string(),
        );
    } else if full_streaming_ready {
        notes.push(
            "Full streaming prerequisites are reported ready by runtime capability state."
                .to_string(),
        );
    }
    if !full_streaming_ready {
        if let Some(source) = capabilities
            .readiness_source
            .as_deref()
            .map(str::trim)
            .filter(|source| !source.is_empty())
        {
            notes.push(format!("Realtime readiness evidence source: {source}."));
        }
    }

    RealtimeStreamingRiskDto {
        stt_transport,
        aec_mode,
        provider_adapter,
        tts_transport,
        recommended_mode: recommended_mode.to_string(),
        full_streaming_ready,
        readiness_gates,
        risk_level: risk_level.to_string(),
        notes,
    }
}

fn realtime_streaming_gate(
    id: &str,
    label: &str,
    ready: bool,
    reason: String,
) -> RealtimeStreamingReadinessGateDto {
    RealtimeStreamingReadinessGateDto {
        id: id.to_string(),
        label: label.to_string(),
        ready,
        reason: if ready { "ready".to_string() } else { reason },
    }
}

fn realtime_streaming_gate_with_confirmation(
    id: &str,
    label: &str,
    capability_matches: bool,
    confirmed: bool,
    current_reason: &str,
) -> RealtimeStreamingReadinessGateDto {
    if capability_matches && confirmed {
        return realtime_streaming_gate(id, label, true, "ready".to_string());
    }
    let reason = if capability_matches {
        format!("{current_reason}; not confirmed by realtime adapter health")
    } else {
        current_reason.to_string()
    };
    realtime_streaming_gate(id, label, false, reason)
}

fn normalize_realtime_requested_mode(value: Option<&str>) -> String {
    let normalized = value
        .unwrap_or(REALTIME_MODE_HALF_DUPLEX_GUARDED)
        .trim()
        .to_ascii_lowercase()
        .replace('-', "_");
    match normalized.as_str() {
        "full" | "full_realtime" | "full_stream" | "full_streaming" | "true_streaming" => {
            REALTIME_MODE_FULL_STREAMING.to_string()
        }
        "guarded" | "half_duplex" | "half_duplex_guarded" | "text_only_guarded" => normalized,
        _ => REALTIME_MODE_HALF_DUPLEX_GUARDED.to_string(),
    }
}

fn realtime_mode_downgrade_reason(
    requested_mode: &str,
    risk: &RealtimeStreamingRiskDto,
) -> Option<String> {
    if requested_mode == REALTIME_MODE_FULL_STREAMING && !risk.full_streaming_ready {
        return Some(
            "Full streaming requested, but true streaming STT, far-end reference AEC, realtime provider adapters, and streaming TTS output are not all ready; downgraded to guarded mode."
                .to_string(),
        );
    }
    None
}

fn resolve_realtime_active_mode(
    requested_mode: &str,
    risk: &RealtimeStreamingRiskDto,
) -> (String, Option<String>) {
    if let Some(reason) = realtime_mode_downgrade_reason(requested_mode, risk) {
        let active_mode = if risk.recommended_mode.trim().is_empty() {
            REALTIME_MODE_HALF_DUPLEX_GUARDED.to_string()
        } else {
            risk.recommended_mode.clone()
        };
        return (active_mode, Some(reason));
    }
    (requested_mode.to_string(), None)
}

async fn realtime_session_status_response() -> RealtimeSessionStatusResponse {
    let config = read_config(|workspace| workspace.audio.realtime.clone());
    let streaming_tts_url = configured_streaming_tts_url(&config);
    let streaming_tts_url_configured = streaming_tts_url.is_some();
    let streaming_tts_timeout_seconds = config.streaming_tts_timeout_seconds.max(1);
    let audio_health = audio_health_snapshot().await;
    let session = realtime_session_state()
        .lock()
        .map(|guard| guard.clone())
        .unwrap_or_default();
    let stream_evidence = session
        .session_id
        .as_deref()
        .map(realtime_voice_stream::evidence_for_session)
        .unwrap_or_default();
    let audio_state = audio_realtime_state()
        .lock()
        .map(|guard| guard.clone())
        .unwrap_or_default();
    let vision = vision_realtime_state()
        .lock()
        .map(|guard| guard.clone())
        .unwrap_or_default();
    let vision_config = active_vision_router_config();
    let detection_model_path_exists = detection_model_path_exists(&vision_config.detection);
    let detection_health = detection_health_snapshot(&vision_config.detection).await;
    let detection_launcher_hint = detection_launcher_hint(&vision_config.detection);

    let vision_state = realtime_session_vision_state_name(&session, &vision);

    let mut main_state = session.main_state.clone();
    if session.running {
        if session.start_vision && vision_state == "warming" {
            main_state = "warming_vision".to_string();
        } else if audio_state.running || session.audio_in_state == "listening" {
            main_state = "listening".to_string();
        }
    }

    let auto_send_transcript = if session.running || audio_state.running {
        audio_state.auto_send_transcript
    } else {
        config.auto_send_transcript
    };
    let auto_tts_reply = if session.running || audio_state.running {
        audio_state.auto_tts_reply
    } else {
        config.auto_tts_reply
    };
    let capabilities = realtime_streaming_capabilities_for_session(&session, &audio_state, &config);
    let streaming_risk = realtime_streaming_risk_with_capabilities(
        &audio_health,
        &session.barge_in_policy,
        &capabilities,
    );
    let (active_mode, mode_downgrade_reason) =
        resolve_realtime_active_mode(&session.requested_mode, &streaming_risk);
    let mut audio_out_state = session.audio_out_state.clone();
    if auto_tts_reply && !audio_health.tts_available {
        audio_out_state = "error".to_string();
    }

    let mut notes = Vec::new();
    notes.push(
        "Unified realtime session coordinates existing audio and vision loops; it does not replace them."
            .to_string(),
    );
    if session.barge_in_policy.browser_echo_cancellation {
        notes.push("Browser microphone capture should request echoCancellation/noiseSuppression/autoGainControl.".to_string());
    }
    if session.running && session.start_vision && !vision.loop_running {
        notes.push("Vision loop is requested but not yet reporting running frames.".to_string());
    }
    if session.start_vision && !detection_health.reachable {
        notes.push(
            "Detection service is offline; realtime vision can degrade while audio remains available."
                .to_string(),
        );
    }
    if session.start_vision && vision_config.detection.model_path.is_none() {
        notes.push(
            "Detection model_path is not configured; start the UI-DETR/RF-DETR wrapper after setting a checkpoint."
                .to_string(),
        );
    } else if session.start_vision && !detection_model_path_exists {
        notes.push("Detection model_path is configured but missing on disk.".to_string());
    }
    if auto_tts_reply && !audio_health.tts_available {
        notes.push(
            "Final-reply TTS is enabled but no TTS backend is currently available.".to_string(),
        );
    }
    if capabilities.tts_transport == REALTIME_TTS_CHUNKED_STREAM && !streaming_tts_url_configured {
        notes.push(
            "Streaming TTS transport is requested, but audio.realtime.streaming_tts_url is not configured for frontend auto playback."
                .to_string(),
        );
    }
    if let Some(reason) = mode_downgrade_reason.clone() {
        notes.push(reason);
    }
    if let Some(error) = audio_health.error.clone() {
        notes.push(format!("Audio health: {error}"));
    }

    RealtimeSessionStatusResponse {
        available: true,
        running: session.running,
        session_id: session.session_id,
        main_state,
        requested_mode: session.requested_mode,
        active_mode,
        mode_downgrade_reason,
        vision_state,
        audio_in_state: if audio_state.running {
            "listening".to_string()
        } else {
            session.audio_in_state
        },
        reasoning_state: session.reasoning_state,
        audio_out_state,
        barge_in_state: session.barge_in_state,
        resource_state: session.resource_state,
        started_at_ms: session.started_at_ms,
        stopped_at_ms: session.stopped_at_ms,
        updated_at_ms: session.updated_at_ms,
        start_vision: session.start_vision,
        start_audio: session.start_audio,
        auto_send_transcript,
        auto_tts_reply,
        audio_realtime_running: audio_state.running,
        stt_available: audio_health.stt_available,
        tts_available: audio_health.tts_available,
        tts_backend: audio_health.tts_backend,
        tts_transport: capabilities.tts_transport,
        index_tts_base_url: audio_health.index_tts_base_url,
        index_tts_available: audio_health.index_tts_available,
        streaming_tts_url,
        streaming_tts_url_configured,
        streaming_tts_timeout_seconds,
        streaming_risk,
        vision_loop_requested: vision.loop_requested,
        vision_loop_running: vision.loop_running,
        vision_frames_processed: vision.frames_processed,
        vision_element_count: vision.elements.len(),
        detection_backend: vision_config.detection.backend.clone(),
        detection_model: vision_config.detection.model.clone(),
        detection_model_path: vision_config.detection.model_path.clone(),
        detection_model_path_exists,
        detection_base_url: vision_config.detection.base_url.clone(),
        detection_service_reachable: detection_health.reachable,
        detection_service_health_url: detection_health.health_url,
        detection_launcher_hint,
        audio_segments_received: audio_state.audio_segments_received,
        audio_bytes_received: audio_state.audio_bytes_received,
        audio_payload_chunks_received: audio_state.audio_payload_chunks_received,
        last_audio_payload_bytes: audio_state
            .last_audio_payload_bytes
            .max(session.last_audio_payload_bytes),
        last_audio_chunk_path: audio_state
            .last_audio_chunk_path
            .or(session.last_audio_chunk_path.clone()),
        active_stt_transport: if audio_state.active_stt_transport.trim().is_empty() {
            session.active_stt_transport
        } else {
            audio_state.active_stt_transport
        },
        partial_transcripts_received: audio_state.partial_transcripts_received,
        last_partial_text: audio_state
            .last_partial_text
            .or(session.last_partial_text.clone()),
        last_partial_confidence: audio_state
            .last_partial_confidence
            .or(session.last_partial_confidence),
        last_partial_is_final: audio_state.last_partial_is_final || session.last_partial_is_final,
        partial_asr_provider: if audio_state.partial_asr_provider.trim().is_empty()
            || audio_state.partial_asr_provider == "none"
        {
            session.partial_asr_provider
        } else {
            audio_state.partial_asr_provider
        },
        pcm_frames_sent: stream_evidence.pcm_frames_sent,
        pcm_bytes_sent: stream_evidence.pcm_bytes_sent,
        pcm_partial_events: stream_evidence.partial_events,
        pcm_final_events: stream_evidence.final_events,
        provider_native_stream_ready: stream_evidence.provider_native_ready(),
        last_error: session.last_error.or(vision.last_error),
        barge_in_policy: session.barge_in_policy,
        notes,
    }
}

async fn api_realtime_session_status() -> Json<RealtimeSessionStatusResponse> {
    Json(realtime_session_status_response().await)
}

async fn api_realtime_session_events(
) -> Sse<impl futures_core::Stream<Item = Result<Event, std::convert::Infallible>>> {
    let mut rx = realtime_session_event_bus().subscribe();
    let stream = async_stream::stream! {
        yield Ok::<Event, std::convert::Infallible>(
            Event::default().event("hello").data("{\"ok\":true,\"service\":\"realtime-session\"}"),
        );
        loop {
            match rx.recv().await {
                Ok(event) => {
                    yield Ok(sse_json_event(&event.kind, &event));
                }
                Err(broadcast::error::RecvError::Lagged(n)) => {
                    let payload = format!(r#"{{"skipped":{n}}}"#);
                    yield Ok(Event::default().event("lagged").data(payload));
                }
                Err(broadcast::error::RecvError::Closed) => break,
            }
        }
    };
    Sse::new(stream)
}

fn reset_audio_realtime_observability_for_session(
    state: &mut AudioRealtimeState,
    now: u64,
    active_stt_transport: &str,
    auto_send_transcript: bool,
    auto_tts_reply: bool,
) {
    state.running = false;
    state.auto_send_transcript = auto_send_transcript;
    state.auto_tts_reply = auto_tts_reply;
    state.session_id = None;
    state.started_at_ms = None;
    state.stopped_at_ms = Some(now);
    state.updated_at_ms = now;
    state.audio_segments_received = 0;
    state.audio_bytes_received = 0;
    state.audio_payload_chunks_received = 0;
    state.last_audio_payload_bytes = 0;
    state.last_audio_chunk_path = None;
    state.active_stt_transport = active_stt_transport.to_string();
    state.partial_transcripts_received = 0;
    state.last_partial_text = None;
    state.last_partial_confidence = None;
    state.last_partial_is_final = false;
    state.partial_asr_provider = "none".to_string();
    state.last_text = None;
    state.last_error = None;
}

async fn start_realtime_child_loops(
    start_vision: bool,
    start_audio: bool,
    auto_send_transcript: bool,
    auto_tts_reply: bool,
    active_stt_transport: &str,
) {
    if start_vision {
        let _ = api_vision_realtime_start(Some(Json(VisionRealtimeControlRequest {
            use_latest_capture: Some(true),
        })))
        .await;
    }
    if start_audio {
        let _ = api_audio_realtime_start(Json(AudioRealtimeToggleRequest {
            auto_send_transcript: Some(auto_send_transcript),
            auto_tts_reply: Some(auto_tts_reply),
            stt_transport: Some(active_stt_transport.to_string()),
        }))
        .await;
    }
}

async fn stop_realtime_child_loops(stop_vision: bool, stop_audio: bool) {
    if stop_audio {
        let _ = api_audio_realtime_stop().await;
    }
    if stop_vision {
        let _ = api_vision_realtime_stop().await;
    }
}

async fn api_realtime_session_start(
    Json(request): Json<RealtimeSessionControlRequest>,
) -> Json<RealtimeSessionStatusResponse> {
    let config = read_config(|workspace| workspace.audio.realtime.clone());
    let now = uuid_timestamp();
    let start_vision = request.start_vision.unwrap_or(true);
    let start_audio = request.start_audio.unwrap_or(true);
    let auto_send_transcript = request
        .auto_send_transcript
        .unwrap_or(config.auto_send_transcript);
    let auto_tts_reply = request.auto_tts_reply.unwrap_or(config.auto_tts_reply);
    let barge_in_policy = request
        .barge_in_policy
        .clone()
        .unwrap_or_else(|| config.barge_in.clone());
    let audio_health = audio_health_snapshot().await;
    let capabilities =
        realtime_start_capabilities(&request, &config, &barge_in_policy, start_audio);
    let streaming_risk =
        realtime_streaming_risk_with_capabilities(&audio_health, &barge_in_policy, &capabilities);
    let requested_mode = normalize_realtime_requested_mode(request.requested_mode.as_deref());
    let (active_mode, mode_downgrade_reason) =
        resolve_realtime_active_mode(&requested_mode, &streaming_risk);
    let requested_mode_for_event = requested_mode.clone();
    let active_mode_for_event = active_mode.clone();
    let resource_state = if mode_downgrade_reason.is_some() {
        "guarded"
    } else if streaming_risk.risk_level == "degraded" {
        "degraded"
    } else {
        "normal"
    };
    let mut session_id_for_event = None;
    if let Ok(mut state) = realtime_session_state().lock() {
        state.running = true;
        state.session_id = Some(format!("rt-{now}"));
        session_id_for_event = state.session_id.clone();
        state.main_state = if start_vision {
            "warming_vision".to_string()
        } else {
            "listening".to_string()
        };
        state.requested_mode = requested_mode;
        state.active_mode = active_mode;
        state.mode_downgrade_reason = mode_downgrade_reason;
        state.vision_state = if start_vision {
            "warming".to_string()
        } else {
            "off".to_string()
        };
        state.audio_in_state = if start_audio {
            "listening".to_string()
        } else {
            "off".to_string()
        };
        state.reasoning_state = "idle".to_string();
        state.audio_out_state = "idle".to_string();
        state.barge_in_state = "quiet".to_string();
        state.resource_state = resource_state.to_string();
        state.started_at_ms = Some(now);
        state.stopped_at_ms = None;
        state.updated_at_ms = now;
        state.start_vision = start_vision;
        state.start_audio = start_audio;
        state.audio_segments_received = 0;
        state.audio_bytes_received = 0;
        state.audio_payload_chunks_received = 0;
        state.last_audio_payload_bytes = 0;
        state.last_audio_chunk_path = None;
        state.active_stt_transport = capabilities.stt_transport.clone();
        state.aec_mode = capabilities.aec_mode.clone();
        state.provider_adapter = capabilities.provider_adapter.clone();
        state.tts_transport = capabilities.tts_transport.clone();
        state.partial_transcripts_received = 0;
        state.last_partial_text = None;
        state.last_partial_confidence = None;
        state.last_partial_is_final = false;
        state.partial_asr_provider = "none".to_string();
        state.realtime_model_adapter_ready = false;
        state.last_model_stream_event_ms = None;
        state.streaming_tts_ready = false;
        state.last_tts_stream_event_ms = None;
        state.far_end_reference_aec_ready = false;
        state.last_aec_reference_event_ms = None;
        state.last_aec_generation_id = None;
        state.last_error = None;
        state.barge_in_policy = barge_in_policy;
    }
    emit_realtime_session_event(
        "session_started",
        session_id_for_event.clone(),
        json!({
            "requested_mode": requested_mode_for_event,
            "active_mode": active_mode_for_event,
            "start_vision": start_vision,
            "start_audio": start_audio,
            "auto_send_transcript": auto_send_transcript,
            "auto_tts_reply": auto_tts_reply,
            "tts_transport": capabilities.tts_transport.clone()
        }),
    );
    if let Ok(mut audio_state) = audio_realtime_state().lock() {
        reset_audio_realtime_observability_for_session(
            &mut audio_state,
            now,
            &capabilities.stt_transport,
            auto_send_transcript,
            auto_tts_reply,
        );
    }
    start_realtime_child_loops(
        start_vision,
        start_audio,
        auto_send_transcript,
        auto_tts_reply,
        &capabilities.stt_transport,
    )
    .await;
    Json(realtime_session_status_response().await)
}

async fn api_realtime_session_stop() -> Json<RealtimeSessionStatusResponse> {
    let now = uuid_timestamp();
    let (stop_vision, stop_audio) = realtime_session_state()
        .lock()
        .map(|state| (state.start_vision, state.start_audio))
        .unwrap_or((true, true));
    stop_realtime_child_loops(stop_vision, stop_audio).await;
    let mut stopped_session_id = None;
    if let Ok(mut state) = realtime_session_state().lock() {
        stopped_session_id = state.session_id.clone();
        state.running = false;
        state.main_state = "idle".to_string();
        state.vision_state = "off".to_string();
        state.audio_in_state = "off".to_string();
        state.reasoning_state = "idle".to_string();
        state.audio_out_state = "idle".to_string();
        state.barge_in_state = "quiet".to_string();
        state.resource_state = "normal".to_string();
        state.stopped_at_ms = Some(now);
        state.updated_at_ms = now;
        state.last_error = None;
    }
    emit_realtime_session_event(
        "session_stopped",
        stopped_session_id,
        json!({
            "stop_vision": stop_vision,
            "stop_audio": stop_audio,
            "stopped_at_ms": now
        }),
    );
    Json(realtime_session_status_response().await)
}

async fn api_realtime_model_stream_probe(
    Json(request): Json<RealtimeModelStreamProbeRequest>,
) -> ApiResult<Json<RealtimeModelStreamProbeResponse>> {
    let agent = {
        let selectable = default_agent_sessions()
            .into_iter()
            .filter(|agent| agent.selectable && agent.enabled)
            .collect::<Vec<_>>();
        if let Some(agent_id) = request
            .agent_id
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            selectable
                .into_iter()
                .find(|agent| agent.id == agent_id)
                .ok_or_else(|| {
                    api_error(StatusCode::NOT_FOUND, "Model stream probe agent not found")
                })?
        } else {
            selectable.into_iter().next().ok_or_else(|| {
                api_error(
                    StatusCode::BAD_REQUEST,
                    "No selectable agent is available for model stream probe",
                )
            })?
        }
    };
    let realtime_session_running = realtime_session_state()
        .lock()
        .map(|state| state.running)
        .unwrap_or(false);
    let started = Instant::now();
    let prompt = request
        .prompt
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("Reply with exactly: ok")
        .to_string();
    let max_events = request.max_events.unwrap_or(24).clamp(1, 128);
    let timeout_ms = request.timeout_ms.unwrap_or(15_000).clamp(1_000, 120_000);
    let stop_after_first_delta = request.stop_after_first_delta.unwrap_or(false);
    let record_runtime_evidence = request.record_runtime_evidence.unwrap_or(false);

    let error_response = |error: String| RealtimeModelStreamProbeResponse {
        ok: false,
        agent_id: agent.id.clone(),
        agent_name: agent.display_name.clone(),
        provider: agent.provider.clone(),
        model: agent.model.clone(),
        realtime_session_running,
        runtime_evidence_recorded: false,
        stream_closed_after_first_delta: false,
        event_count: 0,
        delta_count: 0,
        text_delta_count: 0,
        thinking_delta_count: 0,
        tool_delta_count: 0,
        bytes: 0,
        first_delta_ms: None,
        duration_ms: started.elapsed().as_millis() as u64,
        stopped_reason: "error".to_string(),
        sample: String::new(),
        error: Some(error),
    };

    if !real_llm_enabled() {
        return Ok(Json(error_response(
            "Real LLM is disabled; model stream probe requires the real provider path.".to_string(),
        )));
    }

    let stream_turn_id = diagnostics::TraceIdType::generate().to_hex();
    let stream_result =
        stream_agent_model(&agent, &prompt, &[], &[], None, &stream_turn_id, None).await;
    let Ok((mut model_stream, _assembly)) = stream_result else {
        return Ok(Json(error_response(format!(
            "Model stream probe failed to start: {}",
            stream_result.err().unwrap()
        ))));
    };

    let deadline = tokio::time::Instant::now() + Duration::from_millis(timeout_ms);
    let mut event_count = 0_u32;
    let mut delta_count = 0_u32;
    let mut text_delta_count = 0_u32;
    let mut thinking_delta_count = 0_u32;
    let mut tool_delta_count = 0_u32;
    let mut bytes = 0_u64;
    let mut first_delta_ms = None;
    let mut sample = String::new();
    let mut runtime_evidence_recorded = false;
    let mut stream_closed_after_first_delta = false;
    let mut stopped_reason = "stream_ended".to_string();
    let mut error = None;

    while event_count < max_events {
        let next = tokio::time::timeout_at(deadline, model_stream.next_event()).await;
        let event = match next {
            Ok(Ok(Some(event))) => event,
            Ok(Ok(None)) => {
                stopped_reason = "stream_ended".to_string();
                break;
            }
            Ok(Err(err)) => {
                stopped_reason = "stream_error".to_string();
                error = Some(format!("Model stream probe read failed: {err}"));
                break;
            }
            Err(_) => {
                stopped_reason = "timeout".to_string();
                error = Some(format!("Model stream probe timed out after {timeout_ms}ms"));
                break;
            }
        };
        event_count += 1;

        let mut observed_delta: Option<(&str, String)> = None;
        if let StreamEvent::ContentBlockDelta(delta) = event {
            match delta.delta {
                ContentBlockDelta::TextDelta { text } => {
                    if !text.trim().is_empty() {
                        text_delta_count += 1;
                        observed_delta = Some(("text", text));
                    }
                }
                ContentBlockDelta::ThinkingDelta { thinking } => {
                    if !thinking.trim().is_empty() {
                        thinking_delta_count += 1;
                        observed_delta = Some(("thinking", thinking));
                    }
                }
                ContentBlockDelta::InputJsonDelta { partial_json } => {
                    if !partial_json.trim().is_empty() {
                        tool_delta_count += 1;
                        observed_delta = Some(("tool_json", partial_json));
                    }
                }
                ContentBlockDelta::SignatureDelta { .. } => {}
            }
        }

        if let Some((delta_kind, delta_text)) = observed_delta {
            delta_count += 1;
            bytes = bytes.saturating_add(delta_text.as_bytes().len() as u64);
            if first_delta_ms.is_none() {
                first_delta_ms = Some(started.elapsed().as_millis() as u64);
            }
            if sample.chars().count() < 240 {
                sample.push_str(&delta_text);
                if sample.chars().count() > 240 {
                    sample = sample.chars().take(240).collect();
                }
            }
            if record_runtime_evidence && realtime_session_running {
                emit_active_realtime_session_event(
                    "model_stream_delta",
                    json!({
                        "agent_id": agent.id.clone(),
                        "agent_name": agent.display_name.clone(),
                        "provider": agent.provider.clone(),
                        "model": agent.model.clone(),
                        "delta": delta_text,
                        "delta_kind": delta_kind,
                        "source": "model_stream_probe"
                    }),
                );
                runtime_evidence_recorded = true;
            }
            if stop_after_first_delta {
                stream_closed_after_first_delta = true;
                stopped_reason = "first_delta_observed".to_string();
                break;
            }
        }
    }

    Ok(Json(RealtimeModelStreamProbeResponse {
        ok: delta_count > 0,
        agent_id: agent.id,
        agent_name: agent.display_name,
        provider: agent.provider,
        model: agent.model,
        realtime_session_running,
        runtime_evidence_recorded,
        stream_closed_after_first_delta,
        event_count,
        delta_count,
        text_delta_count,
        thinking_delta_count,
        tool_delta_count,
        bytes,
        first_delta_ms,
        duration_ms: started.elapsed().as_millis() as u64,
        stopped_reason,
        sample,
        error,
    }))
}

fn barge_in_response(
    decision: &str,
    barge_in_state: &str,
    should_interrupt: bool,
    reason: &str,
    recommended_action: &str,
) -> RealtimeBargeInEvaluateResponse {
    RealtimeBargeInEvaluateResponse {
        decision: decision.to_string(),
        barge_in_state: barge_in_state.to_string(),
        should_interrupt,
        reason: reason.to_string(),
        recommended_action: recommended_action.to_string(),
    }
}

fn realtime_barge_in_event_payload(
    response: &RealtimeBargeInEvaluateResponse,
    request: &RealtimeBargeInEvaluateRequest,
) -> JsonValue {
    json!({
        "decision": response.decision.clone(),
        "barge_in_state": response.barge_in_state.clone(),
        "should_interrupt": response.should_interrupt,
        "reason": response.reason.clone(),
        "recommended_action": response.recommended_action.clone(),
        "asr_text": request.asr_text.clone(),
        "asr_confidence": request.asr_confidence,
        "vad_active": request.vad_active,
        "speech_ms": request.speech_ms,
        "tts_playing": request.tts_playing,
        "echo_correlation": request.echo_correlation,
        "manual_interrupt": request.manual_interrupt
    })
}

fn realtime_text_has_interrupt_keyword(policy: &RealtimeBargeInPolicy, text: &str) -> bool {
    let normalized = text.to_lowercase();
    policy
        .interrupt_keywords
        .iter()
        .map(|keyword| keyword.trim().to_lowercase())
        .filter(|keyword| !keyword.is_empty())
        .any(|keyword| normalized.contains(&keyword))
}

fn evaluate_realtime_barge_in(
    policy: &RealtimeBargeInPolicy,
    request: &RealtimeBargeInEvaluateRequest,
) -> RealtimeBargeInEvaluateResponse {
    if !policy.enabled {
        return barge_in_response(
            "disabled",
            "disabled",
            false,
            "Barge-in guard is disabled by policy.",
            "continue_current_output",
        );
    }
    if request.manual_interrupt.unwrap_or(false) {
        return barge_in_response(
            "confirmed",
            "confirmed",
            true,
            "Manual stop/interruption bypassed acoustic and semantic checks.",
            "cancel_tts_and_model_output",
        );
    }

    let tts_playing = request.tts_playing.unwrap_or(false);
    let speech_ms = request.speech_ms.unwrap_or(0);
    let text = request.asr_text.as_deref().unwrap_or("").trim();
    let vad_active = request
        .vad_active
        .unwrap_or_else(|| speech_ms > 0 || !text.is_empty());
    let confidence = request
        .asr_confidence
        .unwrap_or(if text.is_empty() { 0.0 } else { 1.0 });
    let echo_correlation = request.echo_correlation.unwrap_or(0.0);

    if tts_playing && echo_correlation >= policy.echo_correlation_threshold {
        return barge_in_response(
            "echo_detected",
            "echo_detected",
            false,
            "Microphone signal correlates with current TTS playback.",
            "ignore_echo_and_keep_speaking",
        );
    }
    if !vad_active {
        return barge_in_response(
            "quiet",
            "quiet",
            false,
            "No active voice signal was detected.",
            "continue_listening",
        );
    }

    let has_interrupt_keyword = realtime_text_has_interrupt_keyword(policy, text);
    if !tts_playing {
        if !text.is_empty() || speech_ms > 0 {
            return barge_in_response(
                "user_turn",
                "quiet",
                false,
                "Voice input was captured while no realtime output is playing.",
                "continue_listening",
            );
        }
        return barge_in_response(
            "ignored_background",
            "quiet",
            false,
            "Voice activity did not target an active realtime output.",
            "keep_listening",
        );
    }

    if has_interrupt_keyword && speech_ms >= policy.strong_interrupt_min_ms && confidence >= 0.35 {
        return barge_in_response(
            "confirmed",
            "confirmed",
            true,
            "Strong interruption keyword was detected with enough speech duration.",
            "cancel_tts_and_model_output",
        );
    }

    let has_user_turn = !text.is_empty() && confidence >= 0.45;
    if speech_ms >= policy.sustained_speech_min_ms && has_user_turn {
        return barge_in_response(
            "confirmed",
            "confirmed",
            true,
            "Sustained user-directed speech passed the interruption threshold.",
            "cancel_tts_and_model_output",
        );
    }

    if tts_playing {
        return barge_in_response(
            "candidate",
            "candidate",
            false,
            "Speech was detected during TTS, but it is too short or uncertain to interrupt.",
            "collect_more_audio_before_interrupting",
        );
    }

    barge_in_response(
        "ignored_background",
        "ignored_background",
        false,
        "Voice activity did not meet interruption criteria.",
        "keep_listening",
    )
}

async fn api_realtime_barge_in_evaluate(
    Json(request): Json<RealtimeBargeInEvaluateRequest>,
) -> Json<RealtimeBargeInEvaluateResponse> {
    let policy = request.policy.clone().unwrap_or_else(|| {
        realtime_session_state()
            .lock()
            .map(|state| state.barge_in_policy.clone())
            .unwrap_or_default()
    });
    let response = evaluate_realtime_barge_in(&policy, &request);
    if let Ok(mut state) = realtime_session_state().lock() {
        state.barge_in_state = response.barge_in_state.clone();
        if response.should_interrupt {
            state.audio_out_state = "cancelled".to_string();
        }
        state.updated_at_ms = uuid_timestamp();
    }
    emit_active_realtime_session_event(
        "barge_in_decision",
        realtime_barge_in_event_payload(&response, &request),
    );
    Json(response)
}

async fn api_audio_voices() -> Json<AudioVoicesResponse> {
    let tts_config = audio_tts_config_from_workspace(None);
    let index_tts_available = audio::indextts_available(&tts_config.index_tts).await;
    Json(AudioVoicesResponse {
        backend: tts_config.backend.clone(),
        index_tts_base_url: tts_config.index_tts.base_url.clone(),
        index_tts_available,
        voices: audio::available_voices(&tts_config),
    })
}

fn register_tts_audio_file(path: &Path) -> Option<String> {
    if !path.exists() {
        return None;
    }
    let mut hasher = DefaultHasher::new();
    path.to_string_lossy().hash(&mut hasher);
    unix_timestamp_millis().hash(&mut hasher);
    let extension = path
        .extension()
        .and_then(|value| value.to_str())
        .map(|value| value.to_ascii_lowercase())
        .filter(|value| value.chars().all(|ch| ch.is_ascii_alphanumeric()))
        .unwrap_or_else(|| "wav".to_string());
    let file_id = format!(
        "tts-{}-{:016x}.{extension}",
        unix_timestamp_millis(),
        hasher.finish()
    );
    if let Ok(mut registry) = tts_audio_file_registry().lock() {
        registry.insert(file_id.clone(), path.to_path_buf());
        Some(file_id)
    } else {
        None
    }
}

fn tts_audio_url_for_file_id(file_id: &str) -> String {
    format!("/api/audio/tts/files/{file_id}")
}

fn valid_tts_audio_file_id(file_id: &str) -> bool {
    let trimmed = file_id.trim();
    trimmed == file_id
        && trimmed.starts_with("tts-")
        && trimmed.len() <= 96
        && trimmed
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' || ch == '.')
}

fn tts_segment_output_path(
    output_path: Option<&PathBuf>,
    index: usize,
    total: usize,
) -> Option<PathBuf> {
    let base = output_path?;
    if total <= 1 {
        return Some(base.clone());
    }
    let stem = base
        .file_stem()
        .and_then(|value| value.to_str())
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("tts");
    let extension = base
        .extension()
        .and_then(|value| value.to_str())
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("wav");
    let file_name = format!("{stem}.part{:03}.{extension}", index + 1);
    Some(match base.parent() {
        Some(parent) => parent.join(file_name),
        None => PathBuf::from(file_name),
    })
}

fn realtime_tts_chunks_dir() -> PathBuf {
    realtime_audio_chunks_dir().join("tts")
}

fn persist_realtime_tts_chunk(
    session_id: Option<&str>,
    mime_type: &str,
    now: u64,
    index: u64,
    bytes: &[u8],
) -> Result<PathBuf, String> {
    let dir = realtime_tts_chunks_dir();
    std::fs::create_dir_all(&dir)
        .map_err(|error| format!("Failed to create realtime TTS chunk directory: {error}"))?;
    let safe_session = realtime_audio_safe_session_id(session_id);
    let extension = realtime_audio_chunk_extension(mime_type);
    let path = dir.join(format!("{safe_session}-{now}-chunk{index:04}.{extension}"));
    std::fs::write(&path, bytes)
        .map_err(|error| format!("Failed to write realtime TTS chunk: {error}"))?;
    Ok(path)
}

async fn api_audio_tts_file(AxumPath(file_id): AxumPath<String>) -> Response<Body> {
    if !valid_tts_audio_file_id(&file_id) {
        return plain_response(StatusCode::BAD_REQUEST, "invalid tts file id");
    }
    let path = tts_audio_file_registry()
        .lock()
        .ok()
        .and_then(|registry| registry.get(&file_id).cloned());
    let Some(path) = path else {
        return plain_response(StatusCode::NOT_FOUND, "tts audio file not registered");
    };
    let Ok(bytes) = tokio::fs::read(&path).await else {
        return plain_response(StatusCode::NOT_FOUND, "tts audio file not found");
    };
    let mut response = Response::new(Body::from(bytes));
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static(content_type_for_path(&path)),
    );
    response
}

#[instrument]
async fn api_audio_tts_speak(
    Json(request): Json<TtsSpeakRequest>,
) -> Result<Json<TtsSpeakResponse>, ApiError> {
    info!(
        "TTS speak request: {} characters, voice: {:?}",
        request.text.len(),
        request.voice
    );

    if request.text.trim().is_empty() {
        return Err(api_error(StatusCode::BAD_REQUEST, "Text cannot be empty"));
    }

    let tts_config = audio_tts_config_from_workspace(request.backend.as_deref());
    let tts_backend = tts_config.backend.clone();
    let tts_source = request
        .source
        .clone()
        .unwrap_or_else(|| "manual".to_string());
    let engine = audio::TtsEngine::new(tts_config);

    let segment_max_chars = request
        .segment_max_chars
        .unwrap_or(audio::DEFAULT_TTS_MAX_SEGMENT_CHARS)
        .max(1)
        .min(audio::DEFAULT_TTS_MAX_SEGMENT_CHARS);
    let texts = if request.segment.unwrap_or(false) {
        audio::segment_text(&request.text, segment_max_chars)
            .into_iter()
            .map(|segment| segment.text)
            .collect::<Vec<_>>()
    } else {
        vec![request.text.clone()]
    };
    if texts.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "Text cannot be empty after segmentation",
        ));
    }

    let total = texts.len();
    update_active_realtime_session_states(None, Some("synthesizing"));
    emit_active_realtime_session_event(
        "tts_synthesis_started",
        json!({
            "source": tts_source.clone(),
            "voice": request.voice.clone(),
            "backend": tts_backend.clone(),
            "segment": request.segment.unwrap_or(false),
            "segment_count": total,
            "text_len": request.text.chars().count()
        }),
    );
    let mut segments = Vec::with_capacity(total);
    let mut duration_ms = 0_u64;
    for (index, text) in texts.iter().enumerate() {
        let output_path = tts_segment_output_path(request.output_path.as_ref(), index, total);
        let result = match engine
            .speak_with_voice(text, output_path.as_ref(), request.voice.as_deref())
            .await
        {
            Ok(result) => result,
            Err(error) => {
                update_active_realtime_session_states(None, Some("error"));
                emit_active_realtime_session_event(
                    "tts_synthesis_error",
                    json!({
                        "source": tts_source.clone(),
                        "voice": request.voice.clone(),
                        "backend": tts_backend.clone(),
                        "segment_index": index,
                        "segment_count": total,
                        "error": error.clone()
                    }),
                );
                return Err(api_error(StatusCode::INTERNAL_SERVER_ERROR, &error));
            }
        };
        duration_ms = duration_ms.saturating_add(result.duration_ms);
        let audio_url =
            register_tts_audio_file(&result.audio_path).map(|id| tts_audio_url_for_file_id(&id));
        segments.push(TtsSpeakSegmentResponse {
            index,
            text: text.clone(),
            audio_path: result.audio_path,
            audio_url,
            duration_ms: result.duration_ms,
        });
    }

    let mut played = false;
    if request.auto_play.unwrap_or(true) {
        update_active_realtime_session_states(None, Some("speaking"));
        emit_active_realtime_session_event(
            "tts_playback_started",
            json!({
                "source": tts_source.clone(),
                "backend": "server",
                "segment_count": total
            }),
        );
        played = true;
        for segment in &segments {
            if audio::play_audio_file(&segment.audio_path, None)
                .await
                .map_err(|e| {
                    warn!("Audio playback failed: {}", e);
                })
                .is_err()
            {
                played = false;
                break;
            }
        }
        update_active_realtime_session_states(None, Some("idle"));
        emit_active_realtime_session_event(
            "tts_playback_ended",
            json!({
                "source": tts_source.clone(),
                "backend": "server",
                "segment_count": total,
                "played": played
            }),
        );
    } else {
        update_active_realtime_session_states(None, Some("ready"));
    }

    info!(
        "TTS synthesis completed in {}ms across {} segment(s), played: {}",
        duration_ms, total, played
    );

    let audio_path = segments
        .first()
        .map(|segment| segment.audio_path.clone())
        .unwrap_or_default();
    let audio_url = segments
        .first()
        .and_then(|segment| segment.audio_url.clone());
    let audio_urls = segments
        .iter()
        .filter_map(|segment| segment.audio_url.clone())
        .collect::<Vec<_>>();
    emit_active_realtime_session_event(
        "tts_synthesis_ready",
        json!({
            "source": tts_source,
            "voice": request.voice.clone(),
            "backend": tts_backend,
            "segment_count": total,
            "duration_ms": duration_ms,
            "audio_url_count": audio_urls.len(),
            "auto_play": request.auto_play.unwrap_or(true),
            "played": played
        }),
    );
    Ok(Json(TtsSpeakResponse {
        audio_path,
        audio_url,
        audio_urls,
        segments,
        duration_ms,
        played,
    }))
}

async fn api_audio_tts_chunk(
    Json(request): Json<TtsChunkRequest>,
) -> Result<Json<TtsChunkResponse>, ApiError> {
    let now = uuid_timestamp();
    let active_session_id = realtime_session_state()
        .lock()
        .ok()
        .and_then(|state| {
            if state.running {
                state.session_id.clone()
            } else {
                None
            }
        })
        .ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "Realtime session is not running"))?;

    if let Some(request_session_id) = request
        .session_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        if request_session_id != active_session_id {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "TTS chunk session_id does not match the active realtime session",
            ));
        }
    }

    let source = request
        .source
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "streaming_tts".to_string());
    let backend = request
        .backend
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "streaming_tts_bridge".to_string());
    let mime_type = request
        .mime_type
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "audio/wav".to_string());
    let index = request.index.unwrap_or(1);
    let final_chunk = request.final_chunk.unwrap_or(false);
    let decoded_audio = decode_realtime_audio_base64(request.audio_base64.as_deref())
        .map_err(|error| api_error(StatusCode::BAD_REQUEST, &error))?;

    let mut audio_path = None;
    let mut bytes = 0_u64;
    let mut audio_url = request
        .audio_url
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());

    if let Some(payload) = decoded_audio.as_deref() {
        if payload.is_empty() {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "TTS chunk audio payload is empty",
            ));
        }
        bytes = payload.len() as u64;
        let path =
            persist_realtime_tts_chunk(Some(&active_session_id), &mime_type, now, index, payload)
                .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
        audio_path = Some(path.to_string_lossy().to_string());
        if audio_url.is_none() {
            audio_url = register_tts_audio_file(&path).map(|id| tts_audio_url_for_file_id(&id));
        }
    }

    if audio_url.is_none() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "TTS chunk requires audio_base64 or audio_url",
        ));
    }

    let payload = json!({
        "source": source.clone(),
        "backend": backend.clone(),
        "voice": request.voice.clone(),
        "mime_type": mime_type,
        "index": index,
        "total": request.total,
        "duration_ms": request.duration_ms,
        "final_chunk": final_chunk,
        "bytes": bytes,
        "chunk_bytes": bytes,
        "audio_path": audio_path.clone(),
        "audio_url": audio_url.clone()
    });
    emit_realtime_session_event_for("tts_chunk", &active_session_id, payload);

    Ok(Json(TtsChunkResponse {
        ok: true,
        session_id: Some(active_session_id),
        source,
        backend,
        audio_payload_received: decoded_audio.is_some(),
        bytes,
        audio_path,
        audio_url,
        index,
        total: request.total,
        duration_ms: request.duration_ms,
        final_chunk,
        updated_at_ms: now,
    }))
}

fn emit_realtime_tts_chunk_from_bytes(
    active_session_id: &str,
    turn_id: Option<&str>,
    generation_id: Option<u64>,
    segment_index: Option<u64>,
    source: &str,
    backend: &str,
    voice: Option<&str>,
    mime_type: &str,
    now: u64,
    index: u64,
    chunk_count: Option<u64>,
    final_chunk: bool,
    bytes: &[u8],
) -> Result<String, ApiError> {
    if bytes.is_empty() {
        return Err(api_error(
            StatusCode::BAD_GATEWAY,
            "TTS stream chunk is empty",
        ));
    }
    let path = persist_realtime_tts_chunk(Some(active_session_id), mime_type, now, index, bytes)
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
    let audio_url = register_tts_audio_file(&path)
        .map(|id| tts_audio_url_for_file_id(&id))
        .ok_or_else(|| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Failed to register streamed TTS audio chunk",
            )
        })?;
    let chunk_bytes = bytes.len() as u64;
    emit_realtime_session_event_for(
        "tts_chunk",
        active_session_id,
        json!({
            "source": source,
            "backend": backend,
            "turn_id": turn_id,
            "generation_id": generation_id,
            "segment_index": segment_index,
            "voice": voice,
            "mime_type": mime_type,
            "index": index,
            "total": chunk_count,
            "chunk_count": chunk_count,
            "duration_ms": null,
            "final_chunk": final_chunk,
            "bytes": chunk_bytes,
            "chunk_bytes": chunk_bytes,
            "audio_path": path.to_string_lossy().to_string(),
            "audio_url": audio_url
        }),
    );
    Ok(audio_url)
}

async fn api_audio_tts_stream(
    Json(request): Json<TtsStreamRequest>,
) -> Result<Json<TtsStreamResponse>, ApiError> {
    let started = Instant::now();
    let now = uuid_timestamp();
    let active_session_id = realtime_session_state()
        .lock()
        .ok()
        .and_then(|state| {
            if state.running {
                state.session_id.clone()
            } else {
                None
            }
        })
        .ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "Realtime session is not running"))?;

    if let Some(request_session_id) = request
        .session_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        if request_session_id != active_session_id {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "TTS stream session_id does not match the active realtime session",
            ));
        }
    }

    if request.text.trim().is_empty() {
        return Err(api_error(StatusCode::BAD_REQUEST, "Text cannot be empty"));
    }

    let realtime_config = read_config(|workspace| workspace.audio.realtime.clone());
    let upstream_url =
        streaming_tts_url_from_request_or_config(request.upstream_url.as_deref(), &realtime_config)
            .ok_or_else(|| {
                api_error(
                    StatusCode::BAD_REQUEST,
                    "TTS stream requires upstream_url or audio.realtime.streaming_tts_url",
                )
            })?;
    let source = request
        .source
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "streaming_tts".to_string());
    let backend = request
        .backend
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "http_streaming_tts".to_string());
    let requested_mime_type = request
        .mime_type
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());

    update_realtime_session_states_for(&active_session_id, None, Some("synthesizing"));
    emit_realtime_session_event_for(
        "tts_stream_started",
        &active_session_id,
        json!({
            "source": source.clone(),
            "backend": backend.clone(),
            "voice": request.voice.clone(),
            "upstream_url": upstream_url.clone(),
            "text_len": request.text.chars().count()
        }),
    );

    let timeout_seconds = realtime_config.streaming_tts_timeout_seconds.max(1);
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .build()
        .map_err(|error| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                &format!("Failed to create streaming TTS HTTP client: {error}"),
            )
        })?;
    let mut upstream_response = client
        .post(&upstream_url)
        .json(&json!({
            "text": request.text.clone(),
            "voice": request.voice.clone(),
            "session_id": active_session_id.clone(),
            "source": source.clone(),
            "backend": backend.clone(),
            "mime_type": requested_mime_type.clone()
        }))
        .send()
        .await
        .map_err(|error| {
            update_realtime_session_states_for(&active_session_id, None, Some("error"));
            emit_realtime_session_event_for(
                "tts_stream_error",
                &active_session_id,
                json!({
                    "source": source.clone(),
                    "backend": backend.clone(),
                    "upstream_url": upstream_url.clone(),
                    "error": error.to_string()
                }),
            );
            api_error(
                StatusCode::BAD_GATEWAY,
                &format!("Streaming TTS upstream request failed: {error}"),
            )
        })?;

    if !upstream_response.status().is_success() {
        let status = upstream_response.status();
        let error_body = upstream_response
            .text()
            .await
            .unwrap_or_default()
            .chars()
            .take(256)
            .collect::<String>();
        update_realtime_session_states_for(&active_session_id, None, Some("error"));
        emit_realtime_session_event_for(
            "tts_stream_error",
            &active_session_id,
            json!({
                "source": source.clone(),
                "backend": backend.clone(),
                "upstream_url": upstream_url.clone(),
                "status": status.as_u16(),
                "error": error_body.clone()
            }),
        );
        return Err(api_error(
            StatusCode::BAD_GATEWAY,
            &format!("Streaming TTS upstream returned {status}: {error_body}"),
        ));
    }

    let upstream_mime_type = upstream_response
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);
    let mime_type = requested_mime_type
        .or(upstream_mime_type)
        .unwrap_or_else(|| "audio/wav".to_string());

    // reqwest::Response::chunk() 返回的是 HTTP 传输分块，并不保证落在音频帧或文件边界。
    // 当前接口由上层按句调用，因此单次上游响应必须聚合为一个完整、可播放的音频单元。
    let mut complete_audio = Vec::new();

    loop {
        let next = upstream_response.chunk().await.map_err(|error| {
            update_realtime_session_states_for(&active_session_id, None, Some("error"));
            emit_realtime_session_event_for(
                "tts_stream_error",
                &active_session_id,
                json!({
                    "source": source.clone(),
                    "backend": backend.clone(),
                    "upstream_url": upstream_url.clone(),
                    "error": error.to_string()
                }),
            );
            api_error(
                StatusCode::BAD_GATEWAY,
                &format!("Streaming TTS upstream chunk read failed: {error}"),
            )
        })?;
        let Some(bytes) = next else {
            break;
        };
        if bytes.is_empty() {
            continue;
        }
        let exceeds_size_limit = complete_audio
            .len()
            .checked_add(bytes.len())
            .map(|total| total > MAX_TTS_STREAM_RESPONSE_BYTES)
            .unwrap_or(true);
        if exceeds_size_limit {
            let received_bytes = (complete_audio.len() as u64).saturating_add(bytes.len() as u64);
            update_realtime_session_states_for(&active_session_id, None, Some("error"));
            emit_realtime_session_event_for(
                "tts_stream_error",
                &active_session_id,
                json!({
                    "source": source.clone(),
                    "backend": backend.clone(),
                    "upstream_url": upstream_url.clone(),
                    "received_bytes": received_bytes,
                    "max_bytes": MAX_TTS_STREAM_RESPONSE_BYTES,
                    "error": "upstream audio response exceeded the size limit"
                }),
            );
            return Err(api_error(
                StatusCode::BAD_GATEWAY,
                &format!(
                    "Streaming TTS upstream audio exceeds {} bytes",
                    MAX_TTS_STREAM_RESPONSE_BYTES
                ),
            ));
        }
        complete_audio.extend_from_slice(&bytes);
    }

    if complete_audio.is_empty() {
        update_realtime_session_states_for(&active_session_id, None, Some("error"));
        emit_realtime_session_event_for(
            "tts_stream_error",
            &active_session_id,
            json!({
                "source": source.clone(),
                "backend": backend.clone(),
                "upstream_url": upstream_url.clone(),
                "error": "upstream returned no audio chunks"
            }),
        );
        return Err(api_error(
            StatusCode::BAD_GATEWAY,
            "Streaming TTS upstream returned no audio bytes",
        ));
    }

    let total_bytes = complete_audio.len() as u64;
    let final_url = emit_realtime_tts_chunk_from_bytes(
        &active_session_id,
        request.turn_id.as_deref(),
        request.generation_id,
        request.segment_index,
        &source,
        &backend,
        request.voice.as_deref(),
        &mime_type,
        now,
        1,
        Some(1),
        true,
        &complete_audio,
    )?;
    let audio_urls = vec![final_url];
    let chunk_count = 1_u64;

    emit_realtime_session_event_for(
        "tts_stream_ended",
        &active_session_id,
        json!({
            "source": source.clone(),
            "backend": backend.clone(),
            "turn_id": request.turn_id.clone(),
            "generation_id": request.generation_id,
            "segment_index": request.segment_index,
            "upstream_url": upstream_url.clone(),
            "mime_type": mime_type.clone(),
            "chunk_count": chunk_count,
            "bytes": total_bytes,
            "duration_ms": elapsed_millis(started)
        }),
    );

    Ok(Json(TtsStreamResponse {
        ok: true,
        session_id: Some(active_session_id),
        turn_id: request.turn_id,
        generation_id: request.generation_id,
        segment_index: request.segment_index,
        source,
        backend,
        upstream_url,
        mime_type,
        chunk_count,
        bytes: total_bytes,
        audio_urls,
        duration_ms: elapsed_millis(started),
        updated_at_ms: uuid_timestamp(),
    }))
}

async fn api_audio_tts_stream_probe(
    Json(request): Json<TtsStreamProbeRequest>,
) -> Json<TtsStreamProbeResponse> {
    let started = Instant::now();
    let realtime_config = read_config(|workspace| workspace.audio.realtime.clone());
    let source = request
        .source
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "streaming_tts_probe".to_string());
    let backend = request
        .backend
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "http_streaming_tts".to_string());
    let Some(upstream_url) =
        streaming_tts_url_from_request_or_config(request.upstream_url.as_deref(), &realtime_config)
    else {
        return Json(TtsStreamProbeResponse {
            configured: false,
            reachable: false,
            chunk_received: false,
            upstream_url: None,
            source,
            backend,
            mime_type: request.mime_type.clone(),
            bytes: 0,
            status: None,
            duration_ms: elapsed_millis(started),
            error: Some(
                "TTS stream probe requires upstream_url or audio.realtime.streaming_tts_url"
                    .to_string(),
            ),
        });
    };

    let timeout_seconds = realtime_config.streaming_tts_timeout_seconds.max(1);
    let client = match reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .build()
    {
        Ok(client) => client,
        Err(error) => {
            return Json(TtsStreamProbeResponse {
                configured: true,
                reachable: false,
                chunk_received: false,
                upstream_url: Some(upstream_url),
                source,
                backend,
                mime_type: request.mime_type.clone(),
                bytes: 0,
                status: None,
                duration_ms: elapsed_millis(started),
                error: Some(format!(
                    "Failed to create streaming TTS HTTP client: {error}"
                )),
            });
        }
    };

    let probe_text = request
        .text
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "streaming tts probe".to_string());
    let requested_mime_type = request
        .mime_type
        .clone()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let response = client
        .post(&upstream_url)
        .json(&json!({
            "text": probe_text,
            "voice": request.voice.clone(),
            "source": source.clone(),
            "backend": backend.clone(),
            "mime_type": requested_mime_type.clone()
        }))
        .send()
        .await;
    let mut response = match response {
        Ok(response) => response,
        Err(error) => {
            return Json(TtsStreamProbeResponse {
                configured: true,
                reachable: false,
                chunk_received: false,
                upstream_url: Some(upstream_url),
                source,
                backend,
                mime_type: requested_mime_type,
                bytes: 0,
                status: None,
                duration_ms: elapsed_millis(started),
                error: Some(format!("Streaming TTS probe request failed: {error}")),
            });
        }
    };

    let status = response.status();
    let upstream_mime_type = response
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);
    let mime_type = requested_mime_type.or(upstream_mime_type);
    if !status.is_success() {
        let body = response
            .text()
            .await
            .unwrap_or_default()
            .chars()
            .take(256)
            .collect::<String>();
        return Json(TtsStreamProbeResponse {
            configured: true,
            reachable: false,
            chunk_received: false,
            upstream_url: Some(upstream_url),
            source,
            backend,
            mime_type,
            bytes: 0,
            status: Some(status.as_u16()),
            duration_ms: elapsed_millis(started),
            error: Some(format!("Streaming TTS probe returned {status}: {body}")),
        });
    }

    loop {
        match response.chunk().await {
            Ok(Some(bytes)) if bytes.is_empty() => continue,
            Ok(Some(bytes)) => {
                return Json(TtsStreamProbeResponse {
                    configured: true,
                    reachable: true,
                    chunk_received: true,
                    upstream_url: Some(upstream_url),
                    source,
                    backend,
                    mime_type,
                    bytes: bytes.len() as u64,
                    status: Some(status.as_u16()),
                    duration_ms: elapsed_millis(started),
                    error: None,
                });
            }
            Ok(None) => {
                return Json(TtsStreamProbeResponse {
                    configured: true,
                    reachable: true,
                    chunk_received: false,
                    upstream_url: Some(upstream_url),
                    source,
                    backend,
                    mime_type,
                    bytes: 0,
                    status: Some(status.as_u16()),
                    duration_ms: elapsed_millis(started),
                    error: Some("Streaming TTS probe returned no audio chunks".to_string()),
                });
            }
            Err(error) => {
                return Json(TtsStreamProbeResponse {
                    configured: true,
                    reachable: true,
                    chunk_received: false,
                    upstream_url: Some(upstream_url),
                    source,
                    backend,
                    mime_type,
                    bytes: 0,
                    status: Some(status.as_u16()),
                    duration_ms: elapsed_millis(started),
                    error: Some(format!("Streaming TTS probe chunk read failed: {error}")),
                });
            }
        }
    }
}

#[instrument]
async fn api_audio_status() -> Json<audio::AudioStatus> {
    info!("Checking audio status");

    let stt_config = audio::SttConfig::default();
    let tts_config = audio_tts_config_from_workspace(None);

    let mut status = audio::check_audio_status(&stt_config, &tts_config).await;
    status.active_sessions = 0;
    let monitor = voice_monitor_status();
    status.voice_monitor_available = monitor.available;
    status.voice_monitor_running = monitor.running;
    status.voice_monitor_mode = monitor.mode;
    status.voice_monitor_message = monitor.message;

    Json(status)
}

