async fn api_computer_use_browser_response(
    headers: HeaderMap,
    Json(response): Json<browser_bridge_protocol::BridgeResponse>,
) -> (StatusCode, Json<browser_bridge::BrowserBridgeResponseAck>) {
    let reply_token = headers
        .get("x-coolzhu-browser-reply-token")
        .and_then(|value| value.to_str().ok())
        .unwrap_or_default();
    let ack = browser_bridge::complete_http_response(reply_token, response);
    let status = if ack.accepted {
        StatusCode::OK
    } else {
        StatusCode::UNAUTHORIZED
    };
    (status, Json(ack))
}

async fn api_audio_realtime_segment(
    Json(request): Json<AudioRealtimeSegmentRequest>,
) -> Json<AudioRealtimeSegmentResponse> {
    let now = uuid_timestamp();
    let mime_type = request.mime_type.clone().unwrap_or_default();
    let duration_ms = request.duration_ms.unwrap_or(0);
    let final_segment = request.final_segment.unwrap_or(false);
    let decoded_audio = decode_realtime_audio_base64(request.audio_base64.as_deref());
    let (audio_payload, payload_error) = match decoded_audio {
        Ok(payload) => (payload, None),
        Err(error) => (None, Some(error)),
    };
    let persisted_audio = audio_payload.as_deref().and_then(|payload| {
        match persist_realtime_audio_chunk(request.session_id.as_deref(), &mime_type, now, payload)
        {
            Ok(path) => Some((payload.len() as u64, path.to_string_lossy().to_string())),
            Err(error) => Some((0, format!("error:{error}"))),
        }
    });
    let persisted_error = persisted_audio
        .as_ref()
        .and_then(|(_, path)| path.strip_prefix("error:").map(|error| error.to_string()));
    let payload_path =
        persisted_audio
            .as_ref()
            .and_then(|(bytes, path)| if *bytes > 0 { Some(path.clone()) } else { None });
    let payload_bytes = persisted_audio
        .as_ref()
        .map(|(bytes, _)| *bytes)
        .unwrap_or(0);
    let bytes = if payload_bytes > 0 {
        payload_bytes
    } else {
        request.bytes.unwrap_or(0)
    };
    let segment_error = payload_error.or(persisted_error);
    let payload_path_for_asr = payload_path.clone();
    let mut response = AudioRealtimeSegmentResponse {
        running: false,
        session_id: request.session_id.clone(),
        audio_segments_received: 0,
        audio_bytes_received: 0,
        audio_payload_received: payload_bytes > 0,
        audio_payload_bytes: payload_bytes,
        audio_payload_chunks_received: 0,
        last_audio_chunk_path: payload_path.clone(),
        active_stt_transport: "segmented_mediarecorder".to_string(),
        asr_attempted: false,
        asr_transcript_received: false,
        asr_text: None,
        asr_confidence: None,
        asr_provider: None,
        asr_error: None,
        asr_duration_ms: None,
        updated_at_ms: now,
    };
    if let Ok(mut state) = audio_realtime_state().lock() {
        if state.running {
            state.audio_segments_received = state.audio_segments_received.saturating_add(1);
            state.audio_bytes_received = state.audio_bytes_received.saturating_add(bytes);
            if payload_bytes > 0 {
                state.audio_payload_chunks_received =
                    state.audio_payload_chunks_received.saturating_add(1);
                state.last_audio_payload_bytes = payload_bytes;
                state.last_audio_chunk_path = payload_path.clone();
            }
            state.active_stt_transport = "segmented_mediarecorder".to_string();
            if let Some(error) = segment_error.clone() {
                state.last_error = Some(error);
            }
            state.updated_at_ms = now;
        }
        response.running = state.running;
        response.session_id = state.session_id.clone().or(request.session_id.clone());
        response.audio_segments_received = state.audio_segments_received;
        response.audio_bytes_received = state.audio_bytes_received;
        response.audio_payload_chunks_received = state.audio_payload_chunks_received;
        response.last_audio_chunk_path = state.last_audio_chunk_path.clone().or(payload_path);
        response.active_stt_transport = if state.active_stt_transport.trim().is_empty() {
            "segmented_mediarecorder".to_string()
        } else {
            state.active_stt_transport.clone()
        };
        response.updated_at_ms = state.updated_at_ms;
    }
    if let Ok(mut realtime) = realtime_session_state().lock() {
        if realtime.running {
            realtime.audio_segments_received = response.audio_segments_received;
            realtime.audio_bytes_received = response.audio_bytes_received;
            realtime.audio_payload_chunks_received = response.audio_payload_chunks_received;
            realtime.last_audio_payload_bytes = response.audio_payload_bytes;
            realtime.last_audio_chunk_path = response.last_audio_chunk_path.clone();
            realtime.active_stt_transport = response.active_stt_transport.clone();
            realtime.updated_at_ms = now;
        }
    }
    emit_realtime_session_event(
        "audio_segment",
        response.session_id.clone(),
        json!({
            "bytes": response.audio_payload_bytes,
            "duration_ms": duration_ms,
            "final_segment": final_segment,
            "active_stt_transport": response.active_stt_transport.clone(),
            "audio_segments_received": response.audio_segments_received,
            "audio_bytes_received": response.audio_bytes_received,
            "audio_payload_chunks_received": response.audio_payload_chunks_received,
            "last_audio_chunk_path": response.last_audio_chunk_path.clone()
        }),
    );
    let asr_mode = read_config(|workspace| realtime_segment_asr_mode(&workspace.audio.realtime));
    let asr_outcome = transcribe_realtime_final_audio_segment(
        response
            .last_audio_chunk_path
            .as_deref()
            .or(payload_path_for_asr.as_deref()),
        final_segment,
        &asr_mode,
    )
    .await;
    if asr_outcome.attempted {
        response.asr_attempted = true;
        response.asr_transcript_received = asr_outcome.transcript_received;
        response.asr_text = asr_outcome.text.clone();
        response.asr_confidence = asr_outcome.confidence;
        response.asr_provider = asr_outcome.provider.clone();
        response.asr_error = asr_outcome.error.clone();
        response.asr_duration_ms = asr_outcome.duration_ms;

        if let Some(error) = asr_outcome.error.as_deref() {
            record_audio_realtime_error(error, uuid_timestamp());
        }
        if asr_outcome.transcript_received {
            let axum::Json(partial) =
                api_audio_realtime_partial(Json(AudioRealtimePartialRequest {
                    session_id: response.session_id.clone(),
                    text: asr_outcome.text.clone(),
                    confidence: asr_outcome.confidence,
                    is_final: Some(true),
                    provider: asr_outcome.provider.clone(),
                    language: None,
                    speech_ms: Some(duration_ms),
                    tts_playing: Some(false),
                    echo_correlation: None,
                    vad_active: Some(true),
                }))
                .await;
            response.updated_at_ms = partial.updated_at_ms;
            if let Ok(mut state) = audio_realtime_state().lock() {
                if state.running {
                    state.last_text = asr_outcome.text.clone();
                    state.last_error = None;
                    state.updated_at_ms = partial.updated_at_ms;
                }
            }
        }
    }
    Json(response)
}

#[derive(Debug, Default, Deserialize)]
struct AudioRealtimeAecReferenceRequest {
    #[serde(default)]
    session_id: Option<String>,
    /// 远端参考 tap 是否活跃（TTS 播放中前端 WebAudio 参考链路在工作）。
    #[serde(default)]
    reference_active: Option<bool>,
    /// 参考信号与麦克风的相关性 / 参考能量估计（0-1）。
    #[serde(default)]
    correlation: Option<f32>,
    #[serde(default)]
    source: Option<String>,
    #[serde(default)]
    generation_id: Option<u64>,
    #[serde(default)]
    sample_count: Option<u64>,
    #[serde(default)]
    browser_echo_cancellation: Option<bool>,
}

#[derive(Debug, Serialize)]
struct AudioRealtimeAecReferenceResponse {
    running: bool,
    far_end_reference_aec_ready: bool,
    aec_mode: String,
}

/// 远端参考 AEC 运行时证据上报（P2 gate `far_end_reference_aec`）：
/// 前端在 TTS 播放期间把播放音频接 WebAudio 参考 tap 并周期上报。只有当前会话、
/// 单调递增的播放 generation、真实参考样本以及浏览器确认启用 echoCancellation 同时存在，
/// 才能把远端参考链路标为 ready；能量/相关性估计仅用于打断抑制，不能单独满足 AEC gate。
async fn api_audio_realtime_aec_reference(
    Json(request): Json<AudioRealtimeAecReferenceRequest>,
) -> Json<AudioRealtimeAecReferenceResponse> {
    let now = uuid_timestamp();
    let reference_active = request.reference_active.unwrap_or(true);
    let correlation = request.correlation.map(|value| value.clamp(0.0, 1.0));
    let source = request
        .source
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("webaudio_far_end_reference")
        .chars()
        .take(64)
        .collect::<String>();
    let generation_id = request.generation_id;
    let sample_count = request.sample_count.unwrap_or(0);
    let browser_echo_cancellation = request.browser_echo_cancellation.unwrap_or(false);
    let mut running = false;
    let mut ready = false;
    let mut aec_mode = String::new();
    let mut session_id_for_event = None;
    if let Ok(mut state) = realtime_session_state().lock() {
        if state.running {
            running = true;
            session_id_for_event = state.session_id.clone();
            let session_matches = request.session_id.as_deref() == state.session_id.as_deref();
            let generation_is_current = generation_id.is_some_and(|generation| {
                state
                    .last_aec_generation_id
                    .is_none_or(|last_generation| generation >= last_generation)
            });
            let validated_reference = reference_active
                && session_matches
                && generation_is_current
                && sample_count >= 128
                && browser_echo_cancellation
                && source == "webaudio_far_end_reference_pcm";
            if validated_reference {
                state.far_end_reference_aec_ready = true;
                state.last_aec_reference_event_ms = Some(now);
                state.last_aec_generation_id = generation_id;
                state.aec_mode = REALTIME_AEC_FAR_END_REFERENCE.to_string();
            }
            state.updated_at_ms = now;
            ready = state.far_end_reference_aec_ready;
            aec_mode = state.aec_mode.clone();
        }
    }
    if running {
        emit_realtime_session_event(
            "aec_reference",
            session_id_for_event,
            json!({
                "reference_active": reference_active,
                "correlation": correlation,
                "source": source,
                "generation_id": generation_id,
                "sample_count": sample_count,
                "browser_echo_cancellation": browser_echo_cancellation,
                "validated_reference": ready,
            }),
        );
    }
    Json(AudioRealtimeAecReferenceResponse {
        running,
        far_end_reference_aec_ready: ready,
        aec_mode,
    })
}

async fn api_audio_realtime_partial(
    Json(request): Json<AudioRealtimePartialRequest>,
) -> Json<AudioRealtimePartialResponse> {
    let now = uuid_timestamp();
    let text = request
        .text
        .unwrap_or_default()
        .trim()
        .chars()
        .take(512)
        .collect::<String>();
    let confidence = request.confidence.map(|value| value.clamp(0.0, 1.0));
    let is_final = request.is_final.unwrap_or(false);
    let provider = request
        .provider
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("browser_speech_recognition")
        .chars()
        .take(64)
        .collect::<String>();
    let active_stt_transport = realtime_stt_transport_for_partial_provider(&provider);
    let _language = request.language.unwrap_or_default();
    let mut barge_in = barge_in_response(
        "quiet",
        "quiet",
        false,
        "No realtime partial ASR text was evaluated.",
        "continue_listening",
    );
    let mut barge_in_event_payload = None;
    let mut response = AudioRealtimePartialResponse {
        running: false,
        session_id: request.session_id.clone(),
        partial_transcripts_received: 0,
        last_partial_text: None,
        last_partial_confidence: None,
        last_partial_is_final: false,
        partial_asr_provider: provider.clone(),
        barge_in_decision: barge_in.decision.clone(),
        barge_in_state: barge_in.barge_in_state.clone(),
        should_interrupt: barge_in.should_interrupt,
        barge_in_reason: barge_in.reason.clone(),
        barge_in_recommended_action: barge_in.recommended_action.clone(),
        updated_at_ms: now,
    };
    if let Ok(mut state) = audio_realtime_state().lock() {
        if state.running && !text.is_empty() {
            state.partial_transcripts_received =
                state.partial_transcripts_received.saturating_add(1);
            state.last_partial_text = Some(text.clone());
            state.last_partial_confidence = confidence;
            state.last_partial_is_final = is_final;
            state.partial_asr_provider = provider.clone();
            state.active_stt_transport = active_stt_transport.clone();
            state.updated_at_ms = now;
        }
        response.running = state.running;
        response.session_id = state.session_id.clone().or(request.session_id.clone());
        response.partial_transcripts_received = state.partial_transcripts_received;
        response.last_partial_text = state.last_partial_text.clone();
        response.last_partial_confidence = state.last_partial_confidence;
        response.last_partial_is_final = state.last_partial_is_final;
        response.partial_asr_provider = if state.partial_asr_provider.trim().is_empty() {
            provider.clone()
        } else {
            state.partial_asr_provider.clone()
        };
        response.updated_at_ms = state.updated_at_ms;
    }
    if let Ok(mut realtime) = realtime_session_state().lock() {
        if realtime.running {
            realtime.partial_transcripts_received = response.partial_transcripts_received;
            realtime.last_partial_text = response.last_partial_text.clone();
            realtime.last_partial_confidence = response.last_partial_confidence;
            realtime.last_partial_is_final = response.last_partial_is_final;
            realtime.partial_asr_provider = response.partial_asr_provider.clone();
            if response.running && !text.is_empty() {
                realtime.active_stt_transport = active_stt_transport.clone();
                let policy = realtime.barge_in_policy.clone();
                let barge_request = RealtimeBargeInEvaluateRequest {
                    policy: Some(policy.clone()),
                    tts_playing: Some(
                        request
                            .tts_playing
                            .unwrap_or_else(|| realtime.audio_out_state == "speaking"),
                    ),
                    vad_active: Some(request.vad_active.unwrap_or(true)),
                    speech_ms: request.speech_ms,
                    asr_text: response.last_partial_text.clone(),
                    asr_confidence: response.last_partial_confidence,
                    echo_correlation: request.echo_correlation,
                    manual_interrupt: None,
                };
                barge_in = evaluate_realtime_barge_in(&policy, &barge_request);
                realtime.barge_in_state = barge_in.barge_in_state.clone();
                if barge_in.should_interrupt {
                    realtime.audio_out_state = "cancelled".to_string();
                    barge_in_event_payload =
                        Some(realtime_barge_in_event_payload(&barge_in, &barge_request));
                }
                response.barge_in_decision = barge_in.decision.clone();
                response.barge_in_state = barge_in.barge_in_state.clone();
                response.should_interrupt = barge_in.should_interrupt;
                response.barge_in_reason = barge_in.reason.clone();
                response.barge_in_recommended_action = barge_in.recommended_action.clone();
            }
            realtime.updated_at_ms = now;
        }
    }
    if !text.is_empty() {
        emit_realtime_session_event(
            if is_final {
                "final_transcript"
            } else {
                "partial_transcript"
            },
            response.session_id.clone(),
            json!({
                "text": response.last_partial_text.clone(),
                "confidence": response.last_partial_confidence,
                "is_final": response.last_partial_is_final,
                "provider": response.partial_asr_provider.clone(),
                "active_stt_transport": active_stt_transport,
                "barge_in_decision": response.barge_in_decision.clone(),
                "barge_in_state": response.barge_in_state.clone(),
                "should_interrupt": response.should_interrupt,
                "recommended_action": response.barge_in_recommended_action.clone()
            }),
        );
    }
    if let Some(payload) = barge_in_event_payload {
        emit_active_realtime_session_event("barge_in_decision", payload);
    }
    Json(response)
}

async fn api_audio_realtime_start(
    Json(request): Json<AudioRealtimeToggleRequest>,
) -> Json<AudioRealtimeStatusResponse> {
    let config = read_config(|workspace| workspace.audio.realtime.clone());
    let now = uuid_timestamp();
    let active_stt_transport = first_realtime_capability(
        &[
            request.stt_transport.as_deref().unwrap_or_default(),
            config.stt_transport.as_str(),
        ],
        REALTIME_STT_SEGMENTED_MEDIARECORDER,
    );
    if let Ok(mut state) = audio_realtime_state().lock() {
        state.running = true;
        state.session_id = Some(format!("audio-rt-{now}"));
        state.started_at_ms = Some(now);
        state.stopped_at_ms = None;
        state.updated_at_ms = now;
        state.audio_segments_received = 0;
        state.audio_bytes_received = 0;
        state.audio_payload_chunks_received = 0;
        state.last_audio_payload_bytes = 0;
        state.last_audio_chunk_path = None;
        state.active_stt_transport = active_stt_transport.clone();
        state.partial_transcripts_received = 0;
        state.last_partial_text = None;
        state.last_partial_confidence = None;
        state.last_partial_is_final = false;
        state.partial_asr_provider = "none".to_string();
        state.last_error = None;
        state.last_text = None;
        state.auto_send_transcript = request
            .auto_send_transcript
            .unwrap_or(config.auto_send_transcript);
        state.auto_tts_reply = request.auto_tts_reply.unwrap_or(config.auto_tts_reply);
    }
    if let Ok(mut realtime) = realtime_session_state().lock() {
        if realtime.running {
            realtime.audio_in_state = "listening".to_string();
            realtime.audio_segments_received = 0;
            realtime.audio_bytes_received = 0;
            realtime.audio_payload_chunks_received = 0;
            realtime.last_audio_payload_bytes = 0;
            realtime.last_audio_chunk_path = None;
            realtime.active_stt_transport = active_stt_transport.clone();
            realtime.partial_transcripts_received = 0;
            realtime.last_partial_text = None;
            realtime.last_partial_confidence = None;
            realtime.last_partial_is_final = false;
            realtime.partial_asr_provider = "none".to_string();
            realtime.updated_at_ms = now;
        }
    }
    Json(audio_realtime_status_response().await)
}

async fn api_audio_realtime_stop() -> Json<AudioRealtimeStatusResponse> {
    let now = uuid_timestamp();
    if let Ok(mut state) = audio_realtime_state().lock() {
        state.running = false;
        state.stopped_at_ms = Some(now);
        state.updated_at_ms = now;
    }
    if let Ok(mut realtime) = realtime_session_state().lock() {
        if realtime.running {
            realtime.audio_in_state = "off".to_string();
            realtime.updated_at_ms = now;
        }
    }
    Json(audio_realtime_status_response().await)
}

async fn api_voice_monitor_status() -> Json<VoiceMonitorStatus> {
    Json(voice_monitor_status())
}

async fn api_voice_monitor_toggle(
    Json(request): Json<VoiceMonitorToggleRequest>,
) -> Json<VoiceMonitorStatus> {
    let next = request
        .enable
        .unwrap_or_else(|| !VOICE_MONITOR_RUNNING.load(Ordering::Relaxed));
    VOICE_MONITOR_RUNNING.store(next, Ordering::Relaxed);
    Json(voice_monitor_status())
}

fn voice_monitor_status() -> VoiceMonitorStatus {
    let running = VOICE_MONITOR_RUNNING.load(Ordering::Relaxed);
    let wake_script_exists = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tools/voice_wake.py")
        .exists();
    let available = cfg!(windows) || wake_script_exists;
    let mode = if wake_script_exists {
        "wake-script-planned"
    } else {
        "dry-run"
    };
    let message = if running {
        if wake_script_exists {
            "监听开关已开启，真实唤醒脚本需交互验证后接"
        } else {
            "监听开关已开启，当前仅记录 UI 状态"
        }
    } else if wake_script_exists {
        "待开启；opencode voice_wake.py 可作为后续交互实现参"
    } else {
        "待开启；当前仅支持状态桥"
    };

    VoiceMonitorStatus {
        available,
        running,
        mode: mode.to_string(),
        message: message.to_string(),
        backend: if wake_script_exists {
            "voice_wake.py".to_string()
        } else {
            "none".to_string()
        },
        requires_interactive_test: true,
    }
}

fn uuid_timestamp() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64
}

