    #[test]
    fn tools_catalog_exposes_core_plugins_skills_and_safe_actions() {
        let catalog = build_tools_catalog();
        let category_ids = catalog
            .categories
            .iter()
            .map(|category| category.id.as_str())
            .collect::<Vec<_>>();
        assert!(category_ids.contains(&"core-tools"));
        assert!(category_ids.contains(&"vision-tools"));
        assert!(category_ids.contains(&"computer-use"));
        assert!(category_ids.contains(&"plugins"));
        assert!(category_ids.contains(&"skills"));
        assert!(catalog.summary.items >= 20);

        let read_file = catalog
            .categories
            .iter()
            .flat_map(|category| category.items.iter())
            .find(|item| item.item.id == "core.read_file")
            .expect("read_file should be cataloged");
        assert_eq!(read_file.item.status, "available");
        assert!(read_file.input_schema.is_some());
        assert!(read_file
            .actions
            .iter()
            .any(|action| action.id == "execute" && !action.enabled));

        for tool_id in [
            "vision.describe_screen",
            "vision.find_target",
            "vision.find_region",
            "computer.safe_context_menu",
            "computer.safe_drag_select",
            "computer.left_click",
            "computer.right_click",
            "computer.context_menu_select",
            "computer.drag_select",
            "computer.visual_action",
        ] {
            let tool = catalog
                .categories
                .iter()
                .flat_map(|category| category.items.iter())
                .find(|item| item.item.id == tool_id)
                .unwrap_or_else(|| panic!("{tool_id} should be cataloged"));
            assert!(tool
                .actions
                .iter()
                .any(|action| action.id == "dry-run" && action.enabled));
            assert!(tool
                .actions
                .iter()
                .any(|action| action.id == "execute" && !action.enabled));
        }

        let plugins = catalog
            .categories
            .iter()
            .find(|category| category.id == "plugins")
            .expect("plugins category should exist");
        assert!(plugins
            .items
            .iter()
            .any(|item| item.item.source == "local-plugin"));
    }

