    struct SessionStoreTestGuard {
        previous: Option<super::SessionStore>,
        _temp: tempfile::TempDir,
    }

    impl SessionStoreTestGuard {
        fn install(state: super::PersistedSessionState) -> Self {
            let temp = tempfile::tempdir().expect("temp session store");
            let store = super::SessionStore {
                path: temp.path().join("session.sqlite3"),
                legacy_json_path: temp.path().join("session.json"),
                capacity: super::SessionStoreCapacity::default(),
                state,
            };
            let previous = std::mem::replace(
                &mut *super::session_store().lock().expect("session store"),
                store,
            );
            Self {
                previous: Some(previous),
                _temp: temp,
            }
        }
    }

    impl Drop for SessionStoreTestGuard {
        fn drop(&mut self) {
            if let Some(previous) = self.previous.take() {
                let _ = std::mem::replace(
                    &mut *super::session_store().lock().expect("session store"),
                    previous,
                );
            }
        }
    }

    #[test]
    fn multi_agent_counting_dispatch_preserves_requested_order_and_isolated_rosters() {
        let _guard = config_test_guard();
        let now = 42;
        let mut agent_a = super::seed_session();
        agent_a.id = "agent-a".to_string();
        agent_a.name = "Agent A".to_string();
        agent_a.provider = "provider-a".to_string();
        agent_a.model = "model-a".to_string();
        agent_a.model_type = "text".to_string();
        let mut agent_b = super::seed_session();
        agent_b.id = "agent-b".to_string();
        agent_b.name = "Agent B".to_string();
        agent_b.provider = "provider-b".to_string();
        agent_b.model = "model-b".to_string();
        agent_b.model_type = "text".to_string();
        let mut agent_c = super::seed_session();
        agent_c.id = "agent-c".to_string();
        agent_c.name = "Agent C".to_string();
        agent_c.provider = "provider-c".to_string();
        agent_c.model = "model-c".to_string();
        agent_c.model_type = "text".to_string();
        let _store_guard = SessionStoreTestGuard::install(super::PersistedSessionState {
            sessions: vec![agent_a, agent_b, agent_c],
            active_session_id: Some("agent-a".to_string()),
            active_vision_session_id: None,
            chat_rooms: vec![super::PersistedChatRoom {
                id: "room-count".to_string(),
                name: "Counting Room".to_string(),
                created_at: now,
                updated_at: now,
                messages: vec![super::PersistedChatMessage {
                    id: "seed-message".to_string(),
                    author: "".to_string(),
                    role: "user".to_string(),
                    target: "Agent A".to_string(),
                    content: "上一轮消息不应影响本轮目标顺".to_string(),
                    kind: "text".to_string(),
                    attachments: Vec::new(),
                    created_at: now,
                }],
            }],
            active_chat_room_id: Some("room-count".to_string()),
        });

        let prepared = super::prepare_chat_dispatch(super::SendMessageRequest {
            session_id: Some("agent-a".to_string()),
            chat_room_id: Some("room-count".to_string()),
            target_agent_ids: vec![
                "agent-c".to_string(),
                "agent-a".to_string(),
                "agent-b".to_string(),
                "agent-a".to_string(),
            ],
            text: "请各会话配置按目标顺序依次报数，不能抢号".to_string(),
            selected_message_ids: None,
            attachments: None,
        })
        .expect("prepare dispatch");

        let target_ids = prepared
            .targets
            .iter()
            .map(|agent| agent.id.as_str())
            .collect::<Vec<_>>();
        assert_eq!(
            target_ids,
            vec!["agent-c", "agent-a", "agent-b"],
            "counting turns must follow requested target order and de-duplicate repeats"
        );
        assert_eq!(prepared.context_history.len(), 1);

        for target_id in target_ids {
            let roster = prepared
                .context_rosters
                .get(target_id)
                .expect("roster per target");
            assert!(
                roster
                    .members
                    .iter()
                    .all(|member| member.session_id != target_id),
                "each agent roster must exclude itself to avoid self-handoff conflicts"
            );
            assert_eq!(roster.members.len(), 2);
        }

        let mut messages = prepared.messages.clone();
        for (index, agent) in prepared.targets.iter().enumerate() {
            messages.push(super::ChatMessageDto {
                id: format!("count-reply-{index}"),
                author: agent.display_name.clone(),
                role: "assistant".to_string(),
                target: "room-count".to_string(),
                content: format!("报数 {}", index + 1),
                kind: "assistant-reply".to_string(),
                attachments: Vec::new(),
            });
        }

        super::persist_chat_dispatch(
            &prepared.chat_room_id,
            prepared.conversation_session_id.as_deref(),
            &prepared.targets,
            messages,
        )
        .expect("persist counting dispatch");

        let store = super::session_store().lock().expect("session store");
        let room = store
            .state
            .chat_rooms
            .iter()
            .find(|room| room.id == "room-count")
            .expect("room-count");
        let tail = room.messages.iter().skip(1).collect::<Vec<_>>();
        assert!(tail[0]
            .content
            .starts_with("请各会话配置按目标顺序依次报数，不能抢号"));
        assert!(tail[0].content.contains("# Shared Chat Memory"));
        assert_eq!(
            tail.iter()
                .skip(1)
                .map(|message| message.content.as_str())
                .collect::<Vec<_>>(),
            vec!["报数 1", "报数 2", "报数 3"]
        );
        assert_eq!(tail[1].author, "Agent C (model-c)");
        assert_eq!(tail[2].author, "Agent A (model-a)");
        assert_eq!(tail[3].author, "Agent B (model-b)");
    }

    #[test]
    fn multi_agent_group_send_marks_shared_room_memory_for_counting() {
        let _guard = config_test_guard();
        let mut agent_a = super::seed_session();
        agent_a.id = "agent-a".to_string();
        agent_a.name = "Agent A".to_string();
        agent_a.provider = "provider-a".to_string();
        agent_a.model = "model-a".to_string();
        agent_a.model_type = "text".to_string();
        let mut agent_b = super::seed_session();
        agent_b.id = "agent-b".to_string();
        agent_b.name = "Agent B".to_string();
        agent_b.provider = "provider-b".to_string();
        agent_b.model = "model-b".to_string();
        agent_b.model_type = "text".to_string();
        let _store_guard = SessionStoreTestGuard::install(super::PersistedSessionState {
            sessions: vec![agent_a, agent_b],
            active_session_id: Some("agent-a".to_string()),
            active_vision_session_id: None,
            chat_rooms: vec![super::PersistedChatRoom {
                id: "room-shared-count".to_string(),
                name: "Shared Counting".to_string(),
                created_at: 1,
                updated_at: 1,
                messages: Vec::new(),
            }],
            active_chat_room_id: Some("room-shared-count".to_string()),
        });

        let prepared = super::prepare_chat_dispatch(super::SendMessageRequest {
            session_id: Some("agent-a".to_string()),
            chat_room_id: Some("room-shared-count".to_string()),
            target_agent_ids: vec!["agent-a".to_string(), "agent-b".to_string()],
            text: "Group-send counting test: Agent A says 1, Agent B says 2.".to_string(),
            selected_message_ids: None,
            attachments: None,
        })
        .expect("prepare shared counting dispatch");

        assert!(prepared.user_content.contains("# Shared Chat Memory"));
        assert!(prepared.user_content.contains("trigger=\"group-send\""));
        assert!(prepared
            .user_content
            .contains("private session memory separate"));

        super::persist_group_send_shared_memory(&prepared.reference_context, &prepared.targets);

        let store = super::session_store().lock().expect("session store");
        for session_id in ["agent-a", "agent-b"] {
            let session = store
                .state
                .sessions
                .iter()
                .find(|session| session.id == session_id)
                .expect("target session");
            let shared = session
                .memory_beads
                .iter()
                .find(|bead| bead.kind == "chat-room-shared")
                .expect("shared group-send memory bead");
            assert_eq!(shared.layer, "L2");
            assert_eq!(shared.source, "chat-room:group-send");
            assert!(shared.summary.contains("room-shared-count"));
            assert!(shared.summary.contains("Group-send counting test"));
        }
    }

    #[tokio::test]
    async fn goal_command_gate_detects_exit_code() {
        let cwd = std::env::temp_dir();
        // exit 0 → 过门（Ok）
        assert!(
            super::run_goal_gate_command("exit 0", &cwd, 30_000)
                .await
                .is_ok(),
            "exit 0 should pass the command gate"
        );
        // 非零退出 → 未过门（Err，含失败证据）
        let failure = super::run_goal_gate_command("exit 1", &cwd, 30_000).await;
        assert!(failure.is_err(), "exit 1 should fail the command gate");
    }

