    #[test]
    fn workspace_tool_paths_are_scoped_to_selected_workspace() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let outside = tempfile::tempdir().expect("outside tempdir");
        let inside_file = workspace.path().join("notes.md");
        let outside_file = outside.path().join("secrets.md");
        std::fs::write(&inside_file, "inside").expect("inside file");
        std::fs::write(&outside_file, "outside").expect("outside file");

        let resolved =
            super::resolve_workspace_tool_path_in(workspace.path(), Some("notes.md")).unwrap();
        assert_eq!(
            resolved,
            inside_file.canonicalize().expect("canonical inside")
        );
        assert!(super::resolve_workspace_tool_path_in(workspace.path(), Some("..")).is_err());
        assert!(
            super::resolve_workspace_tool_path_in(workspace.path(), outside_file.to_str()).is_err()
        );
    }

