    #[test]
    fn session_store_load_for_workspace_keeps_workspaces_isolated() {
        let temp = tempfile::tempdir().expect("tempdir");
        let ws_a = temp.path().join("ws-a");
        let ws_b = temp.path().join("ws-b");
        std::fs::create_dir_all(&ws_a).expect("ws-a");
        std::fs::create_dir_all(&ws_b).expect("ws-b");
        let config = super::WorkspaceConfig::default();

        let mut store_a = super::SessionStore::load_for_workspace(&ws_a, &config);
        store_a
            .create_session(super::UpsertSessionRequest {
                name: Some("workspace-a-agent".to_string()),
                provider: Some("Custom".to_string()),
                model: Some("local-a".to_string()),
                model_type: None,
                avatar: None,
                base_url: None,
                endpoint: None,
                reasoning_effort: None,
                api_key_ref: None,
            })
            .expect("create session in ws-a");

        let store_a_reloaded = super::SessionStore::load_for_workspace(&ws_a, &config);
        let store_b = super::SessionStore::load_for_workspace(&ws_b, &config);

        assert!(store_a_reloaded
            .state
            .sessions
            .iter()
            .any(|session| session.name == "workspace-a-agent"));
        assert!(!store_b
            .state
            .sessions
            .iter()
            .any(|session| session.name == "workspace-a-agent"));
        assert!(store_a_reloaded.path.starts_with(&ws_a));
        assert!(store_b.path.starts_with(&ws_b));
    }

    #[test]
    fn project_entry_scan_hides_internal_and_target_dirs() {
        let temp = tempfile::tempdir().expect("tempdir");
        std::fs::create_dir(temp.path().join(".hidden")).expect("hidden dir");
        std::fs::create_dir(temp.path().join("target")).expect("target dir");
        std::fs::create_dir(temp.path().join("modules")).expect("modules dir");
        std::fs::write(temp.path().join("Cargo.toml"), "[workspace]").expect("manifest");

        let entries = super::scan_project_entries(temp.path());
        let names = entries
            .iter()
            .map(|entry| entry.name.as_str())
            .collect::<Vec<_>>();
        assert!(names.contains(&"Cargo.toml"));
        assert!(names.contains(&"modules"));
        assert!(!names.contains(&".hidden"));
        assert!(!names.contains(&"target"));
    }

