    #[test]
    fn context_builder_enforces_prompt_budget_with_image_and_history() {
        let agent = context_test_agent();
        let history = (0..20)
            .map(|index| {
                persisted_role_message(
                    format!("h-{index}").as_str(),
                    if index % 2 == 0 { "user" } else { "assistant" },
                    format!("history segment {index} {}", "detail ".repeat(200)).as_str(),
                    index,
                )
            })
            .collect::<Vec<_>>();
        let image_urls = vec!["data:image/png;base64,AAAA".to_string()];

        let assembly = super::build_context_assembly(
            &agent,
            &history,
            "solve the problem shown in the image",
            &image_urls,
            super::ContextBuildOptions {
                history_token_budget: 20_000,
                memory_token_budget: 2_000,
                max_prompt_tokens: 4_000,
                image_token_estimate: 512,
                max_memory_beads: 4,
                history_floor_millis: None,
                chat_room_id: None,
            },
        );

        assert!(assembly.truncated);
        assert!(assembly.token_budget.user >= 512);
        assert!(assembly.token_budget.total <= 4_000);
        assert_eq!(assembly.token_budget.budget, 4_000);
    }

