    #[test]
    fn context_builder_honors_history_floor_after_session_reset() {
        let agent = context_test_agent();
        let history = vec![
            persisted_role_message("h-old", "user", "old task memory should be archived", 10),
            persisted_role_message("h-new", "assistant", "new task context is still active", 30),
        ];

        let assembly = super::build_context_assembly(
            &agent,
            &history,
            "continue from the new task",
            &[],
            super::ContextBuildOptions {
                history_token_budget: 120,
                memory_token_budget: 80,
                max_prompt_tokens: 8_000,
                image_token_estimate: 512,
                max_memory_beads: 4,
                history_floor_millis: Some(20),
                chat_room_id: None,
            },
        );

        let joined = assembly
            .messages
            .iter()
            .map(message_text)
            .collect::<Vec<_>>()
            .join("\n");
        assert!(!joined.contains("old task memory"));
        assert!(joined.contains("new task context"));
        assert!(joined.contains("continue from the new task"));
        assert_eq!(assembly.history_message_count, 1);
        assert_eq!(assembly.history_selection.source, "chat_room.messages");
        assert_eq!(assembly.history_selection.selected_ids, vec!["h-new"]);
        assert_eq!(assembly.history_selection.excluded_ids, vec!["h-old"]);
    }

