    #[test]
    fn goal_g1_sqlite_crud_is_workspace_scoped_and_cancelable() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let workspace_a = "ws-goal-a";
        let workspace_b = "ws-goal-b";

        let created = super::create_goal_sqlite(
            &db_path,
            workspace_a,
            "room-1",
            super::CreateGoalRequest {
                title: "Ship G1 goal contract".to_string(),
                chat_room_id: Some("room-1".to_string()),
                max_iterations: Some(7),
                background: Some(true),
                originating_user_msg_id: Some("user-1".to_string()),
                completion_condition: Some(serde_json::json!({ "type": "UserConfirm" })),
            },
        )
        .expect("create goal");

        assert!(created.id.starts_with("goal-"));
        assert_eq!(created.workspace_id, workspace_a);
        assert_eq!(created.chat_room_id, "room-1");
        assert_eq!(created.status, "planning");
        assert_eq!(created.max_iterations, 7);
        assert!(created.background);
        assert_eq!(created.recent_events[0].event_type, "goal-created");

        let visible = super::query_goals_sqlite(
            &db_path,
            workspace_a,
            super::GoalListQuery {
                status: None,
                chat_room_id: None,
                limit: Some(10),
            },
        )
        .expect("query workspace a");
        assert_eq!(visible.len(), 1);

        let hidden = super::query_goals_sqlite(
            &db_path,
            workspace_b,
            super::GoalListQuery {
                status: None,
                chat_room_id: None,
                limit: Some(10),
            },
        )
        .expect("query workspace b");
        assert!(hidden.is_empty());

        let cancelled =
            super::cancel_goal_sqlite(&db_path, workspace_a, &created.id).expect("cancel goal");
        assert_eq!(cancelled.status, "cancelled");
        assert!(cancelled.cancelled_at.is_some());
        assert!(cancelled
            .recent_events
            .iter()
            .any(|event| event.event_type == "goal-cancelled"));
    }

