    #[test]
    fn goal_role_config_round_trips_and_reports_commander_health() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("roles.sqlite3");
        let now = super::unix_timestamp_millis();
        let sessions = vec![
            super::PersistedSession {
                id: "planner".to_string(),
                name: "Planner".to_string(),
                provider: "Custom".to_string(),
                model: "planner-model".to_string(),
                avatar: None,
                api_key_ref: String::new(),
                base_url: None,
                endpoint: None,
                reasoning_effort: "medium".to_string(),
                model_type: "text".to_string(),
                memory_beads: Vec::new(),
                created_at: now - 100,
                updated_at: now - 100,
                context_reset_at: 0,
                messages: Vec::new(),
            },
            super::PersistedSession {
                id: "worker".to_string(),
                name: "Worker".to_string(),
                provider: "Custom".to_string(),
                model: "worker-model".to_string(),
                avatar: None,
                api_key_ref: String::new(),
                base_url: None,
                endpoint: None,
                reasoning_effort: "medium".to_string(),
                model_type: "text".to_string(),
                memory_beads: Vec::new(),
                created_at: now - 100,
                updated_at: now - 100,
                context_reset_at: 0,
                messages: Vec::new(),
            },
        ];

        super::upsert_goal_role_config_sqlite(
            &db_path,
            "planner",
            super::GoalRoleConfigUpdateRequest {
                role: Some("planner".to_string()),
                responsibility: Some("Break goals into phases".to_string()),
                commander: Some(true),
                heartbeat_timeout_ms: Some(60_000),
                task_timeout_ms: Some(600_000),
            },
        )
        .expect("role config");
        super::record_goal_role_heartbeat_sqlite(
            &db_path,
            "planner",
            super::GoalRoleHeartbeatRequest {
                task_active: Some(true),
            },
        )
        .expect("heartbeat");

        let response = super::goal_role_config_response_from_sqlite(&db_path, &sessions)
            .expect("role response");

        assert_eq!(response.commander_session_id.as_deref(), Some("planner"));
        assert_eq!(response.roles.len(), 1);
        let planner = response
            .roles
            .iter()
            .find(|role| role.session_id == "planner")
            .unwrap();
        assert_eq!(planner.role.as_deref(), Some("planner"));
        assert!(planner.commander);
        assert!(planner.online);
        assert!(!planner.stuck);
        assert_eq!(planner.risk_level, "normal");

        assert!(!response
            .roles
            .iter()
            .any(|role| role.session_id == "worker"));
    }

