    #[test]
    fn goal_run_all_step_limit_clamps_request_value() {
        assert_eq!(
            super::goal_run_all_step_limit(&super::GoalRunAllRequest { max_steps: Some(0) }),
            1
        );
        assert_eq!(
            super::goal_run_all_step_limit(&super::GoalRunAllRequest { max_steps: Some(3) }),
            3
        );
        assert_eq!(
            super::goal_run_all_step_limit(&super::GoalRunAllRequest {
                max_steps: Some(99)
            }),
            20
        );
        assert_eq!(
            super::goal_run_all_step_limit(&super::GoalRunAllRequest { max_steps: None }),
            8
        );
    }

    #[test]
    fn goal_loop_registry_records_running_and_stop_request() {
        let goal_id = "goal-loop-registry-test";
        super::forget_goal_loop_status(goal_id);
        let (started, maybe_cancel) = super::register_goal_loop_start("workspace-loop", goal_id, 5);
        assert!(started.running);
        assert!(!started.stop_requested);
        assert_eq!(started.max_steps, 5);
        assert!(maybe_cancel.is_some());

        let stopped = super::request_goal_loop_stop(goal_id);
        assert!(stopped.running);
        assert!(stopped.stop_requested);
        assert!(stopped
            .stopped_reason
            .as_deref()
            .is_some_and(|reason| reason.contains("Stop requested")));

        super::finish_goal_loop_status(goal_id, 1, "Stopped by test.".to_string());
        let final_status = super::goal_loop_status(goal_id);
        assert!(!final_status.running);
        assert_eq!(final_status.completed_steps, 1);
        super::forget_goal_loop_status(goal_id);
    }

