    fn goal_phase_files_exist_verification_keeps_phase_running_when_artifact_is_missing() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let now = super::unix_timestamp_millis();
        let missing_artifact = format!("goal-artifacts/missing-record-result-{now}.html");
        let agent_session = super::PersistedSession {
            id: "implementer-agent".to_string(),
            name: "implementer".to_string(),
            provider: "Custom".to_string(),
            model: "local-model".to_string(),
            avatar: None,
            base_url: None,
            endpoint: None,
            reasoning_effort: "medium".to_string(),
            model_type: "text".to_string(),
            api_key_ref: String::new(),
            memory_beads: Vec::new(),
            created_at: now,
            updated_at: now,
            context_reset_at: 0,
            messages: Vec::new(),
        };
        let agent = agent_session.to_agent_session(false);
        let mut store = super::SessionStore {
            path: db_path.clone(),
            legacy_json_path: temp.path().join("sessions.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: super::PersistedSessionState {
                sessions: vec![agent_session],
                active_session_id: Some("implementer-agent".to_string()),
                active_vision_session_id: None,
                chat_rooms: vec![super::PersistedChatRoom {
                    id: "room-1".to_string(),
                    name: "Room 1".to_string(),
                    created_at: now,
                    updated_at: now,
                    messages: vec![persisted_role_message(
                        "user-1",
                        "user",
                        "Build an HTML artifact",
                        now,
                    )],
                }],
                active_chat_room_id: Some("room-1".to_string()),
            },
        };
        store.save().expect("save initial sessions");
        super::upsert_goal_role_config_sqlite(
            &db_path,
            "implementer-agent",
            super::GoalRoleConfigUpdateRequest {
                role: Some("implementer".to_string()),
                responsibility: Some("Implement artifact output".to_string()),
                commander: Some(true),
                heartbeat_timeout_ms: Some(60_000),
                task_timeout_ms: Some(600_000),
            },
        )
        .expect("implementer role config");
        let goal = super::create_goal_sqlite(
            &db_path,
            "workspace-files-exist-gate",
            "room-1",
            super::CreateGoalRequest {
                title: "FilesExist gate".to_string(),
                chat_room_id: Some("room-1".to_string()),
                max_iterations: Some(3),
                background: Some(true),
                originating_user_msg_id: Some("user-1".to_string()),
                completion_condition: Some(serde_json::json!({ "type": "UserConfirm" })),
            },
        )
        .expect("goal");
        super::set_goal_plan_sqlite(
            &db_path,
            "workspace-files-exist-gate",
            &goal.id,
            super::GoalPlanRequest {
                phases: vec![super::GoalPlanPhaseRequest {
                    id: "implement".to_string(),
                    title: "Implement the HTML artifact".to_string(),
                    assigned_role: Some("implementer".to_string()),
                    depends_on: Vec::new(),
                    skills_required: vec!["implement".to_string()],
                    output_artifacts: vec![missing_artifact.clone()],
                    verification: Some(serde_json::json!({
                        "type": "FilesExist",
                        "paths": [missing_artifact.clone()]
                    })),
                    requires_human_ack: false,
                }],
            },
        )
        .expect("plan");
        let connection = super::open_session_connection(&db_path).expect("open db");
        super::update_goal_phase_status_connection(
            &connection,
            "workspace-files-exist-gate",
            &goal.id,
            "implement",
            "running",
        )
        .expect("mark running");

        let result = store
            .record_goal_phase_model_result(
                "workspace-files-exist-gate",
                &goal.id,
                "implement",
                &agent,
                super::AgentModelResponse {
                    answer_text: "Implementation is complete.".to_string(),
                    reasoning_text: "I created the directory only.".to_string(),
                    tool_requests: Vec::new(),
                    tool_write_executed: false,
                    model_tool_calls_executed: false,
                    turn_id: "turn-test-files".to_string(),
                    used_real_model: false,
                    diagnostic_note: None,
                    context_footer: None,
                    context_usage: None,
                },
                Vec::new(),
                Vec::new(),
            )
            .expect("record phase result");

        assert_eq!(result.status.goal.phases[0].status, "running");
        assert!(result.messages.iter().any(|message| {
            message.kind == "task-summary" && message.content.contains(&missing_artifact)
        }));
        let refreshed = super::get_goal_sqlite(&db_path, "workspace-files-exist-gate", &goal.id)
            .expect("refreshed goal");
        assert!(refreshed.recent_events.iter().any(|event| {
            event.event_type == "goal-phase-verification-blocked"
                && event.payload["missing_artifacts"]
                    .as_array()
                    .is_some_and(|items| items.iter().any(|item| item == &missing_artifact))
        }));
    }

