    #[test]
    fn goal_phase_completion_report_closes_loop_and_cleans_in_memory_overlay() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let now = super::unix_timestamp_millis();
        let commander = super::PersistedSession {
            id: "goal-commander".to_string(),
            name: "Commander".to_string(),
            provider: "Custom".to_string(),
            model: "local-model".to_string(),
            avatar: None,
            base_url: None,
            endpoint: None,
            reasoning_effort: "medium".to_string(),
            model_type: "text".to_string(),
            api_key_ref: String::new(),
            memory_beads: Vec::new(),
            created_at: now,
            updated_at: now,
            context_reset_at: 0,
            messages: Vec::new(),
        };
        let mut store = super::SessionStore {
            path: db_path.clone(),
            legacy_json_path: temp.path().join("sessions.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: super::PersistedSessionState {
                sessions: vec![commander],
                active_session_id: Some("goal-commander".to_string()),
                active_vision_session_id: None,
                chat_rooms: vec![super::PersistedChatRoom {
                    id: "room-goal-complete".to_string(),
                    name: "Goal Complete".to_string(),
                    created_at: now,
                    updated_at: now,
                    messages: vec![persisted_role_message(
                        "user-goal",
                        "user",
                        "Complete a small goal",
                        now,
                    )],
                }],
                active_chat_room_id: Some("room-goal-complete".to_string()),
            },
        };
        store
            .ensure_goal_role_sessions(vec!["planner".to_string()])
            .expect("bootstrap planner");
        super::upsert_goal_role_config_sqlite(
            &db_path,
            "goal-commander",
            super::GoalRoleConfigUpdateRequest {
                role: Some("commander".to_string()),
                responsibility: Some("Coordinate goal completion".to_string()),
                commander: Some(true),
                heartbeat_timeout_ms: Some(60_000),
                task_timeout_ms: Some(600_000),
            },
        )
        .expect("commander config");
        let goal = super::create_goal_sqlite(
            &db_path,
            "workspace-goal-complete",
            "room-goal-complete",
            super::CreateGoalRequest {
                title: "Completion report".to_string(),
                chat_room_id: Some("room-goal-complete".to_string()),
                max_iterations: Some(2),
                background: Some(false),
                originating_user_msg_id: Some("user-goal".to_string()),
                completion_condition: Some(serde_json::json!({ "type": "UserConfirm" })),
            },
        )
        .expect("goal");
        super::set_goal_plan_sqlite(
            &db_path,
            "workspace-goal-complete",
            &goal.id,
            super::GoalPlanRequest {
                phases: vec![super::GoalPlanPhaseRequest {
                    id: "plan".to_string(),
                    title: "Plan once".to_string(),
                    assigned_role: Some("planner".to_string()),
                    depends_on: Vec::new(),
                    skills_required: vec!["plan".to_string()],
                    output_artifacts: Vec::new(),
                    verification: Some(serde_json::json!({ "type": "UserConfirm" })),
                    requires_human_ack: false,
                }],
            },
        )
        .expect("plan");
        store
            .dispatch_ready_goal_phases("workspace-goal-complete", &goal.id)
            .expect("dispatch");
        assert!(store
            .state
            .sessions
            .iter()
            .find(|session| session.id == "goal-planner")
            .expect("planner")
            .memory_beads
            .iter()
            .any(|bead| bead.kind == "goal-task-skill"));

        // E3a 的 dispatch 只负责 durable claim；这里模拟 E3b finalizer 已收口 claim，
        // 再验证原有完成报告与 overlay 清理路径。
        let connection = super::open_session_connection(&db_path).expect("claim db");
        connection
            .execute(
                "UPDATE goal_phases SET active_run_id=NULL, claim_token=NULL, claim_owner=NULL, claimed_at=NULL, lease_until=NULL \
                 WHERE goal_id=?1 AND id='plan'",
                super::params![&goal.id],
            )
            .expect("release claim fixture");

        let status = store
            .complete_goal_phase(
                "workspace-goal-complete",
                &goal.id,
                "plan",
                super::GoalPhaseCompleteRequest {
                    evidence: Some("Planner produced the accepted phase report.".to_string()),
                    // 模拟自动运行路径：校验通过后显式断言 pass。
                    verdict: Some("pass".to_string()),
                },
            )
            .expect("phase completion");

        assert_eq!(status.goal.status, "completed");
        assert_eq!(status.phase_counts.completed, 1);
        assert!(status
            .goal
            .recent_events
            .iter()
            .any(|event| event.event_type == "phase-completed"
                && event.payload["evidence"]
                    == serde_json::json!("Planner produced the accepted phase report.")));
        assert!(store
            .state
            .sessions
            .iter()
            .find(|session| session.id == "goal-planner")
            .expect("planner")
            .memory_beads
            .iter()
            .all(|bead| bead.kind != "goal-task-skill"));

        // GL-04：完成走的是「校验通过」路径 → phase 记 pass verdict + goal-phase-verdict 事件。
        assert!(status
            .goal
            .recent_events
            .iter()
            .any(|event| event.event_type == "goal-phase-verdict"
                && event.payload["verdict"] == serde_json::json!("pass")));
        let phase = status
            .goal
            .phases
            .iter()
            .find(|phase| phase.id == "plan")
            .expect("plan phase");
        assert_eq!(phase.last_verdict.as_deref(), Some("pass"));
        assert_eq!(
            phase.last_evidence,
            Some(serde_json::json!({ "text": "Planner produced the accepted phase report." }))
        );
    }

    /// GL-04（codex 审查修复）：手工完成（不带 verdict）绝不能伪造 pass——
    /// complete_goal_phase 是通用/前端可调的入口，不重跑校验门，不得凭空写结论。
    #[test]
    fn manual_complete_without_verdict_does_not_fabricate_pass() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("manual.sqlite3");
        let mut store = super::SessionStore {
            path: db.clone(),
            legacy_json_path: tmp.path().join("sessions.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: super::PersistedSessionState {
                sessions: Vec::new(),
                active_session_id: None,
                active_vision_session_id: None,
                chat_rooms: vec![super::PersistedChatRoom {
                    id: "room-manual".to_string(),
                    name: "Room".to_string(),
                    created_at: 1,
                    updated_at: 1,
                    messages: Vec::new(),
                }],
                active_chat_room_id: Some("room-manual".to_string()),
            },
        };
        let goal = super::create_goal_sqlite(
            &db,
            "ws-manual",
            "room-manual",
            super::CreateGoalRequest {
                title: "手工完成".to_string(),
                chat_room_id: Some("room-manual".to_string()),
                max_iterations: Some(2),
                background: Some(false),
                originating_user_msg_id: None,
                completion_condition: Some(serde_json::json!({ "type": "UserConfirm" })),
            },
        )
        .expect("goal");
        super::set_goal_plan_sqlite(
            &db,
            "ws-manual",
            &goal.id,
            super::GoalPlanRequest {
                phases: vec![super::GoalPlanPhaseRequest {
                    id: "impl".to_string(),
                    title: "实现".to_string(),
                    assigned_role: Some("implementer".to_string()),
                    depends_on: Vec::new(),
                    skills_required: Vec::new(),
                    output_artifacts: Vec::new(),
                    verification: None,
                    requires_human_ack: false,
                }],
            },
        )
        .expect("plan");

        let status = store
            .complete_goal_phase(
                "ws-manual",
                &goal.id,
                "impl",
                super::GoalPhaseCompleteRequest {
                    evidence: Some("手工点了完成".to_string()),
                    verdict: None,
                },
            )
            .expect("complete");

        let phase = status
            .goal
            .phases
            .iter()
            .find(|p| p.id == "impl")
            .expect("phase");
        // 状态确实完成了……
        assert_eq!(phase.status, "completed");
        // ……但没有凭空写 verdict（保持 NULL），也没有 goal-phase-verdict 事件。
        assert!(
            phase.last_verdict.is_none(),
            "手工完成不该伪造 pass verdict"
        );
        assert!(!status
            .goal
            .recent_events
            .iter()
            .any(|event| event.event_type == "goal-phase-verdict"));
    }

