    #[test]
    fn delete_session_clears_memory_and_goal_role_config() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let mut deleted = super::seed_session();
        deleted.id = "s-delete".to_string();
        deleted.name = "delete-me".to_string();
        deleted.memory_beads = vec![super::MemoryBeadDto {
            id: "delete-bead".to_string(),
            kind: "decision".to_string(),
            layer: "L2".to_string(),
            summary: "session scoped memory".to_string(),
            source: "test".to_string(),
            pinned: false,
            confidence: 0.5,
            created_at: 1,
            ..super::MemoryBeadDto::default()
        }];
        let mut survivor = super::seed_session();
        survivor.id = "s-keep".to_string();
        survivor.name = "keep-me".to_string();
        let mut store = super::SessionStore {
            path: db_path.clone(),
            legacy_json_path: temp.path().join("sessions.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: super::PersistedSessionState {
                sessions: vec![deleted, survivor],
                active_session_id: Some("s-delete".to_string()),
                active_vision_session_id: None,
                chat_rooms: Vec::new(),
                active_chat_room_id: None,
            },
        };
        store.save().expect("save initial state");
        let connection = super::open_session_connection(&db_path).expect("open db");
        connection
            .execute(
                "INSERT OR REPLACE INTO goal_role_configs(
                    session_id, role, responsibility, commander, heartbeat_timeout_ms,
                    task_timeout_ms, last_heartbeat_at, active_task_started_at, updated_at
                ) VALUES (?1, 'planner', 'plan work', 0, 60000, 600000, NULL, NULL, 1)",
                rusqlite::params!["s-delete"],
            )
            .expect("insert goal role config");
        drop(connection);

        store.delete_session("s-delete").expect("delete session");

        assert!(store
            .state
            .sessions
            .iter()
            .all(|session| session.id != "s-delete"));
        assert_eq!(store.state.active_session_id.as_deref(), Some("s-keep"));
        let connection = super::open_session_connection(&db_path).expect("reopen db");
        let count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM goal_role_configs WHERE session_id=?1",
                rusqlite::params!["s-delete"],
                |row| row.get(0),
            )
            .expect("count configs");
        assert_eq!(count, 0);
    }

