    struct WorkspaceScopeTestGuard {
        previous_config: super::WorkspaceConfig,
        previous_workspace: std::path::PathBuf,
    }

    impl WorkspaceScopeTestGuard {
        fn install(workspace: &std::path::Path) -> Self {
            let patched = super::WorkspaceConfig {
                workspace: super::ConfigWorkspace {
                    default_dir: Some(workspace.display().to_string()),
                    ..Default::default()
                },
                ..Default::default()
            };
            let previous_config = {
                let mut guard = super::workspace_config().lock().expect("lock");
                std::mem::replace(&mut *guard, patched)
            };
            let previous_workspace = {
                let mut guard = super::workspace_state()
                    .lock()
                    .expect("workspace state lock");
                std::mem::replace(&mut guard.current, workspace.to_path_buf())
            };
            Self {
                previous_config,
                previous_workspace,
            }
        }
    }

    impl Drop for WorkspaceScopeTestGuard {
        fn drop(&mut self) {
            let _ = std::mem::replace(
                &mut *super::workspace_config().lock().expect("lock"),
                self.previous_config.clone(),
            );
            let _ = std::mem::replace(
                &mut super::workspace_state()
                    .lock()
                    .expect("workspace state lock")
                    .current,
                self.previous_workspace.clone(),
            );
        }
    }

    struct DevOpenPermissionsTestGuard {
        previous: bool,
    }

    impl DevOpenPermissionsTestGuard {
        fn enable() -> Self {
            let previous = super::test_dev_open_tool_permissions_enabled()
                .swap(true, std::sync::atomic::Ordering::SeqCst);
            Self { previous }
        }
    }

    impl Drop for DevOpenPermissionsTestGuard {
        fn drop(&mut self) {
            super::test_dev_open_tool_permissions_enabled()
                .store(self.previous, std::sync::atomic::Ordering::SeqCst);
        }
    }

