    #[test]
    fn computer_use_prompt_requires_surface_grounding_and_post_action_verification() {
        let constraints = super::computer_use_operation_constraints();
        for required in [
            "surface=desktop|browser",
            "fresh screenshot",
            "Never guess coordinates",
            "verify the visible result",
            "WebView2",
            "untrusted data",
        ] {
            assert!(
                constraints.contains(required),
                "missing constraint: {required}"
            );
        }

        let instruction = super::agent_tool_usage_instruction();
        assert!(instruction.contains(constraints));
        let semantic = super::semantic_dispatch_tool_definition();
        assert!(semantic
            .description
            .as_deref()
            .unwrap_or_default()
            .contains("surface=desktop|browser"));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn task_schedule_run_due_uses_system_room_without_changing_active_room() {
        let _guard = config_test_guard();
        let temp = tempfile::tempdir().expect("tempdir");
        let now = super::unix_timestamp_millis();
        let workspace = temp.path().canonicalize().unwrap();
        let db_path = temp.path().join("sessions.sqlite3");
        let store = super::SessionStore {
            path: db_path,
            legacy_json_path: temp.path().join("sessions.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: super::PersistedSessionState {
                sessions: vec![super::PersistedSession {
                    id: "target-agent".to_string(),
                    name: "target-agent".to_string(),
                    provider: "Custom".to_string(),
                    model: "qwen".to_string(),
                    avatar: None,
                    api_key_ref: String::new(),
                    base_url: None,
                    endpoint: None,
                    reasoning_effort: "medium".to_string(),
                    model_type: "text".to_string(),
                    memory_beads: Vec::new(),
                    created_at: now,
                    updated_at: now,
                    context_reset_at: 0,
                    messages: Vec::new(),
                }],
                active_session_id: Some("target-agent".to_string()),
                active_vision_session_id: None,
                chat_rooms: vec![super::PersistedChatRoom {
                    id: "room-user-active".to_string(),
                    name: "当前聊天室".to_string(),
                    created_at: now,
                    updated_at: now,
                    messages: Vec::new(),
                }],
                active_chat_room_id: Some("room-user-active".to_string()),
            },
        };
        let prev_workspace = {
            let mut guard = super::workspace_state().lock().expect("workspace state");
            std::mem::replace(&mut guard.current, workspace.clone())
        };
        let prev_config = {
            let mut guard = super::workspace_config().lock().expect("config");
            std::mem::replace(&mut *guard, super::WorkspaceConfig::default())
        };
        let prev_store = {
            let mut guard = super::session_store().lock().expect("session store");
            std::mem::replace(&mut *guard, store)
        };

        let Json(created) =
            super::api_create_task_schedule(axum::Json(super::TaskScheduleCreateRequest {
                target_session_id: "target-agent".to_string(),
                content: "run nightly verification".to_string(),
                run_at_ms: 1,
                interval_ms: None,
                permissions: vec!["full-access".to_string()],
                schedule_kind: "once".to_string(),
                wall_hour: 0,
                wall_minute: 0,
                weekdays: Vec::new(),
                tz_offset_minutes: 0,
                task_kind: "poll".to_string(),
                goal_id: None,
            }))
            .await
            .expect("create schedule");
        assert_eq!(created.tasks.len(), 1);
        assert!(created.dev_open_permissions == super::dev_open_tool_permissions_enabled());

        let Json(run) = super::api_run_due_task_schedules().await.expect("run due");
        assert_eq!(run.ran.len(), 1);
        assert_eq!(run.ran[0].status, "executed");
        {
            let guard = super::session_store().lock().expect("session store");
            assert_eq!(
                guard.active_chat_room_id().as_deref(),
                Some("room-user-active")
            );
            assert_eq!(
                guard.state.sessions[0].messages[0].content,
                "run nightly verification"
            );
            let room = guard
                .state
                .chat_rooms
                .iter()
                .find(|room| room.id == super::SCHEDULED_TASK_SYSTEM_ROOM_ID)
                .expect("scheduled task system room");
            assert_eq!(room.name, "定时任务");
            assert!(room
                .messages
                .iter()
                .any(|message| message.content == "run nightly verification"));
        }

        let _ = std::mem::replace(
            &mut super::workspace_state()
                .lock()
                .expect("workspace state")
                .current,
            prev_workspace,
        );
        let _ = std::mem::replace(
            &mut *super::workspace_config().lock().expect("config"),
            prev_config,
        );
        let _ = std::mem::replace(
            &mut *super::session_store().lock().expect("session store"),
            prev_store,
        );
    }

    #[test]
    fn stream_tool_call_tuple_retains_id_name_and_args_slots() {
        // Phase C-13：流"Tool Loop "model_tool_calls value 升级。
        // (tool_use_id, name, argsJson) —"任一 slot 丢失都会"round 2
        // ToolResult 配对失败。这"TDD 钉住 tuple 语义。
        let mut calls: std::collections::BTreeMap<u32, (String, String, String)> =
            std::collections::BTreeMap::new();
        calls.insert(
            0,
            (
                "toolu_stream_1".to_string(),
                "read_file".to_string(),
                "{\"path\":\"a.rs\"}".to_string(),
            ),
        );
        // 模拟 InputJsonDelta 分片 append 到第 3 "(arguments)
        if let Some((_, _, args)) = calls.get_mut(&0) {
            args.push_str(" extra");
        }
        let (id, name, args) = calls.get(&0).expect("present").clone();
        assert_eq!(id, "toolu_stream_1");
        assert_eq!(name, "read_file");
        assert!(args.contains("extra"));
    }

    #[test]
    fn stream_content_block_tool_use_start_populates_full_tuple() {
        // 模拟流式 ContentBlockStart 命中 ToolUse 时的 insert 逻辑。
        // (start.index, (id, name, initial_input))
        use super::OutputContentBlock;
        let block = OutputContentBlock::ToolUse {
            id: "toolu_stream_2".into(),
            name: "glob_search".into(),
            input: serde_json::json!({"pattern": "*.rs"}),
        };
        let OutputContentBlock::ToolUse { id, name, input } = block else {
            panic!("expected ToolUse");
        };
        let initial_input = if input.is_object() && input.as_object().is_some_and(|o| o.is_empty())
        {
            String::new()
        } else {
            input.to_string()
        };
        let tuple = (id.clone(), name.clone(), initial_input);
        assert_eq!(tuple.0, "toolu_stream_2");
        assert_eq!(tuple.1, "glob_search");
        assert!(tuple.2.contains("*.rs"));
    }

    #[test]
    fn model_tool_requests_from_blocks_preserves_tool_use_id() {
        // Phase C-12：tool_use_id 必须"round 0 "round 1 保留，否。
        // round 2 "ToolResult 无法配对，模型会拒绝整条 tool_result 块。
        let blocks = vec![
            super::OutputContentBlock::Text {
                text: "hello".into(),
            },
            super::OutputContentBlock::ToolUse {
                id: "toolu_abc_123".into(),
                name: "read_file".into(),
                input: serde_json::json!({"path": "a.rs"}),
            },
            super::OutputContentBlock::ToolUse {
                id: "toolu_def_456".into(),
                name: "glob_search".into(),
                input: serde_json::json!({"pattern": "*.rs"}),
            },
        ];
        let requests = super::model_tool_requests_from_blocks(&blocks);
        assert_eq!(requests.len(), 2);
        assert_eq!(requests[0].0, "toolu_abc_123");
        assert_eq!(requests[0].1, "read_file");
        assert_eq!(
            requests[0].2,
            serde_json::json!({"path": "a.rs"}),
            "input JSON 应原样传"
        );
        assert_eq!(requests[1].0, "toolu_def_456");
        assert_eq!(requests[1].1, "glob_search");
    }

    #[test]
    fn agent_message_request_with_history_preserves_tools_and_system() {
        // Phase C-12：round 1 "round 2 "with_history 发多"messages。
        // tools / tool_choice / system / reasoning_effort 都应保持 round 0 相同。
        use super::{ConfigModel, WorkspaceConfig};
        let _guard = config_test_guard();
        let patched = WorkspaceConfig {
            model: ConfigModel {
                enable_llm_tools: true,
                llm_tool_exposure: Some("whitelist".into()),
                ..ConfigModel::default()
            },
            ..WorkspaceConfig::default()
        };
        let prev = {
            let mut guard = super::workspace_config().lock().expect("lock");
            std::mem::replace(&mut *guard, patched)
        };
        let agent = super::AgentSessionDto {
            id: "ag-1".into(),
            name: "agent-1".into(),
            display_name: "agent-1".into(),
            avatar: None,
            model: "glm-4.6".into(),
            model_type: "text".into(),
            provider: "ZhipuAi".into(),
            base_url: None,
            endpoint: None,
            reasoning_effort: "medium".into(),
            api_key_status: "present".into(),
            selectable: true,
            enabled: true,
            system: false,
            default_timeout_ms: 15_000,
            memory_beads: Vec::new(),
        };
        let messages = vec![
            super::InputMessage::user_text("round-0 user".to_string()),
            super::InputMessage {
                role: "assistant".into(),
                content: vec![super::InputContentBlock::ToolUse {
                    id: "toolu_test".into(),
                    name: "read_file".into(),
                    input: serde_json::json!({"path": "x"}),
                }],
            },
            super::InputMessage {
                role: "user".into(),
                content: vec![super::InputContentBlock::ToolResult {
                    tool_use_id: "toolu_test".into(),
                    content: vec![super::ToolResultContentBlock::Text {
                        text: "tool ran".into(),
                    }],
                    is_error: false,
                }],
            },
        ];
        let req = super::agent_message_request_with_history(&agent, false, messages.clone());
        assert_eq!(req.messages.len(), 3);
        assert!(req.tools.is_some(), "工具必须和 round 1 请求一起");
        assert!(matches!(req.tool_choice, Some(super::ToolChoice::Auto)));
        assert!(req.system.is_some());
        assert_eq!(req.model, "glm-4.6");

        let _ = std::mem::replace(&mut *super::workspace_config().lock().expect("lock"), prev);
    }

    #[test]
    fn run_model_tool_dispatch_semantic_legacy_path_preserved() {
        // REQ-TOOL-007 Phase C-11 路径 A：元工具继续"legacy semantic_dispatch。
        // 返回"dispatch_plan.tool_id 按旧契约映射 computer-use 工具 id。
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let resp = rt
            .block_on(super::run_model_tool_dispatch(
                "tools_semantic_dispatch",
                &serde_json::json!({ "intent": "点击左上" }),
            ))
            .expect("legacy dispatch succeeds");
        assert!(
            !resp.route.starts_with("runtime-"),
            "semantic_dispatch 不得走 runtime 分支，实际 route={}",
            resp.route
        );
        assert!(resp.dispatch_plan.is_some());
    }

    #[test]
    fn run_model_tool_dispatch_semantic_dev_open_file_write_uses_runtime() {
        let _guard = config_test_guard();
        let _dev_open = DevOpenPermissionsTestGuard::enable();
        let tmp = tempfile::tempdir().expect("tempdir");
        let data_dir = tmp.path().join(super::DATA_DIR_NAME);
        std::fs::create_dir_all(&data_dir).expect("mkdir");
        let _session_db_env = scoped_session_db_env(&data_dir);

        let patched = super::WorkspaceConfig {
            workspace: super::ConfigWorkspace {
                default_dir: Some(tmp.path().display().to_string()),
                ..Default::default()
            },
            tool: super::ConfigTool {
                dev_open_permissions: true,
                ..Default::default()
            },
            ..Default::default()
        };
        let prev_config = {
            let mut guard = super::workspace_config().lock().expect("lock");
            std::mem::replace(&mut *guard, patched)
        };
        let prev_workspace = {
            let mut guard = super::workspace_state()
                .lock()
                .expect("workspace state lock");
            std::mem::replace(&mut guard.current, tmp.path().to_path_buf())
        };

        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let resp = rt
            .block_on(super::run_model_tool_dispatch(
                "tools_semantic_dispatch",
                &serde_json::json!({
                    "intent": "create file semantic-write.txt in current directory with content \"hello semantic\"",
                    "target": "./semantic-write.txt",
                    "text": "hello semantic"
                }),
            ))
            .expect("semantic dispatch file write succeeds");

        let _ = std::mem::replace(
            &mut *super::workspace_config().lock().expect("lock"),
            prev_config,
        );
        let _ = std::mem::replace(
            &mut super::workspace_state()
                .lock()
                .expect("workspace state lock")
                .current,
            prev_workspace,
        );

        assert_eq!(resp.route, "runtime-executed");
        assert_eq!(resp.status, "ok");
        assert_eq!(
            std::fs::read_to_string(tmp.path().join("semantic-write.txt")).expect("created file"),
            "hello semantic"
        );
    }

