    #[test]
    fn run_model_tool_dispatch_chat_handoff_creates_record_and_audit() {
        let _guard = config_test_guard();
        let tmp = tempfile::tempdir().expect("tempdir");
        let data_dir = tmp.path().join(super::DATA_DIR_NAME);
        std::fs::create_dir_all(&data_dir).expect("mkdir");
        let _session_db_env = scoped_session_db_env(&data_dir);

        let db_path = tmp.path().join("sessions.sqlite3");
        let mut a = super::seed_session();
        a.id = "agent-a".to_string();
        a.name = "A-designer".to_string();
        a.messages = Vec::new();
        let mut b = super::seed_session();
        b.id = "agent-b".to_string();
        b.name = "B-dev".to_string();
        b.messages = Vec::new();
        let mut store = super::SessionStore {
            path: db_path.clone(),
            legacy_json_path: tmp.path().join("sessions.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: super::PersistedSessionState {
                sessions: vec![a, b],
                active_session_id: Some("agent-a".to_string()),
                active_vision_session_id: None,
                chat_rooms: vec![super::PersistedChatRoom {
                    id: "room-1".to_string(),
                    name: "Room 1".to_string(),
                    created_at: 1,
                    updated_at: 1,
                    messages: vec![
                        persisted_role_message("user-1", "user", "Create the backend API", 10),
                        persisted_role_message("assistant-a", "assistant", "API plan is ready", 20),
                    ],
                }],
                active_chat_room_id: Some("room-1".to_string()),
            },
        };
        store.save().expect("seed sqlite");

        let previous_store = {
            let mut guard = super::session_store().lock().expect("session lock");
            std::mem::replace(&mut *guard, store)
        };

        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let response = rt.block_on(super::run_model_tool_dispatch(
            "chat_handoff",
            &serde_json::json!({
                "chat_room_id": "room-1",
                "to": "B-dev",
                "intent": "Implement the ready backend API",
                "attach": "message_ids",
                "attach_message_ids": ["assistant-a"]
            }),
        ));

        let _ = {
            let mut guard = super::session_store().lock().expect("session lock");
            std::mem::replace(&mut *guard, previous_store)
        };

        let resp = response.expect("chat_handoff dispatch");
        assert_eq!(resp.route, "chat-handoff");
        assert_eq!(resp.status, "ok");
        let plan = resp.dispatch_plan.as_ref().expect("plan present");
        assert_eq!(plan.tool_id, "chat_handoff");
        assert_eq!(plan.llm_tool_call.mode, "handoff");
        assert!(plan.execute_allowed);
        assert_eq!(plan.safety_gate, "allow-auto");

        let handoffs =
            super::query_chat_handoffs_sqlite(&db_path, "room-1", 10, None).expect("handoffs");
        assert_eq!(handoffs.len(), 1);
        assert_eq!(handoffs[0].from_agent_id, "agent-a");
        assert_eq!(handoffs[0].to_agent_id, "agent-b");
        assert_eq!(handoffs[0].status, "delivered");

        let audit_path = data_dir.join("tool-audit.jsonl");
        let raw = std::fs::read_to_string(&audit_path).expect("audit file exists");
        assert!(raw.lines().any(|line| line.contains("\"caller\":\"llm\"")
            && line.contains("\"tool_name\":\"chat_handoff\"")));
    }

    #[test]
    fn tool_execution_policy_defaults_and_shell_timeout_injection() {
        use super::{ConfigTool, ConfigToolExecution, WorkspaceConfig};
        let _guard = config_test_guard();
        let temp = tempfile::tempdir().expect("tempdir");
        let patched = WorkspaceConfig {
            workspace: super::ConfigWorkspace {
                default_dir: Some(temp.path().display().to_string()),
                ..Default::default()
            },
            tool: ConfigTool {
                execution: ConfigToolExecution {
                    default_timeout_ms: 1_234,
                    max_concurrency: 2,
                    max_feedback_rounds: 6,
                    command_gate_enabled: true,
                },
                ..ConfigTool::default()
            },
            ..WorkspaceConfig::default()
        };
        let prev = {
            let mut guard = super::workspace_config().lock().expect("lock");
            std::mem::replace(&mut *guard, patched)
        };
        let prev_workspace = {
            let mut guard = super::workspace_state()
                .lock()
                .expect("workspace state lock");
            std::mem::replace(&mut guard.current, temp.path().to_path_buf())
        };

        let policy = super::tool_execution_policy();
        assert_eq!(policy.default_timeout_ms, 1_234);
        assert_eq!(policy.max_concurrency, 2);
        assert_eq!(policy.max_feedback_rounds, 6);

        let bash = super::runtime_tool_input_with_defaults(
            "bash",
            &serde_json::json!({ "command": "echo hi" }),
        );
        assert_eq!(bash["timeout"].as_u64(), Some(1_234));
        assert_eq!(
            bash["cwd"].as_str(),
            Some(temp.path().to_string_lossy().as_ref())
        );
        let powershell = super::runtime_tool_input_with_defaults(
            "PowerShell",
            &serde_json::json!({ "command": "Write-Output hi", "timeout": 99 }),
        );
        assert_eq!(powershell["timeout"].as_u64(), Some(99));
        assert_eq!(
            powershell["cwd"].as_str(),
            Some(temp.path().to_string_lossy().as_ref())
        );
        let nested_raw_powershell = super::runtime_tool_input_with_defaults(
            "PowerShell",
            &serde_json::json!({
                "raw": serde_json::json!({
                    "raw": serde_json::json!({
                        "command": "Write-Output nested"
                    }).to_string()
                }).to_string(),
                "timeout": 77
            }),
        );
        assert_eq!(
            nested_raw_powershell["command"].as_str(),
            Some("Write-Output nested")
        );
        assert_eq!(nested_raw_powershell["timeout"].as_u64(), Some(77));
        let repl = super::runtime_tool_input_with_defaults(
            "REPL",
            &serde_json::json!({ "language": "python", "code": "print(1)" }),
        );
        assert_eq!(repl["timeout_ms"].as_u64(), Some(1_234));
        let write = super::runtime_tool_input_with_defaults(
            "write_file",
            &serde_json::json!({ "path": "relative-tool-output.txt", "content": "ok" }),
        );
        assert_eq!(
            write["path"].as_str(),
            Some(
                temp.path()
                    .join("relative-tool-output.txt")
                    .to_string_lossy()
                    .as_ref()
            )
        );

        let _ = std::mem::replace(&mut *super::workspace_config().lock().expect("lock"), prev);
        let _ = std::mem::replace(
            &mut super::workspace_state()
                .lock()
                .expect("workspace state lock")
                .current,
            prev_workspace,
        );
    }

    #[test]
    fn run_model_tool_dispatch_sleep_respects_runtime_timeout() {
        use super::{ConfigTool, ConfigToolExecution, WorkspaceConfig};
        let _guard = config_test_guard();
        let tmp = tempfile::tempdir().expect("tempdir");
        let data_dir = tmp.path().join(super::DATA_DIR_NAME);
        std::fs::create_dir_all(&data_dir).expect("mkdir");
        let _session_db_env = scoped_session_db_env(&data_dir);

        let patched = WorkspaceConfig {
            workspace: super::ConfigWorkspace {
                default_dir: Some(tmp.path().display().to_string()),
                ..Default::default()
            },
            tool: ConfigTool {
                execution: ConfigToolExecution {
                    default_timeout_ms: 20,
                    max_concurrency: 2,
                    max_feedback_rounds: 8,
                    command_gate_enabled: true,
                },
                ..ConfigTool::default()
            },
            ..WorkspaceConfig::default()
        };
        let prev = {
            let mut guard = super::workspace_config().lock().expect("lock");
            std::mem::replace(&mut *guard, patched)
        };

        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let resp = rt
            .block_on(super::run_model_tool_dispatch(
                "Sleep",
                &serde_json::json!({ "duration_ms": 200 }),
            ))
            .expect("timeout should still map to dispatch response");

        assert_eq!(resp.route, "runtime-timeout");
        assert_eq!(resp.status, "timeout");
        assert!(resp
            .notes
            .iter()
            .any(|note| note.contains("exceeded") && note.contains("runtime deadline")));

        let _ = std::mem::replace(&mut *super::workspace_config().lock().expect("lock"), prev);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn dispatch_model_tool_calls_parallel_preserves_order() {
        use super::{ConfigTool, ConfigToolExecution, WorkspaceConfig};
        let _guard = config_test_guard();
        let tmp = tempfile::tempdir().expect("tempdir");
        let data_dir = tmp.path().join(super::DATA_DIR_NAME);
        std::fs::create_dir_all(&data_dir).expect("mkdir");
        let _session_db_env = scoped_session_db_env(&data_dir);

        use std::io::Write;
        let first = tmp.path().join("first.txt");
        let second = tmp.path().join("second.txt");
        std::fs::File::create(&first)
            .expect("create first")
            .write_all(b"first-content")
            .expect("write first");
        std::fs::File::create(&second)
            .expect("create second")
            .write_all(b"second-content")
            .expect("write second");

        let patched = WorkspaceConfig {
            workspace: super::ConfigWorkspace {
                default_dir: Some(tmp.path().display().to_string()),
                ..Default::default()
            },
            tool: ConfigTool {
                execution: ConfigToolExecution {
                    default_timeout_ms: 5_000,
                    max_concurrency: 2,
                    max_feedback_rounds: 8,
                    command_gate_enabled: true,
                },
                ..ConfigTool::default()
            },
            ..WorkspaceConfig::default()
        };
        let prev = {
            let mut guard = super::workspace_config().lock().expect("lock");
            std::mem::replace(&mut *guard, patched)
        };

        let results = super::dispatch_model_tool_calls_parallel(
            vec![
                (
                    "toolu-1".into(),
                    "read_file".into(),
                    serde_json::json!({ "path": first.to_string_lossy() }),
                ),
                (
                    "toolu-2".into(),
                    "read_file".into(),
                    serde_json::json!({ "path": second.to_string_lossy() }),
                ),
            ],
            "[TOOL-LOOP-TEST]",
            None,
            Some("turn-test".into()),
            None,
        )
        .await;

        assert_eq!(results.len(), 2);
        assert_eq!(results[0].tool_use_id, "toolu-1");
        assert_eq!(results[1].tool_use_id, "toolu-2");
        assert_eq!(results[0].name, "read_file");
        assert_eq!(results[1].name, "read_file");
        assert!(!results[0].is_error);
        assert!(!results[1].is_error);
        assert_eq!(
            results[0].input["path"].as_str(),
            Some(first.to_string_lossy().as_ref())
        );

        let _ = std::mem::replace(&mut *super::workspace_config().lock().expect("lock"), prev);
    }

