    #[test]
    fn tool_audit_append_and_read_roundtrip() {
        let _guard = config_test_guard();
        let tmp = tempfile::tempdir().expect("tempdir");
        let data_dir = tmp.path().join(super::DATA_DIR_NAME);
        std::fs::create_dir_all(&data_dir).expect("mkdir .coolzhu");
        let _session_db_env = scoped_session_db_env(&data_dir);
        let audit_path_owned = data_dir.join("tool-audit.jsonl");

        // 直接写一"audit
        let invoke = super::ToolInvoke {
            call_id: "audit-unique-1".into(),
            tool_name: "write_file".into(),
            input: serde_json::json!({
                "path": "x",
                "content": "SECRET_KEY=long-val-should-not-leak"
            }),
            caller: super::ToolCaller::WebUi,
            workspace_id: "ws-audit".into(),
            session_id: Some("ses-audit".into()),
            user_authorized: false,
            user_confirmed_twice: false,
        };
        let outcome = super::ToolOutcome {
            call_id: invoke.call_id.clone(),
            tool_name: invoke.tool_name.clone(),
            status: super::ToolOutcomeStatus::Ok,
            output: serde_json::Value::Null,
            summary_text: "audit_write_ok".into(),
            elapsed_ms: 7,
            permission_gate: runtime::PermissionGateReport {
                required: super::PermissionMode::WorkspaceWrite,
                decision: super::PermissionDecision::AllowAuto,
                reason: "inside-workspace".into(),
                protected_match: None,
                workspace_relative: true,
                affected_paths: vec!["x".into()],
            },
            evidence: None,
        };
        super::append_tool_audit_record(&invoke, &outcome);

        // 内容断言：文件存"+ 不泄"SECRET_KEY 原。
        let raw = std::fs::read_to_string(&audit_path_owned).expect("read audit");
        assert!(
            !raw.contains("long-val-should-not-leak"),
            "审计日志禁止落原 input "
        );
        assert!(raw.contains("audit-unique-1"));
        assert!(raw.contains("write_file"));
        assert!(raw.contains("path=len"));

        // api_tools_audit 能读"1 。
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let Json(list) = rt.block_on(super::api_tools_audit(axum::extract::Query(
            super::ToolAuditQuery { limit: Some(10) },
        )));
        // 其它并行测试可能同时触发真实工具审计；只按本测试唯一 call_id
        // 验证目标记录，避免把进程级审计活动误判为本用例失败。
        let matching = list
            .entries
            .iter()
            .filter(|entry| entry.call_id == "audit-unique-1")
            .collect::<Vec<_>>();
        assert_eq!(matching.len(), 1, "本测试审计记录应恰好出现一次");
        assert_eq!(matching[0].status, "ok");
        assert!(!matching[0]
            .input_summary
            .contains("long-val-should-not-leak"));
    }

