    #[test]
    fn rejected_model_tool_writes_terminal_result_to_original_room_and_session() {
        let _guard = config_test_guard();
        super::clear_pending_approvals_for_test();
        let mut session = super::seed_session();
        session.id = "ses-tool-terminal".into();
        session.messages.clear();
        let room_id = "room-tool-terminal";
        let _store_guard = SessionStoreTestGuard::install(super::PersistedSessionState {
            sessions: vec![session],
            active_session_id: Some("ses-tool-terminal".into()),
            active_vision_session_id: None,
            chat_rooms: vec![super::PersistedChatRoom {
                id: room_id.into(),
                name: "Tool Terminal Room".into(),
                created_at: 1,
                updated_at: 1,
                messages: Vec::new(),
            }],
            active_chat_room_id: Some(room_id.into()),
        });
        let call_id = "call-room-terminal-reject".to_string();
        let invoke = super::ToolInvoke {
            call_id: call_id.clone(),
            tool_name: "write_file".into(),
            input: serde_json::json!({"path": "a.txt", "content": "x"}),
            caller: super::ToolCaller::Llm,
            workspace_id: "ws-room-terminal".into(),
            session_id: Some("ses-tool-terminal".into()),
            user_authorized: false,
            user_confirmed_twice: false,
        };
        let gate = runtime::PermissionGateReport {
            required: super::PermissionMode::WorkspaceWrite,
            decision: super::PermissionDecision::RequireApproval,
            reason: "approval needed".into(),
            protected_match: None,
            workspace_relative: true,
            affected_paths: vec!["a.txt".into()],
        };
        super::enqueue_pending_approval_for_room(&call_id, &invoke, &gate, Some(room_id));
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let _ = rt
            .block_on(super::api_tools_reject(Json(super::RejectRequest {
                call_id,
                reason: Some("用户拒绝测试".into()),
                session_id: Some("ses-tool-terminal".into()),
                chat_room_id: Some(room_id.into()),
                ..Default::default()
            })))
            .expect("reject");

        let store = super::session_store().lock().expect("session store");
        let room_message = store
            .state
            .chat_rooms
            .iter()
            .find(|room| room.id == room_id)
            .and_then(|room| room.messages.last())
            .expect("room terminal message");
        assert_eq!(room_message.role, "assistant");
        assert_eq!(room_message.kind, "tool-result");
        assert!(room_message.content.contains("权限拒绝"));
        assert!(room_message.content.contains("用户拒绝测试"));
        let session_message = store.state.sessions[0]
            .messages
            .last()
            .expect("session terminal message");
        assert_eq!(session_message.id, room_message.id);
    }

    #[test]
    fn pending_approval_approve_once_executes_original_write_file() {
        let _guard = config_test_guard();
        super::clear_pending_approvals_for_test();
        super::clear_session_grants_for_test();
        let temp = tempfile::tempdir().expect("tempdir");
        let patched = super::WorkspaceConfig {
            workspace: super::ConfigWorkspace {
                default_dir: Some(temp.path().display().to_string()),
                ..Default::default()
            },
            ..Default::default()
        };
        let prev_config = {
            let mut guard = super::workspace_config().lock().expect("lock");
            std::mem::replace(&mut *guard, patched)
        };
        let prev_workspace = {
            let mut guard = super::workspace_state()
                .lock()
                .expect("workspace state lock");
            std::mem::replace(&mut guard.current, temp.path().to_path_buf())
        };

        let target = temp.path().join("approved-write.txt");
        let call_id = "call-approve-executes-write-file".to_string();
        let invoke = super::ToolInvoke {
            call_id: call_id.clone(),
            tool_name: "write_file".into(),
            input: serde_json::json!({
                "path": target.to_string_lossy(),
                "content": "approved-write-ok"
            }),
            caller: super::ToolCaller::Llm,
            workspace_id: super::workspace_identity(temp.path()),
            session_id: Some("ses-approval-exec".into()),
            user_authorized: false,
            user_confirmed_twice: false,
        };
        let gate = runtime::PermissionGateReport {
            required: super::PermissionMode::WorkspaceWrite,
            decision: super::PermissionDecision::RequireApproval,
            reason: "workspace-write-needs-approval".into(),
            protected_match: None,
            workspace_relative: true,
            affected_paths: vec![target.to_string_lossy().to_string()],
        };
        super::enqueue_pending_approval(&call_id, &invoke, &gate);

        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let Json(resp) = rt
            .block_on(super::api_tools_approve(Json(super::ApproveRequest {
                call_id: call_id.clone(),
                scope: Some("once".into()),
                confirmed_twice: false,
                session_id: Some("ses-approval-exec".into()),
                ..Default::default()
            })))
            .expect("approve ok");

        let _ = std::mem::replace(
            &mut *super::workspace_config().lock().expect("lock"),
            prev_config,
        );
        let _ = std::mem::replace(
            &mut super::workspace_state()
                .lock()
                .expect("workspace state lock")
                .current,
            prev_workspace,
        );

        assert_eq!(resp.scope, "once");
        assert_eq!(
            std::fs::read_to_string(&target).expect("approved write target"),
            "approved-write-ok"
        );
    }

    #[test]
    fn pending_approval_session_scope_grants_future_preview() {
        let call_id = "call-session-unique-bbb".to_string();
        let invoke = super::ToolInvoke {
            call_id: call_id.clone(),
            tool_name: "bash".into(),
            input: serde_json::json!({}),
            caller: super::ToolCaller::Llm,
            workspace_id: "ws-B-unique".into(),
            session_id: Some("ses-9-unique".into()),
            user_authorized: false,
            user_confirmed_twice: false,
        };
        let gate = runtime::PermissionGateReport {
            required: super::PermissionMode::DangerFullAccess,
            decision: super::PermissionDecision::RequireApproval,
            reason: "danger-inside-needs-first-approval".into(),
            protected_match: None,
            workspace_relative: true,
            affected_paths: vec![],
        };
        super::enqueue_pending_approval(&call_id, &invoke, &gate);

        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let req = super::ApproveRequest {
            call_id: call_id.clone(),
            scope: Some("session".into()),
            confirmed_twice: false,
            session_id: Some("ses-9-unique".into()),
            ..Default::default()
        };
        let Json(resp) = rt
            .block_on(super::api_tools_approve(Json(req)))
            .expect("approve session");
        assert_eq!(resp.scope, "session");
        assert_eq!(resp.ttl_secs, Some(super::SESSION_GRANT_TTL.as_secs()));

        // "workspace/session/tool 的后"preview 应该拿到 session_authorized = true
        let view = super::session_grant_view_for("ws-B-unique", Some("ses-9-unique"), "bash");
        assert!(view.session_authorized);
        assert!(!view.session_confirmed_twice);

        // 不同 tool / session / workspace 不共享授。
        assert!(
            !super::session_grant_view_for("ws-B-unique", Some("ses-9-unique"), "write_file")
                .session_authorized
        );
        assert!(
            !super::session_grant_view_for("ws-B-unique", Some("ses-other-unique"), "bash")
                .session_authorized
        );
        assert!(
            !super::session_grant_view_for("ws-X-unique", Some("ses-9-unique"), "bash")
                .session_authorized
        );
    }

    #[test]
    fn pending_approval_cannot_be_consumed_outside_session_or_room_scope() {
        super::clear_pending_approvals_for_test();
        let call_id = "call-scope-isolation-unique-ddd".to_string();
        let room_id = "room-scope-a";
        let invoke = super::ToolInvoke {
            call_id: call_id.clone(),
            tool_name: "write_file".into(),
            input: serde_json::json!({"path": "scope-a.txt", "content": "scope-a"}),
            caller: super::ToolCaller::Llm,
            workspace_id: "ws-scope-a".into(),
            session_id: Some("session-scope-a".into()),
            user_authorized: false,
            user_confirmed_twice: false,
        };
        let gate = runtime::PermissionGateReport {
            required: super::PermissionMode::WorkspaceWrite,
            decision: super::PermissionDecision::RequireApproval,
            reason: "scope isolation test".into(),
            protected_match: None,
            workspace_relative: true,
            affected_paths: vec!["scope-a.txt".into()],
        };
        super::enqueue_pending_approval_for_room(&call_id, &invoke, &gate, Some(room_id));

        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let wrong_session = rt
            .block_on(super::api_tools_reject(Json(super::RejectRequest {
                call_id: call_id.clone(),
                reason: Some("wrong session".into()),
                session_id: Some("session-scope-b".into()),
                chat_room_id: Some(room_id.into()),
            })))
            .expect_err("不同 session 不得消费 pending");
        assert_eq!(wrong_session.0, super::StatusCode::NOT_FOUND);

        let wrong_room = rt
            .block_on(super::api_tools_approve(Json(super::ApproveRequest {
                call_id: call_id.clone(),
                scope: Some("once".into()),
                confirmed_twice: false,
                session_id: Some("session-scope-a".into()),
                chat_room_id: Some("room-scope-b".into()),
            })))
            .expect_err("不同 room 不得消费 pending");
        assert_eq!(wrong_room.0, super::StatusCode::NOT_FOUND);

        let Json(filtered) = rt.block_on(super::api_tools_pending_for_scope(
            super::PendingApprovalsQuery {
                session_id: Some("session-scope-a".into()),
                chat_room_id: Some(room_id.into()),
            },
        ));
        assert!(filtered.pending.iter().any(|record| record.call_id == call_id));

        let Json(_) = rt
            .block_on(super::api_tools_reject(Json(super::RejectRequest {
                call_id,
                reason: Some("cleanup".into()),
                session_id: Some("session-scope-a".into()),
                chat_room_id: Some(room_id.into()),
            })))
            .expect("正确 session/room 应可消费 pending");
        super::clear_pending_approvals_for_test();
    }

    #[test]
    fn full_access_grant_requires_risk_ack_and_authorizes_all_tools_for_ttl() {
        let _guard = config_test_guard();
        super::clear_session_grants_for_test();
        let missing_ack = super::FullAccessGrantRequest {
            session_id: Some("ses-full".to_string()),
            ttl_secs: Some(120),
            confirmed_twice: true,
            risk_acknowledged: false,
        };
        assert!(super::grant_full_access_for_session("ws-full", missing_ack).is_err());

        let missing_confirm = super::FullAccessGrantRequest {
            session_id: Some("ses-full".to_string()),
            ttl_secs: Some(120),
            confirmed_twice: false,
            risk_acknowledged: true,
        };
        assert!(super::grant_full_access_for_session("ws-full", missing_confirm).is_err());

        let status = super::grant_full_access_for_session(
            "ws-full",
            super::FullAccessGrantRequest {
                session_id: Some("ses-full".to_string()),
                ttl_secs: Some(120),
                confirmed_twice: true,
                risk_acknowledged: true,
            },
        )
        .expect("full access grant");
        assert!(status.active);
        assert_eq!(status.session_id.as_deref(), Some("ses-full"));
        assert!(status.ttl_secs_remaining <= 120);
        assert!(status.warning.contains("完全允许操作用户电脑文件"));

        let bash = super::session_grant_view_for("ws-full", Some("ses-full"), "bash");
        assert!(bash.session_authorized);
        assert!(bash.session_confirmed_twice);
        let write_file = super::session_grant_view_for("ws-full", Some("ses-full"), "write_file");
        assert!(write_file.session_authorized);
        assert!(write_file.session_confirmed_twice);
        assert!(
            !super::session_grant_view_for("ws-full", Some("other-session"), "bash")
                .session_authorized
        );

        let revoked = super::revoke_full_access_for_session("ws-full", Some("ses-full"));
        assert!(!revoked.active);
        assert!(
            !super::session_grant_view_for("ws-full", Some("ses-full"), "bash").session_authorized
        );
    }

    #[test]
    fn chat_room_permission_profile_persists_and_isolated_by_room() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let connection = super::open_session_connection(&db_path).expect("open sqlite");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute(
                "INSERT INTO chat_rooms(id, name, created_at, updated_at) VALUES (?1, ?2, 1, 1)",
                rusqlite::params!["room-full", "Full room"],
            )
            .expect("insert full room");
        connection
            .execute(
                "INSERT INTO chat_rooms(id, name, created_at, updated_at) VALUES (?1, ?2, 1, 1)",
                rusqlite::params!["room-default", "Default room"],
            )
            .expect("insert default room");
        drop(connection);

        super::set_chat_room_permission_profile_sqlite(
            &db_path,
            "room-full",
            super::ROOM_PERMISSION_FULL_ACCESS,
        )
        .expect("persist full access");

        assert_eq!(
            super::chat_room_permission_profile_sqlite(&db_path, "room-full")
                .expect("read profile"),
            super::ROOM_PERMISSION_FULL_ACCESS
        );
        assert_eq!(
            super::chat_room_permission_profile_sqlite(&db_path, "room-default")
                .expect("read default profile"),
            super::ROOM_PERMISSION_WORKSPACE_WRITE
        );
        assert!(
            super::room_permission_grant_view_for_path(&db_path, Some("room-full"))
                .session_authorized
        );
        assert!(
            !super::room_permission_grant_view_for_path(&db_path, Some("room-default"))
                .session_authorized
        );
        assert!(!super::room_permission_grant_view_for_path(&db_path, None).session_authorized);
    }

    #[test]
    fn chat_room_diagnostics_preferences_persist_and_default_safe() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let connection = super::open_session_connection(&db_path).expect("open sqlite");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute(
                "INSERT INTO chat_rooms(id, name, created_at, updated_at) VALUES (?1, ?2, 1, 1)",
                rusqlite::params!["room-diag", "Diag room"],
            )
            .expect("insert room");
        drop(connection);
        let initial = super::chat_room_diagnostics_record_sqlite(&db_path, "room-diag")
            .expect("read default");
        assert_eq!(initial, (true, false, true, true, None));
        super::set_chat_room_diagnostics_sqlite(
            &db_path,
            "room-diag",
            &super::ChatRoomDiagnosticsUpdateRequest {
                enabled: Some(false),
                auto_refresh: Some(true),
                show_stream_interrupts: Some(false),
                show_details: Some(true),
                real_llm_enabled: Some(false),
                llm_tools_enabled: Some(true),
                computer_use_enabled: Some(false),
            },
        )
        .expect("persist preferences");
        let saved =
            super::chat_room_diagnostics_record_sqlite(&db_path, "room-diag").expect("read saved");
        assert_eq!(saved.0, false);
        assert_eq!(saved.1, true);
        assert_eq!(saved.2, false);
        assert_eq!(saved.3, true);
        assert!(saved.4.is_some());
        assert_eq!(
            super::chat_room_capabilities_sqlite(&db_path, "room-diag").expect("read capabilities"),
            (false, true, false)
        );
    }

