    #[test]
    fn registry_executor_runs_read_file_through_runtime() {
        // 端到端：runtime_tool_execute 评估权限 "调用 RegistryExecutor
        // "真实 tools::execute_tool("read_file") 读取临时文件。
        use std::io::Write;

        let temp = tempfile::tempdir().expect("tempdir");
        let file_path = temp.path().join("sample.txt");
        std::fs::File::create(&file_path)
            .expect("create file")
            .write_all(b"hello-phase-c1")
            .expect("write body");

        let exec = super::RegistryExecutor::with_allowlist(vec!["read_file"]);
        let executors: [&dyn super::ToolInvocationExecutor; 1] = [&exec];
        let input = serde_json::json!({ "path": file_path.to_string_lossy() });
        let invoke = super::ToolInvoke {
            call_id: "c-read".into(),
            tool_name: "read_file".into(),
            input: input.clone(),
            caller: super::ToolCaller::Llm,
            workspace_id: "ws-test".into(),
            session_id: None,
            user_authorized: false,
            user_confirmed_twice: false,
        };
        let rules = super::default_protected_rules();
        let ctx = super::RuntimeToolContext {
            workspace_root: temp.path(),
            required_permission: super::PermissionMode::ReadOnly,
            path_targets: super::extract_path_targets("read_file", &input),
            protected_rules: &rules,
            session_grant: super::SessionGrantView::default(),
            executors: &executors,
            profile: super::PermissionProfile::OutsideApproval,
        };
        let outcome = super::runtime_tool_execute(invoke, &ctx);
        assert_eq!(outcome.status, super::ToolOutcomeStatus::Ok);
        assert_eq!(
            outcome.permission_gate.decision,
            super::PermissionDecision::AllowAuto,
            "ReadOnly 必须直"
        );
        assert!(outcome
            .output
            .as_str()
            .map(|s| s.contains("hello-phase-c1"))
            .unwrap_or(false));
    }

