    #[test]
    fn estimate_bead_tokens_mixed_cjk_ascii() {
        // 空字符串 "0
        assert_eq!(super::estimate_bead_tokens(""), 0);
        // 非空但极""至少返回 1
        assert_eq!(super::estimate_bead_tokens("x"), 1);
        // "ASCII"2 字符 × 0.25 = 3
        assert_eq!(super::estimate_bead_tokens("hello world!"), 3);
        // "CJK" 字符 × 0.55 = 4.4 "ceil 5
        assert_eq!(super::estimate_bead_tokens("用户偏好尾调用模"), 5);
        // 混合" CJK(2.2) + 5 ASCII(1.25) = 3.45 "ceil 4
        assert_eq!(super::estimate_bead_tokens("决定使用 FTS5"), 4);
    }

