    fn diagnostics_llm_repair_suggestions_include_base_url_override() {
        let diagnostics = super::build_agent_diagnostics(
            "agent-test".to_string(),
            "DeepSeek".to_string(),
            "deepseek-chat".to_string(),
            Some(api::ProviderKind::DeepSeek),
            api::ProviderKind::DeepSeek,
            true,
            None,
            None,
        );
        let mut agent = super::AgentHealthDto {
            agent_id: diagnostics.agent_id,
            name: "agent-test".to_string(),
            provider_label: diagnostics.provider_label,
            provider_kind: diagnostics.provider_kind,
            selected_provider_kind: diagnostics.selected_provider_kind,
            detected_provider_kind: diagnostics.detected_provider_kind,
            provider_match: diagnostics.provider_match,
            provider_slug: diagnostics.provider_slug,
            model: diagnostics.model,
            canonical_model: diagnostics.canonical_model,
            api_model_id: diagnostics.api_model_id,
            base_url: "http://127.0.0.1:11434/v1".to_string(),
            base_url_default: Some("https://api.deepseek.com/v1".to_string()),
            base_url_env: Some("DEEPSEEK_BASE_URL".to_string()),
            base_url_env_present: true,
            base_url_source: "DEEPSEEK_BASE_URL".to_string(),
            base_url_matches_default: false,
            api_key_present: diagnostics.api_key_present,
            api_key_source: diagnostics.api_key_source,
            api_key_status: diagnostics.api_key_status,
            env_keys: diagnostics.env_keys,
            recommended_models: diagnostics.recommended_models,
            provider_status: "warn".to_string(),
            provider_issue: Some("Effective base_url differs from default.".to_string()),
        };
        let suggestions = super::llm_repair_suggestions(&[agent.clone()]);
        assert!(suggestions
            .iter()
            .any(|suggestion| suggestion.message.contains("DEEPSEEK_BASE_URL")));
        assert!(suggestions
            .iter()
            .any(|suggestion| suggestion.message.contains("https://api.deepseek.com/v1")));

        agent.api_key_present = false;
        agent.provider_status = "error".to_string();
        let suggestions = super::llm_repair_suggestions(&[agent]);
        assert!(suggestions
            .iter()
            .any(|suggestion| suggestion.priority == "high"
                && suggestion.message.contains("API key")));
    }

