    #[test]
    fn web_frontend_media_and_logs_are_not_top_level_workbench_windows() {
        for forbidden in [
            "data-window-target=\"media\"",
            "data-window-target=\"logs\"",
            "data-window-id=\"media\"",
            "data-window-id=\"logs\"",
            "data-window-theme=\"crystal-hall\"",
            "data-window-theme=\"maintenance-bay\"",
        ] {
            assert!(
                !WEB_INDEX_HTML.contains(forbidden),
                "media/logs must be merged into other windows, not rendered as top-level workbench UI: {forbidden}"
            );
        }
        for forbidden_style in [
            ".media-workbench-window",
            ".logs-workbench-window",
            ".media-window",
            ".media-grid",
            ".media-screen",
            ".media-playlist",
            ".logs-window-panel",
        ] {
            assert!(
                !WEB_STYLES_CSS.contains(forbidden_style),
                "stale standalone media/logs window styles must be removed with their DOM: {forbidden_style}"
            );
        }
        assert!(WEB_INDEX_HTML.contains("data-role=\"composer-attachments\""));
        assert!(WEB_INDEX_HTML.contains("data-role=\"module-selfcheck\""));
        assert!(WEB_APP_JS.contains("function renderAttachments"));
        assert!(WEB_APP_JS.contains("function diagnosticsWindowInitialize"));
        assert!(
            !WEB_APP_JS.contains("[\"attachments\", mediaWindowLoadAttachments]"),
            "media library must not eager-load as an independent window refresh target"
        );
    }

