    #[cfg(windows)]
    #[test]
    fn web_listener_socket_can_be_marked_non_inheritable() {
        use std::os::windows::io::AsRawSocket;

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        windows_process_guard::make_socket_non_inheritable(listener.as_raw_socket()).unwrap();

        assert!(
            !windows_process_guard::socket_is_inheritable(listener.as_raw_socket()).unwrap(),
            "web listener socket must not leak into local-model child processes"
        );
    }

    #[cfg(windows)]
    #[test]
    fn kill_on_close_job_terminates_assigned_child() {
        let job = windows_process_guard::ChildProcessJob::new_kill_on_close().unwrap();
        let mut child = std::process::Command::new("cmd")
            .args(["/C", "ping -t 127.0.0.1 >NUL"])
            .spawn()
            .unwrap();
        job.assign(&child).unwrap();

        drop(job);

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        while std::time::Instant::now() < deadline {
            if child.try_wait().unwrap().is_some() {
                return;
            }
            std::thread::sleep(std::time::Duration::from_millis(50));
        }
        let _ = child.kill();
        panic!("assigned child survived after the kill-on-close Job Object was dropped");
    }

