    #[test]
    fn realtime_streaming_risk_lists_full_streaming_readiness_gates() {
        let risk = super::realtime_streaming_risk(
            &super::AudioHealthSnapshot {
                stt_available: true,
                tts_available: true,
                tts_backend: "piper".to_string(),
                index_tts_base_url: None,
                index_tts_available: false,
                error: None,
                checked_at_ms: 0,
            },
            &super::RealtimeBargeInPolicy::default(),
        );

        assert!(!risk.full_streaming_ready);
        assert_eq!(risk.readiness_gates.len(), 4);
        assert!(risk
            .readiness_gates
            .iter()
            .any(|gate| gate.id == "provider_native_partial_asr" && !gate.ready));
        assert!(risk
            .readiness_gates
            .iter()
            .any(|gate| gate.id == "far_end_reference_aec" && !gate.ready));
        assert!(risk
            .readiness_gates
            .iter()
            .any(|gate| gate.id == "realtime_model_adapter" && !gate.ready));
        assert!(risk
            .readiness_gates
            .iter()
            .any(|gate| gate.id == "streaming_tts_output" && !gate.ready));
    }

