            socket
                .write_all(
                    b"HTTP/1.1 200 OK\r\nContent-Type: audio/wav\r\nTransfer-Encoding: chunked\r\n\r\n",
                )
                .await
                .expect("write tts probe response headers");
            socket
                .write_all(format!("{:x}\r\n", chunk.len()).as_bytes())
                .await
                .expect("write tts probe chunk length");
