    #[tokio::test]
    async fn realtime_barge_in_evaluate_emits_unified_decision_event() {
        let _guard = realtime_audio_test_guard().await;
        if let Ok(mut realtime) = super::realtime_session_state().lock() {
            *realtime = super::RealtimeSessionState::default();
            realtime.running = true;
            realtime.session_id = Some("rt-barge-event".to_string());
            realtime.audio_out_state = "speaking".to_string();
        }
        let mut receiver = super::realtime_session_event_bus().subscribe();

        let axum::Json(response) = super::api_realtime_barge_in_evaluate(axum::Json(
            super::RealtimeBargeInEvaluateRequest {
                asr_text: Some("等一下 不对".to_string()),
                asr_confidence: Some(0.91),
                vad_active: Some(true),
                tts_playing: Some(true),
                echo_correlation: Some(0.01),
                speech_ms: Some(450),
                ..Default::default()
            },
        ))
        .await;
        assert!(response.should_interrupt);

        let event = tokio::time::timeout(std::time::Duration::from_secs(1), receiver.recv())
            .await
            .expect("barge-in decision event")
            .expect("valid barge-in decision event");
        assert_eq!(event.kind, "barge_in_decision");
        assert_eq!(event.session_id.as_deref(), Some("rt-barge-event"));
        assert_eq!(event.payload["should_interrupt"], json!(true));
        assert_eq!(
            event.payload["recommended_action"],
            json!("cancel_tts_and_model_output")
        );
    }

