        assert!(WEB_INDEX_HTML.contains("data-bind=\"realtime.session\""));
        assert!(WEB_INDEX_HTML.contains("data-action=\"realtime-session-start\""));
        assert!(WEB_INDEX_HTML.contains("data-action=\"realtime-session-stop\""));
        assert!(WEB_INDEX_HTML.contains("data-role=\"realtime-session-status\""));
        // Phase 3 S1：barge-in 评估面板（调试控件）已从设置窗口移除，前端不再暴露。
        assert!(!WEB_INDEX_HTML.contains("data-role=\"realtime-barge-scenario\""));
        assert!(!WEB_INDEX_HTML.contains("data-action=\"realtime-barge-evaluate\""));
        assert!(WEB_APP_JS.contains("function realtimeSessionStart"));
        assert!(WEB_APP_JS.contains("function realtimeSessionStop"));
        assert!(!WEB_APP_JS.contains("function realtimeBargeInEvaluate"));
        // 打断决策处理器仍在，供实时流水线（partial/最终事件）调用。
        assert!(WEB_APP_JS.contains("function handleRealtimeBargeInDecision"));
        assert!(WEB_APP_JS.contains("handleRealtimeBargeInDecision({"));
        assert!(WEB_APP_JS.contains("audioRealtimeResumeAfterTts = false;"));
