        assert!(WEB_MAIN_RS.contains("api_audio_realtime_stop().await"));
        assert!(WEB_APP_JS.contains("function buildRealtimeAudioConstraints"));
        assert!(WEB_APP_JS.contains("echoCancellation"));
        assert!(WEB_APP_JS.contains("noiseSuppression"));
        assert!(WEB_APP_JS.contains("autoGainControl"));
        assert!(WEB_MAIN_RS.contains("struct RealtimeSessionStatusResponse"));
        assert!(WEB_MAIN_RS.contains("main_state: String"));
        assert!(WEB_MAIN_RS.contains("vision_state: String"));
        assert!(WEB_MAIN_RS.contains("audio_in_state: String"));
        assert!(WEB_MAIN_RS.contains("audio_out_state: String"));
        assert!(WEB_MAIN_RS.contains("barge_in_state: String"));
        assert!(WEB_MAIN_RS.contains("barge_in_policy: RealtimeBargeInPolicy"));
