    #[test]
    fn mem002_bead_crud_and_signature() {
        let mut s = super::PersistedSession {
            id: "m2".to_string(),
            name: "m2".to_string(),
            provider: "t".to_string(),
            model: "m".to_string(),
            avatar: None,
            model_type: "text".to_string(),
            api_key_ref: String::new(),
            base_url: None,
            endpoint: None,
            reasoning_effort: "medium".to_string(),
            memory_beads: Vec::new(),
            created_at: 0,
            updated_at: 0,
            context_reset_at: 0,
            messages: Vec::new(),
        };
        s.memory_beads.push(super::MemoryBeadDto {
            id: "b1".to_string(),
            kind: "decision".to_string(),
            layer: "L2".to_string(),
            summary: "test".to_string(),
            source: "agent".to_string(),
            pinned: false,
            confidence: 0.9_f32,
            created_at: 1,
            ..MemoryBeadDto::default()
        });
        assert_eq!(s.memory_beads.len(), 1);
        s.memory_beads[0].summary = "updated".to_string();
        assert_eq!(s.memory_beads[0].summary, "updated");
        s.memory_beads.retain(|b| b.id != "b1");
        assert!(s.memory_beads.is_empty());

        let sig1 = super::memory_bead_signature("L2", "chat", "user", "hello");
        let sig2 = super::memory_bead_signature("L2", "chat", "user", "hello");
        assert_eq!(sig1, sig2);
    }

