    #[test]
    fn auto_memory_evaluator_archives_plain_chat_and_promotes_verified_experience() {
        let plain = super::ChatMessageDto {
            id: "plain".to_string(),
            author: "Agent A (model-a)".to_string(),
            role: "assistant".to_string(),
            target: "聊天".to_string(),
            content: "好的，我会继续处理".to_string(),
            kind: "assistant-reply".to_string(),
            attachments: Vec::new(),
        };
        let plain_decision =
            super::evaluate_auto_memory_candidate(&plain).expect("plain chat archived");
        assert_eq!(plain_decision.kind, "chat");
        assert_eq!(plain_decision.layer, "L4");
        assert!(plain_decision.confidence < 0.5);

        let verified = super::ChatMessageDto {
            id: "verified".to_string(),
            author: "Agent A (model-a)".to_string(),
            role: "assistant".to_string(),
            target: "聊天".to_string(),
            content: "修复完成；cargo test -p coolzhu-web-console 296 passed；live smoke PASS"
                .to_string(),
            kind: "assistant-reply".to_string(),
            attachments: Vec::new(),
        };
        let verified_decision =
            super::evaluate_auto_memory_candidate(&verified).expect("verified experience");
        assert_eq!(verified_decision.kind, "experience");
        assert_eq!(verified_decision.layer, "L3");
        assert!(verified_decision.confidence >= 0.74);

        let tool_summary = super::ChatMessageDto {
            id: "tool".to_string(),
            author: "Agent A (model-a)".to_string(),
            role: "assistant".to_string(),
            target: "工具结果".to_string(),
            content: "PASS live-session-tool-chain-open-8765".to_string(),
            kind: "tool-summary".to_string(),
            attachments: Vec::new(),
        };
        let tool_decision =
            super::evaluate_auto_memory_candidate(&tool_summary).expect("tool memory");
        assert_eq!(tool_decision.kind, "tool");
        assert_eq!(tool_decision.layer, "L2");
        assert!(tool_decision.confidence >= 0.76);
    }

