    #[test]
    fn context_lifecycle_auto_compact_adds_memory_floor_and_removes_goal_scratch() {
        let temp = tempfile::tempdir().expect("tempdir");
        let mut session = super::seed_session();
        session.id = "agent-context-lifecycle".to_string();
        session.memory_beads = vec![
            super::MemoryBeadDto {
                id: "goal-temp".to_string(),
                kind: "decision".to_string(),
                layer: "L2".to_string(),
                summary: "Goal phase reasoning. Assigned role: verifier. goal-artifacts/demo.html"
                    .to_string(),
                source: "chat-room:auto-extract".to_string(),
                pinned: false,
                confidence: 0.7,
                created_at: 1,
                ..super::MemoryBeadDto::default()
            },
            super::MemoryBeadDto {
                id: "keep".to_string(),
                kind: "experience".to_string(),
                layer: "L3".to_string(),
                summary: "Successful workspace write_file experience.".to_string(),
                source: "manual".to_string(),
                pinned: false,
                confidence: 0.9,
                created_at: 2,
                ..super::MemoryBeadDto::default()
            },
        ];
        let normal_message = super::PersistedChatMessage {
            content: "用户要求分析 clawd-on-desk-main，助手成功读取目录并写入分析文档。"
                .to_string(),
            ..persisted_role_message("normal", "assistant", "ok", 10)
        };
        let goal_scratch = super::PersistedChatMessage {
            id: "msg-goal-temp-1".to_string(),
            author: "test5 implementer".to_string(),
            role: "assistant".to_string(),
            target: "Goal phase reasoning".to_string(),
            content: "Goal phase implement. Assigned role: implementer. goal-artifacts/demo.html"
                .to_string(),
            kind: "reasoning".to_string(),
            attachments: Vec::new(),
            created_at: 11,
        };
        let mut store = super::SessionStore {
            path: temp.path().join("sessions.sqlite3"),
            legacy_json_path: temp.path().join("sessions.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: super::PersistedSessionState {
                sessions: vec![session],
                active_session_id: Some("agent-context-lifecycle".to_string()),
                active_vision_session_id: None,
                chat_rooms: vec![super::PersistedChatRoom {
                    id: "room-context-lifecycle".to_string(),
                    name: "Context lifecycle room".to_string(),
                    created_at: 1,
                    updated_at: 1,
                    messages: vec![normal_message, goal_scratch],
                }],
                active_chat_room_id: Some("room-context-lifecycle".to_string()),
            },
        };
        let policy = super::ContextLifecyclePolicy {
            auto_compact_percent: 80,
            compact_summary_max_messages: 8,
            compact_summary_max_chars: 600,
            ..super::ContextLifecyclePolicy::default()
        };
        let snapshot = super::ContextUsageSnapshot {
            source: super::ContextUsageSource::Remote,
            used_tokens: 112_000,
            context_tokens: 128_000,
            percent_tenths: 875,
            warning_reached: true,
            auto_compact_reached: true,
        };

        let result = store
            .apply_context_lifecycle_after_turn(
                "agent-context-lifecycle",
                "room-context-lifecycle",
                &snapshot,
                policy,
            )
            .expect("apply context lifecycle");

        assert!(result.compacted);
        assert_eq!(result.added_memory_beads, 1);
        assert_eq!(result.removed_goal_memory_beads, 1);
        assert_eq!(result.removed_goal_chat_messages, 1);
        let session = store
            .state
            .sessions
            .iter()
            .find(|s| s.id == "agent-context-lifecycle")
            .expect("session remains");
        assert!(session.context_reset_at > 0);
        assert!(session.memory_beads.iter().any(|bead| {
            bead.source == "context:auto-compact"
                && bead.kind == "compaction"
                && bead.summary.contains("clawd-on-desk-main")
                && !bead.summary.contains("goal-artifacts")
        }));
        assert!(session.memory_beads.iter().any(|bead| bead.id == "keep"));
        let room = store
            .state
            .chat_rooms
            .iter()
            .find(|room| room.id == "room-context-lifecycle")
            .expect("room remains");
        assert_eq!(room.messages.len(), 1);
        assert_eq!(room.messages[0].id, "normal");
    }

    #[test]
    fn context_builder_skips_goal_scratch_messages_even_before_cleanup() {
        let agent = context_test_agent();
        let normal_message = super::PersistedChatMessage {
            content: "普通聊天室消息应该进入下一轮上下文。".to_string(),
            ..persisted_role_message("normal-context", "assistant", "ok", 10)
        };
        let goal_scratch = super::PersistedChatMessage {
            id: "msg-goal-context-1".to_string(),
            author: "planner-agent".to_string(),
            role: "assistant".to_string(),
            target: "Goal phase reasoning".to_string(),
            content: "Goal phase planner details. Assigned role: planner. goal-artifacts/demo.html"
                .to_string(),
            kind: "reasoning".to_string(),
            attachments: Vec::new(),
            created_at: 11,
        };

        let assembly = super::build_context_assembly(
            &agent,
            &[normal_message, goal_scratch],
            "继续",
            &[],
            super::ContextBuildOptions {
                history_token_budget: 10_000,
                memory_token_budget: 1_200,
                max_prompt_tokens: 12_000,
                image_token_estimate: 512,
                max_memory_beads: 8,
                history_floor_millis: None,
                chat_room_id: None,
            },
        );
        let joined = assembly
            .messages
            .iter()
            .flat_map(|message| message.content.iter())
            .filter_map(|block| match block {
                api::InputContentBlock::Text { text } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>()
            .join("\n");

        assert!(joined.contains("普通聊天室消息"));
        assert!(!joined.contains("goal-artifacts"));
        assert!(!joined.contains("Assigned role"));
    }

