    #[test]
    fn scheduled_task_system_room_is_created_idempotently_without_activation() {
        let temp = tempfile::tempdir().expect("temp session store");
        let mut store = super::SessionStore {
            path: temp.path().join("session.sqlite3"),
            legacy_json_path: temp.path().join("session.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: scheduled_room_test_state(),
        };
        let active_before = store.active_chat_room_id();
        assert_eq!(active_before.as_deref(), Some("room-user-a"));

        {
            let summary = store.ensure_scheduled_task_system_room().expect("ensure");
            assert_eq!(summary.id, super::SCHEDULED_TASK_SYSTEM_ROOM_ID);
            assert_eq!(summary.name, "定时任务");
            assert!(!summary.active, "系统室不得被激活");
        }
        // 第二次调用幂等：不重复创建、不改变活动室。
        {
            let summary = store
                .ensure_scheduled_task_system_room()
                .expect("ensure idempotent");
            assert_eq!(summary.id, super::SCHEDULED_TASK_SYSTEM_ROOM_ID);
            let count = store
                .state
                .chat_rooms
                .iter()
                .filter(|room| room.id == super::SCHEDULED_TASK_SYSTEM_ROOM_ID)
                .count();
            assert_eq!(count, 1, "幂等：系统室只存在一个");
        }
        let active_after = store.active_chat_room_id();
        assert_eq!(active_after, active_before, "创建系统室不得改变活动室");
    }

    #[test]
    fn scheduled_task_system_room_is_excluded_from_eight_user_room_limit() {
        let _serial = config_test_guard();
        let _guard = SessionStoreTestGuard::install(scheduled_room_test_state());
        // 先幂等注入系统室。
        {
            let mut store = super::session_store().lock().expect("session store");
            store.ensure_scheduled_task_system_room().expect("ensure");
        }
        // 再创建 7 个用户室（已有 1 个用户室 + 1 个系统室 = 不应计入上限）。
        for index in 0..7 {
            let mut store = super::session_store().lock().expect("session store");
            store
                .create_chat_room(super::CreateChatRoomRequest { name: None })
                .expect(&format!("create user room {index}"));
        }
        // 此时用户室 = 8，系统室 = 1，总计 9 个室；仍可再创建第 9 个用户室吗？不行，
        // 用户室上限是 8。但系统室不计入，所以创建到第 8 个用户室不应报错。
        let user_room_count = super::session_store()
            .lock()
            .expect("session store")
            .state
            .chat_rooms
            .iter()
            .filter(|room| room.id != super::SCHEDULED_TASK_SYSTEM_ROOM_ID)
            .count();
        assert_eq!(user_room_count, 8, "用户室恰好 8 个（系统室不计入上限）");
        // 第 9 个用户室应被拒绝。
        let mut store = super::session_store().lock().expect("session store");
        let err = store
            .create_chat_room(super::CreateChatRoomRequest { name: None })
            .expect_err("第 9 个用户室应被拒绝");
        assert_eq!(err.0, super::StatusCode::BAD_REQUEST);
    }

    #[test]
    fn scheduled_task_system_room_rejects_rename_and_delete() {
        let _serial = config_test_guard();
        let _guard = SessionStoreTestGuard::install(scheduled_room_test_state());
        {
            let mut store = super::session_store().lock().expect("session store");
            store.ensure_scheduled_task_system_room().expect("ensure");
        }
        // 重命名被拒。
        {
            let mut store = super::session_store().lock().expect("session store");
            let err = store
                .update_chat_room(
                    super::SCHEDULED_TASK_SYSTEM_ROOM_ID,
                    super::UpdateChatRoomRequest {
                        name: Some("改名".to_string()),
                    },
                )
                .expect_err("系统室不可重命名");
            assert_eq!(err.0, super::StatusCode::BAD_REQUEST);
            let room = store
                .state
                .chat_rooms
                .iter()
                .find(|room| room.id == super::SCHEDULED_TASK_SYSTEM_ROOM_ID)
                .expect("system room present");
            assert_eq!(room.name, "定时任务", "重命名被拒后名称保持不变");
        }
        // 删除被拒。
        {
            let mut store = super::session_store().lock().expect("session store");
            let err = store
                .delete_chat_room(super::SCHEDULED_TASK_SYSTEM_ROOM_ID)
                .expect_err("系统室不可删除");
            assert_eq!(err.0, super::StatusCode::BAD_REQUEST);
            let still_present = store
                .state
                .chat_rooms
                .iter()
                .any(|room| room.id == super::SCHEDULED_TASK_SYSTEM_ROOM_ID);
            assert!(still_present, "删除被拒后系统室仍存在");
        }
    }

    #[test]
    fn scheduled_task_system_room_mirrors_goal_messages_preserving_ids_without_duplicates() {
        let _serial = config_test_guard();
        let _guard = SessionStoreTestGuard::install(scheduled_room_test_state());
        let message = super::ChatMessageDto {
            id: "goal-msg-1".to_string(),
            author: "COOLZHU AGENT".to_string(),
            role: "assistant".to_string(),
            target: "implementer".to_string(),
            content: "阶段实现完成，构建通过".to_string(),
            kind: "task-summary".to_string(),
            attachments: Vec::new(),
        };
        let first = {
            let mut store = super::session_store().lock().expect("session store");
            store
                .mirror_goal_phase_messages_to_system_room(&[message.clone()])
                .expect("mirror first")
        };
        let second = {
            let mut store = super::session_store().lock().expect("session store");
            store
                .mirror_goal_phase_messages_to_system_room(&[message])
                .expect("mirror duplicate")
        };
        assert_eq!(first, 1);
        assert_eq!(second, 0);
        let store = super::session_store().lock().expect("session store");
        let system_room = store
            .state
            .chat_rooms
            .iter()
            .find(|room| room.id == super::SCHEDULED_TASK_SYSTEM_ROOM_ID)
            .expect("system room present");
        assert_eq!(system_room.messages.len(), 1);
        assert_eq!(system_room.messages[0].id, "goal-msg-1");
    }

    #[test]
    fn scheduled_task_system_room_writes_concise_status_messages() {
        let _serial = config_test_guard();
        let _guard = SessionStoreTestGuard::install(scheduled_room_test_state());
        let cases = [
            ("failed", "执行失败：构建未通过"),
            ("skipped", "已暂停，本次跳过"),
            ("no-output", "无输出：阶段未产生消息"),
        ];
        for (status, detail) in cases {
            let mut store = super::session_store().lock().expect("session store");
            store
                .append_scheduled_task_status_message(status, detail)
                .expect("append status message");
        }
        let store = super::session_store().lock().expect("session store");
        let system_room = store
            .state
            .chat_rooms
            .iter()
            .find(|room| room.id == super::SCHEDULED_TASK_SYSTEM_ROOM_ID)
            .expect("system room present");
        let contents: Vec<&str> = system_room
            .messages
            .iter()
            .map(|message| message.content.as_str())
            .collect();
        assert!(contents.iter().any(|content| content.contains("执行失败")));
        assert!(contents.iter().any(|content| content.contains("跳过")));
        assert!(contents.iter().any(|content| content.contains("无输出")));
        // 精简：每条状态消息长度受限。
        assert!(
            system_room
                .messages
                .iter()
                .all(|message| message.content.chars().count() <= 80),
            "状态消息应精简（≤80 字符）"
        );
    }

